INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我到公园时正好赶上着一场音乐会。", "corrected_sentence": "我到公园时正好赶上了一场音乐会。", "error_description": "体标用错：“赶上着”；正确：“赶上了”。“着”表示动作的持续状态，“赶上”是一次性完成的动作，完成义应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的成绩终于被赶上了班里的平均水平。", "corrected_sentence": "他的成绩终于赶上了班里的平均水平。", "error_description": "句式用错：加上“被”变成被动，句子说成成绩被别人追上，与原意相反；这里应直接用主动式“赶上了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
