INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90259, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "著作是人写出来的书或文章。", "primary_collocate": null, "pronunciation": "zhù zuò", "ipa": "ʈʂu⁵¹ tsuɔ⁵¹", "syllable_count": 2, "sentences": [{"text": "这位老师写过很多著作。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的著作在书店里很好找。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部著作是他十年前写的。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里有他所有的著作。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢这位作家的著作。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在读爷爷留下的著作。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生出版了一部著作。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的著作送给了我。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家的著作我都看过。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些著作都是奶奶写的。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "著作权", "label": "复合"}], "register": "书面语", "sense_fingerprint": "人写出来的书或文章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1bdeefd-92f9-4e14-bb18-a5d8568bc61c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90259, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房子", "is_correct": false, "explanation": "搭配：“写”不能与“房子”搭配，房子不是写出来的"}, {"text": "著作", "is_correct": true, "explanation": "正确：著作指写成的书或文章，“写过很多著作”符合句意"}, {"text": "草莓", "is_correct": false, "explanation": "语义：草莓是水果，不是可以“写”的东西，与句意不合"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，与“写过很多”的语境毫不相关"}], "explanations": {"房子": "搭配：“写”不能与“房子”搭配，房子不是写出来的", "著作": "正确：著作指写成的书或文章，“写过很多著作”符合句意", "草莓": "语义：草莓是水果，不是可以“写”的东西，与句意不合", "汽油": "语义：汽油是燃料，与“写过很多”的语境毫不相关"}, "sentence_index": 0, "correct_answer": "著作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位作曲家的著作在音乐会上演奏了。", "explanation": "这里应该用〈作品〉。著作指写成的书或文章，乐曲要说“作品”，不说“著作”"}, {"text": "我每天晚上写著作，记录生活。", "explanation": "这里应该用〈日记〉。著作指正式写成的书或文章，记录日常生活的文字是“日记”，不说“著作”"}, {"text": "他的著作写得很好，老师让他读给全班听。", "explanation": "这里应该用〈作文〉。著作指正式写成的书或文章，学生写的作文不叫“著作”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电影", "is_correct": false, "explanation": "搭配：“出版”用于书籍，电影应说“拍摄”或“上映”，不说“出版电影”"}, {"text": "著作", "is_correct": true, "explanation": "正确：“出版了一部著作”指出版了一本书，符合句意"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯设备，不是可以出版的作品"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不属于出版物"}], "explanations": {"电影": "搭配：“出版”用于书籍，电影应说“拍摄”或“上映”，不说“出版电影”", "著作": "正确：“出版了一部著作”指出版了一本书，符合句意", "手机": "语义：手机是通讯设备，不是可以出版的作品", "汽车": "语义：汽车是交通工具，不属于出版物"}, "sentence_index": 6, "correct_answer": "著作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的著作写得很好。", "explanation": "这里应该用〈剧本〉。著作指写成的书或文章，电影剧本一般不叫“著作”"}, {"text": "老师批改了我的著作。", "explanation": "这里应该用〈作业〉。著作指正式写成的书或文章，学生的作业不叫“著作”"}, {"text": "妈妈在桌上给我留了一张著作，让我记得吃饭。", "explanation": "这里应该用〈纸条〉。著作指正式写成的书或文章，随手留下的几句话是“纸条”，不说“著作”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她出版了一条著作，很多人都在读。", "corrected_sentence": "她出版了一部著作，很多人都在读。", "error_description": "量词错误：“一条著作”应改为“一部著作”。条多用于细长的东西，书籍要用量词“部”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于写了完这部著作。", "corrected_sentence": "他终于写完了这部著作。", "error_description": "补语位置错误：动补“写完”中的“完”应紧接动词，“了”放在补语之后，说“写完了这部著作”，不能说“写了完这部著作”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
