INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90260, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用文字写成的作品，多指内容较系统、有价值的书籍或论文。", "primary_collocate": null, "pronunciation": "zhù zuò", "ipa": "ʈʂu⁵¹ tsuɔ⁵¹", "syllable_count": 2, "sentences": [{"text": "这部著作对历史研究很有价值。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教授花了二十年写成这部著作。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们都在读这位学者的著作。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本学术著作讲得很系统。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的著作影响了很多学者。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位科学家的著作改变了人们的看法。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求我们读几部经典著作。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部著作分成三章，内容很系统。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的研究成果都写进了这部著作。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆收藏了不少哲学著作。", "target_word": "著作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "著作权", "label": "复合"}], "register": "书面语", "sense_fingerprint": "内容系统、有价值的书籍或论文", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1bdeefd-92f9-4e14-bb18-a5d8568bc61c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯设备，不是书籍或论文，不能“对历史研究很有价值”"}, {"text": "著作", "is_correct": true, "explanation": "正确：著作指内容系统、有价值的书或论文，符合句意"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是学术性的书籍或论文，与句意不合"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不是书籍或论文，也不用量词“部”，与句意不合"}], "explanations": {"手机": "语义：手机是通讯设备，不是书籍或论文，不能“对历史研究很有价值”", "著作": "正确：著作指内容系统、有价值的书或论文，符合句意", "汽车": "语义：汽车不是学术性的书籍或论文，与句意不合", "沙发": "语义：沙发是家具，不是书籍或论文，也不用量词“部”，与句意不合"}, "sentence_index": 0, "correct_answer": "著作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画是他最好的著作。", "explanation": "这里应该用〈作品〉。著作指写成的书或文章，画作要说“作品”，不说“著作”"}, {"text": "我每天在网上写著作，记录生活。", "explanation": "这里应该用〈博客〉。著作指正式成书或成文的作品，网上记录日常的文字是“博客”，不说“著作”"}, {"text": "这位歌手的新著作在网上很受欢迎，大家都会唱。", "explanation": "这里应该用〈歌曲〉。著作指用文字写成的书或论文，能唱的是“歌曲”，不说“著作”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电影", "is_correct": false, "explanation": "搭配：“读”一般用于文字，不说“读几部电影”，应说“看”"}, {"text": "纪录片", "is_correct": false, "explanation": "语义：纪录片是影像作品，不是书面的经典著作"}, {"text": "著作", "is_correct": true, "explanation": "正确：“读几部经典著作”指阅读几部经典书籍，符合句意"}, {"text": "电视剧", "is_correct": false, "explanation": "搭配：“读”不与“电视剧”搭配，电视剧是用来看的"}], "explanations": {"电影": "搭配：“读”一般用于文字，不说“读几部电影”，应说“看”", "纪录片": "语义：纪录片是影像作品，不是书面的经典著作", "著作": "正确：“读几部经典著作”指阅读几部经典书籍，符合句意", "电视剧": "搭配：“读”不与“电视剧”搭配，电视剧是用来看的"}, "sentence_index": 6, "correct_answer": "著作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部著作拍得很好。", "explanation": "这里应该用〈电影〉。著作是用文字写成的书或文章，不能用“拍”"}, {"text": "这部著作唱得很好听。", "explanation": "这里应该用〈歌曲〉。著作是用文字写成的作品，不能用“唱”"}, {"text": "这部著作演奏得很好。", "explanation": "这里应该用〈交响乐〉。著作是文字作品，不能说“演奏”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条著作很有深度，值得一读。", "corrected_sentence": "这部著作很有深度，值得一读。", "error_description": "量词错误：“这条著作”应改为“这部著作”。条多用于细长的东西，书籍要用量词“部”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆收藏了几部学术著作们。", "corrected_sentence": "图书馆收藏了几部学术著作。", "error_description": "后缀错误：“著作”指书或文章，不指人，不能加复数后缀“们”，“几部”已表示数量，应说“几部学术著作”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
