INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90261, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "闭上眼睛，在心里向神说出自己的愿望。", "primary_collocate": null, "pronunciation": "qí dǎo", "ipa": "tɕʰi˧˥ tɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "她闭上眼睛，在心里默默祈祷。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，他闭上眼睛安静地祈祷了一分钟。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞时，我紧紧闭着眼睛祈祷。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他双手合十，安静地祈祷。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈闭眼祈祷，希望我考试顺利。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在心里祈祷：快让雨停吧！", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等结果的时候，大家都在心里祈祷。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子闭上眼睛，小声祈祷着新年愿望能实现。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉以前，小明总是先闭眼祈祷。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有说话，只是闭着眼睛祈祷。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "祈祷了", "label": "体标"}, {"form": "祈祷着", "label": "体标"}, {"form": "祈祷过", "label": "体标"}, {"form": "祈禱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "闭眼在心里默默向神说出愿望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c4d128-43e8-4390-b92a-c10afdd8f3f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90261, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祈祷", "is_correct": true, "explanation": "正确：“祈祷”指闭眼在心里默默向神说出愿望，与“在心里默默”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳需要在水中进行，无法在心里默默完成。"}, {"text": "修车", "is_correct": false, "explanation": "配价：“修车”需要具体的车或机器作宾语，不能在“心里默默”中进行。"}, {"text": "购物", "is_correct": false, "explanation": "语义：购物需要现实中的场所和商品，无法在心里默默完成。"}], "explanations": {"祈祷": "正确：“祈祷”指闭眼在心里默默向神说出愿望，与“在心里默默”相符。", "游泳": "语义：游泳需要在水中进行，无法在心里默默完成。", "修车": "配价：“修车”需要具体的车或机器作宾语，不能在“心里默默”中进行。", "购物": "语义：购物需要现实中的场所和商品，无法在心里默默完成。"}, "sentence_index": 0, "correct_answer": "祈祷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他闭上眼睛祈祷自己的作业。", "explanation": "这里应该用〈检查〉。祈祷是向神灵说出心愿，不能用于查看作业，应说“检查”。"}, {"text": "她闭上眼睛祈祷童年的生活。", "explanation": "这里应该用〈回忆〉。祈祷是向神灵求保佑，不能用于追想过去的事，应说“回忆”。"}, {"text": "他闭上眼睛祈祷课文。", "explanation": "这里应该用〈背诵〉。祈祷是向神说出心愿，不能用于记诵课文，背课文要说“背诵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90261, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "祈祷", "is_correct": true, "explanation": "正确：“祈祷”指在心里默默向神说出愿望，与“等结果的时候，大家都在心里”相符。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡要在浴室进行，不能在心里完成，句意不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“在心里”后接的动作必须能在心里完成，“吃饭”不能。"}, {"text": "摔倒", "is_correct": false, "explanation": "语义：“摔倒”是身体动作，不能发生在心里。"}], "explanations": {"祈祷": "正确：“祈祷”指在心里默默向神说出愿望，与“等结果的时候，大家都在心里”相符。", "洗澡": "语义：洗澡要在浴室进行，不能在心里完成，句意不通。", "吃饭": "搭配：“在心里”后接的动作必须能在心里完成，“吃饭”不能。", "摔倒": "语义：“摔倒”是身体动作，不能发生在心里。"}, "sentence_index": 6, "correct_answer": "祈祷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他闭着眼睛祈祷羊。", "explanation": "这里应该用〈数〉。祈祷是默默向神说出愿望，不能用于数动物，睡前数羊应说“数羊”。"}, {"text": "她在心里祈祷了一首歌。", "explanation": "这里应该用〈唱〉。祈祷是向神说愿望，不能用来表示演唱，应说“唱了一首歌”。"}, {"text": "她闭着眼睛祈祷单词。", "explanation": "这里应该用〈背〉。祈祷是向神说愿望，不能用来记忆单词，应说“背单词”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90261, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他闭着眼睛，在心里默默祈祷着了一会儿。", "corrected_sentence": "他闭着眼睛，在心里默默祈祷了一会儿。", "error_description": "时态标记用错：表示动作完成时只用“了”，“祈祷”后不能再加“着”，应为“祈祷了一会儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90261, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她闭着眼睛祈祷很认真。", "corrected_sentence": "她闭着眼睛祈祷得很认真。", "error_description": "补语结构漏掉“得”：动词后面带“很认真”这类状态补语时要用“得”，应为“祈祷得很认真”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
