INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90263, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跟拍是拿着相机跟在人后面一边走一边拍。", "primary_collocate": null, "pronunciation": "gēn pāi", "ipa": "kən˥ pʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "他拿着相机在后面跟拍新娘。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友跟拍了我们一整天。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一路跟拍小狗，拍了很多照片。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请朋友跟拍我的毕业旅行。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跟着孩子跑，一边跑一边跟拍。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着手机跟拍着那位老人。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在后面跟拍我学走路。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸跟拍过我第一天上学。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们请了一位朋友跟拍婚礼。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以跟拍我，我走慢一点。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跟拍了", "label": "体标（了）"}, {"form": "跟拍着", "label": "体标（着）"}, {"form": "跟拍过", "label": "体标（过）"}], "register": "通用", "sense_fingerprint": "拿着相机跟在人后面一边走一边拍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0e4be8-25eb-4115-9c6a-5a16b534add7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90263, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "画", "is_correct": false, "explanation": "搭配：“画”要用画笔等工具，不能说拿着相机画新娘。"}, {"text": "跟拍", "is_correct": true, "explanation": "跟拍：拿着相机跟在人后面边走边拍，与“拿着相机”和“在后面”相符。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”表示跌落或甩下，与拍摄的动作和新娘的语境不符。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”用于修理物品，不能用于修新娘。"}], "explanations": {"画": "搭配：“画”要用画笔等工具，不能说拿着相机画新娘。", "跟拍": "跟拍：拿着相机跟在人后面边走边拍，与“拿着相机”和“在后面”相符。", "摔": "语义：“摔”表示跌落或甩下，与拍摄的动作和新娘的语境不符。", "修": "语义：“修”用于修理物品，不能用于修新娘。"}, "sentence_index": 0, "correct_answer": "跟拍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在海边跟拍日落。", "explanation": "这里应该用〈拍摄〉。跟拍指跟随移动的人或物边走边拍，日落是静止的，应该用拍摄。"}, {"text": "他站在树下，跟拍那棵老树。", "explanation": "这里应该用〈拍〉。跟拍要求拍摄对象在移动，老树不动，直接用“拍”即可。"}, {"text": "他喜欢跟拍风景。", "explanation": "这里应该用〈拍〉。跟拍需要被拍对象边移动边被跟随，风景是静止的，不能跟拍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能用来指跟着孩子拍。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，与孩子学走路的语境不符。"}, {"text": "跟拍", "is_correct": true, "explanation": "跟拍：跟在孩子后面边走边拍，与“学走路”的场景相符。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”用于烹饪食物，与学走路的语境不符。"}], "explanations": {"写": "搭配：“写”的对象是文字，不能用来指跟着孩子拍。", "煮": "语义：“煮”的对象是食物，与孩子学走路的语境不符。", "跟拍": "跟拍：跟在孩子后面边走边拍，与“学走路”的场景相符。", "烤": "语义：“烤”用于烹饪食物，与学走路的语境不符。"}, "sentence_index": 6, "correct_answer": "跟拍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在草稿纸上跟拍了一道数学题。", "explanation": "这里应该用〈解〉。跟拍是用相机拍摄移动的人或物，不能用于解题，解题要用解。"}, {"text": "他在纸上跟拍字。", "explanation": "这里应该用〈写〉。跟拍是用相机拍摄移动的人或物，不能用于写字。"}, {"text": "妈妈在厨房跟拍饭。", "explanation": "这里应该用〈煮〉。跟拍是用相机拍摄移动的人或物，不能用于烹饪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她没跟拍了那只小狗。", "corrected_sentence": "她没跟拍那只小狗。", "error_description": "错误在“跟拍”后面的“了”。否定句中“没”与“了”不同用，应说“她没跟拍那只小狗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我跟拍他过两天。", "corrected_sentence": "我跟拍过他两天。", "error_description": "错误：“过”放错了位置。“过”要紧跟在“跟拍”后面，放在宾语“他”前面，应说“我跟拍过他两天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
