INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90264, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拍摄者跟随拍摄对象边移动边拍摄。", "primary_collocate": null, "pronunciation": "gēn pāi", "ipa": "kən˥ pʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "电视台的人跟拍这位医生三个月了。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演让摄像师跟拍那辆正在开的车。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的最后一段是跟拍的。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者跟拍着比赛里的每一个运动员。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们跟拍过很多外卖员的生活。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了拍好跑步的人，摄像师骑着车跟拍。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想跟拍一位老师的一天。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节目组跟拍了她一年。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄像师跟拍着队员跑进球场。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跟拍的时候，摄像师要走得很稳。", "target_word": "跟拍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跟拍了", "label": "体标（了）"}, {"form": "跟拍着", "label": "体标（着）"}, {"form": "跟拍过", "label": "体标（过）"}], "register": "通用", "sense_fingerprint": "拍摄者跟随拍摄对象边移动边拍摄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0e4be8-25eb-4115-9c6a-5a16b534add7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90264, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "治疗", "is_correct": false, "explanation": "语义：“治疗”的对象是病人，与电视台拍摄医生的语境不符。"}, {"text": "跟拍", "is_correct": true, "explanation": "跟拍：拍摄者跟随拍摄对象边移动边拍摄，与“电视台的人”和“三个月”相符。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”多用于机器或物品，与电视台拍医生的语境不符。"}, {"text": "卖", "is_correct": false, "explanation": "搭配：“卖”的对象是商品，不能用于人。"}], "explanations": {"治疗": "语义：“治疗”的对象是病人，与电视台拍摄医生的语境不符。", "跟拍": "跟拍：拍摄者跟随拍摄对象边移动边拍摄，与“电视台的人”和“三个月”相符。", "修理": "语义：“修理”多用于机器或物品，与电视台拍医生的语境不符。", "卖": "搭配：“卖”的对象是商品，不能用于人。"}, "sentence_index": 0, "correct_answer": "跟拍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给墙上的画跟拍留念。", "explanation": "这里应该用〈拍照〉。跟拍要求拍摄对象在移动，墙上的画是静止的，应该用拍照。"}, {"text": "记者跟拍那段音乐。", "explanation": "这里应该用〈录音〉。跟拍的对象是可以移动的人或物，音乐不能用相机跟拍，应该用录音。"}, {"text": "保安跟拍门口。", "explanation": "这里应该用〈监控〉。跟拍是拿相机跟随拍摄对象，门口不移动，应该用监控。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "送", "is_correct": false, "explanation": "配价：“送”要带受事和接受者，不能直接带“一位老师的一天”作宾语。"}, {"text": "跟拍", "is_correct": true, "explanation": "跟拍：拍摄者跟随老师拍摄他的一天，与“公司想……”的语境相符。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”表示加热或焚烧，与记录一天的事件不符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能用于“一天”。"}], "explanations": {"送": "配价：“送”要带受事和接受者，不能直接带“一位老师的一天”作宾语。", "跟拍": "跟拍：拍摄者跟随老师拍摄他的一天，与“公司想……”的语境相符。", "烧": "语义：“烧”表示加热或焚烧，与记录一天的事件不符。", "吃": "搭配：“吃”的宾语是食物，不能用于“一天”。"}, "sentence_index": 6, "correct_answer": "跟拍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跟拍了一首诗，念给朋友听。", "explanation": "这里应该用〈写〉。跟拍是用相机拍摄移动的人或物，不能用于创作诗歌，创作要用写。"}, {"text": "他在厨房里跟拍了一锅粥。", "explanation": "这里应该用〈煮〉。跟拍是用相机拍摄，不能用于烹饪，烹饪粥要用煮。"}, {"text": "他跟拍了一首曲子，弹得很熟练。", "explanation": "这里应该用〈弹〉。跟拍是用相机拍摄，不能用于演奏乐曲，演奏要用弹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "记者跟拍在那位运动员。", "corrected_sentence": "记者跟拍着那位运动员。", "error_description": "错误：“在”不能放在“跟拍”之后。动作进行可说“跟拍着”（或“在跟拍”），不能说“跟拍在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "节目组明天跟拍了她。", "corrected_sentence": "节目组明天跟拍她。", "error_description": "错误在“了”。“明天”表示将来，句中不能用表示完成的“了”，应说“节目组明天跟拍她”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90266, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推卸", "is_correct": true, "explanation": "“推卸”指不肯承担责任，与“负”（担负、承担）相反。"}, {"text": "观看", "is_correct": false, "explanation": "“观看”指用眼睛看，与“负”不构成反义。"}, {"text": "陪伴", "is_correct": false, "explanation": "“陪伴”指陪在身边，与“负”不构成反义。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与“负”不构成反义。"}], "correct_answer": "推卸", "explanations": {"推卸": "“推卸”指不肯承担责任，与“负”（担负、承担）相反。", "观看": "“观看”指用眼睛看，与“负”不构成反义。", "陪伴": "“陪伴”指陪在身边，与“负”不构成反义。", "参加": "“参加”指加入某项活动，与“负”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90266, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推卸", "is_correct": true, "explanation": "“推卸”指不肯承担责任，与“负”（担负、承担）相反。"}, {"text": "经历", "is_correct": false, "explanation": "“经历”指亲身遇到过某事，与“负”不构成反义。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指交流看法，与“负”不构成反义。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”指外出游览，与“负”不构成反义。"}], "correct_answer": "推卸", "explanations": {"推卸": "“推卸”指不肯承担责任，与“负”（担负、承担）相反。", "经历": "“经历”指亲身遇到过某事，与“负”不构成反义。", "讨论": "“讨论”指交流看法，与“负”不构成反义。", "旅行": "“旅行”指外出游览，与“负”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90266, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "担负，承担责任或任务。", "primary_collocate": null, "pronunciation": "fù", "ipa": "fu˥˩", "syllable_count": 1, "sentences": [{"text": "他一个人负起了养家的责任。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机对这次事故负有责任。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥负起了照顾弟弟的任务。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长说，学校要对每个学生负起责任。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她肩上负着一家人的希望。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错事的人要自己负起责任。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母年纪大了，儿子应该负起照顾他们的责任。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司对产品的质量负有责任。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长负起了带领大家的任务。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚当上班长，就负起了管理全班的任务。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "负着", "label": "体标"}, {"form": "负了", "label": "体标"}, {"form": "负责", "label": "复合"}, {"form": "負", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "负：担负、承担责任或任务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b53e4b0-c261-4aa3-a7a3-270daa3968ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90266, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "负", "is_correct": true, "explanation": "负（fù）指担负、承担责任或任务，正是听到的词。"}, {"text": "夫", "is_correct": false, "explanation": "夫（第一声）与 fù（第四声）声调不同，意思是丈夫。"}, {"text": "服", "is_correct": false, "explanation": "服（第二声）与 fù（第四声）声调不同，意思是服从或衣服。"}, {"text": "步", "is_correct": false, "explanation": "步（bù）与 fù 声母不同，声母由 f 变为 b，意思是脚步。"}, {"text": "路", "is_correct": false, "explanation": "路（lù）与 fù 声母不同，声母由 f 变为 l，意思是道路。"}], "explanations": {"负": "负（fù）指担负、承担责任或任务，正是听到的词。", "夫": "夫（第一声）与 fù（第四声）声调不同，意思是丈夫。", "服": "服（第二声）与 fù（第四声）声调不同，意思是服从或衣服。", "步": "步（bù）与 fù 声母不同，声母由 f 变为 b，意思是脚步。", "路": "路（lù）与 fù 声母不同，声母由 f 变为 l，意思是道路。"}, "sentence_index": null, "correct_answer": "负"}, "level_3": {"options": [{"text": "负", "is_correct": true, "explanation": "“负起”表示开始承担，与“养家的责任”的语境相符。"}, {"text": "推", "is_correct": false, "explanation": "语义：“推”是推开或推卸，与“承担养家的责任”的意思相反。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”是躲避，与“承担养家的责任”相矛盾。"}, {"text": "赖", "is_correct": false, "explanation": "搭配：“赖”常用于“赖账”，不能与“起……的责任”搭配，意思也与承担相反。"}], "explanations": {"负": "“负起”表示开始承担，与“养家的责任”的语境相符。", "推": "语义：“推”是推开或推卸，与“承担养家的责任”的意思相反。", "躲": "语义：“躲”是躲避，与“承担养家的责任”相矛盾。", "赖": "搭配：“赖”常用于“赖账”，不能与“起……的责任”搭配，意思也与承担相反。"}, "sentence_index": 0, "correct_answer": "负"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年被选为班长，今年又负起了班长。", "explanation": "这里应该用〈担任〉。“负起”用于责任或任务，表示职务时要说“担任”。"}, {"text": "他负起了一杯茶，递给了客人。", "explanation": "这里应该用〈端〉。“负起”只用于责任或任务，不能用于端茶这类动作。"}, {"text": "他负起了一双鞋，穿在了脚上。", "explanation": "这里应该用〈穿〉。“负起”只用于责任或任务，不能用于穿鞋这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90266, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "负", "is_correct": true, "explanation": "负（fù）指担负、承担责任或任务，正是听到的词。"}, {"text": "扶", "is_correct": false, "explanation": "扶（第二声）与 fù（第四声）声调不同，意思是扶持。"}, {"text": "辅", "is_correct": false, "explanation": "辅（第三声）与 fù（第四声）声调不同，意思是辅助。"}, {"text": "布", "is_correct": false, "explanation": "布（bù）与 fù 声母不同，声母由 f 变为 b，意思是布料。"}, {"text": "户", "is_correct": false, "explanation": "户（hù）与 fù 声母不同，声母由 f 变为 h，意思是家庭或门户。"}], "explanations": {"负": "负（fù）指担负、承担责任或任务，正是听到的词。", "扶": "扶（第二声）与 fù（第四声）声调不同，意思是扶持。", "辅": "辅（第三声）与 fù（第四声）声调不同，意思是辅助。", "布": "布（bù）与 fù 声母不同，声母由 f 变为 b，意思是布料。", "户": "户（hù）与 fù 声母不同，声母由 f 变为 h，意思是家庭或门户。"}, "sentence_index": null, "correct_answer": "负"}, "level_3": {"options": [{"text": "负", "is_correct": true, "explanation": "“负起照顾父母的责任”符合“应该”的要求，与语境相符。"}, {"text": "逃", "is_correct": false, "explanation": "语义：“逃”是逃避，与“应该……照顾父母的责任”的意思相反。"}, {"text": "放", "is_correct": false, "explanation": "搭配：“放”不说“放起……的责任”，与“照顾父母”不搭配。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”是丢失，不能表示承担照顾父母的责任。"}], "explanations": {"负": "“负起照顾父母的责任”符合“应该”的要求，与语境相符。", "逃": "语义：“逃”是逃避，与“应该……照顾父母的责任”的意思相反。", "放": "搭配：“放”不说“放起……的责任”，与“照顾父母”不搭配。", "丢": "语义：“丢”是丢失，不能表示承担照顾父母的责任。"}, "sentence_index": 6, "correct_answer": "负"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他负起了一首歌，唱给大家听。", "explanation": "这里应该用〈唱〉。“负起”只用于责任或任务，不能与“歌”搭配。"}, {"text": "他负起了一封信，寄到了北京。", "explanation": "这里应该用〈寄〉。“负起”只用于责任或任务，不能用于寄信这类动作。"}, {"text": "他负起了一个故事，讲给孩子们听。", "explanation": "这里应该用〈讲〉。“负起”只用于责任或任务，讲故事应说“讲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事他应该负下责任。", "corrected_sentence": "这件事他应该负起责任。", "error_description": "错误：“负”后的补语用了“下”。正确：“负起责任”，“起”表示开始承担；“负下”不是这个词的搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经负了起责任。", "corrected_sentence": "他已经负起了责任。", "error_description": "错误：“了”放在了“负”和“起”之间。正确：“负起了责任”，“了”应放在动补结构“负起”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
