INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90269, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "路杀是小动物过马路时，被车撞死了。", "primary_collocate": null, "pronunciation": "lù shā", "ipa": "lu˥˩ ʂa˥", "syllable_count": 2, "sentences": [{"text": "夜里开车慢一点，可以少些路杀。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路车很多，常常发生路杀。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路杀让很多小动物失去了生命。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天青蛙过马路，路杀特别多。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天早上，我在路边看到一起路杀。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了减少路杀，有人在路边放了提示牌。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路杀是很多爱动物的人担心的事。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时看到小动物，要慢慢开，避免路杀。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问什么是路杀，我给他看了照片。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路弯多，路杀很难避免。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "小动物过马路时被车撞死", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9b14e92-3a0f-44e7-b1c6-121a5b382a86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90269, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "路杀", "is_correct": true, "explanation": "路杀指小动物过马路时被车撞死，“少些路杀”与开车慢一点的句意相符。"}, {"text": "路灯", "is_correct": false, "explanation": "语义：句中要减少的应是伤亡，路灯与开车慢无关，句子说不通。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：开车慢不会让乘客变少，“少些乘客”说不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：开车慢与作业多少无关，句子说不通。"}], "explanations": {"路杀": "路杀指小动物过马路时被车撞死，“少些路杀”与开车慢一点的句意相符。", "路灯": "语义：句中要减少的应是伤亡，路灯与开车慢无关，句子说不通。", "乘客": "语义：开车慢不会让乘客变少，“少些乘客”说不通。", "作业": "语义：开车慢与作业多少无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "路杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场路杀让两个人失去了生命。", "explanation": "这里应该用〈车祸〉。路杀只指小动物过马路时被车撞死，撞死人要说车祸。"}, {"text": "农场里，收割机造成了很多路杀。", "explanation": "这个词不这么用。路杀指小动物在马路上被车撞死，农田里的机器伤害小鸡不属于路杀。"}, {"text": "这次路杀让一名骑车的老人住进了医院。", "explanation": "这里应该用〈交通事故〉。路杀只指小动物过马路时被车撞死，撞伤人的事故要说交通事故。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90269, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "路杀", "is_correct": true, "explanation": "路杀指小动物被车撞死，是爱动物的人担心的事，符合句意。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，不是爱动物的人担心的事，句子说不通。"}, {"text": "周末", "is_correct": false, "explanation": "语义：周末是时间，不能作“担心的事”的主语。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“担心的事”要接事情或状况，蛋糕是食物，不能这样搭配。"}], "explanations": {"路杀": "路杀指小动物被车撞死，是爱动物的人担心的事，符合句意。", "花园": "语义：花园是场所，不是爱动物的人担心的事，句子说不通。", "周末": "语义：周末是时间，不能作“担心的事”的主语。", "蛋糕": "搭配：“担心的事”要接事情或状况，蛋糕是食物，不能这样搭配。"}, "sentence_index": 6, "correct_answer": "路杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们周末去路杀散步。", "explanation": "这里应该用〈马路〉。路杀指小动物被车撞死的事件，不是地点，不能说“去路杀”。"}, {"text": "这次路杀的人数比去年多了一倍。", "explanation": "这里应该用〈交通事故〉。路杀只指小动物被车撞死，伤亡的人要说交通事故。"}, {"text": "这起路杀案的凶手至今没找到。", "explanation": "这里应该用〈凶杀〉。路杀是车辆撞死小动物，没有人为的凶手，也不是故意杀人的案件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90269, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上周我在山路上看到一条路杀。", "corrected_sentence": "上周我在山路上看到一起路杀。", "error_description": "错误：“一条路杀”；正确：“一起路杀”。路杀是事件，计量应用“起”，“条”用于细长的东西或消息等，不用于路杀。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90269, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天傍晚，我在路口看到一只路杀。", "corrected_sentence": "昨天傍晚，我在路口看到一起路杀。", "error_description": "错误：“一只路杀”；正确：“一起路杀”。路杀是事件，计量应用〈起〉，〈只〉用于单个的动物，不用于路杀事件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
