INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90270, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "野生动物在道路上被车辆撞死的现象。", "primary_collocate": null, "pronunciation": "lù shā", "ipa": "lu˥˩ ʂa˥", "syllable_count": 2, "sentences": [{"text": "路杀在山区公路上很常见。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，路杀对野生动物影响很大。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护区修了通道，路杀少了很多。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野生动物过公路时容易出现路杀。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公路越修越多，路杀问题也越来越重。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究路杀，想知道动物什么时候过路。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路杀每年让很多野生动物死去。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个保护区，路杀已经不是大问题了。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里车快，动物看不清，所以路杀多。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了不让路杀再发生，司机要慢慢开车。", "target_word": "路杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "野生动物在道路上被车撞死的现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9b14e92-3a0f-44e7-b1c6-121a5b382a86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "路杀", "is_correct": true, "explanation": "路杀指野生动物在道路上被车撞死的现象，与山区公路的句意相符。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁在地下运行，与山区公路无关，句子说不通。"}, {"text": "摩天楼", "is_correct": false, "explanation": "语义：摩天楼是城市建筑，山区公路上不会常见。"}, {"text": "鱼干", "is_correct": false, "explanation": "搭配：“鱼干”与“公路上”不搭配，句子说不通。"}], "explanations": {"路杀": "路杀指野生动物在道路上被车撞死的现象，与山区公路的句意相符。", "地铁": "语义：地铁在地下运行，与山区公路无关，句子说不通。", "摩天楼": "语义：摩天楼是城市建筑，山区公路上不会常见。", "鱼干": "搭配：“鱼干”与“公路上”不搭配，句子说不通。"}, "sentence_index": 0, "correct_answer": "路杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这起路杀造成了两人死亡。", "explanation": "这里应该用〈车祸〉。路杀指野生动物被车撞死，撞死人要说车祸。"}, {"text": "地震后，村里出现了很多路杀。", "explanation": "这个词不这么用。路杀是车辆撞死野生动物的现象，地震造成的死亡不能叫路杀。"}, {"text": "这次路杀造成的伤亡人数比去年多了一倍。", "explanation": "这里应该用〈交通事故〉。路杀指野生动物被车撞死，伤亡的人要说交通事故。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "路杀", "is_correct": true, "explanation": "路杀每年让很多野生动物死去，主语是这种现象，符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资不会让动物死去，句子说不通。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡不会让野生动物死去，句子说不通。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“让……死去”的主语应是灾害或现象，小说不能这样搭配。"}], "explanations": {"路杀": "路杀每年让很多野生动物死去，主语是这种现象，符合句意。", "工资": "语义：工资不会让动物死去，句子说不通。", "咖啡": "语义：咖啡不会让野生动物死去，句子说不通。", "小说": "搭配：“让……死去”的主语应是灾害或现象，小说不能这样搭配。"}, "sentence_index": 6, "correct_answer": "路杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在路杀旁边卖水果。", "explanation": "这里应该用〈路边〉。路杀是事件，不是地点，不能说“路杀旁边”。"}, {"text": "他每天都给路杀洗澡。", "explanation": "这个词不这么用。路杀指野生动物被车撞死这一现象，不是动物本身，所以不能给它洗澡。"}, {"text": "这起路杀的凶手至今没找到。", "explanation": "这里应该用〈凶杀〉。路杀是车辆撞死野生动物，没有人为的凶手，不能说有凶手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年这段公路上出现了三条路杀。", "corrected_sentence": "去年这段公路上出现了三起路杀。", "error_description": "错误：“三条路杀”；正确：“三起路杀”。路杀是事件，计量应用“起”，“条”用于细长的东西或消息等，不用于路杀。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个路口昨天发生了一只路杀。", "corrected_sentence": "这个路口昨天发生了一起路杀。", "error_description": "错误：“一只路杀”；正确：“一起路杀”。路杀是事件，计量应用〈起〉，〈只〉用于单个的动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
