INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90271, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90271, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分成一样大小的几份。", "primary_collocate": null, "pronunciation": "děng fēn", "ipa": "tɤŋ˨˩ fən˥˥", "syllable_count": 2, "sentences": [{"text": "蛋糕等分成了四份。", "target_word": "等分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这块地等分成三块。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条线可以等分成五段。", "target_word": "等分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把西瓜等分成六块。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把巧克力等分成八小块。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让大家把纸等分成两半。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比萨饼先等分成四份，再吃。", "target_word": "等分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块布能等分成几块？", "target_word": "等分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把一根绳子等分成了三段。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把月饼等分成四份给大家。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "等分了", "label": "体标"}, {"form": "等分过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把东西分成大小一样的几份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65a17352-6903-43e6-8fa1-188b5f5fe0c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90271, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拼", "is_correct": false, "explanation": "语义：“拼”是把碎片组合起来，不能指把蛋糕分成四份。"}, {"text": "合", "is_correct": false, "explanation": "搭配：“合成”说的是合为一个整体，不说“合成了四份”。"}, {"text": "等分", "is_correct": true, "explanation": "等分：把蛋糕分成大小相等的四份，符合“成了四份”的结果。"}, {"text": "融", "is_correct": false, "explanation": "语义：“融”指熔化，蛋糕熔化后不会被分成四份。"}], "explanations": {"拼": "语义：“拼”是把碎片组合起来，不能指把蛋糕分成四份。", "合": "搭配：“合成”说的是合为一个整体，不说“合成了四份”。", "等分": "等分：把蛋糕分成大小相等的四份，符合“成了四份”的结果。", "融": "语义：“融”指熔化，蛋糕熔化后不会被分成四份。"}, "sentence_index": 0, "correct_answer": "等分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板按能力把奖金等分给员工。", "explanation": "这里应该用〈分配〉。按能力分配时奖金多少不同，等分要求平均，不能与“按能力”搭配。"}, {"text": "我把蛋糕等分成了大小不一的块。", "explanation": "这里应该用〈切〉。等分的结果必须大小一样，大小不一的块要用“切”。"}, {"text": "他把两块面团等分成了一大块。", "explanation": "这里应该用〈揉〉。等分是把整体平均分开，把两块面团合成一大块要用“揉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90271, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缝", "is_correct": false, "explanation": "语义：“缝”是把东西连接起来，比萨饼不能缝成四份。"}, {"text": "晒", "is_correct": false, "explanation": "语义：“晒”指放在太阳下，不能说把比萨饼晒成四份再吃。"}, {"text": "等分", "is_correct": true, "explanation": "等分：把比萨饼平均分成四份，与“先……再吃”的语境相合。"}, {"text": "凑", "is_correct": false, "explanation": "搭配：“凑成”指凑齐成为一个整体，不说“凑成四份”。"}], "explanations": {"缝": "语义：“缝”是把东西连接起来，比萨饼不能缝成四份。", "晒": "语义：“晒”指放在太阳下，不能说把比萨饼晒成四份再吃。", "等分": "等分：把比萨饼平均分成四份，与“先……再吃”的语境相合。", "凑": "搭配：“凑成”指凑齐成为一个整体，不说“凑成四份”。"}, "sentence_index": 6, "correct_answer": "等分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个人的能力等分了。", "explanation": "这里应该用〈相等〉。等分是动作，指把整体分成几份，不能用来说两人的能力相同。"}, {"text": "孩子们把碎片等分成了一个圆。", "explanation": "这里应该用〈拼〉。等分是把整体分开，拼是把碎片合成整体，方向正好相反。"}, {"text": "这种化合物可以等分成两种元素。", "explanation": "这里应该用〈分解〉。化合物分解成元素是成分分开，不是把整体平均分开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90271, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块饼干等分了成四份。", "corrected_sentence": "这块饼干等分成了四份。", "error_description": "错误在“了”的位置：结果补语“成”要紧接动词，“了”应放在“成”之后，说“等分成了四份”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90271, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把饼干等分成着两份。", "corrected_sentence": "他把饼干等分成了两份。", "error_description": "错误在补语后的助词：“等分成着两份”中的“着”应为“了”。“成”后面表示完成的结果要用“了”，“着”表示动作持续，不能接在“成”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
