INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90272, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把整体分成相等的若干份。", "primary_collocate": null, "pronunciation": "děng fēn", "ipa": "tɤŋ˨˩ fən˥˥", "syllable_count": 2, "sentences": [{"text": "请把这个圆等分成六份。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么等分一条线段。", "target_word": "等分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用尺子把长纸条等分了。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱要等分给三个孩子。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把利润等分给每位工人。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这个角等分，需要用圆规。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人把房租等分，每人付一半。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把木板等分成十段。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先把工作等分，每人负责一部分。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把整张图等分好了。", "target_word": "等分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "等分了", "label": "体标"}, {"form": "等分过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把整体分成相等的若干份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65a17352-6903-43e6-8fa1-188b5f5fe0c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等分", "is_correct": true, "explanation": "等分：把圆平均分成六份，符合“成六份”的语境。"}, {"text": "拼", "is_correct": false, "explanation": "语义：“拼”是把碎片组合起来，不能指把一个圆分成六份。"}, {"text": "合", "is_correct": false, "explanation": "搭配：“合成”说的是合为一个整体，不说“合成六份”。"}, {"text": "捏", "is_correct": false, "explanation": "语义：“捏”是用手塑形，不能指把圆分成六份。"}], "explanations": {"等分": "等分：把圆平均分成六份，符合“成六份”的语境。", "拼": "语义：“拼”是把碎片组合起来，不能指把一个圆分成六份。", "合": "搭配：“合成”说的是合为一个整体，不说“合成六份”。", "捏": "语义：“捏”是用手塑形，不能指把圆分成六份。"}, "sentence_index": 0, "correct_answer": "等分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班长按成绩把奖学金等分给同学。", "explanation": "这里应该用〈分配〉。按成绩分配时奖学金多少不同，等分要求平均，不能与“按成绩”搭配。"}, {"text": "我把布等分成了大小不一的块。", "explanation": "这里应该用〈切〉。等分的结果必须大小一样，大小不一的块要用“切”。"}, {"text": "我们把几张小纸等分成了一张大海报。", "explanation": "这里应该用〈拼〉。等分是把整体平均分开，把几张小纸合成一张大海报要用“拼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抢", "is_correct": false, "explanation": "语义：“抢”是强行夺取，与“每人付一半”的分摊语境相矛盾。"}, {"text": "包", "is_correct": false, "explanation": "搭配：“包”指全部承担，与“每人付一半”矛盾，不用于平均分摊。"}, {"text": "等分", "is_correct": true, "explanation": "等分：平均分摊房租，与“每人付一半”相合。"}, {"text": "独吞", "is_correct": false, "explanation": "语义：“独吞”指一个人全部占有，与“两个人”分摊的语境矛盾。"}], "explanations": {"抢": "语义：“抢”是强行夺取，与“每人付一半”的分摊语境相矛盾。", "包": "搭配：“包”指全部承担，与“每人付一半”矛盾，不用于平均分摊。", "等分": "等分：平均分摊房租，与“每人付一半”相合。", "独吞": "语义：“独吞”指一个人全部占有，与“两个人”分摊的语境矛盾。"}, "sentence_index": 6, "correct_answer": "等分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两幅图的面积等分了。", "explanation": "这里应该用〈相等〉。等分是动作，指把整体分成几份，不能用来说两个面积相同。"}, {"text": "水可以等分成氢和氧。", "explanation": "这里应该用〈分解〉。水分解成氢和氧是化学变化，不是把整体平均分开。"}, {"text": "两家公司等分成了一家。", "explanation": "这里应该用〈合并〉。等分是把整体分开，合并是把几个合成一个，方向正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把这张纸等分到了四份。", "corrected_sentence": "老师把这张纸等分成了四份。", "error_description": "错误在补语：说把整体分为几份时，“等分”后面要用结果补语“成”，说“等分成了四份”，不说“等分到了四份”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹把这块布等分了好。", "corrected_sentence": "妹妹把这块布等分好了。", "error_description": "错误在补语语序：结果补语“好”要紧接动词，“了”应放在“等分好”之后，说“等分好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
