INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90273, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鸡是一种小动物，有两只脚和翅膀。母鸡会下蛋，公鸡早上会叫。", "primary_collocate": null, "pronunciation": "jī", "ipa": "tɕi˥", "syllable_count": 1, "sentences": [{"text": "这只鸡每天都下一个蛋。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上天一亮，鸡就叫了。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡有两只脚和一对翅膀。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在院子里看着鸡。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只鸡正在院子里找吃的。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们很喜欢看鸡下蛋。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷家的鸡晚上睡在笼子里。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在农村见过鸡。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡看见我，马上跑开了。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些鸡会下蛋，也会叫。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "雞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "小动物；两只脚有翅膀，会下蛋、会打鸣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5333b86-458e-4e5c-b1e8-aa02e8ad479d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90273, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鸡", "is_correct": true, "explanation": "鸡（jī）：小动物，正确答案。"}, {"text": "寄", "is_correct": false, "explanation": "寄（jì，第四声）与鸡（jī，第一声）声调不同，意思是“寄送”。"}, {"text": "吸", "is_correct": false, "explanation": "吸（xī）与鸡（jī）声母不同（x 与 j），声调相同，意思是“吸气”。"}, {"text": "极", "is_correct": false, "explanation": "极（jí，第二声）与鸡（jī，第一声）声调不同，意思是“极其”。"}], "explanations": {"鸡": "鸡（jī）：小动物，正确答案。", "寄": "寄（jì，第四声）与鸡（jī，第一声）声调不同，意思是“寄送”。", "吸": "吸（xī）与鸡（jī）声母不同（x 与 j），声调相同，意思是“吸气”。", "极": "极（jí，第二声）与鸡（jī，第一声）声调不同，意思是“极其”。"}, "sentence_index": null, "correct_answer": "鸡"}, "level_3": {"options": [{"text": "鸡", "is_correct": true, "explanation": "正确：会“下蛋”的是禽类，“鸡”与“下一个蛋”搭配、语义都合适。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不会下蛋，“这只狗每天都下一个蛋”与事实冲突。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：“下蛋”一般只说禽类，“猫”与“下蛋”搭配不当。"}, {"text": "猪", "is_correct": false, "explanation": "语义：猪不会下蛋，句子的意思无法成立。"}], "explanations": {"鸡": "正确：会“下蛋”的是禽类，“鸡”与“下一个蛋”搭配、语义都合适。", "狗": "语义：狗不会下蛋，“这只狗每天都下一个蛋”与事实冲突。", "猫": "搭配：“下蛋”一般只说禽类，“猫”与“下蛋”搭配不当。", "猪": "语义：猪不会下蛋，句子的意思无法成立。"}, "sentence_index": 0, "correct_answer": "鸡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明的爷爷卖掉了一头鸡。", "explanation": "这里应该用〈只〉。鸡是小型家禽，量词用“只”；“头”用于牛、猪等大型牲畜。"}, {"text": "小明帮爷爷修理鸡。", "explanation": "这里应该用〈鸡舍〉。“修理”的对象是建筑或设备，不能修理动物。"}, {"text": "妈妈用两只鸡做了蛋饼。", "explanation": "这里应该用〈鸡蛋〉。做蛋饼用的是蛋，“鸡”指整只家禽，不能代替“鸡蛋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90273, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鸡", "is_correct": true, "explanation": "鸡（jī）：小动物，正确答案。"}, {"text": "季", "is_correct": false, "explanation": "季（jì，第四声）与鸡（jī，第一声）声调不同，意思是“季节”。"}, {"text": "今", "is_correct": false, "explanation": "今（jīn）比鸡（jī）多一个韵尾 n，声调相同，意思是“今天”。"}, {"text": "急", "is_correct": false, "explanation": "急（jí，第二声）与鸡（jī，第一声）声调不同，意思是“着急”。"}], "explanations": {"鸡": "鸡（jī）：小动物，正确答案。", "季": "季（jì，第四声）与鸡（jī，第一声）声调不同，意思是“季节”。", "今": "今（jīn）比鸡（jī）多一个韵尾 n，声调相同，意思是“今天”。", "急": "急（jí，第二声）与鸡（jī，第一声）声调不同，意思是“着急”。"}, "sentence_index": null, "correct_answer": "鸡"}, "level_3": {"options": [{"text": "鸡", "is_correct": true, "explanation": "正确：晚上睡在笼子里的是动物，“鸡”与“睡在笼子里”搭配、语义都合适。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会“睡”，“椅子晚上睡在笼子里”说不通。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发不能睡在笼子里，与“笼子”的意思冲突。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“睡”的主语须是能躺卧的生物，“窗户”不能与“睡”搭配。"}], "explanations": {"鸡": "正确：晚上睡在笼子里的是动物，“鸡”与“睡在笼子里”搭配、语义都合适。", "椅子": "语义：椅子不会“睡”，“椅子晚上睡在笼子里”说不通。", "沙发": "语义：沙发不能睡在笼子里，与“笼子”的意思冲突。", "窗户": "搭配：“睡”的主语须是能躺卧的生物，“窗户”不能与“睡”搭配。"}, "sentence_index": 6, "correct_answer": "鸡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庆典上放飞了几只鸡。", "explanation": "这里应该用〈鸽子〉。放飞多用于鸽子、鸟类等能飞走的动物，“鸡”不这样说。"}, {"text": "小明骑着一只鸡去上学。", "explanation": "这里应该用〈自行车〉。鸡不能被骑，骑着去上学的交通工具应说“自行车”；“鸡”是家禽，不是交通工具。"}, {"text": "酒吧里端来一杯鸡。", "explanation": "这里应该用〈鸡尾酒〉。“杯”用于饮品，但“鸡”不是饮料，不能单独指酒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天亮的时候，鸡了叫。", "corrected_sentence": "天亮的时候，鸡叫了。", "error_description": "“了”应放在动词之后，“叫了”是正确的，“了叫”不能说。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子里有三条鸡。", "corrected_sentence": "院子里有三只鸡。", "error_description": "“条”多用于狗、鱼、河等细长事物，“鸡”应用量词“只”。错误形式“三条鸡”应改为“三只鸡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
