INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90274, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "家禽，嘴短而尖，翅膀短，不能高飞，母鸡能产蛋，肉和蛋可供食用。", "primary_collocate": null, "pronunciation": "jī", "ipa": "tɕi˥", "syllable_count": 1, "sentences": [{"text": "农场里养了很多鸡。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每天早上给鸡喂米。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸡飞不高。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场上卖的鸡很新鲜。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚饭妈妈煮了一只鸡。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在村子里养过几百只鸡。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些鸡的肉很嫩，很好吃。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡的嘴又短又尖。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把鸡关进了小房子里。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡的翅膀很短，不能高飞。", "target_word": "鸡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "雞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "家禽；饲养并供食用的鸡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5333b86-458e-4e5c-b1e8-aa02e8ad479d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90274, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鸡", "is_correct": true, "explanation": "鸡（jī）：家禽，正确答案。"}, {"text": "几", "is_correct": false, "explanation": "几（jǐ，第三声）与鸡（jī，第一声）声调不同，意思是“几个”。"}, {"text": "急", "is_correct": false, "explanation": "急（jí，第二声）与鸡（jī，第一声）声调不同，意思是“着急”。"}, {"text": "季", "is_correct": false, "explanation": "季（jì，第四声）与鸡（jī，第一声）声调不同，意思是“季节”。"}, {"text": "七", "is_correct": false, "explanation": "七（qī）与鸡（jī）声母不同（q 与 j），声调相同，意思是数字“七”。"}, {"text": "西", "is_correct": false, "explanation": "西（xī）与鸡（jī）声母不同（x 与 j），声调相同，意思是“西边”。"}, {"text": "金", "is_correct": false, "explanation": "金（jīn）比鸡（jī）多一个韵尾 n，声调相同，意思是“金子”。"}], "explanations": {"鸡": "鸡（jī）：家禽，正确答案。", "几": "几（jǐ，第三声）与鸡（jī，第一声）声调不同，意思是“几个”。", "急": "急（jí，第二声）与鸡（jī，第一声）声调不同，意思是“着急”。", "季": "季（jì，第四声）与鸡（jī，第一声）声调不同，意思是“季节”。", "七": "七（qī）与鸡（jī）声母不同（q 与 j），声调相同，意思是数字“七”。", "西": "西（xī）与鸡（jī）声母不同（x 与 j），声调相同，意思是“西边”。", "金": "金（jīn）比鸡（jī）多一个韵尾 n，声调相同，意思是“金子”。"}, "sentence_index": null, "correct_answer": "鸡"}, "level_3": {"options": [{"text": "鸡", "is_correct": true, "explanation": "正确：“养了很多”的对象是动物，“鸡”与“农场里养”搭配、语义都合适。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是可以饲养的东西，“农场里养了很多汽车”说不通。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“养”一般只带动物或植物，不说“养水”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是饲养的对象，句子的意思与“养”冲突。"}], "explanations": {"鸡": "正确：“养了很多”的对象是动物，“鸡”与“农场里养”搭配、语义都合适。", "汽车": "语义：汽车不是可以饲养的东西，“农场里养了很多汽车”说不通。", "水": "搭配：“养”一般只带动物或植物，不说“养水”。", "桌子": "语义：桌子不是饲养的对象，句子的意思与“养”冲突。"}, "sentence_index": 0, "correct_answer": "鸡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个蛋糕是用三只鸡做的。", "explanation": "这里应该用〈鸡蛋〉。做蛋糕用的是蛋，“鸡”指整只家禽，不能代替“鸡蛋”。"}, {"text": "农场主卖掉了一头鸡。", "explanation": "这里应该用〈只〉。鸡是小型家禽，量词用“只”；“头”用于牛、猪、驴等大型牲畜，不用于鸡。"}, {"text": "我买了一张鸡。", "explanation": "这里应该用〈只〉。“张”用于纸、桌子等平面的东西；鸡是动物，量词用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90274, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鸡", "is_correct": true, "explanation": "鸡（jī）：家禽，正确答案。"}, {"text": "技", "is_correct": false, "explanation": "技（jì，第四声）与鸡（jī，第一声）声调不同，意思是“技术”。"}, {"text": "今", "is_correct": false, "explanation": "今（jīn）比鸡（jī）多一个韵尾 n，声调相同，意思是“今天”。"}, {"text": "集", "is_correct": false, "explanation": "集（jí，第二声）与鸡（jī，第一声）声调不同，意思是“聚集”。"}], "explanations": {"鸡": "鸡（jī）：家禽，正确答案。", "技": "技（jì，第四声）与鸡（jī，第一声）声调不同，意思是“技术”。", "今": "今（jīn）比鸡（jī）多一个韵尾 n，声调相同，意思是“今天”。", "集": "集（jí，第二声）与鸡（jī，第一声）声调不同，意思是“聚集”。"}, "sentence_index": null, "correct_answer": "鸡"}, "level_3": {"options": [{"text": "鸡", "is_correct": true, "explanation": "正确：“肉很嫩、很好吃”描述可食用的动物，“鸡”语义和搭配都合适。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有可以食用的肉，“石头的肉很嫩”说不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不长肉，与“肉很嫩，很好吃”的意思冲突。"}, {"text": "书", "is_correct": false, "explanation": "语义：书没有肉，“这些书的肉很嫩，很好吃”说不通。"}], "explanations": {"鸡": "正确：“肉很嫩、很好吃”描述可食用的动物，“鸡”语义和搭配都合适。", "石头": "语义：石头没有可以食用的肉，“石头的肉很嫩”说不通。", "房子": "语义：房子不长肉，与“肉很嫩，很好吃”的意思冲突。", "书": "语义：书没有肉，“这些书的肉很嫩，很好吃”说不通。"}, "sentence_index": 6, "correct_answer": "鸡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "婚礼上放飞了一群鸡。", "explanation": "这里应该用〈鸽子〉。放飞多用于鸽子、鸟类等能飞走的动物，“鸡”不这样说。"}, {"text": "农民每天都打扫鸡。", "explanation": "这里应该用〈鸡舍〉。“打扫”的对象是场所，“鸡”是动物，不能说打扫鸡。"}, {"text": "我点了一杯鸡。", "explanation": "这里应该用〈鸡尾酒〉。“杯”用于饮品，但“鸡”不是饮料，不能单独指酒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个农场养了两个鸡。", "corrected_sentence": "这个农场养了两只鸡。", "error_description": "“鸡”是动物，量词应用“只”，不用“个”。错误形式“两个鸡”应改为“两只鸡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只鸡进跑了院子。", "corrected_sentence": "那只鸡跑进了院子。", "error_description": "“跑进”是动词加方向补语，顺序不能颠倒。“进跑”错误，应说“跑进了院子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
