INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90277, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很喜欢某个人或明星，一直关注他的人。", "primary_collocate": null, "pronunciation": "fěn sī", "ipa": "fən˨˩ sɹ̩˥", "syllable_count": 2, "sentences": [{"text": "她有一百万粉丝，每条视频都有很多人看。", "target_word": "粉丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是这位歌手的粉丝，他的歌我都听过。", "target_word": "粉丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚发了一张新照片，粉丝们马上点赞。", "target_word": "粉丝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网红的粉丝越来越多，她很高兴。", "target_word": "粉丝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我妹妹是个小粉丝，每天都看那个明星的视频。", "target_word": "粉丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为他的老粉丝，我每年都买他的新专辑。", "target_word": "粉丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主播说谢谢粉丝们一直以来的关注。", "target_word": "粉丝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多粉丝在网上给她留言，说想看她的新电影。", "target_word": "粉丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个男演员有很多女粉丝，她们都喜欢他的笑容。", "target_word": "粉丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不是他的粉丝吗？怎么没看他的新节目？", "target_word": "粉丝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "粉丝团", "label": "复合"}, {"form": "粉絲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "喜欢并一直关注某人或明星的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5461ebd-d36b-4535-a617-61dd6497bd0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90277, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粉丝", "is_correct": true, "explanation": "粉丝指很喜欢并关注某人的人，与“一百万”和“很多人看”的视频情境相符。"}, {"text": "老板", "is_correct": false, "explanation": "语义：“老板”指雇用他人的人，不是关注视频的人，与“很多人看”不符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不可数，不能说“一百万年龄”。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：“眼睛”是身体器官，不能指关注视频的人，与“很多人看”的情境不符。"}], "explanations": {"粉丝": "粉丝指很喜欢并关注某人的人，与“一百万”和“很多人看”的视频情境相符。", "老板": "语义：“老板”指雇用他人的人，不是关注视频的人，与“很多人看”不符。", "年龄": "搭配：“年龄”不可数，不能说“一百万年龄”。", "眼睛": "语义：“眼睛”是身体器官，不能指关注视频的人，与“很多人看”的情境不符。"}, "sentence_index": 0, "correct_answer": "粉丝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "粉丝给病人做了一次手术，手术很成功。", "explanation": "这里应该用〈医生〉。粉丝指追随明星或名人的人，给病人做手术的是医生，不能用粉丝。"}, {"text": "我和小王是粉丝，我们每天一起上学。", "explanation": "这里应该用〈同学〉。粉丝指追随明星或名人的人，每天一起上学的是同学，不是粉丝。"}, {"text": "粉丝每天在游泳池里教我们游泳。", "explanation": "这里应该用〈教练〉。粉丝指追随明星或名人的人，教游泳的是教练，不能用粉丝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90277, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粉丝", "is_correct": true, "explanation": "粉丝指喜爱并追随某人的人，符合“谢谢……的关注”的语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不会关注主播，与“谢谢……的关注”不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人，不能去关注主播，与“谢谢……的关注”不符。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”是抽象名词，不能加“们”，也不说“谢谢工资的关注”。"}], "explanations": {"粉丝": "粉丝指喜爱并追随某人的人，符合“谢谢……的关注”的语境。", "桌子": "语义：“桌子”是家具，不会关注主播，与“谢谢……的关注”不符。", "天气": "语义：“天气”不是人，不能去关注主播，与“谢谢……的关注”不符。", "工资": "搭配：“工资”是抽象名词，不能加“们”，也不说“谢谢工资的关注”。"}, "sentence_index": 6, "correct_answer": "粉丝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "粉丝在路口指挥交通，大家都很感谢他们。", "explanation": "这里应该用〈警察〉。粉丝指追随明星或名人的人，在路口指挥交通的是警察，不能用粉丝。"}, {"text": "粉丝每个月都要核对公司的账目。", "explanation": "这里应该用〈会计〉。粉丝指追随明星或名人的人，核对公司账目的是会计，不能用粉丝。"}, {"text": "粉丝设计了这座大桥，大家都很佩服。", "explanation": "这里应该用〈工程师〉。粉丝指追随明星或名人的人，设计大桥的是工程师，不能用粉丝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90277, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我是这位演员的一只粉丝，他的电影我都看过。", "corrected_sentence": "我是这位演员的一位粉丝，他的电影我都看过。", "error_description": "量词错误：“粉丝”指人，应该用“位”或“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90277, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校门口有一只粉丝在等那位歌手。", "corrected_sentence": "校门口有一群粉丝在等那位歌手。", "error_description": "量词错误：“粉丝”指人，一群人应该用“群”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
