INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90278, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "特别喜爱并追随某位明星或名人的人。", "primary_collocate": null, "pronunciation": "fěn sī", "ipa": "fən˨˩ sɹ̩˥", "syllable_count": 2, "sentences": [{"text": "歌手一到机场，很多粉丝就跑过去了。", "target_word": "粉丝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的粉丝从全国各地赶来看演唱会。", "target_word": "粉丝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位明星对粉丝很好，常常给他们签名。", "target_word": "粉丝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了见偶像，粉丝们在门口等了一夜。", "target_word": "粉丝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "粉丝们举着灯牌，大声喊着歌手的名字。", "target_word": "粉丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是这位足球明星最忠实的粉丝。", "target_word": "粉丝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演出结束后，粉丝们不愿意离开，还在唱他的歌。", "target_word": "粉丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的粉丝每年都会给他办一次生日会。", "target_word": "粉丝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个明星一出门，就有粉丝拿着照相机跟着他。", "target_word": "粉丝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想成为她的粉丝，因为她的歌很好听。", "target_word": "粉丝", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "粉丝团", "label": "复合"}, {"form": "粉絲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "特别喜爱并追随明星名人的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5461ebd-d36b-4535-a617-61dd6497bd0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粉丝", "is_correct": true, "explanation": "粉丝指特别喜爱并追随明星的人，符合“很多人就跑过去”的情境。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：“飞机”不会自己跑过去，句中要求的是会跑的人群。"}, {"text": "行李", "is_correct": false, "explanation": "语义：“行李”是物品，不会“跑过去”，与句意不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”是物质，不会“跑过去”，与句中“很多粉丝就跑过去了”的情境不符。"}], "explanations": {"粉丝": "粉丝指特别喜爱并追随明星的人，符合“很多人就跑过去”的情境。", "飞机": "语义：“飞机”不会自己跑过去，句中要求的是会跑的人群。", "行李": "语义：“行李”是物品，不会“跑过去”，与句意不符。", "空气": "语义：“空气”是物质，不会“跑过去”，与句中“很多粉丝就跑过去了”的情境不符。"}, "sentence_index": 0, "correct_answer": "粉丝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司门口的粉丝等了一夜，等着老板发工资。", "explanation": "这里应该用〈员工〉。粉丝指追随明星或名人的人，等老板发工资的是员工，不是粉丝。"}, {"text": "粉丝每天给病人量体温，很辛苦。", "explanation": "这里应该用〈护士〉。粉丝指追随明星或名人的人，给病人量体温的是护士，不能用粉丝。"}, {"text": "粉丝每天在教室里批改作业。", "explanation": "这里应该用〈老师〉。粉丝指追随明星或名人的人，在教室里批改作业的是老师，不能用粉丝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粉丝", "is_correct": true, "explanation": "粉丝指追随明星的人，符合演出结束后还在唱歌、不愿离开的情境。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”是坐的地方，不是人，不会“不愿意离开”，也不会唱歌。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”是作品，不能“不愿意离开”，句中的主语必须是有意愿的人，不能用“歌曲”。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”是抽象名词，不能加“们”，也不能说“不愿意离开”。"}], "explanations": {"粉丝": "粉丝指追随明星的人，符合演出结束后还在唱歌、不愿离开的情境。", "座位": "语义：“座位”是坐的地方，不是人，不会“不愿意离开”，也不会唱歌。", "歌曲": "语义：“歌曲”是作品，不能“不愿意离开”，句中的主语必须是有意愿的人，不能用“歌曲”。", "工资": "搭配：“工资”是抽象名词，不能加“们”，也不能说“不愿意离开”。"}, "sentence_index": 6, "correct_answer": "粉丝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "粉丝负责为客人做饭，餐厅的生意很好。", "explanation": "这里应该用〈厨师〉。粉丝指追随明星或名人的人，为客人做饭的是厨师，不能用粉丝。"}, {"text": "粉丝在路口指挥交通，大家都很感谢他们。", "explanation": "这里应该用〈警察〉。粉丝指追随明星或名人的人，在路口指挥交通的是警察，不能用粉丝。"}, {"text": "粉丝每个月都要核对公司的账目。", "explanation": "这里应该用〈会计〉。粉丝指追随明星或名人的人，核对公司账目的是会计，不能用粉丝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只粉丝在机场门口等着那位明星。", "corrected_sentence": "一位粉丝在机场门口等着那位明星。", "error_description": "量词错误：“粉丝”指人，应该用“位”或“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三只粉丝在门口等了很久。", "corrected_sentence": "三个粉丝在门口等了很久。", "error_description": "量词错误：“粉丝”指人，应该用“个”或“位”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
