INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90279, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "领土是一个国家的土地。这块地是这个国家的，别人不能随便进来。", "primary_collocate": null, "pronunciation": "lǐng tǔ", "ipa": "liŋ˨˩ tʰu˨˩", "syllable_count": 2, "sentences": [{"text": "这块领土是我们国家的。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别的国家不能随便进入我们的领土。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的领土很大。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的领土不大，但是人很多。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵守着国家的领土。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上能看到每个国家的领土。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护自己国家的领土。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座小岛也是他们的领土。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的领土有山，也有河。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了中国的领土。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "領土", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个国家的土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5333b86-458e-4e5c-b1e8-aa02e8ad479d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90279, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领土", "is_correct": true, "explanation": "正确：“领土”指国家主权管辖的土地，与“这块”和“是我们国家的”搭配、语义都合适。"}, {"text": "黑板擦", "is_correct": false, "explanation": "语义：黑板擦是教室用品，不能说一块黑板擦属于整个国家。"}, {"text": "伤疤", "is_correct": false, "explanation": "语义：伤疤长在人身上，不可能“是我们国家的”。"}, {"text": "橡皮", "is_correct": false, "explanation": "语义：一块橡皮是个人文具，不能说它归属于国家。"}], "explanations": {"领土": "正确：“领土”指国家主权管辖的土地，与“这块”和“是我们国家的”搭配、语义都合适。", "黑板擦": "语义：黑板擦是教室用品，不能说一块黑板擦属于整个国家。", "伤疤": "语义：伤疤长在人身上，不可能“是我们国家的”。", "橡皮": "语义：一块橡皮是个人文具，不能说它归属于国家。"}, "sentence_index": 0, "correct_answer": "领土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民把领土卖给了邻居。", "explanation": "这里应该用〈土地〉。“领土”指国家主权管辖的区域，不能作为私人财产买卖，买卖田地应说“土地”。"}, {"text": "这座城市的领土很大。", "explanation": "这里应该用〈面积〉。“领土”只用于国家主权范围，城市不说“领土”。"}, {"text": "我的领土有很多山。", "explanation": "这里应该用〈家乡〉。“领土”指国家的主权范围，不能用来指个人的家乡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90279, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领土", "is_correct": true, "explanation": "正确：“保护”的对象可以是国家的领土，语义和搭配都合适。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是需要国家保护的对象，“保护自己国家的冰箱”说不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不属于国家的主权范围，与“国家的”冲突。"}, {"text": "玩笑", "is_correct": false, "explanation": "搭配：“保护”的对象多为人、物或权益，“玩笑”不能被保护。"}], "explanations": {"领土": "正确：“保护”的对象可以是国家的领土，语义和搭配都合适。", "冰箱": "语义：冰箱不是需要国家保护的对象，“保护自己国家的冰箱”说不通。", "作业": "语义：作业不属于国家的主权范围，与“国家的”冲突。", "玩笑": "搭配：“保护”的对象多为人、物或权益，“玩笑”不能被保护。"}, "sentence_index": 6, "correct_answer": "领土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块领土很便宜，我们打算在上面盖房子。", "explanation": "这里应该用〈地皮〉。“领土”指国家主权管辖的区域，盖房子的地块应说“地皮”。"}, {"text": "他在数学的领土上很有名。", "explanation": "这里应该用〈领域〉。“领土”指国家主权范围的区域，指专业范围应说“领域”。"}, {"text": "学生们在学校的领土上踢足球。", "explanation": "这里应该用〈操场〉。“领土”指国家主权管辖的区域，学校的运动场地应说“操场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座领土很美丽。", "corrected_sentence": "这块领土很美丽。", "error_description": "“领土”的量词用“块”或“片”，“座”多用于山、桥、楼等，不用于领土。错误形式“这座领土”应改为“这块领土”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要住守自己的领土。", "corrected_sentence": "我们要守住自己的领土。", "error_description": "“守住”是动词加结果补语，顺序不能颠倒。“住守”错误，应说“守住自己的领土”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
