INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90281, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "农业国是大多数人靠种地生活的国家。", "primary_collocate": null, "pronunciation": "nóng yè guó", "ipa": "noŋ˧˥ jɛ˥˩ kwo˧˥", "syllable_count": 3, "sentences": [{"text": "中国以前是一个农业国。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业国的人大多住在农村。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个农业国有很多大米和水果。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，那个国家是农业国，不是工业国。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多农业国想学新技术。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业国的孩子常常帮家里种地。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百年前，这里是个穷农业国。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为农业国，他们不用从国外买太多粮食。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业国的天气对生活很重要。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书上读到了很多农业国的故事。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个农业国", "label": "量词"}, {"form": "农业大国", "label": "复合"}], "register": "中性", "sense_fingerprint": "大多数人靠种地生活的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95593539-6a07-48d3-929c-5995fd291c1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90281, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农业国", "is_correct": true, "explanation": "正确：“农业国”指以农业为主的国家，与“中国以前是一个”的语境相合。"}, {"text": "城市", "is_correct": false, "explanation": "语义：“城市”指城镇，不能说整个国家是一个城市。"}, {"text": "农民", "is_correct": false, "explanation": "语义：“农民”指种地的人，不能说“中国是一个农民”。"}, {"text": "农村", "is_correct": false, "explanation": "语义：“农村”是地方，不是国家，句子不通。"}], "explanations": {"农业国": "正确：“农业国”指以农业为主的国家，与“中国以前是一个”的语境相合。", "城市": "语义：“城市”指城镇，不能说整个国家是一个城市。", "农民": "语义：“农民”指种地的人，不能说“中国是一个农民”。", "农村": "语义：“农村”是地方，不是国家，句子不通。"}, "sentence_index": 0, "correct_answer": "农业国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个县是农业国，不是工业区。", "explanation": "这里应该用〈农业区〉。〈农业国〉指以农业为主的国家，县只能说〈农业区〉。"}, {"text": "这块农业国种了很多玉米。", "explanation": "这里应该用〈农田〉。〈农田〉指一块田地，〈农业国〉指国家，不能用来指地块。"}, {"text": "这家农业国雇了很多工人。", "explanation": "这里应该用〈农场〉。〈农场〉是经营农业的单位，〈农业国〉是国家，不能雇工人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90281, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "农业国", "is_correct": true, "explanation": "正确：“农业国”指以农业为主的国家，与“一百年前，这里是个穷”的语境相合。"}, {"text": "富国", "is_correct": false, "explanation": "语义：“富国”指富裕的国家，与“穷”相矛盾，不能说“这里是个穷富国”。"}, {"text": "富翁", "is_correct": false, "explanation": "语义：“富翁”指富有的人，不是地方，且与“穷”相矛盾。"}, {"text": "农民", "is_correct": false, "explanation": "语义：“农民”指种地的人，不能用来指“这里”这个地方。"}], "explanations": {"农业国": "正确：“农业国”指以农业为主的国家，与“一百年前，这里是个穷”的语境相合。", "富国": "语义：“富国”指富裕的国家，与“穷”相矛盾，不能说“这里是个穷富国”。", "富翁": "语义：“富翁”指富有的人，不是地方，且与“穷”相矛盾。", "农民": "语义：“农民”指种地的人，不能用来指“这里”这个地方。"}, "sentence_index": 6, "correct_answer": "农业国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每年都回农业国老家过春节。", "explanation": "这里应该用〈乡下〉。〈乡下〉指老家所在的乡村，〈农业国〉是国家，不能说回国家老家。"}, {"text": "院子里的农业国长得很好。", "explanation": "这里应该用〈庄稼〉。〈庄稼〉可以长得好，〈农业国〉是国家，不能作庄稼的主语。"}, {"text": "这片农业国养了很多牛羊。", "explanation": "这里应该用〈牧场〉。〈牧场〉用于养牲畜，〈农业国〉是国家，不能养牛羊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90281, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个岛国以前是一座农业国，靠种地为生。", "corrected_sentence": "这个岛国以前是一个农业国，靠种地为生。", "error_description": "量词错误：“农业国”是国家，应该用量词“个”。“座”多用于山、城市等大型固定物，不能用于国家。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90281, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家很农业国，靠种地养活了大多数人。", "corrected_sentence": "这个国家是农业国，靠种地养活了大多数人。", "error_description": "“农业国”是名词，前面不能加程度副词“很”。判断国家的性质要用系动词“是”，应改为“这个国家是农业国”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
