INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90282, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以农业为主要经济部门的国家。", "primary_collocate": null, "pronunciation": "nóng yè guó", "ipa": "noŋ˧˥ jɛ˥˩ kwo˧˥", "syllable_count": 3, "sentences": [{"text": "这个农业国的经济主要靠种植粮食。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业国的工厂少，农业占经济的大部分。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是农业国，所以出口大米和茶叶。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个农业国正在发展工业。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业国的经济容易受天气影响。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前很多农业国都很穷。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变成工业国以前，它是一个农业国。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个农业国的农产品卖到很多地方。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业国要想变富，需要发展工厂。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，这个农业国的农业收入在增加。", "target_word": "农业国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个农业国", "label": "量词"}, {"form": "农业大国", "label": "复合"}], "register": "书面", "sense_fingerprint": "以农业为主要经济部门的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95593539-6a07-48d3-929c-5995fd291c1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农业国", "is_correct": true, "explanation": "正确：“农业国”指以农业为主要经济部门的国家，与“经济主要靠种植粮食”相合。"}, {"text": "工业国", "is_correct": false, "explanation": "语义：“工业国”以工业为主，与“经济主要靠种植粮食”矛盾。"}, {"text": "医院", "is_correct": false, "explanation": "语义：“医院”是机构，不能说它的经济主要靠种植粮食。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“工厂”是企业，不能作为“经济”的主体来说“经济主要靠种植粮食”。"}], "explanations": {"农业国": "正确：“农业国”指以农业为主要经济部门的国家，与“经济主要靠种植粮食”相合。", "工业国": "语义：“工业国”以工业为主，与“经济主要靠种植粮食”矛盾。", "医院": "语义：“医院”是机构，不能说它的经济主要靠种植粮食。", "工厂": "搭配：“工厂”是企业，不能作为“经济”的主体来说“经济主要靠种植粮食”。"}, "sentence_index": 0, "correct_answer": "农业国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个农业国有五亩地。", "explanation": "这里应该用〈农户〉。〈农户〉有田地，〈农业国〉是国家，不能说有五亩地。"}, {"text": "这个农业国每天下地干活。", "explanation": "这里应该用〈农民〉。〈农民〉才下地干活，〈农业国〉是国家，不能下地。"}, {"text": "这片农业国的水稻长得很好。", "explanation": "这里应该用〈稻田〉。〈稻田〉指种水稻的田地，〈农业国〉是国家，不能说“这片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "农业国", "is_correct": true, "explanation": "正确：“变成工业国以前，它是一个农业国”指转变前以农业为主的国家，语境相合。"}, {"text": "学校", "is_correct": false, "explanation": "语义：“它”指国家，“学校”不是国家，“它是一个学校”不通。"}, {"text": "公司", "is_correct": false, "explanation": "语义：“公司”是企业，不能作为国家的经济类型，“它是一个公司”不通。"}, {"text": "医院", "is_correct": false, "explanation": "语义：“医院”是机构，不能指国家，“它是一个医院”不通。"}], "explanations": {"农业国": "正确：“变成工业国以前，它是一个农业国”指转变前以农业为主的国家，语境相合。", "学校": "语义：“它”指国家，“学校”不是国家，“它是一个学校”不通。", "公司": "语义：“公司”是企业，不能作为国家的经济类型，“它是一个公司”不通。", "医院": "语义：“医院”是机构，不能指国家，“它是一个医院”不通。"}, "sentence_index": 6, "correct_answer": "农业国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大学学的是农业国，毕业后去了研究所。", "explanation": "这里应该用〈农学〉。〈农学〉是学科名称，〈农业国〉指国家，不能作所学的专业。"}, {"text": "这种农业国对庄稼很有效。", "explanation": "这里应该用〈农药〉。〈农药〉用于庄稼，〈农业国〉是国家，不能对庄稼有效。"}, {"text": "他每天下班后都要干农业国。", "explanation": "这里应该用〈农活〉。〈农活〉指田里的劳动，〈农业国〉是国家，不能用来做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座农业国的粮食大多供应本国人民。", "corrected_sentence": "这个农业国的粮食大多供应本国人民。", "error_description": "量词错误：“农业国”是国家，应该用量词“个”。“座”多用于山、城市等大型固定物，不能用于国家。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个岛国原来个农业国，后来才开始办工厂。", "corrected_sentence": "那个岛国原来是个农业国，后来才开始办工厂。", "error_description": "缺少系动词“是”。“农业国”作谓语时前面需要“是”，省略后句子不完整，应改为“那个岛国原来是个农业国”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
