INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90283, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90283, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "坏人用力把人抓走，不让他回家。", "primary_collocate": null, "pronunciation": "bǎng jià", "ipa": "pɑŋ˨˩ tɕja˥˩", "syllable_count": 2, "sentences": [{"text": "坏人想绑架那个小男孩。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓住了绑架孩子的坏人。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天有人在路上绑架了一位老人。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为什么要绑架这个女孩？", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个坏人绑架过两个孩子。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈很怕坏人绑架她的女儿。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人把小明绑架到了一个很远的地方。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的坏人绑架了老板的儿子。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绑架孩子的人是谁？", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在找绑架老师的那个人。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绑架了", "label": "完成体"}, {"form": "绑架过", "label": "经历体"}, {"form": "绑架犯", "label": "复合词"}], "register": "中性", "sense_fingerprint": "坏人抓走人，不让人回家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2d745d-2bca-4b89-8b23-ae7e91d17958') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞好的行为，与“坏人”的意图相矛盾。"}, {"text": "绑架", "is_correct": true, "explanation": "正确：“绑架”指用暴力把人抓走，与“坏人想……小男孩”的语境相符。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”的对象是申请、计划等事项，不能直接以“小男孩”作宾语。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是善意的行为，与“坏人”的身份和意图相矛盾。"}], "explanations": {"表扬": "语义：“表扬”是称赞好的行为，与“坏人”的意图相矛盾。", "绑架": "正确：“绑架”指用暴力把人抓走，与“坏人想……小男孩”的语境相符。", "批准": "搭配：“批准”的对象是申请、计划等事项，不能直接以“小男孩”作宾语。", "保护": "语义：“保护”是善意的行为，与“坏人”的身份和意图相矛盾。"}, "sentence_index": 0, "correct_answer": "绑架"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "歹徒绑架了那辆公交车。", "explanation": "这里应该用〈劫持〉。绑架的对象是人，控制公交车、飞机等交通工具要用劫持。"}, {"text": "他用糖果绑架了那个小孩。", "explanation": "这里应该用〈拐骗〉。绑架要用暴力或威胁，用糖果哄骗要用拐骗。"}, {"text": "他用绳子绑架了那个包裹。", "explanation": "这里应该用〈绑〉。绑架只用于把人抓走，捆扎包裹要用绑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，与“坏人”和“把小明带到很远的地方”的语境相矛盾。"}, {"text": "绑架", "is_correct": true, "explanation": "正确：“绑架”指用暴力把人抓走并带走，与“坏人把小明……到很远的地方”相符。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”指采摘花果，不能用来带走人。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”是关爱的行为，与“坏人”的意图相矛盾。"}], "explanations": {"表扬": "语义：“表扬”是称赞，与“坏人”和“把小明带到很远的地方”的语境相矛盾。", "绑架": "正确：“绑架”指用暴力把人抓走并带走，与“坏人把小明……到很远的地方”相符。", "摘": "搭配：“摘”指采摘花果，不能用来带走人。", "照顾": "语义：“照顾”是关爱的行为，与“坏人”的意图相矛盾。"}, "sentence_index": 6, "correct_answer": "绑架"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察依法把那个犯人绑架到了法院。", "explanation": "这里应该用〈押送〉。绑架是违背意愿、非法抢人，依法把犯人送走要用押送。"}, {"text": "救援队绑架了被困在矿井里的工人。", "explanation": "这里应该用〈解救〉。绑架是违法抢人，把被困的人救出要用解救。"}, {"text": "他绑架了迷路的老人，还帮他找到了回家的路。", "explanation": "这里应该用〈带领〉。绑架是违背对方意愿、靠暴力或威胁抢人，给迷路的人带路要用带领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "歹徒把那位老板绑架。", "corrected_sentence": "歹徒把那位老板绑架了。", "error_description": "错误：“绑架”后缺少“了”。把字句的谓语后要有“了”或补语，应说“歹徒把那位老板绑架了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "坏人把小明绑架了走。", "corrected_sentence": "坏人把小明绑架走了。", "error_description": "错误：补语“走”与“了”的位置颠倒。“了”应放在补语“走”之后，应说“坏人把小明绑架走了”，不能说“坏人把小明绑架了走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
