INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90284, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用暴力或威胁手段劫持他人。", "primary_collocate": null, "pronunciation": "bǎng jià", "ipa": "pɑŋ˨˩ tɕja˥˩", "syllable_count": 2, "sentences": [{"text": "绑架别人是严重的犯罪。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们绑架了一位富商，想要很多钱。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "犯人绑架老板后，向他家人要钱。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绑架他人的人会受到法律的处罚。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团伙专门绑架有钱人。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方救出了那位富商，抓住了绑架他的人。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用刀威胁并绑架了司机。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绑架记者的人要求政府放人。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那几个人想绑架这家公司的经理。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为绑架商人，坐了八年牢。", "target_word": "绑架", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绑架了", "label": "完成体"}, {"form": "绑架过", "label": "经历体"}, {"form": "绑架案", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用暴力或威胁劫持他人，常为了要钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2d745d-2bca-4b89-8b23-ae7e91d17958') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是正当的称赞，与“严重的犯罪”相矛盾。"}, {"text": "绑架", "is_correct": true, "explanation": "正确：“绑架别人”是严重的违法行为，与句意相符。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言文字，不能说“翻译别人”。"}, {"text": "关心", "is_correct": false, "explanation": "语义：“关心”是善意的行为，与“严重的犯罪”相矛盾。"}], "explanations": {"表扬": "语义：“表扬”是正当的称赞，与“严重的犯罪”相矛盾。", "绑架": "正确：“绑架别人”是严重的违法行为，与句意相符。", "翻译": "搭配：“翻译”的对象是语言文字，不能说“翻译别人”。", "关心": "语义：“关心”是善意的行为，与“严重的犯罪”相矛盾。"}, "sentence_index": 0, "correct_answer": "绑架"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用假消息绑架了老人。", "explanation": "这里应该用〈诱骗〉。绑架要用暴力或威胁，用假消息骗人要用诱骗。"}, {"text": "歹徒绑架了那艘货船。", "explanation": "这里应该用〈劫持〉。绑架的对象是人，控制货船要用劫持。"}, {"text": "警察依法绑架了那个小偷。", "explanation": "这里应该用〈逮捕〉。绑架是违背意愿、非法抢人，依法抓人要用逮捕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是称赞，与“用刀威胁”的语境相矛盾。"}, {"text": "绑架", "is_correct": true, "explanation": "正确：“绑架”指用暴力或威胁抓人，与“用刀威胁并……了司机”相符。"}, {"text": "装", "is_correct": false, "explanation": "搭配：“装”指装载、安装，不能直接以“司机”作宾语。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”是善意的表达，与“用刀威胁”相矛盾。"}], "explanations": {"赞美": "语义：“赞美”是称赞，与“用刀威胁”的语境相矛盾。", "绑架": "正确：“绑架”指用暴力或威胁抓人，与“用刀威胁并……了司机”相符。", "装": "搭配：“装”指装载、安装，不能直接以“司机”作宾语。", "感谢": "语义：“感谢”是善意的表达，与“用刀威胁”相矛盾。"}, "sentence_index": 6, "correct_answer": "绑架"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消防员绑架了被困的老人。", "explanation": "这里应该用〈救援〉。绑架是违法抢人，救出被困的人要用救援。"}, {"text": "他绑架了那位远道而来的客人，还在门口放鞭炮欢迎他。", "explanation": "这里应该用〈接待〉。绑架是用暴力或威胁抢人，热情欢迎客人要用接待。"}, {"text": "护士绑架了那位住院的病人，每天认真地给他换药。", "explanation": "这里应该用〈护理〉。绑架是用暴力或威胁抢人，照顾病人、换药要用护理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这伙人绑架了过一位富商。", "corrected_sentence": "这伙人绑架过一位富商。", "error_description": "错误：“绑架”后面“了”和“过”不能连用。表示有过这种经历只用“过”，应说“这伙人绑架过一位富商”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "匪徒把那个女孩绑架。", "corrected_sentence": "匪徒把那个女孩绑架了。", "error_description": "错误：“绑架”后缺少“了”。把字句的谓语后要有“了”或补语，应说“匪徒把那个女孩绑架了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
