INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90285, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "饭是我们每天吃的东西。可以是白白的米饭，也可以是一顿饭。", "primary_collocate": null, "pronunciation": "fàn", "ipa": "fan˥˩", "syllable_count": 1, "sentences": [{"text": "我每天在家吃饭。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在厨房做饭。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗饭太热了，我等一下再吃。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我们一起去吃饭吧。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一顿吃了三碗饭。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭做好了，快来吃吧。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想吃一碗热饭。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给孩子盛了一碗饭。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你吃过饭了吗？", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天回家都要先吃饭。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "碗", "label": "量词"}, {"form": "顿", "label": "量词"}, {"form": "米饭", "label": "复合"}, {"form": "饭店", "label": "复合"}], "register": "中性", "sense_fingerprint": "饭：每天吃的东西，可以是米饭，也可以指一顿饭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '334d3bb3-d40f-4673-8ec2-5f77f12859af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90285, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "饭", "is_correct": true, "explanation": "饭（fàn）：每天吃的食物，可指米饭，也可指一顿饭。"}, {"text": "翻", "is_correct": false, "explanation": "翻（fān，第一声）与饭（fàn，第四声）声调不同，意思是翻动、翻译。"}, {"text": "烦", "is_correct": false, "explanation": "烦（fán，第二声）与饭（fàn，第四声）声调不同，意思是烦恼。"}, {"text": "反", "is_correct": false, "explanation": "反（fǎn，第三声）与饭（fàn，第四声）声调不同，意思是相反。"}, {"text": "放", "is_correct": false, "explanation": "放（fàng）与饭（fàn）韵母不同，放是 -ng，饭是 -n，意思是放置。"}], "explanations": {"饭": "饭（fàn）：每天吃的食物，可指米饭，也可指一顿饭。", "翻": "翻（fān，第一声）与饭（fàn，第四声）声调不同，意思是翻动、翻译。", "烦": "烦（fán，第二声）与饭（fàn，第四声）声调不同，意思是烦恼。", "反": "反（fǎn，第三声）与饭（fàn，第四声）声调不同，意思是相反。", "放": "放（fàng）与饭（fàn）韵母不同，放是 -ng，饭是 -n，意思是放置。"}, "sentence_index": null, "correct_answer": "饭"}, "level_3": {"options": [{"text": "饭", "is_correct": true, "explanation": "正确：“每天在家吃饭”中的“饭”，指每天吃的食物。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：“餐厅”是场所，不能作“在家吃”的对象，与“在家”矛盾。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”是地方，与“在家”矛盾，不能说“在家吃食堂”。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“吃”不搭配“水”，应说“喝水”。"}], "explanations": {"饭": "正确：“每天在家吃饭”中的“饭”，指每天吃的食物。", "餐厅": "语义：“餐厅”是场所，不能作“在家吃”的对象，与“在家”矛盾。", "食堂": "语义：“食堂”是地方，与“在家”矛盾，不能说“在家吃食堂”。", "水": "搭配：“吃”不搭配“水”，应说“喝水”。"}, "sentence_index": 0, "correct_answer": "饭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我渴了，想喝饭。", "explanation": "这里应该用〈饮料〉。饭是固体食物，不能用“喝”。"}, {"text": "超市的货架上摆满了饭。", "explanation": "这里应该用〈食品〉。饭指做好的米饭或一顿饭，超市货架上摆的是包装食品，不说“饭”。"}, {"text": "我爷爷在田里种了很多饭。", "explanation": "这里应该用〈稻子〉。“种”的对象是稻、麦等作物，饭是煮熟的食物，不能种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90285, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "饭", "is_correct": true, "explanation": "饭（fàn）：每天吃的食物，可指米饭，也可指一顿饭。"}, {"text": "帆", "is_correct": false, "explanation": "帆（fān，第一声）与饭（fàn，第四声）声调不同，意思是船帆。"}, {"text": "凡", "is_correct": false, "explanation": "凡（fán，第二声）与饭（fàn，第四声）声调不同，意思是凡是、所有。"}, {"text": "返", "is_correct": false, "explanation": "返（fǎn，第三声）与饭（fàn，第四声）声调不同，意思是返回。"}, {"text": "汗", "is_correct": false, "explanation": "汗（hàn）与饭（fàn）声母不同，h 与 f 不同，意思是汗水。"}], "explanations": {"饭": "饭（fàn）：每天吃的食物，可指米饭，也可指一顿饭。", "帆": "帆（fān，第一声）与饭（fàn，第四声）声调不同，意思是船帆。", "凡": "凡（fán，第二声）与饭（fàn，第四声）声调不同，意思是凡是、所有。", "返": "返（fǎn，第三声）与饭（fàn，第四声）声调不同，意思是返回。", "汗": "汗（hàn）与饭（fàn）声母不同，h 与 f 不同，意思是汗水。"}, "sentence_index": null, "correct_answer": "饭"}, "level_3": {"options": [{"text": "饭", "is_correct": true, "explanation": "正确：“我想吃一碗热饭”中的“饭”，指煮熟的米饭。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：蛋糕用“块”计量，不用“碗”，“一碗热蛋糕”不说。"}, {"text": "冰", "is_correct": false, "explanation": "语义：“热”与“冰”相矛盾，冰不能是热的，与“热”矛盾。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能用来吃，“吃一碗热书”不通。"}], "explanations": {"饭": "正确：“我想吃一碗热饭”中的“饭”，指煮熟的米饭。", "蛋糕": "搭配：蛋糕用“块”计量，不用“碗”，“一碗热蛋糕”不说。", "冰": "语义：“热”与“冰”相矛盾，冰不能是热的，与“热”矛盾。", "书": "语义：书不能用来吃，“吃一碗热书”不通。"}, "sentence_index": 6, "correct_answer": "饭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸每天回家都要先喝饭。", "explanation": "这里应该用〈饮料〉。饭是固体食物，不能用“喝”。"}, {"text": "爸爸每天回家都要先洗饭。", "explanation": "这里应该用〈米〉。饭是煮好的食物，不能洗，要洗的是生米。"}, {"text": "爸爸每天回家都要先读饭。", "explanation": "这里应该用〈书〉。“读”的对象是书、文字，饭不能读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90285, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一天只吃一只饭。", "corrected_sentence": "他一天只吃一顿饭。", "error_description": "“饭”的量词应用“顿”（或“碗”），不能用“只”，“只”用于动物。正确说法是“一顿饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90285, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经吃饭过了。", "corrected_sentence": "我们已经吃过饭了。", "error_description": "“过”要紧跟动词，应说“吃过饭”，不能说“吃饭过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
