INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90287, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进军是一队人向前走，去做一件大事。", "primary_collocate": null, "pronunciation": "jìn jūn", "ipa": "tɕin˥˩ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "工人们向荒山进军，要种满树。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全村的人向沙漠进军，开始治沙。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青年们向西部的草原进军，去修一条水渠。", "target_word": "进军", "complexity_tier": "T3", "furigana": "qīng nián men xiàng xī bù de cǎo yuán jìn jūn qù xiū yì tiáo shuǐ qú", "sentence_source": "generated"}, {"text": "同学们向大山进军，去修一条路。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们向灾区进军，去救受伤的人。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起向荒地进军，把它变成田。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们带着工具向河边进军，准备修堤。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支队伍明天出发，向高山进军。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者们向沙漠进军，要把绿色带到那里。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青年突击队向高原进军，去建新学校。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进军了", "label": "完成体"}, {"form": "进军过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "一队人朝着目标前进，去完成一件重要的大事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4f307f-eef1-48f7-ab9e-281d3bff4d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90287, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进军", "is_correct": true, "explanation": "进军：一队人朝荒山前进去完成任务，与“要种满树”的目的相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是悠闲的活动，与“要种满树”的任务不符，句子读不通。"}, {"text": "午睡", "is_correct": false, "explanation": "语义：“午睡”是休息，与“要种满树”的目标相矛盾。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与“要种满树”的劳动目的不符，句子读不通。"}], "explanations": {"进军": "进军：一队人朝荒山前进去完成任务，与“要种满树”的目的相符。", "散步": "语义：“散步”是悠闲的活动，与“要种满树”的任务不符，句子读不通。", "午睡": "语义：“午睡”是休息，与“要种满树”的目标相矛盾。", "唱歌": "语义：“唱歌”与“要种满树”的劳动目的不符，句子读不通。"}, "sentence_index": 0, "correct_answer": "进军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们明天进军去爬山。", "explanation": "这里应该用〈出发〉。进军含一队人朝有目标的大事前进的意味，去爬山这类游玩只说出发。"}, {"text": "老人们进军南方过冬。", "explanation": "这里应该用〈前往〉。进军含有去完成大事的意味，季节性去南方过冬只说前往。"}, {"text": "他们一起进军了新居。", "explanation": "这里应该用〈搬进〉。进军不用于搬家入住，搬进新居只说搬进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90287, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进军", "is_correct": true, "explanation": "进军：一队人朝河边前进去做事，与“准备修堤”的目的相符。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”与“准备修堤”的目的相矛盾，句子读不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是休息，与“带着工具”去修堤的行动不符。"}, {"text": "拜访", "is_correct": false, "explanation": "配价：“拜访”需要以人作宾语，“向河边拜访”没有对象，不成立。"}], "explanations": {"进军": "进军：一队人朝河边前进去做事，与“准备修堤”的目的相符。", "逃跑": "语义：“逃跑”与“准备修堤”的目的相矛盾，句子读不通。", "睡觉": "语义：“睡觉”是休息，与“带着工具”去修堤的行动不符。", "拜访": "配价：“拜访”需要以人作宾语，“向河边拜访”没有对象，不成立。"}, "sentence_index": 6, "correct_answer": "进军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们进军了超市，买了一些水果。", "explanation": "这里应该用〈进入〉。进军指一队人朝目标前进去完成大事，个人进入超市买东西只说进入。"}, {"text": "他进军了一次会议，发了言。", "explanation": "这里应该用〈参加〉。进军指一队人朝目标前进去完成大事，个人去开会只说参加。"}, {"text": "学生们进军了博物馆，看了很久。", "explanation": "这里应该用〈参观〉。进军指一队人朝目标前进去完成大事，去博物馆看展只说参观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90287, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "志愿者们下个月向草原进军了，去种树。", "corrected_sentence": "志愿者们下个月向草原进军，去种树。", "error_description": "错误：“进军”后多加了“了”。“下个月”指将来，应去掉“了”，说“进军，去种树”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90287, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "青年们昨天荒地进军，去修水渠。", "corrected_sentence": "青年们昨天向荒地进军，去修水渠。", "error_description": "错误：漏掉了介词“向”。“进军”前的方向要用“向”引出，应说“向荒地进军”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90288, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "退出", "is_correct": true, "explanation": "反义：“进军”指向某一领域发展，“退出”指离开该领域，二者意思相反。"}, {"text": "购买", "is_correct": false, "explanation": "无关：“购买”指付钱得到东西，与“进军市场”的发展义没有对立关系。"}, {"text": "研究", "is_correct": false, "explanation": "无关：“研究”指探究问题，与“进军”没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：“打扫”指清理卫生，与“进军”没有反义关系。"}], "correct_answer": "退出", "explanations": {"退出": "反义：“进军”指向某一领域发展，“退出”指离开该领域，二者意思相反。", "购买": "无关：“购买”指付钱得到东西，与“进军市场”的发展义没有对立关系。", "研究": "无关：“研究”指探究问题，与“进军”没有反义关系。", "打扫": "无关：“打扫”指清理卫生，与“进军”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90288, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "退出", "is_correct": true, "explanation": "反义：“退出”指离开某一市场，与“进军网络购物市场”正相反。"}, {"text": "旅行", "is_correct": false, "explanation": "无关：“旅行”指出外游览，与“进军”没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”指修补坏的东西，与“进军”没有对立关系。"}, {"text": "演讲", "is_correct": false, "explanation": "无关：“演讲”指当众讲话，与“进军”没有对立关系。"}], "correct_answer": "退出", "explanations": {"退出": "反义：“退出”指离开某一市场，与“进军网络购物市场”正相反。", "旅行": "无关：“旅行”指出外游览，与“进军”没有反义关系。", "修理": "无关：“修理”指修补坏的东西，与“进军”没有对立关系。", "演讲": "无关：“演讲”指当众讲话，与“进军”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90288, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "军队向目的地前进；也比喻向某一领域发展。", "primary_collocate": null, "pronunciation": "jìn jūn", "ipa": "tɕin˥˩ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "大军连夜向北方进军。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队明天早上向山区进军。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司决定进军海外市场。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司今年开始进军汽车行业。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们冒着大雨向前进军。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人想进军娱乐圈。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个品牌打算进军中国市场。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队已经向首都进军了。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想进军体育界，当一名教练。", "target_word": "进军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店老板也想进军网络购物市场。", "target_word": "进军", "complexity_tier": "T3", "furigana": "xiǎo diàn lǎo bǎn yě xiǎng jìn jūn wǎng luò gòu wù shì chǎng", "sentence_source": "generated"}], "morphological_forms": [{"form": "进军了", "label": "完成体"}, {"form": "进军过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "军队向目的地前进；比喻企业或个人向新领域、新市场发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4f307f-eef1-48f7-ab9e-281d3bff4d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90288, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进军", "is_correct": true, "explanation": "进军：军队向目的地前进，与“大军连夜向北方”的行军相符。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：“旅游”指悠闲地游览，与“大军连夜”的紧急行军相矛盾。"}, {"text": "拜访", "is_correct": false, "explanation": "配价：“拜访”需要以人作宾语，“向北方拜访”没有对象，不成立。"}, {"text": "溜达", "is_correct": false, "explanation": "语域：“溜达”是口语，书面句中不合适，且与“大军连夜”的语气冲突。"}], "explanations": {"进军": "进军：军队向目的地前进，与“大军连夜向北方”的行军相符。", "旅游": "语义：“旅游”指悠闲地游览，与“大军连夜”的紧急行军相矛盾。", "拜访": "配价：“拜访”需要以人作宾语，“向北方拜访”没有对象，不成立。", "溜达": "语域：“溜达”是口语，书面句中不合适，且与“大军连夜”的语气冲突。"}, "sentence_index": 0, "correct_answer": "进军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于进军了教室，开始认真听课。", "explanation": "这里应该用〈进入〉。进军多指军队或企业大举向某一领域发展，个人进入教室不用进军。"}, {"text": "她进军了合唱团，每周练习两次。", "explanation": "这里应该用〈加入〉。进军指大举进入某一领域，个人入团一般用加入。"}, {"text": "妈妈进军了邮局，寄了一封信。", "explanation": "这里应该用〈去〉。进军指大举向某一领域发展，个人去邮局办事只说去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90288, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进军", "is_correct": true, "explanation": "进军：向某一市场发展，与“这个品牌打算……中国市场”的语境相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的宾语是歌曲，不能带“中国市场”作宾语，句子读不通。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”不带“市场”这类宾语，“打算结婚中国市场”不成立。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“中国市场”作宾语。"}], "explanations": {"进军": "进军：向某一市场发展，与“这个品牌打算……中国市场”的语境相符。", "唱": "语义：“唱”的宾语是歌曲，不能带“中国市场”作宾语，句子读不通。", "结婚": "配价：“结婚”不带“市场”这类宾语，“打算结婚中国市场”不成立。", "游泳": "配价：“游泳”是不及物动词，不能带“中国市场”作宾语。"}, "sentence_index": 6, "correct_answer": "进军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她终于进军了三十岁，开始关注健康。", "explanation": "这里应该用〈迈入〉。进军指大举向某一领域发展，年龄的增长只说迈入。"}, {"text": "我们进军了一次大扫除，全班都很累。", "explanation": "这里应该用〈进行〉。进军指大举向某一领域发展，开展一次大扫除只说进行。"}, {"text": "她进军了新公寓，每天上下班很方便。", "explanation": "这里应该用〈搬进〉。进军指大举向某一领域发展，入住新居只说搬进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司明年计划进军了东南亚市场。", "corrected_sentence": "这家公司明年计划进军东南亚市场。", "error_description": "错误：“进军”后多加了“了”。“明年”指将来，“计划”要配将来的动作，应去掉“了”，说“计划进军”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "部队昨晚东方进军。", "corrected_sentence": "部队昨晚向东方进军。", "error_description": "错误：漏掉了介词“向”。“进军”前的方向要用“向”引出，应说“向东方进军”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90292, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幼年", "is_correct": true, "explanation": "「幼年」指人生的早期，与「高年」指年纪大的时期正相反，构成反义。"}, {"text": "河流", "is_correct": false, "explanation": "「河流」是地理事物，与「高年」没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "「窗户」是建筑部件，与「高年」不构成反义。"}, {"text": "课本", "is_correct": false, "explanation": "「课本」是学习用品，与「高年」不构成反义。"}], "correct_answer": "幼年", "explanations": {"幼年": "「幼年」指人生的早期，与「高年」指年纪大的时期正相反，构成反义。", "河流": "「河流」是地理事物，与「高年」没有反义关系。", "窗户": "「窗户」是建筑部件，与「高年」不构成反义。", "课本": "「课本」是学习用品，与「高年」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90292, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "童年", "is_correct": true, "explanation": "「童年」指人生的早期，与「高年」指年纪大的时期正相反，构成反义。"}, {"text": "树木", "is_correct": false, "explanation": "「树木」是植物，与「高年」没有反义关系。"}, {"text": "茶杯", "is_correct": false, "explanation": "「茶杯」是器物，与「高年」不构成反义。"}, {"text": "电话", "is_correct": false, "explanation": "「电话」是通讯工具，与「高年」不构成反义。"}], "correct_answer": "童年", "explanations": {"童年": "「童年」指人生的早期，与「高年」指年纪大的时期正相反，构成反义。", "树木": "「树木」是植物，与「高年」没有反义关系。", "茶杯": "「茶杯」是器物，与「高年」不构成反义。", "电话": "「电话」是通讯工具，与「高年」不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90292, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年纪大的时期；老年。", "primary_collocate": null, "pronunciation": "gāo nián", "ipa": "kɑʊ˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "人到高年，身体会慢慢变差。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷到了高年，每天都去公园走路。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进入高年以后，他很少出远门。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在高年时还喜欢读书写字。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母步入高年，子女应多陪伴他们。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望自己的高年过得健康快乐。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人到高年，记性常常不如以前。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的高年过得很平静。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了高年，他才有时间好好休息。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高年的时候，奶奶住在女儿家。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "年纪大的时期；老年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5333b86-458e-4e5c-b1e8-aa02e8ad479d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高年", "is_correct": true, "explanation": "高年：指年纪大的时期，与「人到……身体会慢慢变差」的语境相符。"}, {"text": "青年", "is_correct": false, "explanation": "语义：「青年」指年轻的时期，与「身体会慢慢变差」的衰老语境相反。"}, {"text": "童年", "is_correct": false, "explanation": "语义：「童年」指孩童时期，说人到童年身体变差与句意不合。"}, {"text": "年终", "is_correct": false, "explanation": "搭配：「年终」指一年的末尾，是时间点而非人生阶段，不能说「人到年终」。"}], "explanations": {"高年": "高年：指年纪大的时期，与「人到……身体会慢慢变差」的语境相符。", "青年": "语义：「青年」指年轻的时期，与「身体会慢慢变差」的衰老语境相反。", "童年": "语义：「童年」指孩童时期，说人到童年身体变差与句意不合。", "年终": "搭配：「年终」指一年的末尾，是时间点而非人生阶段，不能说「人到年终」。"}, "sentence_index": 0, "correct_answer": "高年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他读六年级，是学校里的高年学生。", "explanation": "这里应该用〈高年级〉。「高年」指人生的老年时期，不指学校的年级，所以「高年学生」不通。"}, {"text": "这台高年电脑运行得很快。", "explanation": "这里应该用〈旧〉。「高年」指人年纪大的时期，不能用来形容电脑。"}, {"text": "我妈妈每周都去高年大学学画画。", "explanation": "这里应该用〈老年〉。「老年大学」是固定说法，「高年」不能修饰「大学」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高年", "is_correct": true, "explanation": "高年：指年纪大的时期，与「人到……记性常常不如以前」的衰退语境相符。"}, {"text": "少年", "is_correct": false, "explanation": "语义：「少年」指年纪小的时期，与「记性不如以前」的衰退语境相矛盾。"}, {"text": "幼年", "is_correct": false, "explanation": "语义：「幼年」指孩童时期，与「记性常常不如以前」相矛盾。"}, {"text": "雨季", "is_correct": false, "explanation": "语义：「雨季」指一年中多雨的时段，不指人的年龄阶段，与「记性不如以前」不符。"}], "explanations": {"高年": "高年：指年纪大的时期，与「人到……记性常常不如以前」的衰退语境相符。", "少年": "语义：「少年」指年纪小的时期，与「记性不如以前」的衰退语境相矛盾。", "幼年": "语义：「幼年」指孩童时期，与「记性常常不如以前」相矛盾。", "雨季": "语义：「雨季」指一年中多雨的时段，不指人的年龄阶段，与「记性不如以前」不符。"}, "sentence_index": 6, "correct_answer": "高年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的高年很长。", "explanation": "这里应该用〈长度〉。「高年」指人年纪大的时期，不能用来说河流的长短。"}, {"text": "这个高年我们要参加期末考试。", "explanation": "这里应该用〈学期〉。「高年」指人生的老年时期，不指学校的时间单位。"}, {"text": "他十八岁时在高年读书。", "explanation": "这里应该用〈高中〉。「高年」指老年时期，与「十八岁」矛盾，也不指学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲这一只高年过得很充实。", "corrected_sentence": "父亲这一段高年过得很充实。", "error_description": "「高年」指一段时期，量词应用「段」，不能用「只」（「只」用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她这一场高年过得很幸福。", "corrected_sentence": "她这一段高年过得很幸福。", "error_description": "「高年」指一段时期，量词应用「段」，不能用「场」（「场」多用于比赛、雨等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
