INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90293, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "游戏场是小朋友玩耍的地方。", "primary_collocate": null, "pronunciation": "yóu xì chǎng", "ipa": "joʊ³⁵ ɕi⁵¹ ʈʂʰaŋ²¹⁴", "syllable_count": 3, "sentences": [{"text": "小区里有一个游戏场。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在游戏场里跑来跑去。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我带女儿去游戏场玩。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏场里有滑梯和秋千。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，小朋友都跑到游戏场去了。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏场对三岁的孩子很安全。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈坐在游戏场旁边看着孩子。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校后面新建了一个游戏场。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏场里的沙子又软又干净。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在游戏场上认识了新朋友。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个游戏场", "label": "量词"}, {"form": "儿童游戏场", "label": "复合词"}], "register": "中性", "sense_fingerprint": "供小朋友玩耍的户外场地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b588376-c1a7-4853-aa69-24c24846ed71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90293, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游戏场", "is_correct": true, "explanation": "正确：“游戏场”是供小朋友玩耍的场地，小区里有一个这样的场地很自然。"}, {"text": "水库", "is_correct": false, "explanation": "语义：水库是蓄水的大型水利工程，不会建在小区里。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：墓地不适合建在居民区，与小朋友玩耍的环境相冲突。"}, {"text": "宫殿", "is_correct": false, "explanation": "语义：宫殿是帝王居住的建筑，不会建在普通小区里。"}], "explanations": {"游戏场": "正确：“游戏场”是供小朋友玩耍的场地，小区里有一个这样的场地很自然。", "水库": "语义：水库是蓄水的大型水利工程，不会建在小区里。", "墓地": "语义：墓地不适合建在居民区，与小朋友玩耍的环境相冲突。", "宫殿": "语义：宫殿是帝王居住的建筑，不会建在普通小区里。"}, "sentence_index": 0, "correct_answer": "游戏场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "游戏场里养着很多大熊猫。", "explanation": "这里应该用〈动物园〉。游戏场是小朋友玩耍的小场地，不养大熊猫这类动物，应该用动物园。"}, {"text": "游戏场里陈列着很多古代文物。", "explanation": "这里应该用〈博物馆〉。游戏场是小朋友玩耍的地方，不陈列古代文物，应该用博物馆。"}, {"text": "我们去游戏场里游泳。", "explanation": "这里应该用〈游泳池〉。游戏场没有水池，不能在里面游泳，应该用游泳池。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90293, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游戏场", "is_correct": true, "explanation": "正确：“游戏场”是供小朋友玩耍的场地，妈妈坐在它旁边看孩子很自然。"}, {"text": "理想", "is_correct": false, "explanation": "语义：“理想”是抽象概念，不能作为可以坐在旁边的地点。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”是抽象概念，无法作为坐在旁边的地点。"}, {"text": "苍穹", "is_correct": false, "explanation": "语域：“苍穹”是文学用语，与描写育儿场景的日常语境不协调。"}], "explanations": {"游戏场": "正确：“游戏场”是供小朋友玩耍的场地，妈妈坐在它旁边看孩子很自然。", "理想": "语义：“理想”是抽象概念，不能作为可以坐在旁边的地点。", "时间": "语义：“时间”是抽象概念，无法作为坐在旁边的地点。", "苍穹": "语域：“苍穹”是文学用语，与描写育儿场景的日常语境不协调。"}, "sentence_index": 6, "correct_answer": "游戏场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游戏场里有很多过山车。", "explanation": "这里应该用〈游乐园〉。游戏场是小朋友玩耍的小场地，没有过山车这类大型设施，应该用游乐园。"}, {"text": "游戏场里有很多跑步机。", "explanation": "这里应该用〈健身房〉。游戏场不是健身的地方，没有跑步机，健身要去健身房。"}, {"text": "游戏场里养着很多鲨鱼。", "explanation": "这里应该用〈水族馆〉。游戏场是小朋友玩耍的地方，不养鲨鱼，应该用水族馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90293, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这附近新开了一只游戏场。", "corrected_sentence": "这附近新开了一个游戏场。", "error_description": "错误：量词“只”用错了。“只”用于小动物等，游戏场应用量词“个”，应说“一个游戏场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90293, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们游戏场里玩得很开心。", "corrected_sentence": "孩子们在游戏场里玩得很开心。", "error_description": "错误：漏掉了介词“在”。表示在某个地方做某事要说“在游戏场里”，应说“孩子们在游戏场里玩得很开心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
