INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90294, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人玩游戏、娱乐的场所。", "primary_collocate": null, "pronunciation": "yóu xì chǎng", "ipa": "joʊ³⁵ ɕi⁵¹ ʈʂʰaŋ²¹⁴", "syllable_count": 3, "sentences": [{"text": "商场三楼有一家游戏场。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放学后常去游戏场玩电子游戏。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家游戏场晚上十二点才关门。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏场里的机器声音很大。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用游戏币在游戏场玩了一下午。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏场里人太多，我们等了很久。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人喜欢在游戏场里比赛。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏场的价格不贵。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在游戏场赢了一个大玩具。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不让他整天待在游戏场。", "target_word": "游戏场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一家游戏场", "label": "量词"}, {"form": "一个游戏场", "label": "量词"}], "register": "中性", "sense_fingerprint": "放着游戏机、供人娱乐的室内场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b588376-c1a7-4853-aa69-24c24846ed71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游戏场", "is_correct": true, "explanation": "正确：“游戏场”是放着游戏机的娱乐场所，商场三楼开一家很自然。"}, {"text": "农场", "is_correct": false, "explanation": "语义：农场是种植、养殖的地方，不会开在商场三楼。"}, {"text": "湖泊", "is_correct": false, "explanation": "语义：湖泊是天然水域，不可能出现在商场三楼。"}, {"text": "殿堂", "is_correct": false, "explanation": "语义：殿堂指高大庄严的建筑，不是商场里开设的娱乐场所。"}], "explanations": {"游戏场": "正确：“游戏场”是放着游戏机的娱乐场所，商场三楼开一家很自然。", "农场": "语义：农场是种植、养殖的地方，不会开在商场三楼。", "湖泊": "语义：湖泊是天然水域，不可能出现在商场三楼。", "殿堂": "语义：殿堂指高大庄严的建筑，不是商场里开设的娱乐场所。"}, "sentence_index": 0, "correct_answer": "游戏场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "游戏场里可以给汽车加油。", "explanation": "这里应该用〈加油站〉。游戏场是供人玩游戏娱乐的场所，不能给汽车加油，应该用加油站。"}, {"text": "这个游戏场的感冒药很便宜。", "explanation": "这里应该用〈药店〉。游戏场是供人玩游戏娱乐的场所，不卖感冒药，买药要去药店。"}, {"text": "游戏场里有很多锅碗瓢盆。", "explanation": "这里应该用〈厨房〉。游戏场是供人玩游戏娱乐的场所，不放锅碗瓢盆，应该用厨房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游戏场", "is_correct": true, "explanation": "正确：“游戏场”是娱乐场所，年轻人在里面比赛很自然。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：墓地是埋葬死者的地方，不适合用来比赛。"}, {"text": "苍穹", "is_correct": false, "explanation": "语域：“苍穹”是文学用语，与描述年轻人活动的日常语境不协调。"}, {"text": "病房", "is_correct": false, "explanation": "语义：病房是病人休养的地方，不适合用来比赛。"}], "explanations": {"游戏场": "正确：“游戏场”是娱乐场所，年轻人在里面比赛很自然。", "墓地": "语义：墓地是埋葬死者的地方，不适合用来比赛。", "苍穹": "语域：“苍穹”是文学用语，与描述年轻人活动的日常语境不协调。", "病房": "语义：病房是病人休养的地方，不适合用来比赛。"}, "sentence_index": 6, "correct_answer": "游戏场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游戏场里正在上演一出话剧。", "explanation": "这里应该用〈剧院〉。游戏场没有舞台和观众席，不能上演话剧，应该用剧院。"}, {"text": "游戏场里养着很多奶牛。", "explanation": "这里应该用〈农场〉。游戏场不养奶牛，养奶牛要去农场。"}, {"text": "我们在游戏场里游泳。", "explanation": "这里应该用〈游泳池〉。游戏场没有水池，不能在里面游泳，应该用游泳池。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "商场三楼新开了一台游戏场。", "corrected_sentence": "商场三楼新开了一家游戏场。", "error_description": "错误：量词“台”用错了。“台”用于机器、设备，游戏场是经营性场所，应说“一家游戏场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他放学后游戏场里玩了两个小时。", "corrected_sentence": "他放学后在游戏场里玩了两个小时。", "error_description": "错误：漏掉了介词“在”。表示在某个地方做某事要说“在游戏场里”，应说“他放学后在游戏场里玩了两个小时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
