INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90296, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90296, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "自己感到舒适满意。", "primary_collocate": null, "pronunciation": "zì dé", "ipa": "tsɨ˥˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "老人坐在院子里喝茶，样子很自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人在家看书，过得十分自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫躺在阳光下，看上去很自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷退休后养花钓鱼，过得悠闲自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她靠在沙发上听音乐，神态自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的老人钓着鱼，自得地晒着太阳。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山里住着，每天安静又自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在草地上玩，一个个都很自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶躺在椅子上，自得地听着收音机。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末他在家泡茶看书，日子过得自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自得其乐", "label": "复合"}, {"form": "悠闲自得", "label": "复合"}], "register": "书面", "sense_fingerprint": "自得：悠闲舒适、自己感到惬意（多用于休闲安逸的场景）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '472a9012-31ef-4449-9907-721337a9f32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自得", "is_correct": true, "explanation": "“自得”形容悠闲舒适的样子，与“坐在院子里喝茶”的情境相符。"}, {"text": "紧张", "is_correct": false, "explanation": "语义：“坐在院子里喝茶”是悠闲场景，“紧张”与之矛盾。"}, {"text": "匆忙", "is_correct": false, "explanation": "语义：“坐着喝茶”是从容的状态，“匆忙”与之矛盾。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“样子”后不接描写声音的“清脆”，二者搭配不当。"}], "explanations": {"自得": "“自得”形容悠闲舒适的样子，与“坐在院子里喝茶”的情境相符。", "紧张": "语义：“坐在院子里喝茶”是悠闲场景，“紧张”与之矛盾。", "匆忙": "语义：“坐着喝茶”是从容的状态，“匆忙”与之矛盾。", "清脆": "搭配：“样子”后不接描写声音的“清脆”，二者搭配不当。"}, "sentence_index": 0, "correct_answer": "自得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在办公室里忙得很自得。", "explanation": "“自得”形容悠闲舒适的状态，不能形容忙碌；这里应该用〈紧张〉。"}, {"text": "他被蚊子咬了一夜，浑身很自得。", "explanation": "“自得”表示舒适满意，被蚊子咬了一夜后不可能感到舒适，这里应该用〈难受〉。"}, {"text": "得知自己被开除以后，他唉声叹气，过得很自得。", "explanation": "“自得”表示悠闲舒适，与“唉声叹气”的沮丧处境矛盾；这里应该用〈沮丧〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自得", "is_correct": true, "explanation": "“自得”表示安逸舒适，与“安静”并列，符合语境。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：前半句说“安静”，“吵闹”与之直接矛盾。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”与前面的“安静”意思相反，句意不通。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”描写空间，不能与“每天”的生活状态并列。"}], "explanations": {"自得": "“自得”表示安逸舒适，与“安静”并列，符合语境。", "吵闹": "语义：前半句说“安静”，“吵闹”与之直接矛盾。", "热闹": "语义：“热闹”与前面的“安静”意思相反，句意不通。", "狭窄": "搭配：“狭窄”描写空间，不能与“每天”的生活状态并列。"}, "sentence_index": 6, "correct_answer": "自得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在工地上搬砖，累得直不起腰，过得很自得。", "explanation": "“自得”表示悠闲舒适，搬砖劳累，与之矛盾；这里应该用〈辛苦〉。"}, {"text": "一只大狗扑过来，他吓得直往后退，还显得很自得。", "explanation": "“自得”表示舒适满意，被狗吓得直往后退的情境与之矛盾；这里应该用〈害怕〉。"}, {"text": "他迟到了一个小时，被老师批评后一直低着头，显得很自得。", "explanation": "“自得”表示舒适满意，被批评后一直低头，与之矛盾；这里应该用〈难堪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他自得的坐在门口晒太阳。", "corrected_sentence": "他自得地坐在门口晒太阳。", "error_description": "错误：“自得”作状语修饰动词时要用助词〈地〉，不能用〈的〉。应为“自得地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在山里住着，过的悠闲自得。", "corrected_sentence": "他在山里住着，过得悠闲自得。", "error_description": "错误：“过得”后的“得”是补语标记，不能写成“的”，应为〈过得悠闲自得〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
