INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90299, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "远人是住在很远地方的人。", "primary_collocate": null, "pronunciation": "yuǎn rén", "ipa": "ɥɛn˨˩˧ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "村里来了一位远人，大家都很热情。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位远人走了三天才到这里。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远人要来，我们要多做几个菜。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个住在山外的远人。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远人听说这里的茶好，都来买。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对远人，我们应该客气一点。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位远人带来了很多礼物。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，远人坐船来到这个城市。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里有远人来，爷爷很高兴。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个远人说的话，我们听不太懂。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "住在很远地方的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95593539-6a07-48d3-929c-5995fd291c1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90299, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远人", "is_correct": true, "explanation": "远人是名词，指住在很远地方的人，与“村里来了一位”和“大家都很热情”的语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会自己来到村子，也不会让大家“热情”相待。"}, {"text": "山峰", "is_correct": false, "explanation": "语义：山峰是固定的地貌，不会“来”到村子里。"}, {"text": "老虎", "is_correct": false, "explanation": "搭配：人的量词用“位”，不能说“一位老虎”，老虎来到村里也不会让大家热情接待。"}], "explanations": {"远人": "远人是名词，指住在很远地方的人，与“村里来了一位”和“大家都很热情”的语境相符。", "石头": "语义：石头不会自己来到村子，也不会让大家“热情”相待。", "山峰": "语义：山峰是固定的地貌，不会“来”到村子里。", "老虎": "搭配：人的量词用“位”，不能说“一位老虎”，老虎来到村里也不会让大家热情接待。"}, "sentence_index": 0, "correct_answer": "远人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位远人住在我家隔壁，每天都来借东西。", "explanation": "这里应该用〈邻居〉。远人指住在很远地方的人，不能用来指住在隔壁、经常来借东西的人。"}, {"text": "村里的远人一直住在山脚下，从没离开过。", "explanation": "这里应该用〈本地人〉。远人强调住得远，与“一直住在山脚下”的情况矛盾。"}, {"text": "那位远人是我的同桌，每天都和我一起上学。", "explanation": "这里应该用〈同学〉。远人指住在很远地方的人，每天一起上学的同桌住得近，不能说远人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90299, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远人", "is_correct": true, "explanation": "远人是名词，指住在远方的人，可以作“那位”的主语并带来礼物。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不会带来礼物。"}, {"text": "板凳", "is_correct": false, "explanation": "搭配：“位”只用于人，不能说“那位板凳”；板凳也不会带礼物。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有行动能力，不可能带来礼物。"}], "explanations": {"远人": "远人是名词，指住在远方的人，可以作“那位”的主语并带来礼物。", "冰箱": "语义：冰箱是家电，不会带来礼物。", "板凳": "搭配：“位”只用于人，不能说“那位板凳”；板凳也不会带礼物。", "窗户": "语义：窗户没有行动能力，不可能带来礼物。"}, "sentence_index": 6, "correct_answer": "远人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位远人和我在一个办公室上班，每天一起吃午饭。", "explanation": "这里应该用〈同事〉。远人指住在很远地方的人，每天一起吃午饭、在同一办公室上班的人住得近，不能说远人。"}, {"text": "这位远人就住在我家对门，常常来找我下棋。", "explanation": "这里应该用〈朋友〉。远人指住在很远地方的人，住在对门、常来下棋的人不能称远人。"}, {"text": "这位远人的家离我只有一条街，我们天天见面。", "explanation": "这里应该用〈街坊〉。远人指住在很远地方的人，住在一条街外、天天见面的人不能称远人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90299, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只远人昨天刚到，大家都去迎接他了。", "corrected_sentence": "那位远人昨天刚到，大家都去迎接他了。", "error_description": "量词错误：远人指人，量词应为“位”，不能用“只”。正确形式是“那位远人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90299, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们那边来了一位很远人，大家都很热情地接待他。", "corrected_sentence": "我们那边来了一位远人，大家都很热情地接待他。", "error_description": "程度副词错误：“远人”是名词，前面不能加程度副词“很”。应删去“很”，改为“一位远人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90300, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90300, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90300, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "远离家乡、不常在身边的亲人。", "primary_collocate": null, "pronunciation": "yuǎn rén", "ipa": "ɥɛn˨˩˧ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "过年了，他很想念远人。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远人不能回家，大家都很难过。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天给远人打电话。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中秋节，我们都会想起远人。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮很圆，他看着月亮想远人。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶总是把远人的照片放在桌上。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远人在外面工作，家里人很担心。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信是寄给远人的。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远人平安，我们就放心了。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给远人做了一件新衣服。", "target_word": "远人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "远离家乡的亲人，多用于思念、挂念的语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95593539-6a07-48d3-929c-5995fd291c1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90300, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远人", "is_correct": true, "explanation": "远人指远离家乡的亲人，是“想念”的对象，与过年的语境相符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是物件，过年时不会被“想念”，与亲情语境不合。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不是能被思念的对象，与过年的语境无关。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“想念”的宾语应是人或家乡，石头不能充当想念的对象。"}], "explanations": {"远人": "远人指远离家乡的亲人，是“想念”的对象，与过年的语境相符。", "雨伞": "语义：雨伞是物件，过年时不会被“想念”，与亲情语境不合。", "闹钟": "语义：闹钟不是能被思念的对象，与过年的语境无关。", "石头": "配价：“想念”的宾语应是人或家乡，石头不能充当想念的对象。"}, "sentence_index": 0, "correct_answer": "远人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈每天都在家里陪着远人。", "explanation": "这里应该用〈家人〉。远人指远离家乡的亲人，不能与“在家里陪着”同时成立。"}, {"text": "我的远人每天和我一起吃饭。", "explanation": "这里应该用〈室友〉。远人指远离家乡的亲人，不能指每天和我一起吃饭的人。"}, {"text": "隔壁的远人经常来借东西。", "explanation": "这里应该用〈邻居〉。远人指远离家乡的亲人，不能指经常来借东西的隔壁人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远人", "is_correct": true, "explanation": "远人指远离家乡的亲人，“在外面工作”与“家里人很担心”的语境相符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不会在外面工作，家里人也不会为太阳担心。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户无法工作，家里人也不会因此担心。"}, {"text": "手机", "is_correct": false, "explanation": "配价：“工作”的主语要求有行动能力的人，手机不能作主语。"}], "explanations": {"远人": "远人指远离家乡的亲人，“在外面工作”与“家里人很担心”的语境相符。", "太阳": "语义：太阳是天体，不会在外面工作，家里人也不会为太阳担心。", "窗户": "语义：窗户无法工作，家里人也不会因此担心。", "手机": "配价：“工作”的主语要求有行动能力的人，手机不能作主语。"}, "sentence_index": 6, "correct_answer": "远人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位远人每天准时开车来接我上班。", "explanation": "这里应该用〈司机〉。远人指远离家乡、不常在身边的亲人，每天开车来接我上班的人不是远人。"}, {"text": "我的远人每天都来我家下棋，我们很熟。", "explanation": "这里应该用〈朋友〉。远人指远离家乡、不常在身边的亲人，每天来家里下棋的人常在身边，不能说远人。"}, {"text": "这位远人在班上教我们数学，每天准时来上课。", "explanation": "这里应该用〈老师〉。远人指远离家乡、不常在身边的亲人，每天给我们上课的老师不是远人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每天都惦记着一只远人，晚上睡不着。", "corrected_sentence": "妈妈每天都惦记着远人，晚上睡不着。", "error_description": "量词错误：远人指人，不能用“只”。这里思念的是远方的亲人，直接说“惦记着远人”即可，应删去“一只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给很远人寄了一大包衣服。", "corrected_sentence": "妈妈给远人寄了一大包衣服。", "error_description": "程度副词错误：“远人”是名词，前面不能加程度副词“很”。应删去“很”，改为“给远人寄了一大包衣服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
