INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90301, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看到坏事，去告诉管事的人。", "primary_collocate": null, "pronunciation": "jǔ bào", "ipa": "tɕy˨˩˦ pau˥˩", "syllable_count": 2, "sentences": [{"text": "他看见同学作弊，就去举报了。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看到有人乱扔东西，想举报他。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王看见有人偷自行车，马上举报了。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看到坏人做坏事，应该去举报。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕坏人找他麻烦，不敢举报。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟看到同学抽烟，去向老师举报。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我举报了那个乱扔垃圾的人。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：“是谁去举报他的？”", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看见有人欺负小孩，立刻去举报。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举报朋友，不是为了钱。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "举报了", "label": "体标"}, {"form": "举报过", "label": "体标"}, {"form": "举报人", "label": "复合"}, {"form": "舉報", "label": "繁体"}], "register": "中性", "sense_fingerprint": "看到坏事后去告诉管事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3028915b-04fc-4478-8fb7-63277b2eed09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90301, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "举报", "is_correct": true, "explanation": "正确。“举报”表示看到同学作弊后去告诉管事的人，与句中的动作一致。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是悠闲地走，与“看见同学作弊”后的反应不相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”是娱乐活动，与看见同学作弊后的反应不相符。"}, {"text": "报名", "is_correct": false, "explanation": "语义：“报名”指登记参加某项活动，与发现作弊后的行为无关。"}], "explanations": {"举报": "正确。“举报”表示看到同学作弊后去告诉管事的人，与句中的动作一致。", "散步": "语义：“散步”是悠闲地走，与“看见同学作弊”后的反应不相符。", "唱歌": "语义：“唱歌”是娱乐活动，与看见同学作弊后的反应不相符。", "报名": "语义：“报名”指登记参加某项活动，与发现作弊后的行为无关。"}, "sentence_index": 0, "correct_answer": "举报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每周都去向老师举报学习情况。", "explanation": "这里应该用〈报告〉。学习情况是正常信息，应用报告；“举报”只用于告发违规的人或事。"}, {"text": "我把这个好消息举报给父母。", "explanation": "这里应该用〈告诉〉。传达好消息应用告诉；“举报”只用于告发违法违规的人或事。"}, {"text": "他看见朋友过生日，就去举报了他。", "explanation": "这里应该用〈祝贺〉。朋友过生日应去祝贺；“举报”的对象必须是违规的事，过生日不属于此类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90301, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "举报", "is_correct": true, "explanation": "正确。“我举报了那个乱扔垃圾的人”中，“举报”指告发违规的人。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞好的行为，与“乱扔垃圾”的语境相矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示对他人的帮助心存谢意，不适合用于乱扔垃圾的人。"}, {"text": "邀请", "is_correct": false, "explanation": "语义：“邀请”表示请人参加活动，与“乱扔垃圾”的行为不协调。"}], "explanations": {"举报": "正确。“我举报了那个乱扔垃圾的人”中，“举报”指告发违规的人。", "表扬": "语义：“表扬”是称赞好的行为，与“乱扔垃圾”的语境相矛盾。", "感谢": "语义：“感谢”表示对他人的帮助心存谢意，不适合用于乱扔垃圾的人。", "邀请": "语义：“邀请”表示请人参加活动，与“乱扔垃圾”的行为不协调。"}, "sentence_index": 6, "correct_answer": "举报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师因为他的努力，举报了他。", "explanation": "这里应该用〈表扬〉。努力应当受到表扬，“举报”只用于告发违规，不能用于此处。"}, {"text": "我把这盘菜举报给了厨师。", "explanation": "这里应该用〈反映〉。向厨师说明菜的问题应用“反映”；“举报”只用于告发违法违规的人或事。"}, {"text": "这个会议上，他举报了一个新计划。", "explanation": "这里应该用〈提出〉。会上提出新计划应用提出；“举报”的对象是违法违规的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90301, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她看到隔壁有人偷电瓶车，就去举报着。", "corrected_sentence": "她看到隔壁有人偷电瓶车，就去举报了。", "error_description": "错误：“举报着”。正确：“举报了”。表示动作已经完成，要用动态助词“了”；“着”表示动作的持续状态，不能用于“去举报”这种一次性动作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90301, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看到同学抄袭，就跑去老师举报了。", "corrected_sentence": "他看到同学抄袭，就跑去向老师举报了。", "error_description": "错误：“跑去老师”。正确：“跑去向老师”。去向某人举报时，要用介词“向”引出对象，“老师”前缺“向”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
