INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90302, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向有关部门或组织检举揭发。", "primary_collocate": null, "pronunciation": "jǔ bào", "ipa": "tɕy˨˩˦ pau˥˩", "syllable_count": 2, "sentences": [{"text": "他向警察举报了这家公司。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到有人偷东西，请打电话举报。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民可以向有关部门举报污染问题。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举报老板偷税，后来很多人支持他。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人向警察局举报了这家卖假药的店。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她举报了公司里的假账。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发现假货，你可以向有关部门举报。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为举报坏人，受到了保护。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居向环保部门举报了这家工厂。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人举报他开车时玩手机。", "target_word": "举报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "举报了", "label": "体标"}, {"form": "举报过", "label": "体标"}, {"form": "举报人", "label": "复合"}, {"form": "举报信", "label": "复合"}, {"form": "舉報", "label": "繁体"}], "register": "正式", "sense_fingerprint": "向有关部门或组织检举揭发违法违规的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3028915b-04fc-4478-8fb7-63277b2eed09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "举报", "is_correct": true, "explanation": "正确。“举报”指向有关部门检举揭发，与“向警察”搭配，宾语为违法的公司。"}, {"text": "拜访", "is_correct": false, "explanation": "搭配：“拜访”不能用“向警察”引出对象，“向警察拜访了这家公司”句意不通。"}, {"text": "选择", "is_correct": false, "explanation": "搭配：“选择”需要选取的对象，“向警察选择了这家公司”搭配不当。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”不能与“向警察”连用表示对公司的行为，句中介词与动词不搭。"}], "explanations": {"举报": "正确。“举报”指向有关部门检举揭发，与“向警察”搭配，宾语为违法的公司。", "拜访": "搭配：“拜访”不能用“向警察”引出对象，“向警察拜访了这家公司”句意不通。", "选择": "搭配：“选择”需要选取的对象，“向警察选择了这家公司”搭配不当。", "参观": "搭配：“参观”不能与“向警察”连用表示对公司的行为，句中介词与动词不搭。"}, "sentence_index": 0, "correct_answer": "举报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每周都向领导举报工作进展。", "explanation": "这里应该用〈报告〉。工作进展属于正常信息，应用报告；举报只用于揭发违法违规的行为。"}, {"text": "他在朋友面前举报了自己的秘密。", "explanation": "这里应该用〈透露〉。把自己的秘密告诉朋友是主动披露，应用透露；“举报”只指向有关部门揭发他人的违法违规行为。"}, {"text": "他举报了一个好消息。", "explanation": "这里应该用〈告诉〉。传达好消息应用告诉；“举报”的对象只能是违法违规的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "举报", "is_correct": true, "explanation": "正确。“举报”与“向有关部门”搭配，表示检举揭发假货行为。"}, {"text": "采购", "is_correct": false, "explanation": "语义：“采购”指购买物品，与“发现假货”的语境完全不符。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”的对象是人，“向有关部门感谢”后面还需要说明感谢的内容，句子不完整。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：“旅游”是出行游览，与发现假货后应采取的行动无关。"}], "explanations": {"举报": "正确。“举报”与“向有关部门”搭配，表示检举揭发假货行为。", "采购": "语义：“采购”指购买物品，与“发现假货”的语境完全不符。", "感谢": "配价：“感谢”的对象是人，“向有关部门感谢”后面还需要说明感谢的内容，句子不完整。", "旅游": "语义：“旅游”是出行游览，与发现假货后应采取的行动无关。"}, "sentence_index": 6, "correct_answer": "举报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我举报他，劝他开车时别玩手机。", "explanation": "这里应该用〈提醒〉。举报是向有关部门揭发违规，不能用于当面劝告；此处是劝他注意安全，应用提醒。"}, {"text": "这家饭店的菜很好吃，我举报给朋友。", "explanation": "这里应该用〈推荐〉。夸赞饭店的菜好吃、向朋友介绍应用推荐；“举报”只用于揭发违规。"}, {"text": "市政府向全市举报了这次事故的情况。", "explanation": "这里应该用〈通报〉。政府向公众公布事故情况应用通报；“举报”的对象只能是违法违规的行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把消防队举报了这家工厂的火灾隐患。", "corrected_sentence": "他向消防队举报了这家工厂的火灾隐患。", "error_description": "错误：“把消防队”。正确：“向消防队”。“举报”的对象要用介词“向”引出，“把”不能把接收举报的机构当作被处置的对象。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把市场监管局举报了这家店的假货。", "corrected_sentence": "她向市场监管局举报了这家店的假货。", "error_description": "错误：“把市场监管局”。正确：“向市场监管局”。举报的对象要用介词“向”引出，不能用“把”把机构当作被处置的对象。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
