INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90305, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "部长会是各部的部长聚在一起开的会。", "primary_collocate": null, "pronunciation": "bù zhǎng huì", "ipa": "pu˥˩ ʈʂɑŋ˨˩˦ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "下周三要开部长会。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各部的部长都来参加部长会。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次部长会在大楼三层举行。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的部长会开得很长。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在部长会上说了自己的想法。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的部长今天去开部长会了。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部长会的消息已经发给大家了。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次部长会，大家都很认真。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，这次部长会推迟了。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部长会上，大家谈到了新办法。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "各部的部长聚在一起开的会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4f307f-eef1-48f7-ab9e-281d3bff4d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90305, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部长会", "is_correct": true, "explanation": "部长会：各部的部长聚在一起开的会，“下周三要开”的对象符合句意。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“开”一般接会议、活动，“开数学”说不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，书面句中不合适，而且所指不明。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典不是能“开”的活动，句子读不通。"}], "explanations": {"部长会": "部长会：各部的部长聚在一起开的会，“下周三要开”的对象符合句意。", "数学": "语义：“开”一般接会议、活动，“开数学”说不通。", "玩意儿": "语域：“玩意儿”是口语，书面句中不合适，而且所指不明。", "字典": "语义：字典不是能“开”的活动，句子读不通。"}, "sentence_index": 0, "correct_answer": "部长会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周五学校开了部长会，请每位家长准时参加。", "explanation": "这里应该用〈家长会〉。部长会的参加者是各部门部长，面向家长的会议应说家长会。"}, {"text": "我们班昨天开了部长会，讨论了期末考试。", "explanation": "这里应该用〈班会〉。部长会只限各部门部长参加，班级的会议要用班会。"}, {"text": "市里请了专家开部长会，听取大家的意见。", "explanation": "这里应该用〈座谈会〉。部长会只由各部门部长参加，与专家交流、听取意见应说座谈会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90305, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部长会", "is_correct": true, "explanation": "部长会：各部门部长聚会的会议，“消息”与它相关，符合句意。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不会有需要发给大家的“消息”，句子读不通。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套不是能发出消息的对象，“手套的消息”句意不通。"}, {"text": "场子", "is_correct": false, "explanation": "语域：“场子”是口语，且指场地，书面句中不合适。"}], "explanations": {"部长会": "部长会：各部门部长聚会的会议，“消息”与它相关，符合句意。", "鱼": "语义：鱼不会有需要发给大家的“消息”，句子读不通。", "手套": "语义：手套不是能发出消息的对象，“手套的消息”句意不通。", "场子": "语域：“场子”是口语，且指场地，书面句中不合适。"}, "sentence_index": 6, "correct_answer": "部长会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们在部长会上讨论了新的校规。", "explanation": "这里应该用〈全校大会〉。部长会只由各部门部长参加，面向全体学生的会议应说全校大会。"}, {"text": "孩子们在部长会上玩游戏，很开心。", "explanation": "这里应该用〈联欢会〉。部长会是工作会议，玩游戏的活动应说联欢会。"}, {"text": "演员们在部长会上表演节目。", "explanation": "这里应该用〈晚会〉。部长会是工作会议，表演节目应说晚会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90305, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在一只部长会上提了一个问题。", "corrected_sentence": "她在一次部长会上提了一个问题。", "error_description": "错误：“部长会”是会议，量词应用“次”，不能用“只”。应说“在一次部长会上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90305, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上次的部长会开很晚。", "corrected_sentence": "上次的部长会开得很晚。", "error_description": "错误：缺少补语标记“得”。应说“开得很晚”，动词后面接程度补语要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
