INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90306, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由各部门部长参加的会议。", "primary_collocate": null, "pronunciation": "bù zhǎng huì", "ipa": "pu˥˩ ʈʂɑŋ˨˩˦ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "明天的部长会上午九点开始。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次部长会讨论了新的计划。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王部长要去参加部长会。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部长会开了三个小时。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的部长会上有很多人发言。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部长会结束后，大家一起吃饭。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题要在部长会上决定。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秘书正在准备明天的部长会材料。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种部长会每个月开一次。", "target_word": "部长会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她准备在部长会上做一个报告。", "target_word": "部长会", "complexity_tier": "T3", "furigana": "tā zhǔnbèi zài bù zhǎng huì shàng zuò yí gè bào gào", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "各部门部长参加的正式会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4f307f-eef1-48f7-ab9e-281d3bff4d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部长会", "is_correct": true, "explanation": "部长会：由各部门部长参加的会议，明天上午九点开始符合句意。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典不是能在某个时间开始的活动，句子读不通。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：“眼镜”不是会议或活动，不能“开始”，句子读不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，书面句中不合适，而且所指不明确。"}], "explanations": {"部长会": "部长会：由各部门部长参加的会议，明天上午九点开始符合句意。", "字典": "语义：字典不是能在某个时间开始的活动，句子读不通。", "眼镜": "语义：“眼镜”不是会议或活动，不能“开始”，句子读不通。", "玩意儿": "语域：“玩意儿”是口语，书面句中不合适，而且所指不明确。"}, "sentence_index": 0, "correct_answer": "部长会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们和几位专家开了一次部长会，讨论新技术。", "explanation": "这里应该用〈座谈会〉。部长会只由各部门部长参加，与专家交流应用座谈会。"}, {"text": "学校周五开了部长会，请家长来参加。", "explanation": "这里应该用〈家长会〉。部长会的参加者是各部门部长，面向家长的会议要用家长会。"}, {"text": "我们班今天开了部长会，讨论运动会的安排。", "explanation": "这里应该用〈班会〉。部长会只限各部门部长参加，班级的会议要用班会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部长会", "is_correct": true, "explanation": "部长会：各部门部长商议问题的会议，在会上决定问题符合句意。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是决定问题的场合，“在歌曲上决定”读不通。"}, {"text": "广播", "is_correct": false, "explanation": "语义：广播是传播信息的工具，不能在它上面决定问题。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：“家伙”是口语，书面句中不合适，而且指代不明。"}], "explanations": {"部长会": "部长会：各部门部长商议问题的会议，在会上决定问题符合句意。", "歌曲": "语义：歌曲不是决定问题的场合，“在歌曲上决定”读不通。", "广播": "语义：广播是传播信息的工具，不能在它上面决定问题。", "家伙": "语域：“家伙”是口语，书面句中不合适，而且指代不明。"}, "sentence_index": 6, "correct_answer": "部长会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她准备在部长会上唱一首歌。", "explanation": "这里应该用〈联欢会〉。部长会是工作会议，唱歌表演应说联欢会。"}, {"text": "她准备在部长会上参加一场比赛。", "explanation": "这里应该用〈运动会〉。部长会是工作会议，比赛应说运动会。"}, {"text": "她准备在部长会上结婚。", "explanation": "这里应该用〈婚礼〉。部长会是工作会议，结婚应在婚礼上进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在部长会上的发了言。", "corrected_sentence": "我在部长会上发了言。", "error_description": "错误：“上”之后多了“的”。“在部长会上”是状语，后面直接接动词“发了言”，不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的部长会开很顺利。", "corrected_sentence": "我们的部长会开得很顺利。", "error_description": "错误：缺少补语标记“得”。应说“开得很顺利”，动词后面接程度补语要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
