INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90307, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "先写下来、还没有定好的办法。", "primary_collocate": null, "pronunciation": "cǎo àn", "ipa": "tsʰɑʊ˨˩ an˥˩", "syllable_count": 2, "sentences": [{"text": "这只是草案，我们明天再改。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王先写了一份草案，请大家看看。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份草案还有很多地方要改。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让每个同学写一份活动草案。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理看完草案，说想法不错。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草案写好了，但还没有定下来。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把草案发给你了，你看一下。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份草案太简单，没有提到经费的问题。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先写了草案，再和同事商量。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班的春游草案已经写好了。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}], "register": "书面", "sense_fingerprint": "先写出来、尚未定下的办法或想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5695439c-db40-4c72-952c-6632c53558c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90307, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "草案", "is_correct": true, "explanation": "“草案”指先写下来、尚未定下的办法，这里说“只是……明天再改”，符合语境。"}, {"text": "定稿", "is_correct": false, "explanation": "语义：“定稿”指已经定下的最终稿，与“只是”和“明天再改”矛盾。"}, {"text": "定论", "is_correct": false, "explanation": "语义：“定论”指已经确定的结论，不能说“只是定论，明天再改”。"}, {"text": "实物", "is_correct": false, "explanation": "搭配：“改”的对象是方案、文字等，不说改“实物”。"}], "explanations": {"草案": "“草案”指先写下来、尚未定下的办法，这里说“只是……明天再改”，符合语境。", "定稿": "语义：“定稿”指已经定下的最终稿，与“只是”和“明天再改”矛盾。", "定论": "语义：“定论”指已经确定的结论，不能说“只是定论，明天再改”。", "实物": "搭配：“改”的对象是方案、文字等，不说改“实物”。"}, "sentence_index": 0, "correct_answer": "草案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把作文的草案撕掉了，重新写。", "explanation": "这里应该用〈草稿〉。“草案”指初步拟定、尚未定下的计划或规章文本，作文的初稿要用“草稿”。"}, {"text": "会议作出了草案，大家要执行。", "explanation": "这里应该用〈决议〉。“草案”尚待讨论修改，不能要求大家执行；已作出、要执行的决定用“决议”。"}, {"text": "这份草案已经正式颁布了，大家要遵守。", "explanation": "这里应该用〈规定〉。“草案”尚未定下、还要讨论修改，不能说已正式颁布；已颁布的条文要用“规定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90307, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "草案", "is_correct": true, "explanation": "“草案”是待人看的初步文本，可以发给别人看，符合语境。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不是文件，不能“发给你”让人“看一下”。"}, {"text": "冰淇淋", "is_correct": false, "explanation": "语义：冰淇淋是食物，不能“发给你”，也没法“看一下”。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不是文件，不能“发给你”让人“看一下”。"}], "explanations": {"草案": "“草案”是待人看的初步文本，可以发给别人看，符合语境。", "雨伞": "语义：雨伞不是文件，不能“发给你”让人“看一下”。", "冰淇淋": "语义：冰淇淋是食物，不能“发给你”，也没法“看一下”。", "饺子": "语义：饺子是食物，不是文件，不能“发给你”让人“看一下”。"}, "sentence_index": 6, "correct_answer": "草案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的春游草案已经定好了。", "explanation": "这里应该用〈方案〉。“草案”还没有定下来，“已经定好了”要用“方案”。"}, {"text": "我们班的春游草案已经开始实施了。", "explanation": "这里应该用〈安排〉。“草案”还没定下来，不能说已经开始实施；已定下并付诸实施的春游安排要用“安排”。"}, {"text": "我们班按春游草案出发了。", "explanation": "这里应该用〈计划〉。按计划出发要用已经定下来的计划；“草案”还没定下来，不能按它出发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90307, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他给我看了一只草案。", "corrected_sentence": "他给我看了一份草案。", "error_description": "量词错误：“草案”是书面文件，应说“一份草案”，不说“一只草案”（“只”用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90307, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把草案还要再改。", "corrected_sentence": "这份草案还要再改。", "error_description": "量词错误：“草案”用“份”计量，“把”用于有柄的器物，应说“这份草案”，不说“这把草案”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
