INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90308, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "初步拟定、尚待讨论修改的法规或计划。", "primary_collocate": null, "pronunciation": "cǎo àn", "ipa": "tsʰɑʊ˨˩ an˥˩", "syllable_count": 2, "sentences": [{"text": "这部法律草案要先让大家讨论。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里公布了城市规划草案，欢迎大家提意见。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表们正在讨论这份草案。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草案要经过会议讨论才能定下来。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家对环保草案提出了很多意见。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份草案明年才会正式通过。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校公布了新的校规草案。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草案里有一条，大家的意见不一样。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会今天开会，讨论税法草案。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们修改了草案中的几条规定。", "target_word": "草案", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}], "register": "书面", "sense_fingerprint": "尚待讨论修改的法规、规定或计划文本", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5695439c-db40-4c72-952c-6632c53558c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "草案", "is_correct": true, "explanation": "“草案”指尚待讨论修改的法规文本，这里说“这部法律草案要先讨论”，符合语境。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是法律文件，不能拿去讨论。"}, {"text": "游戏", "is_correct": false, "explanation": "搭配：“法律”后接“游戏”不通，游戏不是法律文件。"}, {"text": "配方", "is_correct": false, "explanation": "搭配：“法律”后不接“配方”，修饰关系不成立。"}], "explanations": {"草案": "“草案”指尚待讨论修改的法规文本，这里说“这部法律草案要先讨论”，符合语境。", "蛋糕": "语义：蛋糕不是法律文件，不能拿去讨论。", "游戏": "搭配：“法律”后接“游戏”不通，游戏不是法律文件。", "配方": "搭配：“法律”后不接“配方”，修饰关系不成立。"}, "sentence_index": 0, "correct_answer": "草案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的作文草案写好了，老师说可以修改。", "explanation": "这里应该用〈草稿〉。“草案”专指尚待审议的法规、计划文本，作文的初稿要用“草稿”。"}, {"text": "学校按新草案开学了。", "explanation": "这里应该用〈计划〉。按计划行事要用已经定下来的计划；“草案”尚未定下，不能据此开学。"}, {"text": "这份草案已经实施一年，效果很好。", "explanation": "这里应该用〈方案〉。已定下并实施的计划用“方案”；“草案”尚待讨论修改，不能说实施一年、效果很好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "草案", "is_correct": true, "explanation": "“草案”指公布供讨论修改的校规文本，符合“公布了新的校规”的语境。"}, {"text": "食谱", "is_correct": false, "explanation": "搭配：“校规”后接“食谱”不通，食谱不是规章。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“校规”后接“饼干”不通，饼干不是规章。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“校规”后不接“体重”，修饰关系不成立。"}], "explanations": {"草案": "“草案”指公布供讨论修改的校规文本，符合“公布了新的校规”的语境。", "食谱": "搭配：“校规”后接“食谱”不通，食谱不是规章。", "饼干": "搭配：“校规”后接“饼干”不通，饼干不是规章。", "体重": "搭配：“校规”后不接“体重”，修饰关系不成立。"}, "sentence_index": 6, "correct_answer": "草案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份草案明年就生效了。", "explanation": "这里应该用〈规定〉。草案还要讨论修改，不能说明年生效；生效的条文叫“规定”。"}, {"text": "学校的草案已经正式生效了。", "explanation": "这里应该用〈章程〉。草案尚待审议，不能说已正式生效；已通过、生效的规章叫“章程”。"}, {"text": "他们把作文的草案交给了老师。", "explanation": "这里应该用〈初稿〉。作文的第一稿叫“初稿”；“草案”专指尚待审议的法规、计划文本，不用于作文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只草案明天要交给委员会。", "corrected_sentence": "这份草案明天要交给委员会。", "error_description": "量词错误：“草案”用“份”计量，说“这份草案”，不说“这只草案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "委员会已经讨论了这只草案。", "corrected_sentence": "委员会已经讨论了这份草案。", "error_description": "量词错误：“草案”用“份”计量，“只”用于动物等，应说“这份草案”，不说“这只草案”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
