INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90309, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "见面时用来打招呼的问候语。", "primary_collocate": null, "pronunciation": "nǐ hǎo", "ipa": "ni˨˩ xɑʊ˨˩", "syllable_count": 2, "sentences": [{"text": "早上见到老师，我说：“老师，你好！”", "target_word": "你好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着对我说：“你好！”", "target_word": "你好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你好，我叫小王，很高兴认识你。", "target_word": "你好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我走进教室，对大家说了一声“你好”。", "target_word": "你好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "接电话时，她先说“你好”。", "target_word": "你好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外国朋友学会的第一句中文是“你好”。", "target_word": "你好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见面的时候，大家互相说“你好”。", "target_word": "你好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们看见我，一起喊：“叔叔你好！”", "target_word": "你好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对每一个人都说“你好”，很有礼貌。", "target_word": "你好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你好！请问去地铁站怎么走？", "target_word": "你好", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "您好", "label": "变体"}, {"form": "你们好", "label": "变体"}], "register": "口语", "sense_fingerprint": "见面时打招呼说的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5333b86-458e-4e5c-b1e8-aa02e8ad479d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90309, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "你好", "is_correct": true, "explanation": "“你好”是见面时的问候语，与“早上见到老师”的语境相符。"}, {"text": "再见", "is_correct": false, "explanation": "语义：“再见”用于告别，这里是刚见面，说“再见”不合语境。"}, {"text": "晚上好", "is_correct": false, "explanation": "语义：“晚上好”只用于晚上，句中的“早上见到”与之矛盾。"}, {"text": "喂", "is_correct": false, "explanation": "语域：“喂”多用于叫人或打电话，对老师这样说显得生硬、不礼貌。"}], "explanations": {"你好": "“你好”是见面时的问候语，与“早上见到老师”的语境相符。", "再见": "语义：“再见”用于告别，这里是刚见面，说“再见”不合语境。", "晚上好": "语义：“晚上好”只用于晚上，句中的“早上见到”与之矛盾。", "喂": "语域：“喂”多用于叫人或打电话，对老师这样说显得生硬、不礼貌。"}, "sentence_index": 0, "correct_answer": "你好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下课铃响了，我对老师说：“你好！”", "explanation": "这里应该用〈再见〉。下课离开时说再见，“你好”是见面时的问候。"}, {"text": "他帮我拿了行李，我对他说：“你好！”", "explanation": "这里应该用〈谢谢〉。对方帮了忙，应说谢谢，“你好”不能表示感谢。"}, {"text": "我踩到了她的脚，马上对她说：“你好！”", "explanation": "这里应该用〈对不起〉。踩到别人应道歉，“你好”不能代替对不起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90309, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "你好", "is_correct": true, "explanation": "“你好”是见面时互相问候的话，符合“见面的时候”的语境。"}, {"text": "哎呀", "is_correct": false, "explanation": "语义：“哎呀”表示惊讶或疼痛，不是见面时的问候语。"}, {"text": "晚安", "is_correct": false, "explanation": "语义：“晚安”是晚上睡前的道别语，在见面时说不通。"}, {"text": "拜拜", "is_correct": false, "explanation": "语域：“拜拜”是随意的口语告别词，不适合用作见面时的问候。"}], "explanations": {"你好": "“你好”是见面时互相问候的话，符合“见面的时候”的语境。", "哎呀": "语义：“哎呀”表示惊讶或疼痛，不是见面时的问候语。", "晚安": "语义：“晚安”是晚上睡前的道别语，在见面时说不通。", "拜拜": "语域：“拜拜”是随意的口语告别词，不适合用作见面时的问候。"}, "sentence_index": 6, "correct_answer": "你好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我睡觉前对妈妈说：“你好。”", "explanation": "这里应该用〈晚安〉。睡前道别用“晚安”，“你好”只用于见面问候。"}, {"text": "朋友拿到了奖学金，我对他说：“你好！”", "explanation": "这里应该用〈恭喜〉。祝贺别人时说“恭喜”，“你好”不能表示祝贺。"}, {"text": "加班的同事终于下班了，我对他说：“你好！”", "explanation": "这里应该用〈辛苦了〉。对方辛苦工作后应说“辛苦了”，“你好”不能表示慰劳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90309, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "王老师，你们好！我是小李。", "corrected_sentence": "王老师，你好！我是小李。", "error_description": "“你们好”是对多人的问候，这里只有一位老师，应去掉“们”，说“你好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90309, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师，早上你好！今天很冷，请多穿点衣服。", "corrected_sentence": "老师，你好！今天很冷，请多穿点衣服。", "error_description": "“早上你好”不能说，这里是普通的见面问候，应去掉“早上”，直接说“你好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b730ebde-8c18-45b6-9673-c13f8591ceb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90311, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
