INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90311, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依是顺着别人的意思去做，答应别人的要求。", "primary_collocate": null, "pronunciation": "yī", "ipa": "i˥", "syllable_count": 1, "sentences": [{"text": "这件事就依你吧。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好，我都依你。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈什么都依着孩子。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子想去公园，妈妈就依了他。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸很爱女儿，什么事都依她。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是依着朋友，从不生气。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师依了学生的要求，改了考试时间。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别总想让大家都依你。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟哭了，奶奶只好依他。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不想去，我就依你，不去了。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "依了", "label": "完成体"}, {"form": "依着", "label": "持续体"}], "register": "口语", "sense_fingerprint": "顺着别人的意思去做，依你", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2d745d-2bca-4b89-8b23-ae7e91d17958') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90311, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "依", "is_correct": true, "explanation": "正确：依，yī，第一声，表示顺着别人的意思去做。"}, {"text": "椅", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，意思是椅子。"}, {"text": "姨", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，意思是阿姨。"}, {"text": "易", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是容易。"}], "explanations": {"依": "正确：依，yī，第一声，表示顺着别人的意思去做。", "椅": "yǐ（第三声）与 yī（第一声）声调不同，意思是椅子。", "姨": "yí（第二声）与 yī（第一声）声调不同，意思是阿姨。", "易": "yì（第四声）与 yī（第一声）声调不同，意思是容易。"}, "sentence_index": null, "correct_answer": "依"}, "level_3": {"options": [{"text": "反对", "is_correct": false, "explanation": "语义：“反对”与句中“就……你吧”的顺从语气相矛盾。"}, {"text": "依", "is_correct": true, "explanation": "正确：“依”表示顺着别人的意思，符合“这件事就依你吧”的语气。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“就……吧”的让步语气相反。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打你吧”表示动手打人，与“这件事就……”的顺从语境不符。"}], "explanations": {"反对": "语义：“反对”与句中“就……你吧”的顺从语气相矛盾。", "依": "正确：“依”表示顺着别人的意思，符合“这件事就依你吧”的语气。", "拒绝": "语义：“拒绝”与“就……吧”的让步语气相反。", "打": "搭配：“打你吧”表示动手打人，与“这件事就……”的顺从语境不符。"}, "sentence_index": 0, "correct_answer": "依"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他依了我一拳，我疼得说不出话。", "explanation": "这里应该用〈打〉。依表示靠着或顺从别人，不能用来表示动手，打人一拳要用〈打〉。"}, {"text": "我依了那道题，算了半天也没算出来。", "explanation": "这里应该用〈做〉。依表示靠着或顺从，不能表示做题，做题要用〈做〉。"}, {"text": "他依了一下午的电视，眼睛都累了。", "explanation": "这里应该用〈看〉。依表示靠着或顺从，不能表示看电视，看电视要用〈看〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90311, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "依", "is_correct": true, "explanation": "正确：依，yī，第一声，表示顺着别人的意思去做。"}, {"text": "已", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，意思是已经。"}, {"text": "亿", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是亿。"}, {"text": "意", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是意思。"}, {"text": "忆", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是回忆。"}], "explanations": {"依": "正确：依，yī，第一声，表示顺着别人的意思去做。", "已": "yǐ（第三声）与 yī（第一声）声调不同，意思是已经。", "亿": "yì（第四声）与 yī（第一声）声调不同，意思是亿。", "意": "yì（第四声）与 yī（第一声）声调不同，意思是意思。", "忆": "yì（第四声）与 yī（第一声）声调不同，意思是回忆。"}, "sentence_index": null, "correct_answer": "依"}, "level_3": {"options": [{"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与后半句“改了考试时间”相矛盾，且与“依”的顺从意思相反。"}, {"text": "依", "is_correct": true, "explanation": "正确：“依了学生的要求”表示顺从学生的请求，与后文“改了考试时间”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“要求”作宾语。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”是用脚击打，不能与“要求”搭配。"}], "explanations": {"拒绝": "语义：“拒绝”与后半句“改了考试时间”相矛盾，且与“依”的顺从意思相反。", "依": "正确：“依了学生的要求”表示顺从学生的请求，与后文“改了考试时间”相符。", "吃": "搭配：“吃”不能带“要求”作宾语。", "踢": "搭配：“踢”是用脚击打，不能与“要求”搭配。"}, "sentence_index": 6, "correct_answer": "依"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他依了一大碗汤，很快就饱了。", "explanation": "这里应该用〈喝〉。依表示靠着或顺从，不能表示喝东西，喝汤要用〈喝〉。"}, {"text": "孩子依了两个苹果，就去睡觉了。", "explanation": "这里应该用〈吃〉。依表示靠着或顺从，不能表示吃东西，吃苹果要用〈吃〉。"}, {"text": "他依了钥匙打开了门。", "explanation": "这里应该用〈用〉。依表示靠着或顺从，不能表示使用工具，使用钥匙要用〈用〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90311, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子想买玩具，妈妈就依着了他。", "corrected_sentence": "孩子想买玩具，妈妈就依了他。", "error_description": "错误：“依”后面“着”和“了”不能连用。这里表示妈妈答应了孩子，用完成体“了”，应说“妈妈就依了他”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90311, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你不依了我，我就不去了。", "corrected_sentence": "你不依我，我就不去了。", "error_description": "错误：否定句中“依”后多了“了”。“不”表示未发生，不能与“了”同用，应说“你不依我”，不能说“你不依了我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
