INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90312, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "依是按照某个规定、说法或情况来做或判断。", "primary_collocate": null, "pronunciation": "yī", "ipa": "i˥", "syllable_count": 1, "sentences": [{"text": "依学校的规定，学生不能带手机。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司依合同给我们付钱。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家依顺序上车。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "依我看，这个办法不太好。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他依着地图找到了那家店。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们依年纪站成两排。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "依老师说的，明天考试。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "依天气来看，下午会下雨。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们依图纸盖了一座小房子。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "依现在的情况，我们先别走。", "target_word": "依", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "依着", "label": "持续体"}], "register": "书面", "sense_fingerprint": "按照某个规定、说法或情况来做或判断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2d745d-2bca-4b89-8b23-ae7e91d17958') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90312, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "依", "is_correct": true, "explanation": "正确：依，yī，第一声，表示按照某种规定、说法或情况。"}, {"text": "椅", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，意思是椅子。"}, {"text": "亿", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是亿。"}, {"text": "姨", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，意思是阿姨。"}], "explanations": {"依": "正确：依，yī，第一声，表示按照某种规定、说法或情况。", "椅": "yǐ（第三声）与 yī（第一声）声调不同，意思是椅子。", "亿": "yì（第四声）与 yī（第一声）声调不同，意思是亿。", "姨": "yí（第二声）与 yī（第一声）声调不同，意思是阿姨。"}, "sentence_index": null, "correct_answer": "依"}, "level_3": {"options": [{"text": "向", "is_correct": false, "explanation": "搭配：“向”引出对象或方向，不能引出依据，“向学校的规定”不成立。"}, {"text": "依", "is_correct": true, "explanation": "正确：“依”是介词，表示按照某种规定，符合“依学校的规定，学生不能带手机”的句意。"}, {"text": "沿", "is_correct": false, "explanation": "搭配：“沿”表示沿着路线，不能说“沿学校的规定”。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替某人做事，“规定”不能代替“学生”行事。"}], "explanations": {"向": "搭配：“向”引出对象或方向，不能引出依据，“向学校的规定”不成立。", "依": "正确：“依”是介词，表示按照某种规定，符合“依学校的规定，学生不能带手机”的句意。", "沿": "搭配：“沿”表示沿着路线，不能说“沿学校的规定”。", "替": "语义：“替”表示代替某人做事，“规定”不能代替“学生”行事。"}, "sentence_index": 0, "correct_answer": "依"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他依了那个球一脚，球飞进了门。", "explanation": "这里应该用〈踢〉。依表示靠着、按照或顺从，不能表示踢，踢球要用〈踢〉。"}, {"text": "他依了一幅画在墙上。", "explanation": "这里应该用〈挂〉。依表示靠着、按照或顺从，不能表示把东西挂起来，挂画要用〈挂〉。"}, {"text": "小狗依了一大碗饭，很快就舔干净了。", "explanation": "这里应该用〈吃〉。依表示靠着、按照或顺从，不能表示吃饭，吃饭要用〈吃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90312, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "依", "is_correct": true, "explanation": "正确：依，yī，第一声，表示按照某种规定、说法或情况。"}, {"text": "已", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，意思是已经。"}, {"text": "意", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是意思。"}, {"text": "忆", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是回忆。"}, {"text": "易", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是容易。"}], "explanations": {"依": "正确：依，yī，第一声，表示按照某种规定、说法或情况。", "已": "yǐ（第三声）与 yī（第一声）声调不同，意思是已经。", "意": "yì（第四声）与 yī（第一声）声调不同，意思是意思。", "忆": "yì（第四声）与 yī（第一声）声调不同，意思是回忆。", "易": "yì（第四声）与 yī（第一声）声调不同，意思是容易。"}, "sentence_index": null, "correct_answer": "依"}, "level_3": {"options": [{"text": "朝", "is_correct": false, "explanation": "搭配：“朝”引出方向，不能说“朝老师说的”。"}, {"text": "依", "is_correct": true, "explanation": "正确：“依”是介词，表示按照老师的说法，符合“依老师说的，明天考试”的句意。"}, {"text": "比", "is_correct": false, "explanation": "配价：“比”需要比较的两方，“比老师说的”不成句。"}, {"text": "向", "is_correct": false, "explanation": "搭配：“向”引出对象或方向，“向老师说的”不通。"}], "explanations": {"朝": "搭配：“朝”引出方向，不能说“朝老师说的”。", "依": "正确：“依”是介词，表示按照老师的说法，符合“依老师说的，明天考试”的句意。", "比": "配价：“比”需要比较的两方，“比老师说的”不成句。", "向": "搭配：“向”引出对象或方向，“向老师说的”不通。"}, "sentence_index": 6, "correct_answer": "依"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他依了一封信，寄给了朋友。", "explanation": "这里应该用〈写〉。依表示靠着、按照或顺从，不能表示写信，写信要用〈写〉。"}, {"text": "我依了一首歌，心情好了很多。", "explanation": "这里应该用〈听〉。依表示靠着、按照或顺从，不能表示听歌，听歌要用〈听〉。"}, {"text": "他依了一杯水，然后继续工作。", "explanation": "这里应该用〈喝〉。依表示靠着、按照或顺从，不能表示喝水，喝水要用〈喝〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "按依公司的制度，员工不能迟到。", "corrected_sentence": "依公司的制度，员工不能迟到。", "error_description": "错误：“按”和“依”都表示“按照”，重复使用。只用“依”即可，应说“依公司的制度，员工不能迟到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "依了说明书，他很快装好了椅子。", "corrected_sentence": "依着说明书，他很快装好了椅子。", "error_description": "错误：介词“依”后不能带“了”，“依了说明书”不成立。应说“依着说明书，他很快装好了椅子”（“依说明书”同样成立），不能说“依了说明书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
