INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90313, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "金色是像金子一样亮亮的黄颜色。", "primary_collocate": null, "pronunciation": "jīn sè", "ipa": "tɕin˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "金色的沙子在海边闪闪发光。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用金色的笔写了名字。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夕阳下，河水变成了金色。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩戴着金色的帽子。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门上有一个金色的大字。", "target_word": "金色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树叶到了秋天会变成金色。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的封面是金色的。", "target_word": "金色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买一块金色的手表。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金色的麦田一眼看不到头。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光是金色的，房间很温暖。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "金黄色", "label": "复合"}], "register": "中性", "sense_fingerprint": "像金子一样发亮的黄色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b205cd2-e5b8-488e-969b-5b81b72010f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90313, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "金色", "is_correct": true, "explanation": "正确。“金色的沙子在海边闪闪发光”：沙子呈金黄色，并在阳光下发亮，符合语境。"}, {"text": "木头", "is_correct": false, "explanation": "语义：沙子不是木头，“木头的沙子”句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“的”后修饰沙子的应是颜色或质地，“声音”不能修饰沙子。"}, {"text": "雨", "is_correct": false, "explanation": "语义：“雨的沙子”不成立，雨不是沙子的属性。"}], "explanations": {"金色": "正确。“金色的沙子在海边闪闪发光”：沙子呈金黄色，并在阳光下发亮，符合语境。", "木头": "语义：沙子不是木头，“木头的沙子”句意不通。", "声音": "搭配：“的”后修饰沙子的应是颜色或质地，“声音”不能修饰沙子。", "雨": "语义：“雨的沙子”不成立，雨不是沙子的属性。"}, "sentence_index": 0, "correct_answer": "金色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向银行存了一份金色。", "explanation": "这里应该存“金子”。“存”的对象是钱或物品，“金色”是颜色，不能存。"}, {"text": "这顶帽子是金色做的，很漂亮。", "explanation": "这里应该用“金子”。“是……做的”要接材料名词，“金色”是颜色，不能作材料。"}, {"text": "她把金色戴在头上，很好看。", "explanation": "这里应该说“金色的发夹”等东西。“金色”是颜色，不是物品，不能“戴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b707e52-d132-4454-90c2-19cc87727299') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90313, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金色", "is_correct": true, "explanation": "正确。“这本书的封面是金色的”：封面的颜色是金色，符合语境。"}, {"text": "夜晚", "is_correct": false, "explanation": "搭配：“是……的”要接颜色或质地，“夜晚”是时间，不能作封面的属性。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：封面不是声音，“封面是歌声的”句意不通。"}, {"text": "雷", "is_correct": false, "explanation": "语义：封面不可能是雷，“封面是雷的”句意不通。"}], "explanations": {"金色": "正确。“这本书的封面是金色的”：封面的颜色是金色，符合语境。", "夜晚": "搭配：“是……的”要接颜色或质地，“夜晚”是时间，不能作封面的属性。", "歌声": "语义：封面不是声音，“封面是歌声的”句意不通。", "雷": "语义：封面不可能是雷，“封面是雷的”句意不通。"}, "sentence_index": 6, "correct_answer": "金色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯有一个金色，房间很温暖。", "explanation": "这里的量词应用“种”。“一个金色”的量词用错，颜色名词应说“一种金色”。"}, {"text": "他喝了一杯金色，觉得很甜。", "explanation": "这里应该说“金色的饮料”。“金色”是颜色，不能被喝。"}, {"text": "灯光是金色做的，房间很温暖。", "explanation": "这里应该用“金子”。“是……做的”要接材料名词，“金色”是颜色，不能作材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b707e52-d132-4454-90c2-19cc87727299') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90313, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小女孩的帽子金色的。", "corrected_sentence": "小女孩的帽子是金色的。", "error_description": "错误：缺少“是”。说明颜色要用“是……的”结构，应说“帽子是金色的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b707e52-d132-4454-90c2-19cc87727299') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90313, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块玻璃的金色的很亮。", "corrected_sentence": "这块玻璃的金色很亮。", "error_description": "错误：“金色”后多加了一个“的”。“玻璃的金色”是名词短语，后面直接接谓语“很亮”，不应再加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b707e52-d132-4454-90c2-19cc87727299') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90315, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升", "is_correct": true, "explanation": "升：向上移动，与“落”（从高处往下掉）方向相反，构成反义。"}, {"text": "站", "is_correct": false, "explanation": "站：站立，与“落”不构成反义关系。"}, {"text": "藏", "is_correct": false, "explanation": "藏：隐藏，与“落”不构成反义关系。"}, {"text": "转", "is_correct": false, "explanation": "转：转动，与“落”不构成反义关系。"}], "correct_answer": "升", "explanations": {"升": "升：向上移动，与“落”（从高处往下掉）方向相反，构成反义。", "站": "站：站立，与“落”不构成反义关系。", "藏": "藏：隐藏，与“落”不构成反义关系。", "转": "转：转动，与“落”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90315, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升", "is_correct": true, "explanation": "升：向上移动，与“落”（从高处往下掉）方向相反，构成反义。"}, {"text": "跑", "is_correct": false, "explanation": "跑：快速移动，与“落”不构成反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱：发出乐音，与“落”不构成反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑：面部表情或发声，与“落”不构成反义关系。"}], "correct_answer": "升", "explanations": {"升": "升：向上移动，与“落”（从高处往下掉）方向相反，构成反义。", "跑": "跑：快速移动，与“落”不构成反义关系。", "唱": "唱：发出乐音，与“落”不构成反义关系。", "笑": "笑：面部表情或发声，与“落”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90315, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从高的地方往下掉。", "primary_collocate": null, "pronunciation": "luò", "ipa": "lu̯ɔ˥˩", "syllable_count": 1, "sentences": [{"text": "秋天到了，树叶一片片落下来。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨点落在窗户上。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一片雪花落在我的手上。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书从桌子上落到了地上。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花瓣落了一地。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的帽子落进了河里。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼泪从她的脸上落下来。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "果子熟了，自己落到了地上。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪落在山上，山变白了。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，树上的花就落了。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "落了", "label": "体标"}, {"form": "落过", "label": "体标"}, {"form": "落日", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西从高处往下掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad8dbc6-820a-4e36-a32d-a214082bc3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90315, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "落", "is_correct": true, "explanation": "落（luò，第四声）：从高处往下掉，是本义。"}, {"text": "罗", "is_correct": false, "explanation": "罗（luó，第二声）与落（luò，第四声）声调不同，意思是罗网、罗马，不是往下掉。"}, {"text": "路", "is_correct": false, "explanation": "路（lù）与落（luò）只差韵母 o，意思是道路，不是往下掉。"}, {"text": "诺", "is_correct": false, "explanation": "诺（nuò）与落（luò）声母不同（n 与 l），意思是承诺。"}, {"text": "做", "is_correct": false, "explanation": "做（zuò）与落（luò）声母不同（z 与 l），意思是做、制作。"}, {"text": "裸", "is_correct": false, "explanation": "裸（luǒ，第三声）与落（luò，第四声）声调不同，意思是赤裸、裸露。"}], "explanations": {"落": "落（luò，第四声）：从高处往下掉，是本义。", "罗": "罗（luó，第二声）与落（luò，第四声）声调不同，意思是罗网、罗马，不是往下掉。", "路": "路（lù）与落（luò）只差韵母 o，意思是道路，不是往下掉。", "诺": "诺（nuò）与落（luò）声母不同（n 与 l），意思是承诺。", "做": "做（zuò）与落（luò）声母不同（z 与 l），意思是做、制作。", "裸": "裸（luǒ，第三声）与落（luò，第四声）声调不同，意思是赤裸、裸露。"}, "sentence_index": null, "correct_answer": "落"}, "level_3": {"options": [{"text": "升", "is_correct": false, "explanation": "语义：“升”指向上，与“下来”的向下方向相反。"}, {"text": "落", "is_correct": true, "explanation": "落：从高处往下掉，与“下来”搭配，符合树叶飘落的语境。"}, {"text": "站", "is_correct": false, "explanation": "搭配：“站”要求有生命的主体，树叶不能站。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要送的人和被送的东西，句中“树叶”无法充当送的对象。"}], "explanations": {"升": "语义：“升”指向上，与“下来”的向下方向相反。", "落": "落：从高处往下掉，与“下来”搭配，符合树叶飘落的语境。", "站": "搭配：“站”要求有生命的主体，树叶不能站。", "送": "配价：“送”需要送的人和被送的东西，句中“树叶”无法充当送的对象。"}, "sentence_index": 0, "correct_answer": "落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "风筝落到了天上，孩子们在下面拍手。", "explanation": "这里应该用〈飞〉。落表示从高处往下掉，风筝是向上飞，方向相反，不能说“落到天上”。"}, {"text": "电梯从一楼落到了十楼，他很快就到了。", "explanation": "这里应该用〈升〉。落表示从高处往下掉，电梯是向上运行，方向相反。"}, {"text": "火箭落到了高空，越来越小。", "explanation": "这里应该用〈冲〉。落表示往下掉，火箭是向上冲，方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90315, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "落", "is_correct": true, "explanation": "落（luò，第四声）：从高处往下掉，是本义。"}, {"text": "螺", "is_correct": false, "explanation": "螺（luó，第二声）与落（luò，第四声）声调不同，意思是螺类、螺丝。"}, {"text": "鹿", "is_correct": false, "explanation": "鹿（lù）与落（luò）只差韵母 o，意思是鹿。"}, {"text": "糯", "is_correct": false, "explanation": "糯（nuò）与落（luò）声母不同（n 与 l），意思是糯米。"}, {"text": "座", "is_correct": false, "explanation": "座（zuò）与落（luò）声母不同（z 与 l），意思是座位。"}], "explanations": {"落": "落（luò，第四声）：从高处往下掉，是本义。", "螺": "螺（luó，第二声）与落（luò，第四声）声调不同，意思是螺类、螺丝。", "鹿": "鹿（lù）与落（luò）只差韵母 o，意思是鹿。", "糯": "糯（nuò）与落（luò）声母不同（n 与 l），意思是糯米。", "座": "座（zuò）与落（luò）声母不同（z 与 l），意思是座位。"}, "sentence_index": null, "correct_answer": "落"}, "level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语义：“扔”指抛掷，眼泪不能被扔下来。"}, {"text": "跪", "is_correct": false, "explanation": "搭配：“跪”是人的身体动作，眼泪不能跪下来。"}, {"text": "落", "is_correct": true, "explanation": "落：从高处往下掉，与“下来”搭配，符合眼泪滑落的语境。"}, {"text": "读", "is_correct": false, "explanation": "语义：“读”指看着文字念，眼泪不能读，与“下来”也不搭配。"}], "explanations": {"扔": "语义：“扔”指抛掷，眼泪不能被扔下来。", "跪": "搭配：“跪”是人的身体动作，眼泪不能跪下来。", "落": "落：从高处往下掉，与“下来”搭配，符合眼泪滑落的语境。", "读": "语义：“读”指看着文字念，眼泪不能读，与“下来”也不搭配。"}, "sentence_index": 6, "correct_answer": "落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵小树落到了屋顶那么高。", "explanation": "这里应该用〈长〉。落表示从高处往下掉，小树是向上生长，不能用“落”表示长高。"}, {"text": "登山队落到了雪线以上。", "explanation": "这里应该用〈攀〉。落表示往下掉，登山队是向上攀登，方向相反。"}, {"text": "蜗牛慢慢落上了墙。", "explanation": "这里应该用〈爬〉。落表示往下掉，蜗牛是向上爬，方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90315, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋天到了，雨点一滴滴落上来，地上湿了。", "corrected_sentence": "秋天到了，雨点一滴滴落下来，地上湿了。", "error_description": "“落”表示从高处往下掉，应与趋向补语“下来”搭配；写成“上来”方向错了，应为“落下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90315, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪花轻轻落了在我的肩膀上。", "corrected_sentence": "雪花轻轻落在了我的肩膀上。", "error_description": "动态助词“了”应放在“落在”之后表示完成；写成“落了在”是错误，应为“落在了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90316, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升", "is_correct": true, "explanation": "升：上升，与“落”（太阳、潮水等向下降）相对，如“日升日落”。"}, {"text": "跳", "is_correct": false, "explanation": "跳：跃起，与“落”不构成反义关系。"}, {"text": "说", "is_correct": false, "explanation": "说：讲话，与“落”不构成反义关系。"}, {"text": "走", "is_correct": false, "explanation": "走：移动，与“落”不构成反义关系。"}], "correct_answer": "升", "explanations": {"升": "升：上升，与“落”（太阳、潮水等向下降）相对，如“日升日落”。", "跳": "跳：跃起，与“落”不构成反义关系。", "说": "说：讲话，与“落”不构成反义关系。", "走": "走：移动，与“落”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
