INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90316, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "下降；掉下。", "primary_collocate": null, "pronunciation": "luò", "ipa": "lu̯ɔ˥˩", "syllable_count": 1, "sentences": [{"text": "天快黑了，太阳已经落下去了。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "傍晚，太阳慢慢落下去了。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮落了，天快亮了。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的雨停了，河水落了很多。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "潮水涨了又落，天天如此。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的潮水落了，沙滩上有很多小贝壳。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳落得很快，天一下子黑了。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幕布落下来，演出结束了。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水慢慢落下去了。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着太阳落下去，心里很平静。", "target_word": "落", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "落了", "label": "体标"}, {"form": "落过", "label": "体标"}, {"form": "落日", "label": "复合"}], "register": "中性", "sense_fingerprint": "太阳、潮水、幕布等向下降", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad8dbc6-820a-4e36-a32d-a214082bc3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90316, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "落", "is_correct": true, "explanation": "落（luò，第四声）：太阳、潮水等向下降，是本义。"}, {"text": "锣", "is_correct": false, "explanation": "锣（luó，第二声）与落（luò，第四声）声调不同，意思是打击乐器锣。"}, {"text": "陆", "is_correct": false, "explanation": "陆（lù）与落（luò）只差韵母 o，意思是陆地。"}, {"text": "诺", "is_correct": false, "explanation": "诺（nuò）与落（luò）声母不同（n 与 l），意思是承诺。"}, {"text": "作", "is_correct": false, "explanation": "作（zuò）与落（luò）声母不同（z 与 l），意思是作为、写作。"}], "explanations": {"落": "落（luò，第四声）：太阳、潮水等向下降，是本义。", "锣": "锣（luó，第二声）与落（luò，第四声）声调不同，意思是打击乐器锣。", "陆": "陆（lù）与落（luò）只差韵母 o，意思是陆地。", "诺": "诺（nuò）与落（luò）声母不同（n 与 l），意思是承诺。", "作": "作（zuò）与落（luò）声母不同（z 与 l），意思是作为、写作。"}, "sentence_index": null, "correct_answer": "落"}, "level_3": {"options": [{"text": "跳", "is_correct": false, "explanation": "搭配：“跳”指人或动物起跳，不能用来描述太阳下沉。"}, {"text": "冲", "is_correct": false, "explanation": "语义：“冲”指向前猛进，与太阳缓缓下沉的意思不合。"}, {"text": "落", "is_correct": true, "explanation": "落：太阳向下降，与“下去”搭配，符合日落的语境。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”指击打，与太阳下降无关。"}], "explanations": {"跳": "搭配：“跳”指人或动物起跳，不能用来描述太阳下沉。", "冲": "语义：“冲”指向前猛进，与太阳缓缓下沉的意思不合。", "落": "落：太阳向下降，与“下去”搭配，符合日落的语境。", "打": "语义：“打”指击打，与太阳下降无关。"}, "sentence_index": 0, "correct_answer": "落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的工资落了一倍，全家都很高兴。", "explanation": "这里应该用〈涨〉。落表示下降、掉下，不能表示数量增加，“落了一倍”说不通。"}, {"text": "炊烟慢慢落上了天空。", "explanation": "这里应该用〈升〉。落表示往下降，炊烟是向上升，方向相反。"}, {"text": "鸟儿落上了蓝天。", "explanation": "这里应该用〈飞〉。落表示往下掉，鸟儿是向上飞，方向相反，不能说“落上了蓝天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90316, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "落", "is_correct": true, "explanation": "落（luò，第四声）：太阳、潮水等向下降，是本义。"}, {"text": "萝", "is_correct": false, "explanation": "萝（luó，第二声）与落（luò，第四声）声调不同，意思是萝卜。"}, {"text": "录", "is_correct": false, "explanation": "录（lù）与落（luò）只差韵母 o，意思是记录。"}, {"text": "糯", "is_correct": false, "explanation": "糯（nuò）与落（luò）声母不同（n 与 l），意思是糯米。"}, {"text": "座", "is_correct": false, "explanation": "座（zuò）与落（luò）声母不同（z 与 l），意思是座位。"}], "explanations": {"落": "落（luò，第四声）：太阳、潮水等向下降，是本义。", "萝": "萝（luó，第二声）与落（luò，第四声）声调不同，意思是萝卜。", "录": "录（lù）与落（luò）只差韵母 o，意思是记录。", "糯": "糯（nuò）与落（luò）声母不同（n 与 l），意思是糯米。", "座": "座（zuò）与落（luò）声母不同（z 与 l），意思是座位。"}, "sentence_index": null, "correct_answer": "落"}, "level_3": {"options": [{"text": "碎", "is_correct": false, "explanation": "语义：“碎”指破成小块，与太阳运动的意思不符。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”指重重击打，不用来形容太阳下沉的速度。"}, {"text": "说", "is_correct": false, "explanation": "搭配：“说”的主体要能发出言语，太阳不能“说得很快”。"}, {"text": "落", "is_correct": true, "explanation": "落：太阳向下降，与“得很快”的程度补语搭配，符合日落的语境。"}], "explanations": {"碎": "语义：“碎”指破成小块，与太阳运动的意思不符。", "砸": "语义：“砸”指重重击打，不用来形容太阳下沉的速度。", "说": "搭配：“说”的主体要能发出言语，太阳不能“说得很快”。", "落": "落：太阳向下降，与“得很快”的程度补语搭配，符合日落的语境。"}, "sentence_index": 6, "correct_answer": "落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他沿着梯子落上了屋顶。", "explanation": "这里应该用〈爬〉。落表示往下掉，人沿梯子是向上爬，方向相反。"}, {"text": "他的个子慢慢落到了门框那么高。", "explanation": "这里应该用〈长〉。落表示往下掉，人是向上长高，不能用“落”表示生长。"}, {"text": "下了三天大雨，河水落得快到桥面了。", "explanation": "这里应该用〈涨〉。落表示水位下降，大雨后河水上升，应说“涨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
