INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90317, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "长队是很多人一个接一个排成的长长的队。", "primary_collocate": null, "pronunciation": "cháng duì", "ipa": "ʈʂʰɑŋ twei", "syllable_count": 2, "sentences": [{"text": "门口排着一条长队。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店前面排起了长队。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站外排着长队。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家在售票处排成长队。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在银行门口等了很久，前面还是长队。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机一开卖，店外就出现了长队。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想排长队，明天再来吧。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到长队，我们决定换一家店。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长队一直排到了街角。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跟着老师走，形成一条长队。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条长队", "label": "量词"}, {"form": "長隊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长队：很多人一个接一个排成的长长的队", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20f9c372-ecc3-4b34-9028-39b875025280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90317, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "长队", "is_correct": true, "explanation": "正确。长队：很多人一个接一个排成的长长的队，读作 cháng duì。"}, {"text": "成对", "is_correct": false, "explanation": "“成对”（chéng duì）第一音节的韵母是 eng，与“长队”的 ang 不同，意思是成双成对。"}, {"text": "长度", "is_correct": false, "explanation": "“长度”（cháng dù）第二音节韵母是 u，与“队”（duì）的韵母 uei 不同，意思是长短。"}, {"text": "强队", "is_correct": false, "explanation": "“强队”（qiáng duì）声母是 q，与“长队”的 ch 不同，意思是实力强的队伍。"}], "explanations": {"长队": "正确。长队：很多人一个接一个排成的长长的队，读作 cháng duì。", "成对": "“成对”（chéng duì）第一音节的韵母是 eng，与“长队”的 ang 不同，意思是成双成对。", "长度": "“长度”（cháng dù）第二音节韵母是 u，与“队”（duì）的韵母 uei 不同，意思是长短。", "强队": "“强队”（qiáng duì）声母是 q，与“长队”的 ch 不同，意思是实力强的队伍。"}, "sentence_index": null, "correct_answer": "长队"}, "level_3": {"options": [{"text": "长队", "is_correct": true, "explanation": "正确。“门口排着一条长队”指排成行等候的人群，符合句意。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是水道，不能排成行列，“门口排着一条河”说不通。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾是用来保暖的物件，无法排成队伍。"}, {"text": "辫子", "is_correct": false, "explanation": "体貌：辫子是头发编成的，不是人群排成的行列。"}], "explanations": {"长队": "正确。“门口排着一条长队”指排成行等候的人群，符合句意。", "河": "语义：河是水道，不能排成行列，“门口排着一条河”说不通。", "围巾": "语义：围巾是用来保暖的物件，无法排成队伍。", "辫子": "体貌：辫子是头发编成的，不是人群排成的行列。"}, "sentence_index": 0, "correct_answer": "长队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他写了一部很长的长队，三百页还没写完。", "explanation": "这里应该用〈长篇〉。长队指排成行的人，写作的长篇小说要用“长篇”。"}, {"text": "这碗面的长队很香，我全吃光了。", "explanation": "这里应该用〈味道〉。长队指排成行的人，形容食物的香气要用“味道”。"}, {"text": "这位老人的长队很高，几乎碰到门框。", "explanation": "这里应该用〈身高〉。长队指排成行的人，不能用来形容人的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90317, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长队", "is_correct": true, "explanation": "正确。“不想排长队”指不愿意在后面排队等候，符合句意。"}, {"text": "长假", "is_correct": false, "explanation": "语义：长假是较长的假期，不能排成行，“我不想排长假”说不通。"}, {"text": "长裙", "is_correct": false, "explanation": "语义：长裙是衣服，不能“排”，“我不想排长裙”说不通。"}, {"text": "长笛", "is_correct": false, "explanation": "搭配：“排”通常与人群、车辆、号码等搭配，不能说“排长笛”。"}], "explanations": {"长队": "正确。“不想排长队”指不愿意在后面排队等候，符合句意。", "长假": "语义：长假是较长的假期，不能排成行，“我不想排长假”说不通。", "长裙": "语义：长裙是衣服，不能“排”，“我不想排长裙”说不通。", "长笛": "搭配：“排”通常与人群、车辆、号码等搭配，不能说“排长笛”。"}, "sentence_index": 6, "correct_answer": "长队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "长队在台上演奏了一首歌。", "explanation": "这里应该用〈乐队〉。长队指排成行的人，不能指演奏的乐队。"}, {"text": "长队在比赛中表现得很出色。", "explanation": "这里应该用〈球队〉。长队指等候的人群，不能指参赛的队伍。"}, {"text": "长队下周要在城里演出三场。", "explanation": "这里应该用〈剧团〉。长队不指演出的团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90317, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上周我们排了过一次长队。", "corrected_sentence": "上周我们排过一次长队。", "error_description": "“排过”表示曾经有过这种经历，“了”与“过”不能同时用，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90317, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店开业那天，门口排起了一把长队。", "corrected_sentence": "这家店开业那天，门口排起了一条长队。", "error_description": "“长队”的量词应用“条”（一条长队）；“把”用于有柄的器具，不能修饰长队，应改为“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
