INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90318, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "排得很长的行列。", "primary_collocate": null, "pronunciation": "cháng duì", "ipa": "ʈʂʰɑŋ twei", "syllable_count": 2, "sentences": [{"text": "周末公园门口总有长队。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买早饭的人排成了长队。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院门口的长队越来越长。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们在景点入口排着长队。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕店外面的长队让我吃惊。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了看演出，很多人在门口排长队。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时火车站有长队。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在长队的最后面。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家面馆每天中午都有长队。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着那条长队，我不想进去了。", "target_word": "长队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条长队", "label": "量词"}, {"form": "長隊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长队：排得很长的行列", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20f9c372-ecc3-4b34-9028-39b875025280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
