INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长队", "is_correct": true, "explanation": "正确。“过年时火车站有长队”指过年时车站排起的等候队伍，符合句意。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪是海上的波涛，火车站不会有海浪。"}, {"text": "眉毛", "is_correct": false, "explanation": "体貌：眉毛是脸上的毛发，不是能排成行列的东西。"}, {"text": "冰山", "is_correct": false, "explanation": "语义：冰山是海里的巨大冰体，与火车站无关。"}], "explanations": {"长队": "正确。“过年时火车站有长队”指过年时车站排起的等候队伍，符合句意。", "海浪": "语义：海浪是海上的波涛，火车站不会有海浪。", "眉毛": "体貌：眉毛是脸上的毛发，不是能排成行列的东西。", "冰山": "语义：冰山是海里的巨大冰体，与火车站无关。"}, "sentence_index": 6, "correct_answer": "长队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "长队赢了比赛，大家都很高兴。", "explanation": "这里应该用〈球队〉。长队指排队等候的人，不能参加比赛。"}, {"text": "长队在台上唱了三首歌。", "explanation": "这里应该用〈歌手〉。长队指排队的人群，不指演唱的人。"}, {"text": "长队在会议上发言。", "explanation": "这里应该用〈经理〉。长队是排队的人群，不能在会议上发言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末的早市门口总有一座长队。", "corrected_sentence": "周末的早市门口总有一条长队。", "error_description": "“长队”前的量词应用“条”（一条长队）；“座”用于山、楼等大型固定物，不能修饰长队，应改为“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候在食堂排了过长队。", "corrected_sentence": "他小时候在食堂排过长队。", "error_description": "“排过”表示曾经有过这种经历，“了”与“过”不能同时用，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
