INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90319, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "信心是你觉得自己一定能做好的心情。", "primary_collocate": null, "pronunciation": "xìn xīn", "ipa": "ɕin˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "我对自己的汉语很有信心。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很紧张，一点信心也没有。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一个月的练习，我有信心考好。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“你要对自己有信心。”", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌唱得好，所以上台的时候很有信心。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，他对自己充满了信心。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有信心一个人去外国旅行。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多做练习，你的信心会越来越大。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的信心来自每天的努力。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败以后，她慢慢失去了信心。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自信心", "label": "复合"}, {"form": "信心十足", "label": "复合"}], "register": "中性", "sense_fingerprint": "相信自己一定能做好某事的心情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3028915b-04fc-4478-8fb7-63277b2eed09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90319, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "信心", "is_correct": true, "explanation": "信心（xìn xīn）：相信自己一定能做好某事的心情。"}, {"text": "信息", "is_correct": false, "explanation": "信息（xìn xī）第二音节少了韵尾 n，声音不同，意思是消息、资料。"}, {"text": "尽心", "is_correct": false, "explanation": "尽心（jìn xīn）第一音节声母不同（j，不是 x），意思是竭尽心力。"}, {"text": "欣欣", "is_correct": false, "explanation": "欣欣（xīn xīn）第一音节声调不同（第一声，不是第四声），意思是欣喜、生机勃勃的样子。"}], "explanations": {"信心": "信心（xìn xīn）：相信自己一定能做好某事的心情。", "信息": "信息（xìn xī）第二音节少了韵尾 n，声音不同，意思是消息、资料。", "尽心": "尽心（jìn xīn）第一音节声母不同（j，不是 x），意思是竭尽心力。", "欣欣": "欣欣（xīn xīn）第一音节声调不同（第一声，不是第四声），意思是欣喜、生机勃勃的样子。"}, "sentence_index": null, "correct_answer": "信心"}, "level_3": {"options": [{"text": "信心", "is_correct": true, "explanation": "信心：对自己的汉语有把握的心理状态，符合句意。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情，不能用来说对汉语能力的心理状态。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”说的是外形体态，与对语言的态度无关。"}, {"text": "面子", "is_correct": false, "explanation": "语义：“面子”指社会声望，不能用于说对汉语的态度。"}], "explanations": {"信心": "信心：对自己的汉语有把握的心理状态，符合句意。", "脾气": "语义：“脾气”指性情，不能用来说对汉语能力的心理状态。", "身材": "体貌：“身材”说的是外形体态，与对语言的态度无关。", "面子": "语义：“面子”指社会声望，不能用于说对汉语的态度。"}, "sentence_index": 0, "correct_answer": "信心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下定了信心要学好汉语。", "explanation": "这里应该用〈决心〉。“下定”搭配“决心”，“信心”不能用“下定”。"}, {"text": "我有一本信心，一定能考上大学。", "explanation": "“信心”不能用量词“本”修饰（“本”用于书籍），应直接说“有信心”。"}, {"text": "他给我们出了一个好信心。", "explanation": "这里应该用〈主意〉。“出主意”是固定搭配，“信心”不能被“出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90319, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信心", "is_correct": true, "explanation": "信心：没有相信自己能做到的心理，符合句意。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：“镜子”与独自出国旅行无关，句子不通。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：“发型”指外貌，与一个人出国旅行的心理条件不符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”与独自出国旅行毫无关系，句意荒谬。"}], "explanations": {"信心": "信心：没有相信自己能做到的心理，符合句意。", "镜子": "语义：“镜子”与独自出国旅行无关，句子不通。", "发型": "体貌：“发型”指外貌，与一个人出国旅行的心理条件不符。", "厨房": "语义：“厨房”与独自出国旅行毫无关系，句意荒谬。"}, "sentence_index": 6, "correct_answer": "信心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做生意很讲信心，大家都愿意跟他合作。", "explanation": "这里应该用〈信用〉。“讲”搭配“信用”，“讲信心”不成立。"}, {"text": "他经过反复思考，终于做出了信心。", "explanation": "这里应该用〈决定〉。“做出”搭配“决定”，“信心”不能被“做出”。"}, {"text": "学校向优秀学生颁发了信心。", "explanation": "这里应该用〈奖金〉。“颁发”的对象是奖金、证书，“信心”不能被颁发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她对这次比赛很信心。", "corrected_sentence": "她对这次比赛很有信心。", "error_description": "错误形式“很信心”，正确形式“很有信心”。“信心”是名词，前面需要动词“有”来带出，不能直接用“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不有信心赢这场比赛。", "corrected_sentence": "他没有信心赢这场比赛。", "error_description": "错误形式“不有”，正确形式“没有”。表示没有某种心理状态要用“没有”，不能用“不有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
