INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90320, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "相信自己或他人能够做成某事的心理状态。", "primary_collocate": null, "pronunciation": "xìn xīn", "ipa": "ɕin˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "大家对这个队很有信心。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对我考上大学充满信心。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他会好起来，这让病人有了信心。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对我们公司的将来有信心。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板对新来的经理很有信心。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到他的进步，老师对他更有信心了。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷们对今年的比赛充满信心。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的话让我重新有了信心。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母对孩子的将来很有信心。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好消息给大家带来了信心。", "target_word": "信心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自信心", "label": "复合"}, {"form": "信心十足", "label": "复合"}], "register": "中性", "sense_fingerprint": "相信自己或别人能做成某事的心理状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3028915b-04fc-4478-8fb7-63277b2eed09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90320, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "信心", "is_correct": true, "explanation": "信心（xìn xīn）：相信自己或他人能做成某事的心理状态。"}, {"text": "信息", "is_correct": false, "explanation": "信息（xìn xī）第二音节少了韵尾 n，声音不同，意思是消息、资料。"}, {"text": "尽心", "is_correct": false, "explanation": "尽心（jìn xīn）第一音节声母不同（j，不是 x），意思是竭尽心力。"}, {"text": "欣欣", "is_correct": false, "explanation": "欣欣（xīn xīn）第一音节声调不同（第一声，不是第四声），意思是欣喜、生机勃勃的样子。"}], "explanations": {"信心": "信心（xìn xīn）：相信自己或他人能做成某事的心理状态。", "信息": "信息（xìn xī）第二音节少了韵尾 n，声音不同，意思是消息、资料。", "尽心": "尽心（jìn xīn）第一音节声母不同（j，不是 x），意思是竭尽心力。", "欣欣": "欣欣（xīn xīn）第一音节声调不同（第一声，不是第四声），意思是欣喜、生机勃勃的样子。"}, "sentence_index": null, "correct_answer": "信心"}, "level_3": {"options": [{"text": "信心", "is_correct": true, "explanation": "信心：对球队能取得好成绩的信任，符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”与球队的状态无关，句子不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用于形容球队。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：“镜子”不能用来说球队的状态。"}], "explanations": {"信心": "信心：对球队能取得好成绩的信任，符合句意。", "房子": "语义：“房子”与球队的状态无关，句子不通。", "身材": "体貌：“身材”指人的体形，不能用于形容球队。", "镜子": "语义：“镜子”不能用来说球队的状态。"}, "sentence_index": 0, "correct_answer": "信心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向我许下了信心。", "explanation": "这里应该用〈承诺〉。“许下”搭配“诺言、愿望”，“信心”不能被“许下”。"}, {"text": "他有一条信心，能把工作做好。", "explanation": "这里应该说〈有信心〉。量词“条”用于细长之物，不能修饰“信心”；直接说“有信心”即可。"}, {"text": "这家公司很讲信心，从不拖欠货款。", "explanation": "这里应该用〈信用〉。“讲”搭配“信用”，“讲信心”不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信心", "is_correct": true, "explanation": "信心：对比赛有相信能赢的心理，符合句意。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“充满”后接的是情绪或状态，不能接“咖啡”。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”与球迷的心情无关，句子不通。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：“发型”指外貌，不能说“充满发型”。"}], "explanations": {"信心": "信心：对比赛有相信能赢的心理，符合句意。", "咖啡": "搭配：“充满”后接的是情绪或状态，不能接“咖啡”。", "鞋子": "语义：“鞋子”与球迷的心情无关，句子不通。", "发型": "体貌：“发型”指外貌，不能说“充满发型”。"}, "sentence_index": 6, "correct_answer": "信心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向大家作出了信心。", "explanation": "这里应该用〈保证〉。“作出”搭配“保证”，“信心”不能被“作出”。"}, {"text": "他向大家提出了信心。", "explanation": "这里应该用〈建议〉。“提出”的对象是建议、要求，“信心”不能被提出。"}, {"text": "政府颁布了新的信心。", "explanation": "这里应该用〈法律〉。“颁布”的对象是法律、规章，“信心”不能被颁布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家对这支球队很信心。", "corrected_sentence": "大家对这支球队很有信心。", "error_description": "错误形式“很信心”，正确形式“很有信心”。“信心”是名词，前面需要动词“有”来带出，不能直接用“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不有信心完成这份工作。", "corrected_sentence": "我没有信心完成这份工作。", "error_description": "错误形式“不有”，正确形式“没有”。表示没有某种心理状态要用“没有”，不能用“不有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
