INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90321, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在西边和北边中间的方向。", "primary_collocate": null, "pronunciation": "xī běi", "ipa": "ɕi˥ pei˨˩˦", "syllable_count": 2, "sentences": [{"text": "屋顶的西北有一个小洞。", "target_word": "西北", "complexity_tier": "T3", "furigana": "xī běi", "sentence_source": "generated"}, {"text": "他们坐火车往西北去。", "target_word": "西北", "complexity_tier": "T3", "furigana": "xī běi", "sentence_source": "generated"}, {"text": "云从西北慢慢飘过来。", "target_word": "西北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子的西北比东南低。", "target_word": "西北", "complexity_tier": "T3", "furigana": "xī běi", "sentence_source": "generated"}, {"text": "我朋友住在城市的西北。", "target_word": "西北", "complexity_tier": "T3", "furigana": "xī běi", "sentence_source": "generated"}, {"text": "那座城市在我们国家的西北。", "target_word": "西北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的西北有一片小树林。", "target_word": "西北", "complexity_tier": "T3", "furigana": "xī běi", "sentence_source": "generated"}, {"text": "公园的西北有一棵大树。", "target_word": "西北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "往西北走五分钟就到了。", "target_word": "西北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北边是山，往西北走有一条河。", "target_word": "西北", "complexity_tier": "T3", "furigana": "xī běi", "sentence_source": "generated"}], "morphological_forms": [{"form": "西北部", "label": "复合"}, {"form": "西北方", "label": "复合"}], "register": "中性", "sense_fingerprint": "西边与北边中间的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab11b7c9-d5a8-4a17-9c0b-0279c3fa91db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90321, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "西北", "is_correct": true, "explanation": "正确。“屋顶的西北”指屋顶的西北部分，与句意相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：屋顶上不会有厨房，与句中“屋顶”不符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不会在屋顶上，“屋顶的书包”不成立。"}, {"text": "卧室", "is_correct": false, "explanation": "语义：屋顶不能是卧室，与句意不符。"}], "explanations": {"西北": "正确。“屋顶的西北”指屋顶的西北部分，与句意相符。", "厨房": "语义：屋顶上不会有厨房，与句中“屋顶”不符。", "书包": "语义：书包是装东西的袋子，不会在屋顶上，“屋顶的书包”不成立。", "卧室": "语义：屋顶不能是卧室，与句意不符。"}, "sentence_index": 0, "correct_answer": "西北"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "月亮从西北升起。", "explanation": "这里应该用〈东〉。月亮一般从东边升起，“西北”不能作月升的方向。"}, {"text": "星星从西北升起。", "explanation": "这里应该用〈东〉。星星多从东边升起，“西北”不能作星升的方向。"}, {"text": "院子的西北在东边。", "explanation": "“西北”是西与北之间的方向，不能位于东边，这句话自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90321, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西北", "is_correct": true, "explanation": "正确。“我家的西北”指家的西北方向，与“一片小树林”相符。"}, {"text": "车库", "is_correct": false, "explanation": "语义：车库是放车的地方，不会有一片小树林，与句意不符。"}, {"text": "浴室", "is_correct": false, "explanation": "语义：浴室是洗澡的地方，不会有一片小树林，与句意不符。"}, {"text": "书桌", "is_correct": false, "explanation": "搭配：“书桌”与“一片小树林”不搭配，不能说书桌上有一片小树林。"}], "explanations": {"西北": "正确。“我家的西北”指家的西北方向，与“一片小树林”相符。", "车库": "语义：车库是放车的地方，不会有一片小树林，与句意不符。", "浴室": "语义：浴室是洗澡的地方，不会有一片小树林，与句意不符。", "书桌": "搭配：“书桌”与“一片小树林”不搭配，不能说书桌上有一片小树林。"}, "sentence_index": 6, "correct_answer": "西北"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "北边是山，太阳从西北升起。", "explanation": "这里应该用〈东〉。太阳从东边升起，“西北”不能作日出的方位。"}, {"text": "北边是山，太阳从西北落下去。", "explanation": "这里应该用〈西〉。太阳从西边落下，“西北”不能作日落的方向。"}, {"text": "北边是山，西北是我的朋友。", "explanation": "“西北”是方位词，不能指人，这里应说“西北有一个朋友”或“我的朋友在西北”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90321, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在西北去了一趟。", "corrected_sentence": "他们往西北去了一趟。", "error_description": "介词用错。表示去的方向要用“往”，“在西北”表示处所，“在西北去”不通，应改为“往西北去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90321, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "池塘是学校的西北。", "corrected_sentence": "池塘在学校的西北。", "error_description": "动词用错。说明某物位于某处要用“在”，“是”不能引出处所，应改为“池塘在学校的西北”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
