INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90322, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "西和北之间的方位。", "primary_collocate": null, "pronunciation": "xī běi", "ipa": "ɕi˥ pei˨˩˦", "syllable_count": 2, "sentences": [{"text": "我家在中国的西北。", "target_word": "西北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从我家往西北看，能看见一座山。", "target_word": "西北", "complexity_tier": "T3", "furigana": "xī běi", "sentence_source": "generated"}, {"text": "从北京往西北走，有一座大山。", "target_word": "西北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车往西北开了十公里。", "target_word": "西北", "complexity_tier": "T3", "furigana": "xī běi", "sentence_source": "generated"}, {"text": "风从西北来，有点冷。", "target_word": "西北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家在我家的西北，走路五分钟就到。", "target_word": "西北", "complexity_tier": "T3", "furigana": "xī běi", "sentence_source": "generated"}, {"text": "地图上，西北在左上边。", "target_word": "西北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河从西北流向东南。", "target_word": "西北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想往西北走走，看看风景。", "target_word": "西北", "complexity_tier": "T3", "furigana": "xī běi", "sentence_source": "generated"}, {"text": "学校的西北有一家小商店。", "target_word": "西北", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "西北部", "label": "复合"}, {"form": "西北方", "label": "复合"}], "register": "中性", "sense_fingerprint": "方位词，西与北之间的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab11b7c9-d5a8-4a17-9c0b-0279c3fa91db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90322, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "西北", "is_correct": true, "explanation": "正确。“西北”指西与北之间的方位，“中国的西北”指中国的西北部。"}, {"text": "后面", "is_correct": false, "explanation": "语义：“后面”指次序或位置在后，国家没有“后面”这样的方位，与句意不符。"}, {"text": "前面", "is_correct": false, "explanation": "语义：“前面”指前方，不能说“中国的前面”，与句意不符。"}, {"text": "身边", "is_correct": false, "explanation": "搭配：“身边”指人或物的近旁，不说“中国的身边”，这里应使用方位词。"}], "explanations": {"西北": "正确。“西北”指西与北之间的方位，“中国的西北”指中国的西北部。", "后面": "语义：“后面”指次序或位置在后，国家没有“后面”这样的方位，与句意不符。", "前面": "语义：“前面”指前方，不能说“中国的前面”，与句意不符。", "身边": "搭配：“身边”指人或物的近旁，不说“中国的身边”，这里应使用方位词。"}, "sentence_index": 0, "correct_answer": "西北"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳每天从西北升起。", "explanation": "这里应该用〈东〉。太阳从东边升起，西北不是日出的方向，“西北”不能用来说明日出的方位。"}, {"text": "日出的方向是西北。", "explanation": "这里应该用〈东〉。日出的方向是东边，“西北”不能作日出的方向。"}, {"text": "早上，太阳从我家的西北窗户升起。", "explanation": "这里应该用〈东〉。日出的方向是东边，“西北”不能用来描述太阳升起的方位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90322, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西北", "is_correct": true, "explanation": "正确。标准地图上北在上、西在左，西北位于左上，与句中“左上边”一致。"}, {"text": "东北", "is_correct": false, "explanation": "语义：标准地图上东北在右上，与句中“左上边”不符。"}, {"text": "西南", "is_correct": false, "explanation": "语义：标准地图上西南在左下，与句中“左上边”不符。"}, {"text": "东方", "is_correct": false, "explanation": "语义：标准地图上东在右，“东方”在右侧，与句中“左上边”不符。"}], "explanations": {"西北": "正确。标准地图上北在上、西在左，西北位于左上，与句中“左上边”一致。", "东北": "语义：标准地图上东北在右上，与句中“左上边”不符。", "西南": "语义：标准地图上西南在左下，与句中“左上边”不符。", "东方": "语义：标准地图上东在右，“东方”在右侧，与句中“左上边”不符。"}, "sentence_index": 6, "correct_answer": "西北"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月亮从西北升起。", "explanation": "这里应该用〈东〉。月亮一般从东边升起，“西北”不能作月升的方向。"}, {"text": "星星从西北升起。", "explanation": "这里应该用〈东〉。星星多从东边升起，“西北”不能作星升的方向。"}, {"text": "太阳从学校的西北边升起。", "explanation": "这里应该用〈东〉。太阳从东边升起，“西北”不能作日出的方位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的学校是城市的西北。", "corrected_sentence": "我的学校在城市的西北。", "error_description": "动词用错。说明某物位于某处要用“在”，“是”不能引出处所，应改为“我的学校在城市的西北”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们从车站在西北走。", "corrected_sentence": "我们从车站往西北走。", "error_description": "介词用错。表示行进的方向要用“往”，“在西北”表示处所，“在西北走”不通，应改为“往西北走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
