INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90325, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90325, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "候选人是大家选人的时候，名字被写在名单上的人。大家投票，选出最好的一个。", "primary_collocate": null, "pronunciation": "hòu xuǎn rén", "ipa": "xou˥˩ ɕɥɛn˨˩˦ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "这次选班长，有三个候选人。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "候选人的名字都写在名单上。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个候选人你最喜欢？", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有两位候选人。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家今天要选出最好的候选人。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是第一个候选人。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把候选人的名字写在黑板上。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个候选人都说了几句话。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "候选人站在台上，大家看着他。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你给哪位候选人投票？", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "候选人们", "label": "复数"}], "register": "中性", "sense_fingerprint": "选人时名字在名单上、等待大家投票的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab11b7c9-d5a8-4a17-9c0b-0279c3fa91db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90325, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "候选人", "is_correct": true, "explanation": "正确。“候选人”指被提名、等待投票的人，句中“有三个候选人”与选班长相符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不是能被选出的人，“有三个教室”与句意不符。"}, {"text": "名单", "is_correct": false, "explanation": "语义：名单是写名字的单子，不是被选的人，“选班长，有三个名单”与句意不符。"}, {"text": "选票", "is_correct": false, "explanation": "语义：选票是投票用的纸，不是被选的人，“选班长，有三个选票”与句意不符。"}], "explanations": {"候选人": "正确。“候选人”指被提名、等待投票的人，句中“有三个候选人”与选班长相符。", "教室": "语义：教室是上课的地方，不是能被选出的人，“有三个教室”与句意不符。", "名单": "语义：名单是写名字的单子，不是被选的人，“选班长，有三个名单”与句意不符。", "选票": "语义：选票是投票用的纸，不是被选的人，“选班长，有三个选票”与句意不符。"}, "sentence_index": 0, "correct_answer": "候选人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场足球比赛有十六名候选人。", "explanation": "这里应该用〈选手〉。比赛中参赛的人叫选手，“候选人”指选举或提名中供挑选的人。"}, {"text": "这次期末考试有三十名候选人。", "explanation": "这里应该用〈考生〉。参加考试的人叫考生，“候选人”不用于考试。"}, {"text": "这档歌唱节目有十位候选人。", "explanation": "这里应该用〈参赛者〉。节目中的表演者称参赛者，“候选人”指选举中被提名的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90325, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "候选人", "is_correct": true, "explanation": "正确。句中要写的是候选人的名字，与句意相符。"}, {"text": "讲台", "is_correct": false, "explanation": "语义：“名字”是人或物的名称，讲台不是要写名字的对象，句意不通。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是写字的地方，“黑板的名字”不成立，“写在黑板上”已说明地点。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户一般没有名字，“窗户的名字”不成立，句意不通。"}], "explanations": {"候选人": "正确。句中要写的是候选人的名字，与句意相符。", "讲台": "语义：“名字”是人或物的名称，讲台不是要写名字的对象，句意不通。", "黑板": "语义：黑板是写字的地方，“黑板的名字”不成立，“写在黑板上”已说明地点。", "窗户": "语义：窗户一般没有名字，“窗户的名字”不成立，句意不通。"}, "sentence_index": 6, "correct_answer": "候选人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你给哪张候选人投票？", "explanation": "这里应该用〈位〉。“张”多用于纸张、桌子等，不能用来计量人。"}, {"text": "你给哪本候选人投票？", "explanation": "这里应该用〈位〉。“本”用于书册，不能用来计量人。"}, {"text": "你给哪台候选人投票？", "explanation": "这里应该用〈位〉。“台”用于机器等，不能用来计量人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90325, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次班长选举有两只候选人。", "corrected_sentence": "这次班长选举有两位候选人。", "error_description": "量词用错。人应用“位”或“个”，“只”用于动物等，不能用于“候选人”，应改为“两位候选人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90325, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位候选人们都参加了班会。", "corrected_sentence": "两位候选人都参加了班会。", "error_description": "“们”用错。“候选人们”表示复数，不能与数词加量词同用，应去掉“们”，改为“两位候选人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
