INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90326, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在选举中被提名、供选举人挑选的人。", "primary_collocate": null, "pronunciation": "hòu xuǎn rén", "ipa": "xou˥˩ ɕɥɛn˨˩˦ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "市长选举有四位候选人。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位候选人得到了很多人的支持。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位候选人今天在电视上见面。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "候选人要告诉大家他的想法。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政党提名了一位新的候选人。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "候选人的年龄不能太小。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是这次选举最年轻的候选人。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选民要从候选人里选一个。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位候选人去了很多城市。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "候选人在会上说了他的计划。", "target_word": "候选人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "候选人们", "label": "复数"}], "register": "书面", "sense_fingerprint": "选举中被提名、供选民挑选的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab11b7c9-d5a8-4a17-9c0b-0279c3fa91db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "候选人", "is_correct": true, "explanation": "正确。市长选举中被提名、供选民挑选的人称候选人，句中“四位”与之相符。"}, {"text": "市长", "is_correct": false, "explanation": "语义：市长是选举产生的职位，不是候选的人选，“有四位市长”与句意不符。"}, {"text": "选票", "is_correct": false, "explanation": "搭配：量词“位”不搭配“选票”，应说“张”。"}, {"text": "选区", "is_correct": false, "explanation": "语义：选区是地域范围，不能用“位”计量，“四位选区”不成立。"}], "explanations": {"候选人": "正确。市长选举中被提名、供选民挑选的人称候选人，句中“四位”与之相符。", "市长": "语义：市长是选举产生的职位，不是候选的人选，“有四位市长”与句意不符。", "选票": "搭配：量词“位”不搭配“选票”，应说“张”。", "选区": "语义：选区是地域范围，不能用“位”计量，“四位选区”不成立。"}, "sentence_index": 0, "correct_answer": "候选人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项法律是候选人投票通过的。", "explanation": "这里应该用〈议员〉。议员有权投票表决法律，候选人还未当选，不能投票通过法律。"}, {"text": "这位候选人昨天正式就职，成为市长。", "explanation": "这里应该用〈当选者〉。候选人还未当选，不能就职；就职的是已经当选的人。"}, {"text": "这位候选人已经当了十年市长，选举早就结束了。", "explanation": "这里应该用〈市长〉。选举结束、已经任职的人不再是候选人，“候选人”只指选举中等待挑选的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "候选人", "is_correct": true, "explanation": "正确。“最年轻的候选人”指年纪最轻的一位候选人，与句意相符。"}, {"text": "投票箱", "is_correct": false, "explanation": "语义：投票箱是放选票的箱子，“她是最年轻的投票箱”句意不通。"}, {"text": "政党", "is_correct": false, "explanation": "语义：“她”是人，不能是政党，句意不通。"}, {"text": "广告", "is_correct": false, "explanation": "语义：“她”是人，不能是广告，“她是这次选举最年轻的广告”句意不通。"}], "explanations": {"候选人": "正确。“最年轻的候选人”指年纪最轻的一位候选人，与句意相符。", "投票箱": "语义：投票箱是放选票的箱子，“她是最年轻的投票箱”句意不通。", "政党": "语义：“她”是人，不能是政党，句意不通。", "广告": "语义：“她”是人，不能是广告，“她是这次选举最年轻的广告”句意不通。"}, "sentence_index": 6, "correct_answer": "候选人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那张候选人在会上说了他的计划。", "explanation": "这里应该用〈位〉。“张”多用于纸张、桌子等，不能用来计量人。"}, {"text": "那本候选人在会上说了他的计划。", "explanation": "这里应该用〈位〉。“本”用于书册，不能用来计量人。"}, {"text": "那台候选人在会上说了他的计划。", "explanation": "这里应该用〈位〉。“台”用于机器等，不能用来计量人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次市长选举有五只候选人。", "corrected_sentence": "这次市长选举有五位候选人。", "error_description": "量词用错。人应用“位”或“个”，“只”用于动物等，不能用于“候选人”，应改为“五位候选人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三位候选人们都来参加了辩论会。", "corrected_sentence": "三位候选人都来参加了辩论会。", "error_description": "“们”用错。“候选人们”表示复数，不能与数词加量词同用，应去掉“们”，改为“三位候选人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
