INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90329, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "开放系统是能让别人加入、一起用的系统。", "primary_collocate": null, "pronunciation": "kāi fàng xì tǒng", "ipa": "kaɪ˥ faŋ˥˩ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "这个开放系统，谁都可以加入。", "target_word": "开放系统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开放系统让大家一起用，也一起改。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在开放系统里分享作业。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢开放系统，因为谁都能加入一起用。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个开放系统，不用申请就能用。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开放系统欢迎新朋友一起来用。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区建了一个开放系统，大家都能用。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人也可以用这个开放系统。", "target_word": "开放系统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开放系统里的东西，人人都能看。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己做的软件放进了开放系统。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "開放系統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让人加入、大家共用的系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb690da-b4fb-44a8-8915-e03b8c08ddd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90329, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开放系统", "is_correct": true, "explanation": "正确：“开放系统”指让人加入、共用的系统，与“谁都可以加入”一致，是句中唯一能填入的词。"}, {"text": "封闭系统", "is_correct": false, "explanation": "语义：封闭系统不对外开放，与“谁都可以加入”相矛盾。"}, {"text": "私人俱乐部", "is_correct": false, "explanation": "语义：“私人”指只限特定人员，与“谁都可以加入”相矛盾。"}, {"text": "电灯", "is_correct": false, "explanation": "搭配：“加入”的对象是团体、组织，“电灯”不能被加入。"}], "explanations": {"开放系统": "正确：“开放系统”指让人加入、共用的系统，与“谁都可以加入”一致，是句中唯一能填入的词。", "封闭系统": "语义：封闭系统不对外开放，与“谁都可以加入”相矛盾。", "私人俱乐部": "语义：“私人”指只限特定人员，与“谁都可以加入”相矛盾。", "电灯": "搭配：“加入”的对象是团体、组织，“电灯”不能被加入。"}, "sentence_index": 0, "correct_answer": "开放系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个开放系统只能我一个人用，别人不能加入。", "explanation": "这里应该用〈封闭系统〉或〈私人系统〉。开放系统是让别人加入、共用的系统，不能只许一个人用、不让别人加入。"}, {"text": "我喜欢一块开放系统，因为谁都能加入一起用。", "explanation": "这里应该用〈个〉或〈套〉。“块”用于块状的东西，系统不能用“块”来计量。"}, {"text": "我喜欢一把开放系统，因为谁都能加入一起用。", "explanation": "这里应该用〈个〉或〈套〉。“把”用于有柄或可握的东西，系统不能用“把”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90329, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开放系统", "is_correct": true, "explanation": "正确：“社区建了一个开放系统，大家都能用”说的是大家可共用的系统，是句中唯一合适的词。"}, {"text": "私人会所", "is_correct": false, "explanation": "语义：“私人会所”限特定人员使用，与“大家都能用”相矛盾。"}, {"text": "单人床", "is_correct": false, "explanation": "语义：单人床只供一人睡，与“大家都能用”相矛盾。"}, {"text": "问候", "is_correct": false, "explanation": "搭配：“建”的对象是设施或平台，不能说“建问候”。"}], "explanations": {"开放系统": "正确：“社区建了一个开放系统，大家都能用”说的是大家可共用的系统，是句中唯一合适的词。", "私人会所": "语义：“私人会所”限特定人员使用，与“大家都能用”相矛盾。", "单人床": "语义：单人床只供一人睡，与“大家都能用”相矛盾。", "问候": "搭配：“建”的对象是设施或平台，不能说“建问候”。"}, "sentence_index": 6, "correct_answer": "开放系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把自己做的软件放进了一颗开放系统。", "explanation": "这里应该用〈个〉或〈套〉。“颗”用于小而圆的东西，系统不能用“颗”来计量。"}, {"text": "他把自己做的软件放进了一条开放系统。", "explanation": "这里应该用〈个〉或〈套〉。“条”用于长条形的东西，系统不能用“条”来计量。"}, {"text": "他把自己做的软件放进了一张开放系统。", "explanation": "这里应该用〈个〉或〈套〉。“张”用于纸张、桌子等平面的东西，系统不能用“张”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90329, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些开放系统们谁都能用，不收费。", "corrected_sentence": "这些开放系统谁都能用，不收费。", "error_description": "多余的“们”：“开放系统”是事物名词，不能加“们”表示复数；表示多个直接用“这些”即可，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90329, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个社区有一只开放系统，谁都能用。", "corrected_sentence": "这个社区有一个开放系统，谁都能用。", "error_description": "量词错误：“只”用于动物或成对物品中的一个，“开放系统”应用“个”或“套”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
