INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90330, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "允许与外部其他系统交换信息、互相连接的系统。", "primary_collocate": null, "pronunciation": "kāi fàng xì tǒng", "ipa": "kaɪ˥ faŋ˥˩ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "这个开放系统可以和别的软件连接。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院用开放系统交换病人的资料。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开放系统能和外面的系统互相传信息。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司买了一套开放系统。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开放系统的数据可以传到别的平台。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在研究开放系统怎么连接别的系统。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的开放系统让客户用不同的软件。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开放系统需要把外部的接口打开。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "封闭系统不能连外面，开放系统可以。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个开放系统和旧系统连着。", "target_word": "开放系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "開放系統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "能与外部系统交换信息的系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb690da-b4fb-44a8-8915-e03b8c08ddd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开放系统", "is_correct": true, "explanation": "正确：“这个开放系统可以和别的软件连接”说的是能与外部系统连接的系统，是句中唯一能填入的词。"}, {"text": "封闭系统", "is_correct": false, "explanation": "语义：封闭系统不与外界连通，与“可以和别的软件连接”相矛盾。"}, {"text": "木材", "is_correct": false, "explanation": "搭配：“连接”的主体是设备或系统，“木材”不能与软件连接。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不能和软件连接。"}], "explanations": {"开放系统": "正确：“这个开放系统可以和别的软件连接”说的是能与外部系统连接的系统，是句中唯一能填入的词。", "封闭系统": "语义：封闭系统不与外界连通，与“可以和别的软件连接”相矛盾。", "木材": "搭配：“连接”的主体是设备或系统，“木材”不能与软件连接。", "小说": "语义：小说是文学作品，不能和软件连接。"}, "sentence_index": 0, "correct_answer": "开放系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个开放系统不能和外面连接，只能自己用。", "explanation": "这里应该用〈封闭系统〉。开放系统必须能与外部系统连接、交换信息，不能说不能连外面的系统。"}, {"text": "我们公司买了一块开放系统。", "explanation": "这里应该用〈套〉或〈个〉。“块”用于块状的东西，系统不能用“块”来计量。"}, {"text": "我们公司买了一把开放系统。", "explanation": "这里应该用〈套〉或〈个〉。“把”用于有柄或可握的东西，系统不能用“把”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开放系统", "is_correct": true, "explanation": "正确：“银行的开放系统让客户用不同的软件”说的是能与外部软件连接、交换信息的系统，是句中唯一合适的词。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂提供餐饮，不能让客户用不同的软件。"}, {"text": "咖啡馆", "is_correct": false, "explanation": "语义：咖啡馆是饮食场所，不是让客户使用软件的系统。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“让客户用不同的软件”的主语应是系统或平台，“礼物”不能让人用软件。"}], "explanations": {"开放系统": "正确：“银行的开放系统让客户用不同的软件”说的是能与外部软件连接、交换信息的系统，是句中唯一合适的词。", "食堂": "语义：食堂提供餐饮，不能让客户用不同的软件。", "咖啡馆": "语义：咖啡馆是饮食场所，不是让客户使用软件的系统。", "礼物": "搭配：“让客户用不同的软件”的主语应是系统或平台，“礼物”不能让人用软件。"}, "sentence_index": 6, "correct_answer": "开放系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只开放系统和旧系统连着。", "explanation": "这里应该用〈个〉或〈套〉。“只”用于动物或成对东西中的一个，系统不能用“只”来计量。"}, {"text": "这张开放系统和旧系统连着。", "explanation": "这里应该用〈个〉或〈套〉。“张”用于纸张、桌子等平面的东西，系统不能用“张”来计量。"}, {"text": "这片开放系统和旧系统连着。", "explanation": "这里应该用〈个〉或〈套〉。“片”用于薄片或成片的东西，系统不能用“片”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些开放系统们都能和别的软件连接。", "corrected_sentence": "这些开放系统都能和别的软件连接。", "error_description": "多余的“们”：“开放系统”是事物名词，不能加“们”表示复数；表示多个直接用“这些”即可，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "银行买了一颗开放系统，客户都能用。", "corrected_sentence": "银行买了一套开放系统，客户都能用。", "error_description": "量词错误：“颗”用于小而圆的东西，“开放系统”应用“套”或“个”，不能用“颗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
