INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90331, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "伤是身体被弄坏的地方，会流血或者很痛。", "primary_collocate": null, "pronunciation": "shāng", "ipa": "ʂɑŋ˥", "syllable_count": 1, "sentences": [{"text": "他腿上有一道很深的伤。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生看了看我手上的伤。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个伤还在流血，快去医院。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了一个星期，他腿上的伤好了。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给弟弟的伤上了药。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她手上的伤很痛，不能拿东西。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身上有很多小时候留下的伤。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个伤不重，不用去医院。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷的时候，他腿上的伤会痛。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子摔倒了，膝盖上有一道伤。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "处", "label": "量词"}, {"form": "傷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体上被弄坏、会流血或疼痛的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a22d3499-ca45-4e80-9518-98ccdc905de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90331, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伤", "is_correct": true, "explanation": "伤 shāng（第一声）：身体上被弄坏、会流血或疼痛的地方，即本题目标词。"}, {"text": "上", "is_correct": false, "explanation": "shàng（第四声）与 shāng（第一声）声调不同，意思是“上面”，不是伤口。"}, {"text": "山", "is_correct": false, "explanation": "shān 与 shāng 韵母不同（an 与 ang），意思是“山”。"}, {"text": "烧", "is_correct": false, "explanation": "shāo 与 shāng 韵母不同（ao 与 ang），意思是“燃烧”或“发烧”。"}, {"text": "桑", "is_correct": false, "explanation": "sāng 与 shāng 声母不同（s 与 sh），意思是“桑树”。"}], "explanations": {"伤": "伤 shāng（第一声）：身体上被弄坏、会流血或疼痛的地方，即本题目标词。", "上": "shàng（第四声）与 shāng（第一声）声调不同，意思是“上面”，不是伤口。", "山": "shān 与 shāng 韵母不同（an 与 ang），意思是“山”。", "烧": "shāo 与 shāng 韵母不同（ao 与 ang），意思是“燃烧”或“发烧”。", "桑": "sāng 与 shāng 声母不同（s 与 sh），意思是“桑树”。"}, "sentence_index": null, "correct_answer": "伤"}, "level_3": {"options": [{"text": "伤", "is_correct": true, "explanation": "伤：身体上留下的伤处，与“腿上”和“很深的”搭配自然。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙不是身体的一部分，“腿上”不可能有一道“很深的墙”。"}, {"text": "血", "is_correct": false, "explanation": "搭配：“一道”用于线状的伤痕，不能说“一道很深的血”。"}, {"text": "肉", "is_correct": false, "explanation": "语义：肉是身体组织，不是可以“很深”地裂开的伤处，“一道很深的肉”说不通。"}], "explanations": {"伤": "伤：身体上留下的伤处，与“腿上”和“很深的”搭配自然。", "墙": "语义：墙不是身体的一部分，“腿上”不可能有一道“很深的墙”。", "血": "搭配：“一道”用于线状的伤痕，不能说“一道很深的血”。", "肉": "语义：肉是身体组织，不是可以“很深”地裂开的伤处，“一道很深的肉”说不通。"}, "sentence_index": 0, "correct_answer": "伤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他腿上有一本很深的伤。", "explanation": "这里应该用〈道〉。伤是细长的伤口，用“道”；“本”用于书，不能用来量伤口。"}, {"text": "他腿上有一张很深的伤。", "explanation": "这里应该用〈道〉。伤口细长时用“道”；“张”用于纸、桌子等扁平的东西，不能用来量伤。"}, {"text": "他腿上有一颗细小的伤。", "explanation": "这里应该用〈道〉。伤是细长的伤口，用“道”；“颗”用于圆形的小颗粒，不能用来量伤口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90331, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "伤", "is_correct": true, "explanation": "伤 shāng（第一声）：身体上被弄坏、会流血或疼痛的地方，即本题目标词。"}, {"text": "生", "is_correct": false, "explanation": "shēng 与 shāng 韵母不同（e 与 a），意思是“生出”或“生活”。"}, {"text": "汤", "is_correct": false, "explanation": "tāng 与 shāng 声母不同（t 与 sh），意思是“汤”。"}, {"text": "赏", "is_correct": false, "explanation": "shǎng（第三声）与 shāng（第一声）声调不同，意思是“赏赐”或“欣赏”。"}, {"text": "尚", "is_correct": false, "explanation": "shàng（第四声）与 shāng（第一声）声调不同，意思是“还”或“崇尚”。"}], "explanations": {"伤": "伤 shāng（第一声）：身体上被弄坏、会流血或疼痛的地方，即本题目标词。", "生": "shēng 与 shāng 韵母不同（e 与 a），意思是“生出”或“生活”。", "汤": "tāng 与 shāng 声母不同（t 与 sh），意思是“汤”。", "赏": "shǎng（第三声）与 shāng（第一声）声调不同，意思是“赏赐”或“欣赏”。", "尚": "shàng（第四声）与 shāng（第一声）声调不同，意思是“还”或“崇尚”。"}, "sentence_index": null, "correct_answer": "伤"}, "level_3": {"options": [{"text": "伤", "is_correct": true, "explanation": "伤：身体上留下的伤处，与“身上”和“小时候留下的”搭配自然。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不会留在身上，“身上留下的星星”说不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是身体上的痕迹，与“身上留下”的意思冲突。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“留下”多接“伤痕、印记”等，不说“留下颜色”。"}], "explanations": {"伤": "伤：身体上留下的伤处，与“身上”和“小时候留下的”搭配自然。", "星星": "语义：星星不会留在身上，“身上留下的星星”说不通。", "房子": "语义：房子不是身体上的痕迹，与“身上留下”的意思冲突。", "颜色": "搭配：“留下”多接“伤痕、印记”等，不说“留下颜色”。"}, "sentence_index": 6, "correct_answer": "伤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子膝盖上有一件伤。", "explanation": "这里应该用〈道〉。伤是细长的伤口，用“道”；“件”用于衣服、事情，不能用来量伤口。"}, {"text": "孩子膝盖上有一粒伤。", "explanation": "这里应该用〈道〉。伤是细长的伤口，用“道”；“粒”用于颗粒状的小东西，不能用来量伤口。"}, {"text": "孩子膝盖上有一棵伤。", "explanation": "这里应该用〈道〉。伤是细长的伤口，用“道”；“棵”用于树木、植物，不能用来量伤口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的膝盖上有一只很长的伤。", "corrected_sentence": "他的膝盖上有一道很长的伤。", "error_description": "量词错误：“伤”是细长的伤口，应该用量词“道”；“只”用于动物或成对物品中的一个，不能用来量伤口。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的手指上有一张细细的伤。", "corrected_sentence": "她的手指上有一道细细的伤。", "error_description": "量词错误：“伤”是细长的伤口，应该用“道”；“张”用于纸、桌子等扁平的东西，不能用来量伤口。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
