INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90332, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体受到损害的部位；也指损害、伤害。", "primary_collocate": null, "pronunciation": "shāng", "ipa": "ʂɑŋ˥", "syllable_count": 1, "sentences": [{"text": "他背上的伤是那年留下的。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道伤很长，一直到手腕。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的伤要三个月才能好。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里的伤，很多年都没有好。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开家人，在他心里留下了一道伤。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伤在左腿，所以他走不快。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么大的伤，要去医院看看。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争在这座城市留下了很深的伤。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的伤已经好了，可以踢球了。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她手上有几道旧的伤。", "target_word": "伤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "傷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体受损的部位，也比喻心里或事物受到的损害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a22d3499-ca45-4e80-9518-98ccdc905de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90332, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伤", "is_correct": true, "explanation": "伤 shāng（第一声）：身体受损的部位，也指心里或事物受到的损害，即本题目标词。"}, {"text": "尚", "is_correct": false, "explanation": "shàng（第四声）与 shāng（第一声）声调不同，意思是“还”或“崇尚”。"}, {"text": "山", "is_correct": false, "explanation": "shān 与 shāng 韵母不同（an 与 ang），意思是“山”。"}, {"text": "烧", "is_correct": false, "explanation": "shāo 与 shāng 韵母不同（ao 与 ang），意思是“燃烧”或“发烧”。"}, {"text": "生", "is_correct": false, "explanation": "shēng 与 shāng 韵母不同（e 与 a），意思是“生出”或“生活”。"}], "explanations": {"伤": "伤 shāng（第一声）：身体受损的部位，也指心里或事物受到的损害，即本题目标词。", "尚": "shàng（第四声）与 shāng（第一声）声调不同，意思是“还”或“崇尚”。", "山": "shān 与 shāng 韵母不同（an 与 ang），意思是“山”。", "烧": "shāo 与 shāng 韵母不同（ao 与 ang），意思是“燃烧”或“发烧”。", "生": "shēng 与 shāng 韵母不同（e 与 a），意思是“生出”或“生活”。"}, "sentence_index": null, "correct_answer": "伤"}, "level_3": {"options": [{"text": "伤", "is_correct": true, "explanation": "伤：身体上留下的伤处，与“背上”和“那年留下的”搭配自然。"}, {"text": "胎记", "is_correct": false, "explanation": "体貌：胎记是天生的，不是“那年留下”的，与句中的时间信息冲突。"}, {"text": "河", "is_correct": false, "explanation": "语义：河不会长在背上，也不会是“那年留下”的。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子不是身体上的东西，“背上的镜子”说不通。"}], "explanations": {"伤": "伤：身体上留下的伤处，与“背上”和“那年留下的”搭配自然。", "胎记": "体貌：胎记是天生的，不是“那年留下”的，与句中的时间信息冲突。", "河": "语义：河不会长在背上，也不会是“那年留下”的。", "镜子": "语义：镜子不是身体上的东西，“背上的镜子”说不通。"}, "sentence_index": 0, "correct_answer": "伤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她心里有一只很深的伤。", "explanation": "这里应该用〈道〉。伤是细长的，量词用“道”；“只”用于动物或成对物品中的一个，不能用来量伤。"}, {"text": "她心里留着一颗深深的伤。", "explanation": "这里应该用〈道〉。伤是细长的，用“道”；“颗”用于圆形的小颗粒，不能用来量伤。"}, {"text": "她心里有一张很长的伤。", "explanation": "这里应该用〈道〉。伤是细长的，用“道”；“张”用于纸、桌子等扁平的东西，不能用来量伤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90332, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "伤", "is_correct": true, "explanation": "伤 shāng（第一声）：身体受损的部位，也指心里或事物受到的损害，即本题目标词。"}, {"text": "上", "is_correct": false, "explanation": "shàng（第四声）与 shāng（第一声）声调不同，意思是“上面”。"}, {"text": "汤", "is_correct": false, "explanation": "tāng 与 shāng 声母不同（t 与 sh），意思是“汤”。"}, {"text": "赏", "is_correct": false, "explanation": "shǎng（第三声）与 shāng（第一声）声调不同，意思是“赏赐”或“欣赏”。"}, {"text": "桑", "is_correct": false, "explanation": "sāng 与 shāng 声母不同（s 与 sh），意思是“桑树”。"}], "explanations": {"伤": "伤 shāng（第一声）：身体受损的部位，也指心里或事物受到的损害，即本题目标词。", "上": "shàng（第四声）与 shāng（第一声）声调不同，意思是“上面”。", "汤": "tāng 与 shāng 声母不同（t 与 sh），意思是“汤”。", "赏": "shǎng（第三声）与 shāng（第一声）声调不同，意思是“赏赐”或“欣赏”。", "桑": "sāng 与 shāng 声母不同（s 与 sh），意思是“桑树”。"}, "sentence_index": null, "correct_answer": "伤"}, "level_3": {"options": [{"text": "伤", "is_correct": true, "explanation": "伤：身体受伤的部位，与“这么大的”和“要去医院看看”搭配自然。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是身体的损伤，“要去医院看看”说不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不会需要去医院看看，句子的语义说不通。"}, {"text": "隐患", "is_correct": false, "explanation": "语义：隐患指潜在的危险，还没有造成伤害，“要去医院看看”说不通。"}], "explanations": {"伤": "伤：身体受伤的部位，与“这么大的”和“要去医院看看”搭配自然。", "房子": "语义：房子不是身体的损伤，“要去医院看看”说不通。", "作业": "语义：作业不会需要去医院看看，句子的语义说不通。", "隐患": "语义：隐患指潜在的危险，还没有造成伤害，“要去医院看看”说不通。"}, "sentence_index": 6, "correct_answer": "伤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她手上有几朵旧的伤。", "explanation": "这里应该用〈道〉。伤是细长的伤口，用“道”；“朵”用于花、云等，不能用来量伤口。"}, {"text": "她手上有几颗旧的伤。", "explanation": "这里应该用〈道〉。伤是细长的伤口，用“道”；“颗”用于圆形的小东西，不能用来量伤口。"}, {"text": "她手上有一场旧的伤。", "explanation": "这里应该用〈道〉。伤是细长的伤口，用“道”；“场”用于比赛、战争等事件，不能用来量伤口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的胳膊上有一张很长的伤。", "corrected_sentence": "他的胳膊上有一道很长的伤。", "error_description": "量词错误：“伤”是细长的伤口，应该用“道”；“张”用于纸、桌子等扁平的东西，不能用来量伤口。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只伤已经结痂了。", "corrected_sentence": "这道伤已经结痂了。", "error_description": "量词错误：“伤”是细长的伤口，应该用“道”；“只”用于动物或成对物品中的一个，不能用来量伤口。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
