INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90333, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "最近这几年。", "primary_collocate": null, "pronunciation": "jìn nián lái", "ipa": "tɕin˥˩ njɛn˧˥ laɪ˧˥", "syllable_count": 3, "sentences": [{"text": "近年来，我们城市的空气越来越好。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年来，坐高铁旅行的人越来越多。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年来，这家小商店的生意一直不错。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他近年来很少回老家看父母。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年来，买东西的方式变化很大。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年来，越来越多的年轻人喜欢在家工作。", "target_word": "近年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家那条街近年来新开了很多咖啡店。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年来，中国的手机用户一年比一年多。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年来，这个地方的房子贵了很多。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的汉语近年来进步很快，我很高兴。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "近年來", "label": "繁体"}], "register": "书面", "sense_fingerprint": "指最近几年这段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5461ebd-d36b-4535-a617-61dd6497bd0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90333, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近年来", "is_correct": true, "explanation": "近年来指最近几年，与“越来越好”这种长期变化相符。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”指突然发生，与“越来越好”这种逐渐变化不符。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”表示马上，不能和“越来越好”这种渐进变化搭配。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指很快就会发生，与讲几年间变化的“越来越好”不符。"}], "explanations": {"近年来": "近年来指最近几年，与“越来越好”这种长期变化相符。", "忽然": "语义：“忽然”指突然发生，与“越来越好”这种逐渐变化不符。", "立刻": "搭配：“立刻”表示马上，不能和“越来越好”这种渐进变化搭配。", "马上": "语义：“马上”指很快就会发生，与讲几年间变化的“越来越好”不符。"}, "sentence_index": 0, "correct_answer": "近年来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天他近年来很忙，没有时间吃饭。", "explanation": "这里应该用〈近来〉。近年来指最近几年，说几天的情况要用〈近来〉。"}, {"text": "这座桥近年来在一九五〇年建成。", "explanation": "这里不能用〈近年来〉。它指最近几年的情况或变化，不能用来说明一九五〇年这样确定的时间点。"}, {"text": "我近年来明天要出国。", "explanation": "这里不能用〈近年来〉。它指过去到现在的一段时间，不能和“明天”这样的将来时间词同用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90333, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近年来", "is_correct": true, "explanation": "近年来指最近几年，符合几年间积累起来的“新开了很多咖啡店”这种变化。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：“连忙”指急忙去做某事，需要有人主动去做，不能用来说街道新开店铺。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“新开了很多”的大量变化相冲突。"}, {"text": "故意", "is_correct": false, "explanation": "搭配：“故意”说有意去做，不用来说店铺自然地新开。"}], "explanations": {"近年来": "近年来指最近几年，符合几年间积累起来的“新开了很多咖啡店”这种变化。", "连忙": "语义：“连忙”指急忙去做某事，需要有人主动去做，不能用来说街道新开店铺。", "偶尔": "语义：“偶尔”表示不常发生，与“新开了很多”的大量变化相冲突。", "故意": "搭配：“故意”说有意去做，不用来说店铺自然地新开。"}, "sentence_index": 6, "correct_answer": "近年来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我近年来三天都在复习汉语，很辛苦。", "explanation": "这里应该用〈最近〉。近年来指最近几年，说三天的情况要用〈最近〉。"}, {"text": "近年来，请你快点来。", "explanation": "这里应该用〈马上〉。句子是催对方立刻过来，要表达“立刻”的意思，而近年来指最近几年，不表示“立刻”。"}, {"text": "我今天早上近年来去了超市。", "explanation": "这里不能用〈近年来〉。它指几年的时间段，不能和“今天早上”这样的当天时间同用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90333, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐的近年来很少回老家看父母。", "corrected_sentence": "我姐姐近年来很少回老家看父母。", "error_description": "结构错误：“我姐姐的”后面没有中心语，句子结构不通；“近年来”应直接作状语修饰后面的动词，应说“我姐姐近年来很少回老家看父母”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90333, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近年来以来，他的收入增加了不少。", "corrected_sentence": "近年来，他的收入增加了不少。", "error_description": "重复：“近年来”已经包含“以来”的意思，不能再加“以来”，应只说“近年来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
