INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90334, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "最近几年以来。", "primary_collocate": null, "pronunciation": "jìn nián lái", "ipa": "tɕin˥˩ njɛn˧˥ laɪ˧˥", "syllable_count": 3, "sentences": [{"text": "近年来，网上看电影的人多了起来。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家近年来发展得很快。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年来，很多家庭都买了小汽车。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年来，爸爸每天早上都去公园走路。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年来，大学生找工作比以前难了。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她近年来一直在国外工作，很少回家。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年来，这里的天气一年比一年热。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年来，去外国旅游的中国人多了很多。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年来，我们学校开了不少新课。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥近年来很忙，没有时间陪家人。", "target_word": "近年来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "近年來", "label": "繁体"}], "register": "书面", "sense_fingerprint": "从最近几年到现在的这段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5461ebd-d36b-4535-a617-61dd6497bd0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90334, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近年来", "is_correct": true, "explanation": "近年来指从最近几年到现在，与“多了起来”这种渐进变化相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示很少发生，与“人多了起来”的变化相冲突。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”表示马上，不能和“多了起来”这种逐渐变化搭配。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”指有意去做，“人多起来”不是有意做的动作，与句意不符。"}], "explanations": {"近年来": "近年来指从最近几年到现在，与“多了起来”这种渐进变化相符。", "偶尔": "语义：“偶尔”表示很少发生，与“人多了起来”的变化相冲突。", "立刻": "搭配：“立刻”表示马上，不能和“多了起来”这种逐渐变化搭配。", "故意": "语义：“故意”指有意去做，“人多起来”不是有意做的动作，与句意不符。"}, "sentence_index": 0, "correct_answer": "近年来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一个星期，爸爸近年来每天早上都去公园走路。", "explanation": "这里应该用〈近来〉。近年来指最近几年，说这一个星期的情况要用〈近来〉。"}, {"text": "这座桥近年来建于一九五〇年。", "explanation": "这里不能用〈近年来〉。它指离现在最近几年的情况，不能说明一九五〇年这样确定的过去时间。"}, {"text": "秦朝近年来统一了中国。", "explanation": "这里不能用〈近年来〉。它指离现在最近几年，不能用于远古的历史事件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近年来", "is_correct": true, "explanation": "近年来指最近几年，与“一年比一年热”的逐年变化相符。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示从过去到现在一直如此，多用于否定句，不能放在句首说“一年比一年热”的变化。"}, {"text": "立即", "is_correct": false, "explanation": "搭配：“立即”表示马上，不能和“一年比一年”这种渐进的长期变化搭配。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”指一直不变，与“一年比一年热”的逐年变化不符。"}], "explanations": {"近年来": "近年来指最近几年，与“一年比一年热”的逐年变化相符。", "从来": "语义：“从来”表示从过去到现在一直如此，多用于否定句，不能放在句首说“一年比一年热”的变化。", "立即": "搭配：“立即”表示马上，不能和“一年比一年”这种渐进的长期变化搭配。", "始终": "语义：“始终”指一直不变，与“一年比一年热”的逐年变化不符。"}, "sentence_index": 6, "correct_answer": "近年来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我近年来三分钟就做完了作业。", "explanation": "这里不能用〈近年来〉。它指几年的时间段，不能和“三分钟”这样极短的时间同用。"}, {"text": "近年来，你快点去吃饭吧。", "explanation": "这里应该用〈马上〉。句子是催对方立刻去吃饭，要表达“立刻”的意思，而近年来指最近几年，不表示“立刻”。"}, {"text": "他下个月近年来会搬家。", "explanation": "这里不能用〈近年来〉。它指过去到现在的时间段，不能和“下个月”这样的将来时间词同用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
