INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90335, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "降临是从天上来到，或者到来。", "primary_collocate": null, "pronunciation": "jiàng lín", "ipa": "tɕjɑŋ˥˩ lin˧˥", "syllable_count": 2, "sentences": [{"text": "传说神仙会在夜里降临人间。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天使降临在小镇的上空。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外星人降临地球了吗？", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人相信神灵会降临到山顶。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞船安静地降临在沙漠里。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们盼着天使降临。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说中，龙王降临了这个村子。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说昨晚有神降临过这里。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神仙降临时，天空亮了起来。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们站在山上，等着神降临。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "降临了", "label": "体标"}, {"form": "降临过", "label": "体标"}], "register": "书面", "sense_fingerprint": "从天上降下来到，多指神仙、天使、飞船等来到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95593539-6a07-48d3-929c-5995fd291c1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90335, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降临", "is_correct": true, "explanation": "降临表示从天上来到，与“传说神仙会在夜里”的语境相符。"}, {"text": "入侵", "is_correct": false, "explanation": "语义：入侵含有敌对意味，与神仙从天而降的传说语境相冲突。"}, {"text": "撤离", "is_correct": false, "explanation": "语义：撤离表示离开，方向与“降临人间”正好相反。"}, {"text": "飞翔", "is_correct": false, "explanation": "配价：飞翔不能以“人间”作为到达点的宾语，不能表示来到人间。"}], "explanations": {"降临": "降临表示从天上来到，与“传说神仙会在夜里”的语境相符。", "入侵": "语义：入侵含有敌对意味，与神仙从天而降的传说语境相冲突。", "撤离": "语义：撤离表示离开，方向与“降临人间”正好相反。", "飞翔": "配价：飞翔不能以“人间”作为到达点的宾语，不能表示来到人间。"}, "sentence_index": 0, "correct_answer": "降临"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅行团昨晚降临了酒店。", "explanation": "这里应该用〈抵达〉。降临多指神仙、天使、飞船等从天而降，普通旅行团抵达应说抵达。"}, {"text": "他慢慢降临了教室。", "explanation": "这里应该用〈走进〉。降临只用于神灵、天使等从天而降，人走进教室不能说降临。"}, {"text": "树叶慢慢降临在草地上。", "explanation": "这里应该用〈飘落〉。降临指神灵、天使等从天而降，树叶飘落应说飘落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降临", "is_correct": true, "explanation": "降临表示从天上来到，龙王降临村子符合“传说中”的语境。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译的对象是语言或文字，村子不能被翻译。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象应是人或活动，不说“欢迎村子”。"}, {"text": "抄写", "is_correct": false, "explanation": "语义：抄写的对象是文字，村子不能被抄写。"}], "explanations": {"降临": "降临表示从天上来到，龙王降临村子符合“传说中”的语境。", "翻译": "语义：翻译的对象是语言或文字，村子不能被翻译。", "欢迎": "搭配：“欢迎”的对象应是人或活动，不说“欢迎村子”。", "抄写": "语义：抄写的对象是文字，村子不能被抄写。"}, "sentence_index": 6, "correct_answer": "降临"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他骑着马降临到山顶，累得满头大汗。", "explanation": "这里应该用〈登上〉。降临指从天而降或抽象事物到来，骑马上山应说登上。"}, {"text": "我放学后降临到操场，和同学踢球。", "explanation": "这里应该用〈去〉。降临指从天而降或抽象事物到来，学生去操场应说去。"}, {"text": "他从楼上降临到楼下，取了一杯水。", "explanation": "这里应该用〈下楼〉。降临是从天上来到，人从楼上走到楼下应说下楼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "神仙曾经降临了过这座村子。", "corrected_sentence": "神仙曾经降临过这座村子。", "error_description": "体标重复：“降临”后同时用了“了”和“过”，两个体标不能并用。正确形式是“降临过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "神仙会不降临到我们这个小村。", "corrected_sentence": "神仙不会降临到我们这个小村。", "error_description": "否定副词位置错误：“不”应放在助动词“会”前面，正确形式是“不会降临”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
