INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90336, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90336, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "来到，到来。", "primary_collocate": null, "pronunciation": "jiàng lín", "ipa": "tɕjɑŋ˥˩ lin˧˥", "syllable_count": 2, "sentences": [{"text": "夜幕降临了，街上亮起了灯。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天降临了，花都开了。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灾难降临时，大家都很害怕。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好运终于降临到他身上。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜晚降临，村子安静下来。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸福降临在这个小家庭里。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们等着新年降临。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑暗降临了，孩子有点怕。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴风雨降临前，天很闷。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的一年降临了，大家一起倒数。", "target_word": "降临", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "降临了", "label": "体标"}, {"form": "降临过", "label": "体标"}], "register": "书面", "sense_fingerprint": "夜晚、季节、灾难、好运等抽象事物来到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95593539-6a07-48d3-929c-5995fd291c1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90336, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降临", "is_correct": true, "explanation": "降临表示夜幕到来，与“街上亮起了灯”的语境相符。"}, {"text": "离去", "is_correct": false, "explanation": "语义：离去表示离开，与街上亮起灯所说明的夜幕到来相反。"}, {"text": "扩散", "is_correct": false, "explanation": "搭配：扩散多用于气味、疾病、消息，不说“夜幕扩散”。"}, {"text": "清除", "is_correct": false, "explanation": "语义：清除表示除去，与夜幕降临的语境相反。"}], "explanations": {"降临": "降临表示夜幕到来，与“街上亮起了灯”的语境相符。", "离去": "语义：离去表示离开，与街上亮起灯所说明的夜幕到来相反。", "扩散": "搭配：扩散多用于气味、疾病、消息，不说“夜幕扩散”。", "清除": "语义：清除表示除去，与夜幕降临的语境相反。"}, "sentence_index": 0, "correct_answer": "降临"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议终于降临了，大家都坐了下来。", "explanation": "这里应该用〈开始〉。降临指夜晚、灾难、好运等来到，会议开始不能说降临。"}, {"text": "他们终于降临了车站。", "explanation": "这里应该用〈到达〉。降临的主语多是夜晚、灾难、好运等抽象事物，人不能说降临到车站。"}, {"text": "比赛终于降临了，观众都散去了。", "explanation": "这里应该用〈结束〉。降临指来到，比赛结束不能说降临。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降临", "is_correct": true, "explanation": "降临表示新年来到，与“我们等着”的期待语境相符。"}, {"text": "离开", "is_correct": false, "explanation": "语义：离开表示离去，与“等着新年”的期待语境相反。"}, {"text": "搬走", "is_correct": false, "explanation": "配价：搬走要求有形的物体作宾语，新年不能被搬走。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：逃跑表示躲避，新年不会逃跑，这种说法与语境不符。"}], "explanations": {"降临": "降临表示新年来到，与“我们等着”的期待语境相符。", "离开": "语义：离开表示离去，与“等着新年”的期待语境相反。", "搬走": "配价：搬走要求有形的物体作宾语，新年不能被搬走。", "逃跑": "语义：逃跑表示躲避，新年不会逃跑，这种说法与语境不符。"}, "sentence_index": 6, "correct_answer": "降临"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家降临在广场上，一起倒数。", "explanation": "这里应该用〈聚集〉。降临指好运、灾难、夜晚等抽象事物到来，人们在广场聚集不能用降临。"}, {"text": "一个陌生的男人降临了我们面前，大家都很害怕。", "explanation": "这里应该用〈出现〉。降临指好运、灾难等到来，陌生人出现在面前应说出现。"}, {"text": "父亲终于降临家门，妈妈高兴地跑出来。", "explanation": "这里应该用〈回来〉。降临指抽象事物到来，父亲回到家应说回来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋天降临了过，树叶一片片黄了。", "corrected_sentence": "秋天降临了，树叶一片片黄了。", "error_description": "体标重复：“降临”后同时用了“了”和“过”，两个体标不能并用。正确形式是“降临了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暴风雨会不降临到我们村。", "corrected_sentence": "暴风雨不会降临到我们村。", "error_description": "否定副词位置错误：“不”应放在助动词“会”前面，正确形式是“不会降临”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
