INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90337, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "创建是把一个新的东西做出来，比如新学校、新商店。", "primary_collocate": null, "pronunciation": "chuàng jiàn", "ipa": "tʂʰuɑŋ˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他在小城里创建了第一所新学校。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐想在这条街上创建一家小商店。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们几个同学创建了一个读书小组。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先创建一个新账号，再登录网站。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用电脑创建了一个新文件夹。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要创建一个学生音乐社团。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就想创建自己的小公司。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷当年创建过一家小工厂。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起创建了一个爱心网站。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以在手机上创建一个微信群。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "创建了", "label": "完成体"}, {"form": "创建过", "label": "经历体"}, {"form": "创建者", "label": "复合词"}], "register": "中性", "sense_fingerprint": "创建：把新学校、新商店、新账号等新东西做出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc92a6b-6dc2-4a5f-9877-7bf97a1744bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90337, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创建", "is_correct": true, "explanation": "创建：开始建立一所新的学校，与句意相符。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：「拆除」指拆掉已有的建筑，与「第一所新学校」的意思相反。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：「擦」用于擦拭表面或污渍，不能说擦一所学校。"}, {"text": "派遣", "is_correct": false, "explanation": "配价：「派遣」的宾语应是人，如派人去，不能派遣一所学校。"}], "explanations": {"创建": "创建：开始建立一所新的学校，与句意相符。", "拆除": "语义：「拆除」指拆掉已有的建筑，与「第一所新学校」的意思相反。", "擦": "搭配：「擦」用于擦拭表面或污渍，不能说擦一所学校。", "派遣": "配价：「派遣」的宾语应是人，如派人去，不能派遣一所学校。"}, "sentence_index": 0, "correct_answer": "创建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位作曲家创建了一首新歌。", "explanation": "这里应该用〈谱写〉。创建指建立机构、账号等新事物；乐曲这类作品要用谱写。"}, {"text": "工人们创建了一辆新汽车。", "explanation": "这里应该用〈组装〉。创建指建立机构、账号等新事物；汽车这类由零件拼成的机器要用组装。"}, {"text": "这位画家创建了一幅名画。", "explanation": "这里应该用〈创作〉。画作、诗文等艺术作品要用创作；创建指建立机构、账号等新事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90337, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创建", "is_correct": true, "explanation": "创建：想建立自己的公司，与句意相符。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：「喂」的宾语多是人或动物，不能用来指一家公司。"}, {"text": "鼓励", "is_correct": false, "explanation": "配价：「鼓励」的对象应是人，不能说鼓励一家公司。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：「浇」用于给植物或土地灌水，不能用于公司。"}], "explanations": {"创建": "创建：想建立自己的公司，与句意相符。", "喂": "搭配：「喂」的宾语多是人或动物，不能用来指一家公司。", "鼓励": "配价：「鼓励」的对象应是人，不能说鼓励一家公司。", "浇": "搭配：「浇」用于给植物或土地灌水，不能用于公司。"}, "sentence_index": 6, "correct_answer": "创建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们创建了一条通往山顶的小路。", "explanation": "这里应该用〈修建〉。创建用于机构、账号等新事物；道路、桥梁这类工程要用修建。"}, {"text": "这位厨师创建了一道新菜。", "explanation": "这里应该用〈推出〉。创建指建立机构、账号等新事物；新菜式、新产品要用推出。"}, {"text": "学校准备创建一场运动会。", "explanation": "这里应该用〈举办〉。运动会、比赛这类活动要用举办；创建用于新建机构或账号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90337, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校去年创建的一个机器人社团。", "corrected_sentence": "学校去年创建了一个机器人社团。", "error_description": "结构助词错误：「创建」后面缺少谓语，应用动态助词「了」表示完成，不能用「的」。「学校去年创建的一个机器人社团」只是一个名词短语，不成句；应改为「学校去年创建了一个机器人社团」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90337, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所小学在操场边没创建了一个小花园。", "corrected_sentence": "这所小学在操场边创建了一个小花园。", "error_description": "否定与体标错误：「没」表示未发生，不能和「了」同用。「没创建了」是错误的，否定应说「没创建」；肯定句则应说「创建了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
