INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90338, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "首次建立或开创。", "primary_collocate": null, "pronunciation": "chuàng jiàn", "ipa": "tʂʰuɑŋ˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这所大学创建于一百年前。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孙中山创建了中华民国。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授创建了国内第一个考古研究所。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在一九五〇年创建了这家报社。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市是古人在河边创建的。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李老先生创建了这个学会，已有三十年。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府创建了一个新的研究中心。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家出版社创建以来，出过很多好书。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生创建过三所医院。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司创建的第一年，只有五个人。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "创建了", "label": "完成体"}, {"form": "创建过", "label": "经历体"}, {"form": "创建者", "label": "复合词"}], "register": "书面", "sense_fingerprint": "创建：首次建立或开创机构、学校、城市等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc92a6b-6dc2-4a5f-9877-7bf97a1744bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创建", "is_correct": true, "explanation": "创建：首次建立这所大学，与「一百年前」的开办时间相符。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：「出版」用于书籍、报刊，不能用于大学。"}, {"text": "出生", "is_correct": false, "explanation": "配价：「出生」的主语应是人或动物，大学不能出生。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：「发表」用于文章、言论，不能用来说大学的成立。"}], "explanations": {"创建": "创建：首次建立这所大学，与「一百年前」的开办时间相符。", "出版": "搭配：「出版」用于书籍、报刊，不能用于大学。", "出生": "配价：「出生」的主语应是人或动物，大学不能出生。", "发表": "搭配：「发表」用于文章、言论，不能用来说大学的成立。"}, "sentence_index": 0, "correct_answer": "创建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在一九五〇年创建了这座大桥。", "explanation": "这里应该用〈修建〉。创建指首次建立机构或城市；桥梁这类实体工程要用修建。"}, {"text": "他们在一九五〇年创建了这部小说。", "explanation": "这里应该用〈写〉。创建用于建立机构或城市；小说是写出来的作品，应说写。"}, {"text": "他们在一九五〇年创建了这只船。", "explanation": "这里应该用〈造〉。创建用于建立机构或城市；船只这类器物要用造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创建", "is_correct": true, "explanation": "创建：首次建立了这个研究中心，与句意相符。"}, {"text": "出生", "is_correct": false, "explanation": "配价：「出生」不带宾语，主语应是人或动物，不能说出生一个研究中心。"}, {"text": "派遣", "is_correct": false, "explanation": "配价：「派遣」的宾语应是人，不能派遣一个研究中心。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：「摔」常用于杯子、东西等，不能用来指建立研究中心。"}], "explanations": {"创建": "创建：首次建立了这个研究中心，与句意相符。", "出生": "配价：「出生」不带宾语，主语应是人或动物，不能说出生一个研究中心。", "派遣": "配价：「派遣」的宾语应是人，不能派遣一个研究中心。", "摔": "搭配：「摔」常用于杯子、东西等，不能用来指建立研究中心。"}, "sentence_index": 6, "correct_answer": "创建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位工程师创建了一种新型发动机。", "explanation": "这里应该用〈研制〉。创建指建立机构或账号等；发动机这类技术产品要用研制。"}, {"text": "这位画家创建了一座新房子。", "explanation": "这里应该用〈建造〉。创建用于建立机构、账号等；房子这类建筑要用建造。"}, {"text": "孩子们在草地上创建了一个沙堡。", "explanation": "这里应该用〈堆〉。创建用于建立机构或城市；沙堡是堆出来的，应说堆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个协会创建了于上世纪三十年代。", "corrected_sentence": "这个协会创建于上世纪三十年代。", "error_description": "动态助词错误：「创建于」表示创建的时间，「创建」和「于」之间不能加「了」，应说「创建于上世纪三十年代」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学院创建了以来，培养了很多人才。", "corrected_sentence": "这所学院创建以来，培养了很多人才。", "error_description": "动态助词错误：「创建以来」是固定的时间表达，「创建」之后不能加「了」，应说「创建以来」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90339, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "收：接受、收下别人给的东西，与“送给”（把东西赠与他人）构成反义。"}, {"text": "站", "is_correct": false, "explanation": "站：站立，与“送给”不构成反义关系。"}, {"text": "藏", "is_correct": false, "explanation": "藏：隐藏，与“送给”不构成反义关系。"}, {"text": "转", "is_correct": false, "explanation": "转：转动，与“送给”不构成反义关系。"}], "correct_answer": "收", "explanations": {"收": "收：接受、收下别人给的东西，与“送给”（把东西赠与他人）构成反义。", "站": "站：站立，与“送给”不构成反义关系。", "藏": "藏：隐藏，与“送给”不构成反义关系。", "转": "转：转动，与“送给”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90339, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "收：接受、收下别人给的东西，与“送给”（把东西赠与他人）构成反义。"}, {"text": "跑", "is_correct": false, "explanation": "跑：快速移动，与“送给”不构成反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱：发出乐音，与“送给”不构成反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑：面部表情或发声，与“送给”不构成反义关系。"}], "correct_answer": "收", "explanations": {"收": "收：接受、收下别人给的东西，与“送给”（把东西赠与他人）构成反义。", "跑": "跑：快速移动，与“送给”不构成反义关系。", "唱": "唱：发出乐音，与“送给”不构成反义关系。", "笑": "笑：面部表情或发声，与“送给”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90339, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西拿给别人，不要钱，当作礼物。", "primary_collocate": null, "pronunciation": "sòng gěi", "ipa": "soŋ˥˩ kei˨˩˦", "syllable_count": 2, "sentences": [{"text": "我把这本书送给了朋友。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日那天，妈妈送给我一块手表。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把这束花送给老师。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我送给你的新年礼物。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王送给我一盒茶叶。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我送给奶奶一条红围巾。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己做的蛋糕送给了邻居。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们送给老师一张卡片。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想送给他什么礼物？", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送给过我一本词典。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "送给了", "label": "完成体"}, {"form": "送给过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "把东西当作礼物免费给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad8dbc6-820a-4e36-a32d-a214082bc3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90339, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骗", "is_correct": false, "explanation": "语义：“骗”指欺骗，与“把书给朋友”的赠予义不合。"}, {"text": "送给", "is_correct": true, "explanation": "送给：把东西当作礼物给别人，与“把这本书”和“朋友”搭配。"}, {"text": "问", "is_correct": false, "explanation": "搭配：“问”的对象是问题或人，不能与“这本书”搭配表示赠予。"}, {"text": "抢", "is_correct": false, "explanation": "语义：“抢”是夺取，与免费赠予的意思相反。"}], "explanations": {"骗": "语义：“骗”指欺骗，与“把书给朋友”的赠予义不合。", "送给": "送给：把东西当作礼物给别人，与“把这本书”和“朋友”搭配。", "问": "搭配：“问”的对象是问题或人，不能与“这本书”搭配表示赠予。", "抢": "语义：“抢”是夺取，与免费赠予的意思相反。"}, "sentence_index": 0, "correct_answer": "送给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把旧手机送给了同学，还收了他一百块钱。", "explanation": "这里应该用〈卖给〉。“送给”表示免费赠与，不能同时收钱，收钱的买卖要用“卖给”。"}, {"text": "我把作业送给了老师，还要老师把它还给我。", "explanation": "这里应该用〈交给〉。作业是上交的，不是赠与；后半句“还给我”又与“送给”的白白赠与相矛盾。"}, {"text": "这台电脑我送给了他，他付了我两千块钱。", "explanation": "这里应该用〈卖给〉。“送给”是免费赠与，对方付了钱就是买卖，应该说“卖给”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90339, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夸", "is_correct": false, "explanation": "搭配：“夸”的对象是人，不能说“把蛋糕夸了邻居”，也不表示赠予。"}, {"text": "收", "is_correct": false, "explanation": "语义：“收”指接受或收取，与“把蛋糕给邻居”的赠予义相反。"}, {"text": "送给", "is_correct": true, "explanation": "送给：把东西当作礼物给别人，与“把自己做的蛋糕”和“邻居”搭配。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”指加热制作食物，与赠予的意思无关。"}], "explanations": {"夸": "搭配：“夸”的对象是人，不能说“把蛋糕夸了邻居”，也不表示赠予。", "收": "语义：“收”指接受或收取，与“把蛋糕给邻居”的赠予义相反。", "送给": "送给：把东西当作礼物给别人，与“把自己做的蛋糕”和“邻居”搭配。", "烤": "语义：“烤”指加热制作食物，与赠予的意思无关。"}, "sentence_index": 6, "correct_answer": "送给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学送给我一支笔，说好下周还给他。", "explanation": "这里应该用〈借给〉。“送给”是赠与，不能约定归还，借东西才会说还。"}, {"text": "他终于把欠我的钱送给了我。", "explanation": "这里应该用〈还给〉。欠款是要偿还的，“送给”是白送，不能用于归还。"}, {"text": "他把旧衣服送给了垃圾箱。", "explanation": "这里应该用〈扔进〉。送给的对象应是人，垃圾箱不能接受赠与；这里是丢弃，不是赠与。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90339, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这份礼物送给给了同学。", "corrected_sentence": "我把这份礼物送给了同学。", "error_description": "多写了一个“给”：“送给”是固定动词，“给”只出现一次，应删去重复的“给”，写作“送给了同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90339, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们送给老师了一张卡片。", "corrected_sentence": "孩子们送给老师一张卡片。", "error_description": "多了一个“了”：“送给”后面接人和东西两个宾语时，“了”不能插在“老师”和“一张卡片”之间，应删去这个“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
