INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90340, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把物品赠与他人。", "primary_collocate": null, "pronunciation": "sòng gěi", "ipa": "soŋ˥˩ kei˨˩˦", "syllable_count": 2, "sentences": [{"text": "爷爷把旧自行车送给了邻居的孩子。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司送给每位客人一份小礼品。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画是画家送给学校的。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把多余的衣服送给需要的人。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她送给同学一支漂亮的笔。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友从日本回来，送给我一个小玩偶。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叔叔送给弟弟一个足球。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把那块玉送给了女朋友。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁送给你这束花？", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板送给我们每人一盒月饼。", "target_word": "送给", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "送给了", "label": "完成体"}, {"form": "送给过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "把物品赠与他人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad8dbc6-820a-4e36-a32d-a214082bc3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象不能是“旧自行车”，句中无法表示赠予。"}, {"text": "夺", "is_correct": false, "explanation": "语义：“夺”是抢夺，与赠予的意思相反。"}, {"text": "送给", "is_correct": true, "explanation": "送给：把东西当作礼物给予，与“旧自行车”和“邻居的孩子”搭配。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”的对象是车或动物，不能用于人，不表示赠予。"}], "explanations": {"唱": "搭配：“唱”的对象不能是“旧自行车”，句中无法表示赠予。", "夺": "语义：“夺”是抢夺，与赠予的意思相反。", "送给": "送给：把东西当作礼物给予，与“旧自行车”和“邻居的孩子”搭配。", "骑": "搭配：“骑”的对象是车或动物，不能用于人，不表示赠予。"}, "sentence_index": 0, "correct_answer": "送给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把房子送给了同学，每个月还收他的租金。", "explanation": "这里应该用〈租给〉。“送给”是免费赠与，不能一边送一边收租金。"}, {"text": "他捡到的钱，都送给了警察，还要警察把钱还给他。", "explanation": "这里应该用〈上交〉。捡到的钱要交给公安，不是赠与；后半句“还给他”又与“送给”的白白赠与相矛盾。"}, {"text": "他把烂苹果送给了河里。", "explanation": "这里应该用〈扔进〉。送给的对象应是人，河里不能接受赠与；这里是丢弃，不是赠与。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骂", "is_correct": false, "explanation": "搭配：“骂”的对象是人，不能与“一个足球”搭配表示赠予。"}, {"text": "罚", "is_correct": false, "explanation": "语义：“罚”指惩处，与赠予的意思相反。"}, {"text": "送给", "is_correct": true, "explanation": "送给：把东西当作礼物给予，与“叔叔”“弟弟”和“一个足球”搭配。"}, {"text": "劝", "is_correct": false, "explanation": "语义：“劝”指说服或规劝，与“给弟弟一个足球”的赠予义不合。"}], "explanations": {"骂": "搭配：“骂”的对象是人，不能与“一个足球”搭配表示赠予。", "罚": "语义：“罚”指惩处，与赠予的意思相反。", "送给": "送给：把东西当作礼物给予，与“叔叔”“弟弟”和“一个足球”搭配。", "劝": "语义：“劝”指说服或规劝，与“给弟弟一个足球”的赠予义不合。"}, "sentence_index": 6, "correct_answer": "送给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他借了我的书包，用完却把它送给了我。", "explanation": "这里应该用〈还给〉。书包本是我的，借后归还是“还给”，“送给”是赠与，不能用于此。"}, {"text": "老师把课本送给了我们，下课后要收回。", "explanation": "这里应该用〈借给〉。“送给”是赠与，不能约定收回，借东西才会说收回。"}, {"text": "这双鞋不合适，我把它送给了商店，还要求商店退钱。", "explanation": "这里应该用〈退给〉。退货是把东西还回去并要求退款；“送给”是白白赠与，且后半句“要求退钱”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这台旧电脑送给了了表弟。", "corrected_sentence": "我把这台旧电脑送给了表弟。", "error_description": "多写了一个“了”：“送给了”后面只需一个“了”，应删去重复的“了”，写作“送给了表弟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把那条围巾送给着好朋友。", "corrected_sentence": "她把那条围巾送给了好朋友。", "error_description": "“着”表示持续状态，不能用于已完成的赠与动作，应改为动态助词“了”：“送给了好朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
