INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90341, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90341, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "难怪是知道原因以后，觉得不奇怪了。", "primary_collocate": null, "pronunciation": "nán guài", "ipa": "nan˧˥ kwaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他昨晚没睡，难怪今天这么累。", "target_word": "难怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难怪你这么高兴，原来明天放假。", "target_word": "难怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下雪了，难怪这么冷。", "target_word": "难怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难怪她汉语说得好，她在北京住过。", "target_word": "难怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原来他是老师的儿子，难怪这么聪明。", "target_word": "难怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难怪路上这么堵，前面出事故了。", "target_word": "难怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一天只吃一顿饭，难怪这么瘦。", "target_word": "难怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难怪没人接电话，他们都出去了。", "target_word": "难怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你没带伞啊，难怪衣服都湿了。", "target_word": "难怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难怪他不来，他今天要加班。", "target_word": "难怪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "知道原因后，对结果不再感到奇怪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4f307f-eef1-48f7-ab9e-281d3bff4d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90341, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "难怪", "is_correct": true, "explanation": "难怪表示明白了原因（昨晚没睡），对今天很累不再觉得奇怪，与句意一致。"}, {"text": "却", "is_correct": false, "explanation": "语义：却表示转折，但没睡导致累是顺理成章的因果关系，不构成转折。"}, {"text": "反而", "is_correct": false, "explanation": "搭配：反而要求前文有相反的预期，这里前后是因果关系，不能搭配。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：幸好表示庆幸的结果，累不是值得庆幸的事。"}], "explanations": {"难怪": "难怪表示明白了原因（昨晚没睡），对今天很累不再觉得奇怪，与句意一致。", "却": "语义：却表示转折，但没睡导致累是顺理成章的因果关系，不构成转折。", "反而": "搭配：反而要求前文有相反的预期，这里前后是因果关系，不能搭配。", "幸好": "语义：幸好表示庆幸的结果，累不是值得庆幸的事。"}, "sentence_index": 0, "correct_answer": "难怪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我还不知道他为什么哭，难怪他哭了。", "explanation": "难怪要求说话人已经知道原因。这里说“还不知道”，前后矛盾，应改用〈原来〉表示刚发现原因。"}, {"text": "他考了满分，难怪他很伤心。", "explanation": "难怪要求前面的原因能解释后面的结果。考了满分不能解释“很伤心”，所以这里不能用“难怪”；可以说“他考了满分，难怪他很高兴”。"}, {"text": "他一直很努力，难怪他没考上。", "explanation": "这里应该用〈却〉或〈居然〉表示出乎意料。难怪只能解释原因与结果相符的情况，“很努力”无法解释“没考上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90341, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "难怪", "is_correct": true, "explanation": "难怪表示明白了原因（一天只吃一顿饭），对他很瘦不再觉得奇怪。"}, {"text": "反而", "is_correct": false, "explanation": "搭配：反而要求前文有相反的预期，“只吃一顿饭”与“瘦”是顺理成章的关系，不构成反预期。"}, {"text": "甚至", "is_correct": false, "explanation": "搭配：甚至要求前文有出人意料的极端情况，这里没有这样的语境。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：偏偏表示与预期相反或故意作对，这里前后是顺理成章的因果关系。"}], "explanations": {"难怪": "难怪表示明白了原因（一天只吃一顿饭），对他很瘦不再觉得奇怪。", "反而": "搭配：反而要求前文有相反的预期，“只吃一顿饭”与“瘦”是顺理成章的关系，不构成反预期。", "甚至": "搭配：甚至要求前文有出人意料的极端情况，这里没有这样的语境。", "偏偏": "语义：偏偏表示与预期相反或故意作对，这里前后是顺理成章的因果关系。"}, "sentence_index": 6, "correct_answer": "难怪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "难怪你快去写作业！", "explanation": "这里应该用〈赶快〉表示催促。难怪只用于叙述已知原因后不再感到奇怪，不能用于命令。"}, {"text": "我以为他是外国人，难怪他是中国人。", "explanation": "这里应该用〈原来〉，表示发现与想象不同的事实。难怪只用于解释已知的结果，不能用来引出与预期相反的情况。"}, {"text": "明天下雨，难怪今天很冷。", "explanation": "难怪与〈因为〉不同：难怪只能用于已知且已发生的原因，“明天下雨”尚未发生，不能解释“今天很冷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90341, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他带钥匙，难怪进不了门。", "corrected_sentence": "他没带钥匙，难怪进不了门。", "error_description": "错误：“难怪”要求前面的原因能解释结果。“带钥匙”无法解释“进不了门”，应说“没带钥匙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90341, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他带了手机，难怪我们联系不上他。", "corrected_sentence": "他没带手机，难怪我们联系不上他。", "error_description": "错误：“难怪”要求前面的原因能解释后面的结果。“带了手机”无法解释“联系不上他”，应说“没带手机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
