INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90343, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "受害者是被坏人或坏事弄伤、弄痛的人。", "primary_collocate": null, "pronunciation": "shòu hài zhě", "ipa": "ʂoʊ˥˩ xaɪ˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "警察把受害者送到了医院。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受害者的腿受了重伤。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生正在检查受害者的伤。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受害者躺在地上，不能动。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次火灾有三个受害者。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问受害者当时看见了什么。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受害者的头上流了很多血。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们去医院看望受害者。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受害者说他的手很痛。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救护车来得很快，受害者没有危险。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "在事故或暴力中身体受伤的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2d745d-2bca-4b89-8b23-ae7e91d17958') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90343, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气不是人，不能被警察“送到医院”。"}, {"text": "受害者", "is_correct": true, "explanation": "受害者：遭受伤害的人，可以被警察送到医院，与句中的“把……送到了医院”搭配。"}, {"text": "伤势", "is_correct": false, "explanation": "搭配：“伤势”是伤的情况，不能用“把……送到医院”来说。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜不是遭受伤害的人，不能成为被送医的对象。"}], "explanations": {"空气": "语义：空气不是人，不能被警察“送到医院”。", "受害者": "受害者：遭受伤害的人，可以被警察送到医院，与句中的“把……送到了医院”搭配。", "伤势": "搭配：“伤势”是伤的情况，不能用“把……送到医院”来说。", "蔬菜": "语义：蔬菜不是遭受伤害的人，不能成为被送医的对象。"}, "sentence_index": 0, "correct_answer": "受害者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法庭判决了受害者三年监禁。", "explanation": "这里应该用〈加害者〉，指造成伤害的人；“受害者”是被伤害的人，不会被判刑入狱。"}, {"text": "受害者已经被警方拘留。", "explanation": "这里应该用〈肇事者〉，指造成事故的人；“受害者”是遭受伤害的人，不会被警方拘留。"}, {"text": "这个受害者杀害了三个人。", "explanation": "这里应该用〈凶手〉，指杀人的人；“受害者”是遭受伤害的人，不会去杀人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90343, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墙", "is_correct": false, "explanation": "语义：墙不会流血，句子说的是有头部的人受伤。"}, {"text": "受害者", "is_correct": true, "explanation": "受害者：受伤的人，头上可以流血，与“流了很多血”搭配。"}, {"text": "树", "is_correct": false, "explanation": "语义：树没有头，也不会流血，不能说“树的头上流了血”。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“流血”的主语须是有生命的人或动物，不能说石头流血。"}], "explanations": {"墙": "语义：墙不会流血，句子说的是有头部的人受伤。", "受害者": "受害者：受伤的人，头上可以流血，与“流了很多血”搭配。", "树": "语义：树没有头，也不会流血，不能说“树的头上流了血”。", "石头": "搭配：“流血”的主语须是有生命的人或动物，不能说石头流血。"}, "sentence_index": 6, "correct_answer": "受害者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这名受害者开车撞伤了三个行人。", "explanation": "这里应该用〈肇事者〉，指造成事故、伤了别人的人；“受害者”是被伤害的人，不是撞伤别人的人。"}, {"text": "警方抓到的是这次抢劫的受害者。", "explanation": "这里应该用〈施害者〉，指实施抢劫的人；“受害者”是被伤害的人，不是被抓的对象。"}, {"text": "这个受害者被罚了五千块钱。", "explanation": "这里应该用〈违法者〉，指违反法律的人；“受害者”是遭受伤害的人，不会因违法被罚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90343, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我认识一只受害者。", "corrected_sentence": "我认识一位受害者。", "error_description": "量词错误：“只”多用于动物，指人应用“位”，应说“一位受害者”，不能说“一只受害者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90343, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次地震有两只受害者。", "corrected_sentence": "这次地震有两名受害者。", "error_description": "量词错误：“只”多用于动物，指人应用“名”，应说“两名受害者”，不能说“两只受害者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
