INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90344, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "遭受侵害、损失或伤害的人。", "primary_collocate": null, "pronunciation": "shòu hài zhě", "ipa": "ʂoʊ˥˩ xaɪ˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这次骗局有很多受害者。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受害者损失了五万块钱。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察帮受害者要回了钱。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上诈骗的受害者越来越多。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这次地震的受害者。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受害者的家人要求公开道歉。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司让受害者得到了赔偿。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多老人成了电话诈骗的受害者。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受害者把经过告诉了律师。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的污染有很多受害者。", "target_word": "受害者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "在诈骗、灾害、污染等事件中遭受损失或伤害的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2d745d-2bca-4b89-8b23-ae7e91d17958') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是遭受损失的人，“骗局有很多钥匙”说不通。"}, {"text": "受害者", "is_correct": true, "explanation": "受害者：在骗局中遭受损失的人，与“骗局”和“很多”搭配。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“很多”修饰的是可数的人或物，“天气”不能这样修饰。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是人，不能成为骗局的受害对象。"}], "explanations": {"钥匙": "语义：钥匙不是遭受损失的人，“骗局有很多钥匙”说不通。", "受害者": "受害者：在骗局中遭受损失的人，与“骗局”和“很多”搭配。", "天气": "搭配：“很多”修饰的是可数的人或物，“天气”不能这样修饰。", "花园": "语义：花园不是人，不能成为骗局的受害对象。"}, "sentence_index": 0, "correct_answer": "受害者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这起骗局的受害者已经被判刑。", "explanation": "这里应该用〈加害者〉，指造成伤害的人；“受害者”是被骗的人，不会被判刑。"}, {"text": "受害者用假身份骗了很多老人。", "explanation": "这里应该用〈诈骗犯〉，指实施诈骗的人；“受害者”是被骗的人，不会去骗人。"}, {"text": "受害者被罚了五千元。", "explanation": "这里应该用〈违法者〉，指违反法律的人；“受害者”是遭受伤害的人，不会因违法被罚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会得到赔偿，“让……得到赔偿”的对象须是人。"}, {"text": "受害者", "is_correct": true, "explanation": "受害者：可以得到赔偿的人，与“得到赔偿”搭配。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不能得到赔偿，句子说的是人。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“数字”不能“得到赔偿”，搭配不当。"}], "explanations": {"石头": "语义：石头不会得到赔偿，“让……得到赔偿”的对象须是人。", "受害者": "受害者：可以得到赔偿的人，与“得到赔偿”搭配。", "太阳": "语义：太阳不能得到赔偿，句子说的是人。", "数字": "搭配：“数字”不能“得到赔偿”，搭配不当。"}, "sentence_index": 6, "correct_answer": "受害者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场骗局的受害者被判了无期徒刑。", "explanation": "这里应该用〈策划者〉，指策划骗局的人；“受害者”是被骗的人，不会被判刑。"}, {"text": "警方抓获了诈骗案的受害者。", "explanation": "这里应该用〈施害者〉，指实施诈骗的人；“受害者”是被骗的人，不是被抓的对象。"}, {"text": "这个受害者三次被警告，仍然不收手。", "explanation": "这里应该用〈诈骗者〉，指实施诈骗的人；“受害者”是被骗的人，不会因不收手而被警告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只受害者。", "corrected_sentence": "他是一位受害者。", "error_description": "量词错误：“受害者”指人，量词应用“位”，“只”多用于动物，不能说“一只受害者”，应说“一位受害者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次诈骗有两只受害者。", "corrected_sentence": "这次诈骗有两名受害者。", "error_description": "量词错误：“只”多用于动物，指人应用“名”，应说“两名受害者”，不能说“两只受害者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
