INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90345, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人去世后留下来的东西或钱。", "primary_collocate": null, "pronunciation": "yí chǎn", "ipa": "i˧˥ ʈʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "爷爷去世后，留下了一笔遗产。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他父亲的遗产有一套房子和一些钱。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人没有孩子，遗产给了他的侄子。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用母亲留下的遗产开了一家小店。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟两人为了遗产吵了起来。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不要父母的遗产，想自己赚钱。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师正在帮大家分遗产。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人把所有遗产都捐给了学校。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他继承了叔叔的遗产。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从没想过要拿父亲的遗产。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔遗产", "label": "量词"}, {"form": "一份遗产", "label": "量词"}, {"form": "遺產", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人去世后留给家人的钱和财物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '624b5296-b316-469e-b898-2490f7fe2795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90345, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遗产", "is_correct": true, "explanation": "正确。「一笔」与「遗产」搭配，指人去世后留下的钱或财物，符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词「笔」用于钱款，不能说「一笔房子」，应说「一套房子」。"}, {"text": "故事", "is_correct": false, "explanation": "语义：去世后留下的应是钱财，「故事」不属于遗产的范畴，句意不通。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是个人用品，不能用「一笔」计量，也不符合「留下财产」的意思。"}], "explanations": {"遗产": "正确。「一笔」与「遗产」搭配，指人去世后留下的钱或财物，符合句意。", "房子": "搭配：量词「笔」用于钱款，不能说「一笔房子」，应说「一套房子」。", "故事": "语义：去世后留下的应是钱财，「故事」不属于遗产的范畴，句意不通。", "眼镜": "语义：眼镜是个人用品，不能用「一笔」计量，也不符合「留下财产」的意思。"}, "sentence_index": 0, "correct_answer": "遗产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天背诵祖父的遗产，努力做人。", "explanation": "这里应该用〈遗训〉。能背诵的是教导的话，遗产是钱和财物，不能背诵。"}, {"text": "大家在大厅里向老人的遗产告别。", "explanation": "这里应该用〈遗体〉。向去世的人告别时面对的是遗体，遗产是留下的钱和财物，不能「告别」。"}, {"text": "爷爷临终前写下了遗产。", "explanation": "这里应该用〈遗嘱〉。写下的是遗嘱这种文件，遗产是留下的财物，不能「写下」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90345, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遗产", "is_correct": true, "explanation": "正确。「分」的对象是遗产，指按继承人分配死者留下的财物，符合句意。"}, {"text": "方向", "is_correct": false, "explanation": "语义：「分」用于分配物品，「方向」不能被分配，不符合句意。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：「分」不与「脚步」搭配，人们不说「分脚步」。"}, {"text": "影子", "is_correct": false, "explanation": "语义：「影子」是光线形成的影像，不能作为分配的对象。"}], "explanations": {"遗产": "正确。「分」的对象是遗产，指按继承人分配死者留下的财物，符合句意。", "方向": "语义：「分」用于分配物品，「方向」不能被分配，不符合句意。", "脚步": "搭配：「分」不与「脚步」搭配，人们不说「分脚步」。", "影子": "语义：「影子」是光线形成的影像，不能作为分配的对象。"}, "sentence_index": 6, "correct_answer": "遗产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父亲的遗产很安详，大家都来告别。", "explanation": "这里应该用〈遗容〉。「安详」形容的是人的神态，遗产是财物，不能这样用。"}, {"text": "父亲的遗产一直是我的座右铭。", "explanation": "这里应该用〈遗言〉。「座右铭」是用来勉励自己的话，遗产是财物，不能这样用。"}, {"text": "他终于完成了父亲的遗产。", "explanation": "这里应该用〈遗愿〉。「完成」的对象是心愿或任务，遗产是财物，不能「完成」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90345, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸留下了一位遗产，我们很感激。", "corrected_sentence": "爸爸留下了一份遗产，我们很感激。", "error_description": "错误形式「留下了一位遗产」；正确形式「留下了一份遗产」。「位」是用于人的量词，「遗产」不是人，应使用「份」或「笔」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90345, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经继承过父亲的一位遗产。", "corrected_sentence": "他曾经继承过父亲的一份遗产。", "error_description": "错误形式「一位遗产」；正确形式「一份遗产」。「位」用于人，「遗产」应使用「份」，此处应说「一份遗产」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
