INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90347, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "难当是说（某种感受）让人受不了。", "primary_collocate": null, "pronunciation": "nán dāng", "ipa": "nan˧˥ tɑŋ˥", "syllable_count": 2, "sentences": [{"text": "今天热得难当，我们躲在家里不出门。", "target_word": "难当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牙疼得厉害，他痛苦难当。", "target_word": "难当", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听到这个消息，她悲痛难当。", "target_word": "难当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试没通过，他羞愧难当。", "target_word": "难当", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "走了一天山路，我们饥渴难当。", "target_word": "难当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "伤口疼痛难当，医生马上给他打了针。", "target_word": "难当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孤独难当的时候，她就给妈妈打电话。", "target_word": "难当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天的太阳晒得人燥热难当。", "target_word": "难当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想到自己做错的事，内心愧疚难当。", "target_word": "难当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看着孩子生病，妈妈心里焦急难当。", "target_word": "难当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "难当：担不起、受不了，多用在痛苦、羞愧、饥渴、酷热等感受之后作补充", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20f9c372-ecc3-4b34-9028-39b875025280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90347, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "难当", "is_correct": true, "explanation": "正确：“难当”表示受不了，符合“热得……”的补充结构。"}, {"text": "凉快", "is_correct": false, "explanation": "语义：凉快与“热”相反，句意矛盾。"}, {"text": "安静", "is_correct": false, "explanation": "语义：安静说声音或环境，不能用来形容天气的热。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”不与“热得”搭配，热的程度不能说清楚。"}], "explanations": {"难当": "正确：“难当”表示受不了，符合“热得……”的补充结构。", "凉快": "语义：凉快与“热”相反，句意矛盾。", "安静": "语义：安静说声音或环境，不能用来形容天气的热。", "清楚": "搭配：“清楚”不与“热得”搭配，热的程度不能说清楚。"}, "sentence_index": 0, "correct_answer": "难当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题难当，我做了一个小时。", "explanation": "这里应该用〈难做〉。“难当”说承受不了或担不起，多指痛苦、羞愧、饥渴等难受的感受，不表示事情难做。"}, {"text": "最近身体不舒服，他的难当很厉害。", "explanation": "这里应该用〈难受〉。“难当”是形容词，不能加“的”当名词用；表示身体不舒服，应说“他很难受”。"}, {"text": "他开心得难当，唱歌跳舞了一整晚。", "explanation": "这里应该用〈欣喜〉。难当说承受不了，多指痛苦、羞愧、饥渴等难受的感受，不能形容开心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90347, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "难当", "is_correct": true, "explanation": "正确：“难当”表示受不了，与“孤独”的感受搭配，符合句意。"}, {"text": "难看", "is_correct": false, "explanation": "语义：“难看”说外表或样子，不能形容“孤独”。"}, {"text": "清爽", "is_correct": false, "explanation": "语义：清爽说凉快干净的感觉，不能用来形容孤独。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌，不能与“孤独”组合。"}], "explanations": {"难当": "正确：“难当”表示受不了，与“孤独”的感受搭配，符合句意。", "难看": "语义：“难看”说外表或样子，不能形容“孤独”。", "清爽": "语义：清爽说凉快干净的感觉，不能用来形容孤独。", "漂亮": "搭配：“漂亮”形容外貌，不能与“孤独”组合。"}, "sentence_index": 6, "correct_answer": "难当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个会议室大得难当，大家在里面很舒服。", "explanation": "这里应该用〈宽敞〉。“难当”说承受不了，不表示空间大；形容房间大而舒适时用“宽敞”。"}, {"text": "这台电脑难当，我一天就把它修好了。", "explanation": "这里应该用〈难修〉。“难当”说难以担当或承受，不表示机器难修。"}, {"text": "这次旅行难当，大家都玩得很尽兴。", "explanation": "这里应该用〈精彩〉。“难当”说承受不了，不能用来形容旅行精彩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里的夏天热地难当。", "corrected_sentence": "这里的夏天热得难当。", "error_description": "错误：“热”和“难当”之间用了“地”，应为“得”。“得”引出补语，表示程度；“地”用于状语，不能接在补语前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子摔伤了，疼地难当，哭个不停。", "corrected_sentence": "孩子摔伤了，疼得难当，哭个不停。", "error_description": "错误：“疼”和“难当”之间用了“地”，应为“得”。“得”引出程度补语，即“疼得难当”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
