INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90349, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "嘴在脸的下面，用来吃饭、说话、唱歌。", "primary_collocate": null, "pronunciation": "zuǐ", "ipa": "tsweɪ˨˩˦", "syllable_count": 1, "sentences": [{"text": "孩子张开嘴，吃了一口饭。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的嘴很小，唱歌很好听。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭时请闭上嘴，不要说话。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的嘴里有一块糖。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说：“请张开嘴。”", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴里吃着苹果，没法回答。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用手擦了擦孩子的嘴。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的嘴上有一点米饭。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝了一口水，然后用手擦嘴。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别用手捂着嘴说话，我听不见。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "嘴巴", "label": "复合"}, {"form": "嘴唇", "label": "复合"}], "register": "口语", "sense_fingerprint": "人脸下方用来吃饭、说话、唱歌的嘴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2d745d-2bca-4b89-8b23-ae7e91d17958') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90349, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嘴", "is_correct": true, "explanation": "嘴 zuǐ：人脸下方用来吃饭、说话的器官，是本题的正确答案。"}, {"text": "最", "is_correct": false, "explanation": "zuì（第四声）与 zuǐ（第三声）声调不同，意思是“最”。"}, {"text": "醉", "is_correct": false, "explanation": "zuì（第四声）与 zuǐ（第三声）声调不同，意思是“喝醉”。"}, {"text": "水", "is_correct": false, "explanation": "shuǐ 与 zuǐ 声母不同（sh 与 z），意思是“水”。"}, {"text": "组", "is_correct": false, "explanation": "zǔ 与 zuǐ 韵母不同，意思是“组”。"}], "explanations": {"嘴": "嘴 zuǐ：人脸下方用来吃饭、说话的器官，是本题的正确答案。", "最": "zuì（第四声）与 zuǐ（第三声）声调不同，意思是“最”。", "醉": "zuì（第四声）与 zuǐ（第三声）声调不同，意思是“喝醉”。", "水": "shuǐ 与 zuǐ 声母不同（sh 与 z），意思是“水”。", "组": "zǔ 与 zuǐ 韵母不同，意思是“组”。"}, "sentence_index": null, "correct_answer": "嘴"}, "level_3": {"options": [{"text": "碗", "is_correct": false, "explanation": "搭配：“张开”不能用于“碗”，碗也不是吃饭时张开的部位。"}, {"text": "嘴", "is_correct": true, "explanation": "嘴：人脸下方吃饭、说话的器官，与“张开”和“吃饭”搭配。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是人的身体部位，“孩子张开窗户”说不通。"}, {"text": "脚", "is_correct": false, "explanation": "语义：脚不能用来吃饭，句子说的是用嘴吃饭。"}], "explanations": {"碗": "搭配：“张开”不能用于“碗”，碗也不是吃饭时张开的部位。", "嘴": "嘴：人脸下方吃饭、说话的器官，与“张开”和“吃饭”搭配。", "窗户": "语义：窗户不是人的身体部位，“孩子张开窗户”说不通。", "脚": "语义：脚不能用来吃饭，句子说的是用嘴吃饭。"}, "sentence_index": 0, "correct_answer": "嘴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用嘴走路，一下子就到了学校。", "explanation": "这里应该用〈腿〉或〈脚〉，指走路的器官；“嘴”不能用来走路。"}, {"text": "他一吹嘴哨，大家都回头看他。", "explanation": "这里应该用〈口哨〉，指吹出声音的小哨子；“口”组成“口哨”，“嘴哨”不成词。"}, {"text": "他说话的嘴气很硬，大家都不敢反驳。", "explanation": "这里应该用〈口气〉，指说话的语气或态度；“嘴气”不成词，“口气”的“口”不能换成“嘴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90349, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "嘴", "is_correct": true, "explanation": "嘴 zuǐ：人脸下方用来吃饭、说话的器官，是本题的正确答案。"}, {"text": "罪", "is_correct": false, "explanation": "zuì（第四声）与 zuǐ（第三声）声调不同，意思是“罪”。"}, {"text": "祖", "is_correct": false, "explanation": "zǔ 与 zuǐ 韵母不同，意思是“祖先”。"}, {"text": "子", "is_correct": false, "explanation": "zǐ 与 zuǐ 韵母不同，意思是“儿子”或“子”。"}, {"text": "紫", "is_correct": false, "explanation": "zǐ 与 zuǐ 韵母不同，意思是“紫色”。"}], "explanations": {"嘴": "嘴 zuǐ：人脸下方用来吃饭、说话的器官，是本题的正确答案。", "罪": "zuì（第四声）与 zuǐ（第三声）声调不同，意思是“罪”。", "祖": "zǔ 与 zuǐ 韵母不同，意思是“祖先”。", "子": "zǐ 与 zuǐ 韵母不同，意思是“儿子”或“子”。", "紫": "zǐ 与 zuǐ 韵母不同，意思是“紫色”。"}, "sentence_index": null, "correct_answer": "嘴"}, "level_3": {"options": [{"text": "尾巴", "is_correct": false, "explanation": "语义：孩子没有尾巴，“孩子的”不能指尾巴。"}, {"text": "嘴", "is_correct": true, "explanation": "嘴：与“擦”搭配，指孩子脸上需要擦的部位。"}, {"text": "云", "is_correct": false, "explanation": "语义：云不是人的身体部位，“擦孩子的云”说不通。"}, {"text": "翅膀", "is_correct": false, "explanation": "语义：孩子没有翅膀，不能说“孩子的翅膀”。"}], "explanations": {"尾巴": "语义：孩子没有尾巴，“孩子的”不能指尾巴。", "嘴": "嘴：与“擦”搭配，指孩子脸上需要擦的部位。", "云": "语义：云不是人的身体部位，“擦孩子的云”说不通。", "翅膀": "语义：孩子没有翅膀，不能说“孩子的翅膀”。"}, "sentence_index": 6, "correct_answer": "嘴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个菜很合我的嘴味。", "explanation": "这里应该用〈口味〉，指对食物味道的喜好；“嘴味”不成词，“口味”的“口”不能换成“嘴”。"}, {"text": "他把钱放进了嘴袋。", "explanation": "这里应该用〈口〉组成“口袋”，不说“嘴袋”。"}, {"text": "他一边看电影，一边嚼嘴香糖。", "explanation": "这里应该用〈口〉组成“口香糖”，不说“嘴香糖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90349, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你闭嘴上。", "corrected_sentence": "请你闭上嘴。", "error_description": "补语位置错误：“上”作结果补语应紧跟动词，应说“闭上嘴”，不能说“闭嘴上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90349, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他张嘴着睡觉。", "corrected_sentence": "他张着嘴睡觉。", "error_description": "助词位置错误：“着”应紧跟动词“张”，说“张着嘴”，不能说“张嘴着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
