INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90350, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动物（如鸟、鱼、兽等）用来进食、啄食或吼叫的器官，位于头部前端。", "primary_collocate": null, "pronunciation": "zuǐ", "ipa": "tsweɪ˨˩˦", "syllable_count": 1, "sentences": [{"text": "小鸟的嘴又小又尖。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸭子的嘴是扁的。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马用嘴吃草，吃得很慢。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟张着嘴，等妈妈喂虫子。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗的嘴里有很多牙。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼在水里，嘴一张一合。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎张开大嘴，叫了一声。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟用嘴整理羽毛。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫的嘴边有一点牛奶。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "啄木鸟用嘴在树上敲洞。", "target_word": "嘴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "嘴巴", "label": "复合"}, {"form": "嘴唇", "label": "复合"}], "register": "口语", "sense_fingerprint": "动物（鸟、鱼、兽等）用来进食和发声的嘴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2d745d-2bca-4b89-8b23-ae7e91d17958') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90350, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嘴", "is_correct": true, "explanation": "嘴 zuǐ：动物用来进食和发声的器官，是本题的正确答案。"}, {"text": "最", "is_correct": false, "explanation": "zuì（第四声）与 zuǐ（第三声）声调不同，意思是“最”。"}, {"text": "醉", "is_correct": false, "explanation": "zuì（第四声）与 zuǐ（第三声）声调不同，意思是“喝醉”。"}, {"text": "水", "is_correct": false, "explanation": "shuǐ 与 zuǐ 声母不同（sh 与 z），意思是“水”。"}, {"text": "组", "is_correct": false, "explanation": "zǔ 与 zuǐ 韵母不同，意思是“组”。"}], "explanations": {"嘴": "嘴 zuǐ：动物用来进食和发声的器官，是本题的正确答案。", "最": "zuì（第四声）与 zuǐ（第三声）声调不同，意思是“最”。", "醉": "zuì（第四声）与 zuǐ（第三声）声调不同，意思是“喝醉”。", "水": "shuǐ 与 zuǐ 声母不同（sh 与 z），意思是“水”。", "组": "zǔ 与 zuǐ 韵母不同，意思是“组”。"}, "sentence_index": null, "correct_answer": "嘴"}, "level_3": {"options": [{"text": "钉子", "is_correct": false, "explanation": "语义：钉子不是小鸟的器官，“小鸟的钉子”说不通。"}, {"text": "嘴", "is_correct": true, "explanation": "嘴：鸟类用来啄食的器官，又小又尖，与“小鸟的”搭配。"}, {"text": "手", "is_correct": false, "explanation": "语义：小鸟没有手，不能说“小鸟的手”。"}, {"text": "笔", "is_correct": false, "explanation": "搭配：“笔”不属于小鸟的身体部位，“小鸟的笔”搭配不当。"}], "explanations": {"钉子": "语义：钉子不是小鸟的器官，“小鸟的钉子”说不通。", "嘴": "嘴：鸟类用来啄食的器官，又小又尖，与“小鸟的”搭配。", "手": "语义：小鸟没有手，不能说“小鸟的手”。", "笔": "搭配：“笔”不属于小鸟的身体部位，“小鸟的笔”搭配不当。"}, "sentence_index": 0, "correct_answer": "嘴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只狗的嘴吻很长，跑起来很快。", "explanation": "这里应该用〈口吻〉，指动物突出的嘴部；“嘴吻”不成词，“口吻”的“口”不能换成“嘴”。"}, {"text": "小狗看到骨头，嘴水流个不停。", "explanation": "这里应该用〈口水〉，指从口中流出的唾液；“嘴水”不成词。"}, {"text": "小鸟的嘴腔很小，吞不下大虫子。", "explanation": "这里应该用〈口腔〉，指口内的空间；“嘴腔”不成词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90350, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "嘴", "is_correct": true, "explanation": "嘴 zuǐ：动物用来进食和发声的器官，是本题的正确答案。"}, {"text": "罪", "is_correct": false, "explanation": "zuì（第四声）与 zuǐ（第三声）声调不同，意思是“罪”。"}, {"text": "祖", "is_correct": false, "explanation": "zǔ 与 zuǐ 韵母不同，意思是“祖先”。"}, {"text": "子", "is_correct": false, "explanation": "zǐ 与 zuǐ 韵母不同，意思是“儿子”或“子”。"}, {"text": "紫", "is_correct": false, "explanation": "zǐ 与 zuǐ 韵母不同，意思是“紫色”。"}], "explanations": {"嘴": "嘴 zuǐ：动物用来进食和发声的器官，是本题的正确答案。", "罪": "zuì（第四声）与 zuǐ（第三声）声调不同，意思是“罪”。", "祖": "zǔ 与 zuǐ 韵母不同，意思是“祖先”。", "子": "zǐ 与 zuǐ 韵母不同，意思是“儿子”或“子”。", "紫": "zǐ 与 zuǐ 韵母不同，意思是“紫色”。"}, "sentence_index": null, "correct_answer": "嘴"}, "level_3": {"options": [{"text": "花", "is_correct": false, "explanation": "语义：花不会张开大嘴叫，句子说的是老虎发声。"}, {"text": "尾巴", "is_correct": false, "explanation": "搭配：“张开”不能修饰“尾巴”，不说“张开大尾巴”。"}, {"text": "嘴", "is_correct": true, "explanation": "嘴：与“张开”搭配，指动物发出叫声的器官。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会叫，不能“张开大石头”。"}], "explanations": {"花": "语义：花不会张开大嘴叫，句子说的是老虎发声。", "尾巴": "搭配：“张开”不能修饰“尾巴”，不说“张开大尾巴”。", "嘴": "嘴：与“张开”搭配，指动物发出叫声的器官。", "石头": "语义：石头不会叫，不能“张开大石头”。"}, "sentence_index": 6, "correct_answer": "嘴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "狗跑累了，嘴沫直流，喘个不停。", "explanation": "这里应该用〈口沫〉，指唾沫或白沫；“嘴沫”不成词，“口沫”的“口”不能换成“嘴”。"}, {"text": "老虎吼了一声，像在吹嘴哨。", "explanation": "这里应该用〈口哨〉，指吹出声音的小哨子；“口”组成“口哨”，“嘴哨”不成词。"}, {"text": "老虎呼出的嘴气很热。", "explanation": "这里应该用〈口气〉，指呼出的气；“嘴气”不成词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只鸟有一块小嘴。", "corrected_sentence": "这只鸟有一张小嘴。", "error_description": "量词错误：“嘴”应用量词“张”，不能用“块”，应说“一张小嘴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猫吃饱后闭下了嘴。", "corrected_sentence": "猫吃饱后闭上了嘴。", "error_description": "结果补语选错：嘴的合拢应用“闭上”，“闭下”不能表示嘴合拢，应说“闭上了嘴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
