INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90351, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "离我们远一点的那一个人。", "primary_collocate": null, "pronunciation": "nà ge rén", "ipa": "na˥˩ kɤ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "坐在窗边的那个人在看书。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，那个人是不是小李？", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人离我们很远，听不见。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想问问那个人去哪儿。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人跑得真快。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河对面那个人在向我们招手。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人手里拿着一把伞。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人是我的朋友，那个人是他哥哥。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人走过来了。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面那个人是谁的爸爸？", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那些人", "label": "复数"}, {"form": "那位", "label": "敬称"}], "register": "通用", "sense_fingerprint": "指离我们较远的那一个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad8dbc6-820a-4e36-a32d-a214082bc3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90351, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那个人", "is_correct": true, "explanation": "正确。「那个人」指离我们较远的一个人，句中指坐在窗边看书的人。"}, {"text": "那只猫", "is_correct": false, "explanation": "搭配：「看书」要求人作主语，猫不能看书。"}, {"text": "那张桌子", "is_correct": false, "explanation": "语义：「桌子」是物品，不能看书。"}, {"text": "那棵树", "is_correct": false, "explanation": "语义：「树」不会看书，与句意矛盾。"}], "explanations": {"那个人": "正确。「那个人」指离我们较远的一个人，句中指坐在窗边看书的人。", "那只猫": "搭配：「看书」要求人作主语，猫不能看书。", "那张桌子": "语义：「桌子」是物品，不能看书。", "那棵树": "语义：「树」不会看书，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "那个人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个人太便宜了，我买了两个。", "explanation": "这里说的是商品，应该用〈那件〉（指物），「那个人」只指人。"}, {"text": "那个人离我们很近，我一抬头就能看见他。", "explanation": "这里应该用〈这个人〉。「那个人」指远处的人，与「离我们很近」矛盾。"}, {"text": "那个人在树上做窝。", "explanation": "这里说的是鸟，应该用〈那只鸟〉，「那个人」只指人，不能指鸟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90351, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那个人", "is_correct": true, "explanation": "正确。「那个人」指人，可以用「手里拿着」描述。"}, {"text": "那张椅子", "is_correct": false, "explanation": "搭配：椅子没有手，不能「手里拿着」伞。"}, {"text": "那座房子", "is_correct": false, "explanation": "语义：房子不能拿东西，与句意矛盾。"}, {"text": "那本词典", "is_correct": false, "explanation": "语义：词典是书，不能手里拿着伞。"}], "explanations": {"那个人": "正确。「那个人」指人，可以用「手里拿着」描述。", "那张椅子": "搭配：椅子没有手，不能「手里拿着」伞。", "那座房子": "语义：房子不能拿东西，与句意矛盾。", "那本词典": "语义：词典是书，不能手里拿着伞。"}, "sentence_index": 6, "correct_answer": "那个人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去前面那个人吃饭了。", "explanation": "这里应该用〈那家饭馆〉。「那个人」只指人，不能指吃饭的地方。"}, {"text": "前面那个人是一本书，很厚。", "explanation": "这里说的是书，应该用〈那本〉，「那个人」只指人，不能指书。"}, {"text": "前面那个人很辣，我喝了好几杯水。", "explanation": "这里应该用〈那道菜〉。「那个人」只指人，不能指菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个人们在路口等公交车。", "corrected_sentence": "那个人在路口等公交车。", "error_description": "错误：「那个人」指单个人，后面不能加「们」。正确应为「那个人」（单数）或「那些人」（复数）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个人了站在小路的尽头，离我们很远。", "corrected_sentence": "那个人站在小路的尽头，离我们很远。", "error_description": "错误：“了”不能紧跟主语“那个人”，多出的“了”应删去。正确应为“那个人站在小路的尽头，离我们很远。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
