INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90352, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90352, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指说话人和听话人以外的、较远的某一个人。", "primary_collocate": null, "pronunciation": "nà ge rén", "ipa": "na˥˩ kɤ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "那个人是我们的新老师。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你认识那个人吗？", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在门口的那个人是谁？", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不认识那个人。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人一直看着我们。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人穿着红色的外套。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，那个人是你哥哥吗？", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人在远处的树下等车。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我见过那个人。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人的声音真大。", "target_word": "那个人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那些人", "label": "复数"}, {"form": "那位", "label": "敬称"}], "register": "通用", "sense_fingerprint": "指说话人和听话人以外的某个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad8dbc6-820a-4e36-a32d-a214082bc3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那个人", "is_correct": true, "explanation": "正确。「那个人」指说话人和听话人以外、较远的某一个人，这里指新老师。"}, {"text": "那个东西", "is_correct": false, "explanation": "语义：「东西」指物，不能是老师。"}, {"text": "它", "is_correct": false, "explanation": "语义：「它」指物或动物，不能指新老师这样的人。"}, {"text": "那张桌子", "is_correct": false, "explanation": "语义：「桌子」不是人，不能是新老师。"}], "explanations": {"那个人": "正确。「那个人」指说话人和听话人以外、较远的某一个人，这里指新老师。", "那个东西": "语义：「东西」指物，不能是老师。", "它": "语义：「它」指物或动物，不能指新老师这样的人。", "那张桌子": "语义：「桌子」不是人，不能是新老师。"}, "sentence_index": 0, "correct_answer": "那个人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个人太贵了，我买不起。", "explanation": "这里说的是东西，应该用〈那件〉（指物），「那个人」只指人，不能指东西。"}, {"text": "那个人就站在我身边，我一伸手就能碰到他。", "explanation": "这里应该用〈这个人〉。「那个人」指较远的人，与「就站在我身边」矛盾。"}, {"text": "我每天都给那个人浇水，它长得很好。", "explanation": "这里应该用〈那盆花〉。「那个人」指人，不能用来浇水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那个人", "is_correct": true, "explanation": "正确。「那个人」指人，可以作「是……哥哥」的主语。"}, {"text": "那只狗", "is_correct": false, "explanation": "语义：「狗」不能是「你哥哥」。"}, {"text": "那座楼", "is_correct": false, "explanation": "配价：「是……哥哥」要求人作主语，「楼」不能充当。"}, {"text": "那辆车", "is_correct": false, "explanation": "语义：「车」不是人，与「你哥哥」矛盾。"}], "explanations": {"那个人": "正确。「那个人」指人，可以作「是……哥哥」的主语。", "那只狗": "语义：「狗」不能是「你哥哥」。", "那座楼": "配价：「是……哥哥」要求人作主语，「楼」不能充当。", "那辆车": "语义：「车」不是人，与「你哥哥」矛盾。"}, "sentence_index": 6, "correct_answer": "那个人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在那个人玩得很开心。", "explanation": "这里应该用〈那里〉（地点）。「那个人」只指人，不能当作地点。"}, {"text": "那个人很好吃，我吃了两碗。", "explanation": "这里说的是食物，应该用〈那道菜〉，「那个人」只指人，不能指食物。"}, {"text": "那个人是一本书，很厚。", "explanation": "这里说的是书，应该用〈那本〉，「那个人」只指人，不能指书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个人们站在很远的地方。", "corrected_sentence": "那个人站在很远的地方。", "error_description": "错误：「那个人」指单个人，后面不能加「们」。正确应为「那个人」（单数）或「那些人」（复数）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个人了在河对岸，离我们很远。", "corrected_sentence": "那个人在河对岸，离我们很远。", "error_description": "错误：“了”不能紧跟主语“那个人”，多出的“了”应删去。正确应为“那个人在河对岸，离我们很远。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
