INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90353, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90353, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "面的是一种方形的小面包车，可以像出租车一样载人。", "primary_collocate": null, "pronunciation": "miàn dī", "ipa": "mjɛn˥˩ ti˥", "syllable_count": 2, "sentences": [{"text": "我们坐面的去火车站吧。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边停着一辆黄色的面的。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面的比公共汽车快一点。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天开面的拉客人。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我叫了一辆面的。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆面的能坐六个人。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在路边打了面的，司机问我去哪儿。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城里到处都是面的。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们四个人打一辆面的。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在车站门口等面的。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "面的司机", "label": "复合"}], "register": "口语", "sense_fingerprint": "方形小面包车，当出租车载客", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95593539-6a07-48d3-929c-5995fd291c1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90353, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面的", "is_correct": true, "explanation": "面的：载客的小型面包车，可以坐着去火车站，符合句意。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是坐具，不是交通工具，不能坐着去火车站。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是坐具，不能载人前往车站，“坐椅子去火车站”说不通。"}, {"text": "行李", "is_correct": false, "explanation": "配价：“坐”后接的是可乘坐的车辆或座位，行李不能被坐着去车站。"}], "explanations": {"面的": "面的：载客的小型面包车，可以坐着去火车站，符合句意。", "沙发": "语义：沙发是坐具，不是交通工具，不能坐着去火车站。", "椅子": "语义：椅子是坐具，不能载人前往车站，“坐椅子去火车站”说不通。", "行李": "配价：“坐”后接的是可乘坐的车辆或座位，行李不能被坐着去车站。"}, "sentence_index": 0, "correct_answer": "面的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天开面的压路。", "explanation": "这里应该用〈压路机〉。面的只用于载客，压路要用压路机。"}, {"text": "他每天开面的耕田。", "explanation": "这里应该用〈拖拉机〉。面的只用于载客，耕田要用拖拉机。"}, {"text": "他每天开面的清运垃圾。", "explanation": "这里应该用〈垃圾车〉。面的不用来清运垃圾，清运垃圾要用垃圾车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90353, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面的", "is_correct": true, "explanation": "面的：载客的小型面包车，有司机驾驶，符合句意。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不是交通工具，不能用来打车，句子说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能载人，也没有司机，句子说不通。"}, {"text": "粉笔", "is_correct": false, "explanation": "搭配：“司机”指驾驶车辆的人，粉笔不能与之搭配。"}], "explanations": {"面的": "面的：载客的小型面包车，有司机驾驶，符合句意。", "黑板": "语义：黑板不是交通工具，不能用来打车，句子说不通。", "冰箱": "语义：冰箱不能载人，也没有司机，句子说不通。", "粉笔": "搭配：“司机”指驾驶车辆的人，粉笔不能与之搭配。"}, "sentence_index": 6, "correct_answer": "面的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天坐了一张面的回家。", "explanation": "这里应该用〈辆〉。面的是车，量词用“辆”，不用“张”。"}, {"text": "他买了一条面的做生意。", "explanation": "这里应该用〈辆〉。面的是车，量词用“辆”，不用“条”。"}, {"text": "他家里有一匹面的。", "explanation": "这里应该用〈辆〉。面的是车，量词用“辆”，“匹”多用于马。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90353, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校门口停着一本白色的面的。", "corrected_sentence": "学校门口停着一辆白色的面的。", "error_description": "量词错误：面的是车，量词应用“辆”，“本”用于书本，不用于车。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90353, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站门口停着一只面的。", "corrected_sentence": "车站门口停着一辆面的。", "error_description": "量词错误：面的是车，量词应用“辆”，“只”用于动物或成对、小件的东西，不用于车。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
