INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90354, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "载客的小型面包车，常用作出租车。", "primary_collocate": null, "pronunciation": "miàn dī", "ipa": "mjɛn˥˩ ti˥", "syllable_count": 2, "sentences": [{"text": "老张开了十年面的。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面的价钱不贵，大家都爱坐。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里很晚了，路上还有面的。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坐过一次面的，车里很挤。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面的停在小区门口。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一辆旧面的做生意。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上的面的很多。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们三个同学合坐一辆面的。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面的在路口等着客人。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把行李放进面的里。", "target_word": "面的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "面的司机", "label": "复合"}], "register": "口语", "sense_fingerprint": "载客的小型面包车，常当出租车用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95593539-6a07-48d3-929c-5995fd291c1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面的", "is_correct": true, "explanation": "面的：载客的小型面包车，老张可以开十年，符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能被驾驶，“开了十年书包”说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能驾驶，“开了十年冰箱”说不通。"}, {"text": "行李", "is_correct": false, "explanation": "配价：“开”要求可以驾驶或打开的对象，行李不能被开了十年。"}], "explanations": {"面的": "面的：载客的小型面包车，老张可以开十年，符合句意。", "书包": "语义：书包不能被驾驶，“开了十年书包”说不通。", "冰箱": "语义：冰箱不能驾驶，“开了十年冰箱”说不通。", "行李": "配价：“开”要求可以驾驶或打开的对象，行李不能被开了十年。"}, "sentence_index": 0, "correct_answer": "面的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天开面的种地。", "explanation": "这里应该用〈拖拉机〉。面的只载客，种地要用拖拉机。"}, {"text": "他每天开面的修路。", "explanation": "这里应该用〈压路机〉。面的只载客，修路要用压路机。"}, {"text": "他每天开面的收垃圾。", "explanation": "这里应该用〈垃圾车〉。面的只用于载客，收垃圾要用垃圾车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面的", "is_correct": true, "explanation": "面的：载客的小型面包车，常在路上行驶，符合句意。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：路上不会有很多黑板，句子说不通。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：路上不会成堆出现粉笔，“这条路上的粉笔很多”不成立。"}, {"text": "台灯", "is_correct": false, "explanation": "搭配：“路上的……很多”多说车辆或行人，不说路上的台灯很多。"}], "explanations": {"面的": "面的：载客的小型面包车，常在路上行驶，符合句意。", "黑板": "语义：路上不会有很多黑板，句子说不通。", "粉笔": "语义：路上不会成堆出现粉笔，“这条路上的粉笔很多”不成立。", "台灯": "搭配：“路上的……很多”多说车辆或行人，不说路上的台灯很多。"}, "sentence_index": 6, "correct_answer": "面的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天坐了一根面的回家。", "explanation": "这里应该用〈辆〉。面的是车，量词用“辆”，不用“根”。"}, {"text": "她买了一张面的做生意。", "explanation": "这里应该用〈辆〉。面的是车，量词用“辆”，不用“张”。"}, {"text": "车站门口停着一头面的。", "explanation": "这里应该用〈辆〉。面的是车，量词用“辆”，“头”多用于牲畜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条面的跑得很快。", "corrected_sentence": "这辆面的跑得很快。", "error_description": "量词错误：面的是车，量词应用“辆”，不用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司机把一只面的开到门口。", "corrected_sentence": "司机把一辆面的开到门口。", "error_description": "量词错误：面的是车，量词应用“辆”，不用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
