INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90355, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己感到害怕，心跳得很快。", "primary_collocate": null, "pronunciation": "xià", "ipa": "ɕja⁵¹", "syllable_count": 1, "sentences": [{"text": "他吓得脸都白了。", "target_word": "吓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到雷声，我吓了一跳。", "target_word": "吓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子吓得哭了起来。", "target_word": "吓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "半夜听到响声，我吓坏了。", "target_word": "吓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗吓得躲在桌子下面。", "target_word": "吓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她吓得不敢动，心跳得很快。", "target_word": "吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到蛇，她吓得大叫起来。", "target_word": "吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吓得说不出话来。", "target_word": "吓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我吓得手都在发抖。", "target_word": "吓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那天我吓过一次，到现在还害怕。", "target_word": "吓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吓了", "label": "体标（了）"}, {"form": "吓着", "label": "体标（着）"}, {"form": "吓过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "吓（xià）：不及物，自己感到害怕、心跳加快，如“吓得发抖、吓坏了”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4928fe74-fd92-43fa-8886-52fe0aa8b3e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90355, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吓", "is_correct": true, "explanation": "吓（xià，第四声）：自己感到害怕、受惊，即本词条的意思。"}, {"text": "瞎", "is_correct": false, "explanation": "瞎（xiā，第一声）与 xià（第四声）声调不同，意思是看不见。"}, {"text": "虾", "is_correct": false, "explanation": "虾（xiā，第一声）与 xià（第四声）声调不同，意思是水生动物。"}, {"text": "霞", "is_correct": false, "explanation": "霞（xiá，第二声）与 xià（第四声）声调不同，意思是彩色的云。"}, {"text": "狭", "is_correct": false, "explanation": "狭（xiá，第二声）与 xià（第四声）声调不同，意思是窄。"}, {"text": "侠", "is_correct": false, "explanation": "侠（xiá，第二声）与 xià（第四声）声调不同，意思是侠客。"}], "explanations": {"吓": "吓（xià，第四声）：自己感到害怕、受惊，即本词条的意思。", "瞎": "瞎（xiā，第一声）与 xià（第四声）声调不同，意思是看不见。", "虾": "虾（xiā，第一声）与 xià（第四声）声调不同，意思是水生动物。", "霞": "霞（xiá，第二声）与 xià（第四声）声调不同，意思是彩色的云。", "狭": "狭（xiá，第二声）与 xià（第四声）声调不同，意思是窄。", "侠": "侠（xiá，第二声）与 xià（第四声）声调不同，意思是侠客。"}, "sentence_index": null, "correct_answer": "吓"}, "level_3": {"options": [{"text": "吓", "is_correct": true, "explanation": "吓得：因受惊而脸色发白，符合“他”受惊的语境。"}, {"text": "晒", "is_correct": false, "explanation": "语义：“晒”会使皮肤变黑，与“脸都白了”相反。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”会使皮肤发红或变黑，与“脸都白了”冲突。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”会使脸发红，与“脸都白了”不符。"}], "explanations": {"吓": "吓得：因受惊而脸色发白，符合“他”受惊的语境。", "晒": "语义：“晒”会使皮肤变黑，与“脸都白了”相反。", "烤": "语义：“烤”会使皮肤发红或变黑，与“脸都白了”冲突。", "烫": "语义：“烫”会使脸发红，与“脸都白了”不符。"}, "sentence_index": 0, "correct_answer": "吓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一句俏皮话吓得全班都笑了。", "explanation": "这里应用〈逗〉（使人发笑）。“吓”表示受惊、害怕，不会让人发笑；让人发笑要说〈逗〉。"}, {"text": "得知考试通过，我吓得高兴得跳起来。", "explanation": "这里应用〈惊喜〉（又惊又喜）。“吓”表示因害怕而受惊，与“高兴”的情绪矛盾；考试通过引起的是〈惊喜〉。"}, {"text": "我吓了一杯茶，觉得很好喝。", "explanation": "这里应用〈喝〉。“吓”不能带“茶”作宾语，表示喝茶要说〈喝〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90355, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吓", "is_correct": true, "explanation": "吓（xià，第四声）：自己感到害怕、受惊，即本词条的意思。"}, {"text": "峡", "is_correct": false, "explanation": "峡（xiá，第二声）与 xià（第四声）声调不同，意思是两山之间的狭长水道。"}, {"text": "暇", "is_correct": false, "explanation": "暇（xiá，第二声）与 xià（第四声）声调不同，意思是空闲。"}, {"text": "架", "is_correct": false, "explanation": "架（jià，第四声）与 xià 只有声母不同（j 与 x），意思是支架。"}, {"text": "恰", "is_correct": false, "explanation": "恰（qià，第四声）与 xià 只有声母不同（q 与 x），意思是正好。"}], "explanations": {"吓": "吓（xià，第四声）：自己感到害怕、受惊，即本词条的意思。", "峡": "峡（xiá，第二声）与 xià（第四声）声调不同，意思是两山之间的狭长水道。", "暇": "暇（xiá，第二声）与 xià（第四声）声调不同，意思是空闲。", "架": "架（jià，第四声）与 xià 只有声母不同（j 与 x），意思是支架。", "恰": "恰（qià，第四声）与 xià 只有声母不同（q 与 x），意思是正好。"}, "sentence_index": null, "correct_answer": "吓"}, "level_3": {"options": [{"text": "吓", "is_correct": true, "explanation": "吓得：因受惊而大叫，符合“看到蛇”之后的语境。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡觉时不会大叫，与“大叫起来”冲突。"}, {"text": "躺", "is_correct": false, "explanation": "语义：躺着不会出现大叫的动作，与“大叫起来”冲突。"}, {"text": "走", "is_correct": false, "explanation": "搭配：“走得”不能接“大叫起来”作补语，两者无法搭配。"}], "explanations": {"吓": "吓得：因受惊而大叫，符合“看到蛇”之后的语境。", "睡": "语义：睡觉时不会大叫，与“大叫起来”冲突。", "躺": "语义：躺着不会出现大叫的动作，与“大叫起来”冲突。", "走": "搭配：“走得”不能接“大叫起来”作补语，两者无法搭配。"}, "sentence_index": 6, "correct_answer": "吓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到这个笑话，我吓得哈哈大笑。", "explanation": "这里应用〈乐〉（高兴、发笑）。“吓”表示受惊害怕，不会引起大笑；因笑话而发笑要说〈乐〉。"}, {"text": "吃完晚饭，我吓得很饱。", "explanation": "这里应用〈吃〉。“吓”表示受惊害怕，与“饱”无关；吃饭后觉得饱要说“吃得很饱”。"}, {"text": "他跑了一整天，吓得很累。", "explanation": "这里应用〈跑〉。“吓”表示受惊害怕，不会让人身体疲劳；跑步后觉得累要说“跑得很累”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90355, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到门外的巨响，他吓跳了起来。", "corrected_sentence": "听到门外的巨响，他吓得跳了起来。", "error_description": "错误在补语标记：表示程度结果要用“吓得”，漏掉“得”后应说“吓得跳了起来”，“吓跳”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90355, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "走夜路时突然听到口哨，他吓地拔腿就跑。", "corrected_sentence": "走夜路时突然听到口哨，他吓得拔腿就跑。", "error_description": "错误在助词：表示“吓”的结果要用补语标记“得”，“地”用于修饰动词，不能接在“吓”后；应说“吓得拔腿就跑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
