INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90356, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使人感到害怕、受惊。", "primary_collocate": null, "pronunciation": "xià", "ipa": "ɕja⁵¹", "syllable_count": 1, "sentences": [{"text": "别吓孩子，他胆子很小。", "target_word": "吓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你突然出来，吓了我一跳。", "target_word": "吓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只大狗吓了小女孩。", "target_word": "吓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "突然的响声吓到了我。", "target_word": "吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他躲在门后面，想吓妈妈一下。", "target_word": "吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要吓小猫，它很怕人。", "target_word": "吓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电影吓着了很多人。", "target_word": "吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把弟弟吓哭了。", "target_word": "吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你吓着我了，我没听到你进来。", "target_word": "吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的大叫声吓了大家一跳。", "target_word": "吓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吓了", "label": "体标（了）"}, {"form": "吓着", "label": "体标（着）"}, {"form": "吓过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "吓（xià）：及物，使别人害怕，如“吓孩子、吓我一跳”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4928fe74-fd92-43fa-8886-52fe0aa8b3e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90356, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吓", "is_correct": true, "explanation": "吓（xià，第四声）：使人害怕，即本词条的意思。"}, {"text": "瞎", "is_correct": false, "explanation": "瞎（xiā，第一声）与 xià（第四声）声调不同，意思是看不见，与“使人害怕”无关。"}, {"text": "虾", "is_correct": false, "explanation": "虾（xiā，第一声）与 xià（第四声）声调不同，意思是水生动物。"}, {"text": "霞", "is_correct": false, "explanation": "霞（xiá，第二声）与 xià（第四声）声调不同，意思是彩色的云。"}, {"text": "狭", "is_correct": false, "explanation": "狭（xiá，第二声）与 xià（第四声）声调不同，意思是窄。"}, {"text": "侠", "is_correct": false, "explanation": "侠（xiá，第二声）与 xià（第四声）声调不同，意思是侠客。"}], "explanations": {"吓": "吓（xià，第四声）：使人害怕，即本词条的意思。", "瞎": "瞎（xiā，第一声）与 xià（第四声）声调不同，意思是看不见，与“使人害怕”无关。", "虾": "虾（xiā，第一声）与 xià（第四声）声调不同，意思是水生动物。", "霞": "霞（xiá，第二声）与 xià（第四声）声调不同，意思是彩色的云。", "狭": "狭（xiá，第二声）与 xià（第四声）声调不同，意思是窄。", "侠": "侠（xiá，第二声）与 xià（第四声）声调不同，意思是侠客。"}, "sentence_index": null, "correct_answer": "吓"}, "level_3": {"options": [{"text": "吓", "is_correct": true, "explanation": "吓：使孩子受惊，与“他胆子很小”的语境相符，是“别吓孩子”的正确说法。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，孩子不是食物，“别吃孩子”不成立。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指加热或燃烧，不能用来对待孩子。"}, {"text": "闻", "is_correct": false, "explanation": "搭配：“闻”指用鼻子嗅，需要气味等对象，“别闻孩子”不这样说。"}], "explanations": {"吓": "吓：使孩子受惊，与“他胆子很小”的语境相符，是“别吓孩子”的正确说法。", "吃": "语义：“吃”指进食，孩子不是食物，“别吃孩子”不成立。", "烧": "语义：“烧”指加热或燃烧，不能用来对待孩子。", "闻": "搭配：“闻”指用鼻子嗅，需要气味等对象，“别闻孩子”不这样说。"}, "sentence_index": 0, "correct_answer": "吓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个好消息，我吓得高兴坏了。", "explanation": "这里应用〈惊喜〉（又惊又喜）。“吓”表示因害怕而受惊，与“高兴”的情绪矛盾；好消息引起的是〈惊喜〉。"}, {"text": "他的笑话吓得大家都笑了。", "explanation": "这里应用〈逗〉（使人发笑）。“吓”表示使人害怕，不是使人发笑；笑话让人发笑要说〈逗〉。"}, {"text": "我吓了一碗汤，觉得味道很好。", "explanation": "这里应用〈喝〉。“吓”的宾语必须是人或动物，“汤”不能受惊；喝汤要说〈喝〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90356, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吓", "is_correct": true, "explanation": "吓（xià，第四声）：使人害怕，即本词条的意思。"}, {"text": "峡", "is_correct": false, "explanation": "峡（xiá，第二声）与 xià（第四声）声调不同，意思是两山之间的狭长水道。"}, {"text": "暇", "is_correct": false, "explanation": "暇（xiá，第二声）与 xià（第四声）声调不同，意思是空闲。"}, {"text": "架", "is_correct": false, "explanation": "架（jià，第四声）与 xià 只有声母不同（j 与 x），意思是支架。"}, {"text": "恰", "is_correct": false, "explanation": "恰（qià，第四声）与 xià 只有声母不同（q 与 x），意思是正好。"}], "explanations": {"吓": "吓（xià，第四声）：使人害怕，即本词条的意思。", "峡": "峡（xiá，第二声）与 xià（第四声）声调不同，意思是两山之间的狭长水道。", "暇": "暇（xiá，第二声）与 xià（第四声）声调不同，意思是空闲。", "架": "架（jià，第四声）与 xià 只有声母不同（j 与 x），意思是支架。", "恰": "恰（qià，第四声）与 xià 只有声母不同（q 与 x），意思是正好。"}, "sentence_index": null, "correct_answer": "吓"}, "level_3": {"options": [{"text": "吓", "is_correct": true, "explanation": "吓着：使很多人受惊，符合“电影”造成惊吓的语境。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理或修饰，不能使人受惊。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，电影不能“写”人使人受惊。"}, {"text": "装", "is_correct": false, "explanation": "搭配：“装”表示装入或假装，与“很多人”受惊的语境不搭配。"}], "explanations": {"吓": "吓着：使很多人受惊，符合“电影”造成惊吓的语境。", "修": "语义：“修”指修理或修饰，不能使人受惊。", "写": "语义：“写”指书写文字，电影不能“写”人使人受惊。", "装": "搭配：“装”表示装入或假装，与“很多人”受惊的语境不搭配。"}, "sentence_index": 6, "correct_answer": "吓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他讲的笑话吓得大家哈哈大笑。", "explanation": "这里应用〈逗〉（使人发笑）。“吓”是使人害怕，不会使人发笑；让大家发笑要说〈逗〉。"}, {"text": "他吓了一顿饭，吃得很饱。", "explanation": "这里应用〈吃〉。“吓”的对象必须是能感到害怕的人或动物，“饭”不能受惊；吃饭要说〈吃〉。"}, {"text": "他给朋友吓了一封长信。", "explanation": "这里应用〈写〉。“吓”的对象必须能感到害怕，信不会受惊；书写信件要说〈写〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里的鞭炮突然响了，吓我了一跳。", "corrected_sentence": "院子里的鞭炮突然响了，吓了我一跳。", "error_description": "错误在“了”的位置：“吓了我一跳”中的“了”紧跟动词“吓”，写成“吓我了一跳”不符合汉语的固定格式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只猫突然从床底下窜出来，吓到了我一跳。", "corrected_sentence": "那只猫突然从床底下窜出来，吓了我一跳。", "error_description": "错误在补语：“吓了我一跳”已用“吓了……一跳”表示受惊，“吓”后再加“到”与“一跳”重复；正确形式为“吓了我一跳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
