INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90358, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90358, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "钱财；货币。", "primary_collocate": null, "pronunciation": "jīn qián", "ipa": "tɕin˥ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "金钱不是最重要的东西。", "target_word": "金钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把金钱看得很重。", "target_word": "金钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人为了金钱放弃了家人。", "target_word": "金钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金钱买不到真正的快乐。", "target_word": "金钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就不在乎金钱。", "target_word": "金钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能只追求金钱。", "target_word": "金钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子对金钱没有概念。", "target_word": "金钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金钱和时间，你更看重哪个？", "target_word": "金钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活里除了金钱什么也没有。", "target_word": "金钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱情不能用金钱来衡量。", "target_word": "金钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "金钱观", "label": "复合"}], "register": "书面", "sense_fingerprint": "泛指钱财，常与价值观相关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad8dbc6-820a-4e36-a32d-a214082bc3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90358, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "金钱", "is_correct": true, "explanation": "正确。「金钱」指钱财，是句中所说的东西。"}, {"text": "非常", "is_correct": false, "explanation": "语法：「非常」是副词，不能作主语。"}, {"text": "已经", "is_correct": false, "explanation": "语法：「已经」是副词，不能作主语，句子不成立。"}, {"text": "和", "is_correct": false, "explanation": "语法：「和」是连词，不能单独作主语。"}], "explanations": {"金钱": "正确。「金钱」指钱财，是句中所说的东西。", "非常": "语法：「非常」是副词，不能作主语。", "已经": "语法：「已经」是副词，不能作主语，句子不成立。", "和": "语法：「和」是连词，不能单独作主语。"}, "sentence_index": 0, "correct_answer": "金钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对他有很深的金钱。", "explanation": "这里应该用〈感情〉。「金钱」指钱财，不能用「很深的」修饰。"}, {"text": "这块金钱很重，值很多钱。", "explanation": "这里应该用〈金子〉。「金钱」指钱财，不能指金属块。"}, {"text": "我们把金钱养在了鱼缸里。", "explanation": "这里应该用〈金鱼〉。「金钱」指钱财，不是动物，不能养在鱼缸里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金钱", "is_correct": true, "explanation": "正确。「金钱」指钱财，与「概念」搭配，指人对钱财的认识。"}, {"text": "很", "is_correct": false, "explanation": "语法：「对」后要接名词，「很」是副词，句子不成立。"}, {"text": "已经", "is_correct": false, "explanation": "语法：「对」后要接名词，「已经」是副词，不能作宾语。"}, {"text": "把", "is_correct": false, "explanation": "语法：「把」是介词，不能放在「对」后面。"}], "explanations": {"金钱": "正确。「金钱」指钱财，与「概念」搭配，指人对钱财的认识。", "很": "语法：「对」后要接名词，「很」是副词，句子不成立。", "已经": "语法：「对」后要接名词，「已经」是副词，不能作宾语。", "把": "语法：「把」是介词，不能放在「对」后面。"}, "sentence_index": 6, "correct_answer": "金钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件东西的金钱很高。", "explanation": "这里应该用〈价钱〉。「金钱」指钱财，不能说东西的价钱高。"}, {"text": "我们每天都在金钱里学习汉语。", "explanation": "这里应该用〈教室〉。「金钱」指钱财，不能当作地点。"}, {"text": "我们的金钱去上学了。", "explanation": "这里应该用〈学生〉。「金钱」指钱财，不是人，不能去上学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他捐了一只金钱给学校。", "corrected_sentence": "他捐了一笔金钱给学校。", "error_description": "错误：「金钱」数量要用「笔」，「只」用于动物等，不能用于金钱。正确应为「一笔金钱」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把金钱们都花在孩子身上了。", "corrected_sentence": "我把金钱都花在孩子身上了。", "error_description": "错误：「金钱」是不可数名词，不能加「们」表示复数。正确应直接说「金钱」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90359, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "满意", "is_correct": true, "explanation": "反义：失望指想要的没得到，满意指达到了期望，二者意思相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：漂亮形容外貌好看，与失望的意思没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：安静形容声音或环境，与失望的心理状态无关。"}, {"text": "善良", "is_correct": false, "explanation": "无关：善良形容品性，与失望没有反义关系。"}], "correct_answer": "满意", "explanations": {"满意": "反义：失望指想要的没得到，满意指达到了期望，二者意思相反。", "漂亮": "无关：漂亮形容外貌好看，与失望的意思没有反义关系。", "安静": "无关：安静形容声音或环境，与失望的心理状态无关。", "善良": "无关：善良形容品性，与失望没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90359, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "满意", "is_correct": true, "explanation": "反义：失望指想要的没得到，满意指达到了期望，二者意思相反。"}, {"text": "健康", "is_correct": false, "explanation": "无关：健康形容身体或状态，与失望没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "无关：便宜形容价格，与失望的心理状态无关。"}, {"text": "苦涩", "is_correct": false, "explanation": "无关：苦涩形容味道，与失望没有反义关系。"}], "correct_answer": "满意", "explanations": {"满意": "反义：失望指想要的没得到，满意指达到了期望，二者意思相反。", "健康": "无关：健康形容身体或状态，与失望没有反义关系。", "便宜": "无关：便宜形容价格，与失望的心理状态无关。", "苦涩": "无关：苦涩形容味道，与失望没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90359, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "失望是你很想要一件事，可是没有得到，心里很难过。", "primary_collocate": null, "pronunciation": "shī wàng", "ipa": "ʂʅ˥ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我没有得到那份礼物，很失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考得不好，看起来很失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子没吃到冰淇淋，非常失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她等了一天，电话还是没来，很失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，大家都很失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到不能去旅行，弟弟很失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失望地回了家。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈今天没来，我有点失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她失望地看着空盘子。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "票卖完了，我们都很失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "失望了", "label": "完成体"}, {"form": "失望地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "想要的没得到，心里难过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2d745d-2bca-4b89-8b23-ae7e91d17958') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90359, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "失望", "is_correct": true, "explanation": "与语境相符：没有得到想要的礼物，心里难过，正是失望。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：没有得到礼物却说很高兴，与“没有得到”的语境矛盾。"}, {"text": "满意", "is_correct": false, "explanation": "语义：没有得到想要的东西，不会感到满意。"}, {"text": "欣慰", "is_correct": false, "explanation": "语义：欣慰表示心里得到安慰、感到高兴，与没得到礼物的语境相反。"}], "explanations": {"失望": "与语境相符：没有得到想要的礼物，心里难过，正是失望。", "高兴": "语义：没有得到礼物却说很高兴，与“没有得到”的语境矛盾。", "满意": "语义：没有得到想要的东西，不会感到满意。", "欣慰": "语义：欣慰表示心里得到安慰、感到高兴，与没得到礼物的语境相反。"}, "sentence_index": 0, "correct_answer": "失望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到你父亲去世，我很失望。", "explanation": "这里应该用〈遗憾〉。失望表示自己想要的没有得到而难过；对别人的不幸应说“很遗憾”。"}, {"text": "他拿到了想要的奖学金，非常失望。", "explanation": "这里应该用〈高兴〉。失望指想要的没有得到而难过，拿到想要的奖学金应说“高兴”。"}, {"text": "他想要的东西都得到了，心里很失望。", "explanation": "这里应该用〈满足〉。失望指想要的没有得到，想要的都得到了应说“满足”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90359, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失望", "is_correct": true, "explanation": "与语境相符：“他……地回了家”需要一个表示心情的词，失望符合。"}, {"text": "吃", "is_correct": false, "explanation": "语法：吃是动词，不能用“地”字结构修饰“回家”，“吃地回了家”不成立。"}, {"text": "睡", "is_correct": false, "explanation": "语法：睡是动词，不能用“地”字结构修饰“回家”，“睡地回了家”不成立。"}, {"text": "高大", "is_correct": false, "explanation": "语义：高大形容身材，不能修饰回家的动作。"}], "explanations": {"失望": "与语境相符：“他……地回了家”需要一个表示心情的词，失望符合。", "吃": "语法：吃是动词，不能用“地”字结构修饰“回家”，“吃地回了家”不成立。", "睡": "语法：睡是动词，不能用“地”字结构修饰“回家”，“睡地回了家”不成立。", "高大": "语义：高大形容身材，不能修饰回家的动作。"}, "sentence_index": 6, "correct_answer": "失望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服正合我意，我很失望。", "explanation": "这里应该用〈满意〉。失望指想要的没得到而难过，衣服正合心意应说“满意”。"}, {"text": "老师表扬了我的作业，我很失望。", "explanation": "这里应该用〈开心〉。失望指想要的没得到而难过，受到表扬应说“开心”。"}, {"text": "妈妈为我骄傲，我很失望。", "explanation": "这里应该用〈自豪〉。失望指希望落空而难过，被父母认可时应说“自豪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90359, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈失望的看着我。", "corrected_sentence": "妈妈失望地看着我。", "error_description": "错误：“失望的”后接动词。正确：“失望地”，形容词作状语修饰动作时要用“地”，用“的”是常见的学习者错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90359, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听说音乐会取消了，他很失望着。", "corrected_sentence": "听说音乐会取消了，他很失望。", "error_description": "错误：形容词“失望”前有“很”时，后面不能加“着”。正确：“他很失望”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
