INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90360, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "希望落空而不愉快；失去信心。", "primary_collocate": null, "pronunciation": "shī wàng", "ipa": "ʂʅ˥ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他总是迟到，老师对他很失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样做，让我很失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这个工作越来越失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别让爱你的人失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己的成绩感到失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队总是输，球迷对他们失望了。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想让爸爸妈妈失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几次考试都没过，他对自己失望了。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友一次又一次骗他，他对朋友很失望。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆越来越差，客人们都失望了。", "target_word": "失望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "失望了", "label": "完成体"}, {"form": "失望地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "对人或事失去信心，对…失望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2d745d-2bca-4b89-8b23-ae7e91d17958') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90360, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "失望", "is_correct": true, "explanation": "与语境相符：他总是迟到，老师对他失去信心，正是失望。"}, {"text": "佩服", "is_correct": false, "explanation": "语义：他总是迟到，老师不会因此佩服他，与语境矛盾。"}, {"text": "感激", "is_correct": false, "explanation": "语义：感激指受到对方的帮助，与迟到的语境不符。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：老师因他总是迟到而感谢他，与语境矛盾。"}], "explanations": {"失望": "与语境相符：他总是迟到，老师对他失去信心，正是失望。", "佩服": "语义：他总是迟到，老师不会因此佩服他，与语境矛盾。", "感激": "语义：感激指受到对方的帮助，与迟到的语境不符。", "感谢": "语义：老师因他总是迟到而感谢他，与语境矛盾。"}, "sentence_index": 0, "correct_answer": "失望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个结果正是我希望的，我对此很失望。", "explanation": "这里应该用〈满意〉。失望表示希望落空而不愉快，结果正合心意时应说“满意”。"}, {"text": "他每次都热心地帮助我，我对他很失望。", "explanation": "这里应该用〈感激〉。失望表示希望落空、失去信心，别人总是帮助你时应说“感激”。"}, {"text": "大家都非常赞赏这次的计划，都对它失望了。", "explanation": "这里应该用〈赞赏〉。失望表示失去信心，对计划非常赞赏时应说“赞赏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失望", "is_correct": true, "explanation": "与语境相符：不想让父母失望，正是“失望”的用法。"}, {"text": "眼泪", "is_correct": false, "explanation": "语法：眼泪是名词，不能直接作“让”后的谓语，句子不成立。"}, {"text": "石头", "is_correct": false, "explanation": "语法：石头是名词，不能直接作“让”后的谓语，句子不成立。"}, {"text": "桌子", "is_correct": false, "explanation": "语法：桌子是名词，不能直接作“让”后的谓语，句子不成立。"}], "explanations": {"失望": "与语境相符：不想让父母失望，正是“失望”的用法。", "眼泪": "语法：眼泪是名词，不能直接作“让”后的谓语，句子不成立。", "石头": "语法：石头是名词，不能直接作“让”后的谓语，句子不成立。", "桌子": "语法：桌子是名词，不能直接作“让”后的谓语，句子不成立。"}, "sentence_index": 6, "correct_answer": "失望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次我能参加比赛，我很失望。", "explanation": "这里应该用〈高兴〉。失望表示希望落空而不愉快，能参加比赛应说“高兴”。"}, {"text": "他们的表现超出了所有人的期待，所有人都对他们失望。", "explanation": "这里应该用〈佩服〉。失望表示希望落空而不愉快，表现超出期待时应说“佩服”。"}, {"text": "这次旅行让我们玩得很痛快，我们都对它失望。", "explanation": "这里应该用〈满意〉。失望表示希望落空，旅行玩得痛快应说“对它很满意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我他的态度失望了。", "corrected_sentence": "我对他的态度失望了。", "error_description": "错误：漏掉了“对”。正确：“对……失望”，表示对某人或某事失去信心，失望的对象前要加“对”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这件事越来越的失望了。", "corrected_sentence": "他对这件事越来越失望了。", "error_description": "错误：“越来越”与“失望”之间多加了“的”。正确：“越来越”直接修饰“失望”，说“越来越失望了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
