INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90361, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女士是对成年女性很有礼貌的称呼。", "primary_collocate": null, "pronunciation": "nǚ shì", "ipa": "ny˨˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "服务员对她说：“女士，请坐这里。”", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位女士在门口等朋友。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问女士，您要喝茶还是咖啡？", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女士的包忘在车上了。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理客气地问：“女士，需要帮忙吗？”", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位女士走进了商店。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在饭店里，服务员叫她“女士”。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女士请排在后面。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位女士笑着问我路怎么走。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女士，您的菜来了，请慢用。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "女士们", "label": "复数"}], "register": "正式", "sense_fingerprint": "礼貌地称呼或指称成年女性（日常服务场合）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2d745d-2bca-4b89-8b23-ae7e91d17958') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90361, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女士", "is_correct": true, "explanation": "与语境相符：服务员礼貌地称呼成年女性，用“女士”。"}, {"text": "同学", "is_correct": false, "explanation": "语义：服务员不会称顾客为同学，与服务场合的语境不符。"}, {"text": "妈妈", "is_correct": false, "explanation": "语义：服务员不会称陌生顾客为妈妈。"}, {"text": "老公", "is_correct": false, "explanation": "语域：老公是私人称呼，不适用于服务场合。"}], "explanations": {"女士": "与语境相符：服务员礼貌地称呼成年女性，用“女士”。", "同学": "语义：服务员不会称顾客为同学，与服务场合的语境不符。", "妈妈": "语义：服务员不会称陌生顾客为妈妈。", "老公": "语域：老公是私人称呼，不适用于服务场合。"}, "sentence_index": 0, "correct_answer": "女士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口站着一只女士。", "explanation": "这里应该用〈位〉。女士指人，“只”用于动物或小物件，不能用来数人。"}, {"text": "窗边坐着一条女士。", "explanation": "这里应该用〈位〉。女士指人，“条”用于细长的物件，不能用来数人。"}, {"text": "桌边坐着一把女士。", "explanation": "这里应该用〈位〉。女士指人，“把”用于有柄的物件，不能用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90361, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女士", "is_correct": true, "explanation": "与语境相符：服务员称呼的是女性顾客，用“女士”。"}, {"text": "先生", "is_correct": false, "explanation": "语义：说话对象是女性，不能称“先生”。"}, {"text": "老婆", "is_correct": false, "explanation": "语域：老婆是私人称呼，服务员不会这样称呼顾客。"}, {"text": "叔叔", "is_correct": false, "explanation": "语义：叔叔指男性长辈，不能用来称呼这位女性。"}], "explanations": {"女士": "与语境相符：服务员称呼的是女性顾客，用“女士”。", "先生": "语义：说话对象是女性，不能称“先生”。", "老婆": "语域：老婆是私人称呼，服务员不会这样称呼顾客。", "叔叔": "语义：叔叔指男性长辈，不能用来称呼这位女性。"}, "sentence_index": 6, "correct_answer": "女士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位女士才五岁，在门口等妈妈。", "explanation": "这里应该用〈小女孩〉。女士指成年女性，五岁的孩子应称“小女孩”。"}, {"text": "这位女士还是小学生，每天背书包上学。", "explanation": "这里应该用〈小女孩〉。女士是对成年女性的尊称，用来称呼小学生不合适。"}, {"text": "那位女士是个男人，正在理发。", "explanation": "这里应该用〈男士〉。女士指女性，描述男性时要用“男士”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90361, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只女士走进了餐厅。", "corrected_sentence": "一位女士走进了餐厅。", "error_description": "错误：量词“只”多用于动物，指人应用“位”。正确：应说“一位女士”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90361, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一位女士们在等公交车。", "corrected_sentence": "一位女士在等公交车。", "error_description": "错误：“一位”已表示数量，又在“女士”后加了“们”。正确：单独指一位女性时不加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
