INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90362, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对成年女子的尊称。", "primary_collocate": null, "pronunciation": "nǚ shì", "ipa": "ny˨˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "会议上，王女士介绍了新产品。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李女士是我们公司的经理。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎各位先生和女士来参加晚会。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张女士昨天去北京出差了。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女士是今天的主讲人。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，哪位是陈女士？", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先生和女士的座位在左边。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刘女士在大学教了二十年书。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话里的那位女士说她姓赵。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的客人有三位先生和两位女士。", "target_word": "女士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "女士们", "label": "复数"}], "register": "正式", "sense_fingerprint": "对成年女子的尊称，常用于姓氏后或正式场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2d745d-2bca-4b89-8b23-ae7e91d17958') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女士", "is_correct": true, "explanation": "与语境相符：会议上在姓氏后用“女士”表示尊称。"}, {"text": "同桌", "is_correct": false, "explanation": "语义：同桌指同学关系，不能在会议上用于姓氏后的称呼。"}, {"text": "宝宝", "is_correct": false, "explanation": "语域：宝宝是亲昵称呼，不适合正式的会议场合。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“学生”不能用作姓氏后的敬称。"}], "explanations": {"女士": "与语境相符：会议上在姓氏后用“女士”表示尊称。", "同桌": "语义：同桌指同学关系，不能在会议上用于姓氏后的称呼。", "宝宝": "语域：宝宝是亲昵称呼，不适合正式的会议场合。", "学生": "搭配：“学生”不能用作姓氏后的敬称。"}, "sentence_index": 0, "correct_answer": "女士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只张女士昨天去北京出差了。", "explanation": "这里应该用〈位〉。女士指人，“只”用于动物等，不能用来数人。"}, {"text": "这条张女士昨天去北京出差了。", "explanation": "这里应该用〈位〉。女士指人，“条”用于细长的事物，不能用来数人。"}, {"text": "这副张女士昨天去北京出差了。", "explanation": "这里应该用〈位〉。女士指人，“副”用于成对的物件，不能用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女士", "is_correct": true, "explanation": "与语境相符：与“先生”并列，指女性客人的座位，用“女士”。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不能与“先生”并列作为座位的主人，语境不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：桌子不能拥有座位，“桌子的座位”搭配不当。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能坐人，与座位的语境矛盾。"}], "explanations": {"女士": "与语境相符：与“先生”并列，指女性客人的座位，用“女士”。", "猫": "语义：猫不能与“先生”并列作为座位的主人，语境不通。", "桌子": "搭配：桌子不能拥有座位，“桌子的座位”搭配不当。", "石头": "语义：石头不能坐人，与座位的语境矛盾。"}, "sentence_index": 6, "correct_answer": "女士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位女士才五岁，已经会写字了。", "explanation": "这里应该用〈小女孩〉。女士指成年女性，五岁的孩子应称“小女孩”。"}, {"text": "那位女士是个男人，头发全白了。", "explanation": "这里应该用〈男士〉。女士指女性，描述男性时要用“男士”。"}, {"text": "这位女士今年才三岁，还不会说话。", "explanation": "这里应该用〈小宝宝〉。女士指成年女性，三岁的幼儿应称“小宝宝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "张女士们今天来了。", "corrected_sentence": "张女士今天来了。", "error_description": "错误：姓氏加“女士”后又加了“们”。正确：指某位具体的女性时，“张女士”不加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这女士，请问您需要帮忙吗？", "corrected_sentence": "这位女士，请问您需要帮忙吗？", "error_description": "错误：指示词“这”后漏掉了量词“位”。正确：“这位女士”，指人要用“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bce26d45-ba91-422f-92ee-4bed92668099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
