INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90364, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "取消已有的决定、职务或处分等。", "primary_collocate": null, "pronunciation": "chè xiāo", "ipa": "ʈʂʰɤ˥˩ ɕiɑʊ̯˥", "syllable_count": 2, "sentences": [{"text": "学校撤销了对他的处分。", "target_word": "撤销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司撤销了他的职务。", "target_word": "撤销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院撤销了原来的决定。", "target_word": "撤销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理撤销了这个命令。", "target_word": "撤销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里撤销了那项旧规定。", "target_word": "撤销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长撤销了那个决定。", "target_word": "撤销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府撤销了这条规定。", "target_word": "撤销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司撤销了对她的处分。", "target_word": "撤销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理把原来的决定撤销了。", "target_word": "撤销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板撤销了那个人的职务。", "target_word": "撤销", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撤销了", "label": "体标"}, {"form": "撤销过", "label": "体标"}, {"form": "撤銷", "label": "繁体"}], "register": "正式", "sense_fingerprint": "正式取消已有的决定、职务、处分或规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a22d3499-ca45-4e80-9518-98ccdc905de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撤销", "is_correct": true, "explanation": "撤销：正式取消已有的处分，与“学校”和“对他的处分”搭配自然。"}, {"text": "颁发", "is_correct": false, "explanation": "语义：颁发用于奖状、证书等，不能用于处分。"}, {"text": "设立", "is_correct": false, "explanation": "搭配：“设立”用于机构、制度，不说“设立处分”。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：奖励与处分意思相反，学校不会“奖励”处分。"}], "explanations": {"撤销": "撤销：正式取消已有的处分，与“学校”和“对他的处分”搭配自然。", "颁发": "语义：颁发用于奖状、证书等，不能用于处分。", "设立": "搭配：“设立”用于机构、制度，不说“设立处分”。", "奖励": "语义：奖励与处分意思相反，学校不会“奖励”处分。"}, "sentence_index": 0, "correct_answer": "撤销"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛因为下雨撤销了。", "explanation": "这里应该用〈取消〉。撤销多用于决定、命令、处分等，比赛因天气停止要用取消。"}, {"text": "他撤销了那句不合适的话。", "explanation": "这里应该用〈撤回〉。撤销用于已有的决定、职务或处分，说出去的话要用“撤回”。"}, {"text": "这座老桥被经理撤销了。", "explanation": "撤销用于决定、命令、规定等抽象事项，不能用于具体的桥梁；拆除桥梁要用〈拆除〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撤销", "is_correct": true, "explanation": "撤销：正式取消已有的规定，与“政府”和“这条规定”搭配自然。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能用于规定，“政府吃了这条规定”说不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”不能用于规定，“洗这条规定”说不通。"}, {"text": "开通", "is_correct": false, "explanation": "搭配：“开通”用于线路、业务等，不说“开通规定”。"}], "explanations": {"撤销": "撤销：正式取消已有的规定，与“政府”和“这条规定”搭配自然。", "吃": "语义：“吃”不能用于规定，“政府吃了这条规定”说不通。", "洗": "语义：“洗”不能用于规定，“洗这条规定”说不通。", "开通": "搭配：“开通”用于线路、业务等，不说“开通规定”。"}, "sentence_index": 6, "correct_answer": "撤销"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司撤销了那个人。", "explanation": "这里应该用〈解雇〉。撤销用于职务、决定等，不直接用于人；公司辞退员工要用〈解雇〉。"}, {"text": "我撤销了那条短信。", "explanation": "这里应该用〈删除〉。撤销用于决定、职务、处分等，短信要说“删除”。"}, {"text": "我撤销了这把椅子。", "explanation": "撤销用于抽象的决定、命令、规定，不用于具体的家具；这里应该用〈搬走〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校上个月撤销着对她的处分。", "corrected_sentence": "学校上个月撤销了对她的处分。", "error_description": "体标错误：“撤销”是一次完成的动作，不表示持续，不能用“着”；“上个月”已经完成，应说“撤销了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校方撤销得那项决定。", "corrected_sentence": "校方撤销了那项决定。", "error_description": "结构错误：“撤销”后直接加“得”没有补语，结构不成立；这里应说“撤销了”，表示已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
