INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90365, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旁边是靠近某个东西的左边或右边。", "primary_collocate": null, "pronunciation": "páng biān", "ipa": "pʰɑŋ³⁵ pjɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "书在桌子旁边。", "target_word": "旁边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校旁边有一家小商店。", "target_word": "旁边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "椅子旁边放着一个大包。", "target_word": "旁边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把花放在门旁边。", "target_word": "旁边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行旁边是一家咖啡店。", "target_word": "旁边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河旁边有很多高高的树。", "target_word": "旁边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁站旁边新开了一家面包店。", "target_word": "旁边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家旁边有一个公园。", "target_word": "旁边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "床旁边有一个小桌子，上面放着一杯水。", "target_word": "旁边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视旁边的那盆花开了。", "target_word": "旁边", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "旁边儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "旁边（páng biān）：处所名词，指某个物体、建筑左右靠近的位置，如“学校旁边”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4928fe74-fd92-43fa-8886-52fe0aa8b3e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90365, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旁边", "is_correct": true, "explanation": "旁边：表示书在桌子的一侧，符合“书在桌子”的语境。"}, {"text": "门口", "is_correct": false, "explanation": "语义：“门口”指门的附近，“书在桌子门口”指向不明，与桌子的位置不符。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“厨房”是房间，不能直接作“桌子”的处所，“桌子厨房”不成立。"}, {"text": "天空", "is_correct": false, "explanation": "语义：书不会放在天空中，“书在桌子天空”与事实不符。"}], "explanations": {"旁边": "旁边：表示书在桌子的一侧，符合“书在桌子”的语境。", "门口": "语义：“门口”指门的附近，“书在桌子门口”指向不明，与桌子的位置不符。", "厨房": "搭配：“厨房”是房间，不能直接作“桌子”的处所，“桌子厨房”不成立。", "天空": "语义：书不会放在天空中，“书在桌子天空”与事实不符。"}, "sentence_index": 0, "correct_answer": "旁边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙放进了抽屉旁边。", "explanation": "“放进”表示放到某物的内部，这里应用〈里面〉；“旁边”指物体外侧，与“放进”不搭配。"}, {"text": "这件事的旁边还有很多问题。", "explanation": "“旁边”只指具体事物或地点的一侧，不能指抽象的事情；这里应说〈另外〉或〈此外〉。"}, {"text": "我们在三点旁边见面吧。", "explanation": "这里应用〈左右〉。“旁边”只表示空间的一侧，表示时间大约要用〈左右〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90365, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旁边", "is_correct": true, "explanation": "旁边：表示地铁站的一侧，符合“新开了一家面包店”的语境。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是教室里的用具，不能作地铁站的位置。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”不是开店的场所，“地铁站教室”不成立。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“河流”是自然水体，不能说“地铁站河流”。"}], "explanations": {"旁边": "旁边：表示地铁站的一侧，符合“新开了一家面包店”的语境。", "黑板": "语义：“黑板”是教室里的用具，不能作地铁站的位置。", "教室": "语义：“教室”不是开店的场所，“地铁站教室”不成立。", "河流": "搭配：“河流”是自然水体，不能说“地铁站河流”。"}, "sentence_index": 6, "correct_answer": "旁边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的旁边很便宜。", "explanation": "这里应用〈价格〉。“旁边”只表示位置，不能形容价钱；应说“这件衣服的价格很便宜”。"}, {"text": "我们的旁边有很多机会。", "explanation": "这里应用〈周围〉（四周的人或事物）。“旁边”只指具体位置的一侧，不能指抽象的机会；这里应说〈周围〉。"}, {"text": "我家在学校旁边一百米之外。", "explanation": "“旁边”指紧靠的一侧，与“一百米之外”的远距离矛盾；这里应说〈附近〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫床旁边睡着了。", "corrected_sentence": "小猫在床旁边睡着了。", "error_description": "错误在介词：“床旁边”作处所要在前面加介词“在”，应说“在床旁边”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋楼旁边上停着很多自行车。", "corrected_sentence": "这栋楼旁边停着很多自行车。", "error_description": "错误在方位词：“旁边”本身已表示方位，后面不能再加“上”，应说“旁边停着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
