INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90366, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "靠近某人或某物的一侧的位置。", "primary_collocate": null, "pronunciation": "páng biān", "ipa": "pʰɑŋ³⁵ pjɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "我旁边坐着一位老人。", "target_word": "旁边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在我旁边。", "target_word": "旁边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈旁边的小女孩是我妹妹。", "target_word": "旁边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你站在老师旁边。", "target_word": "旁边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他旁边的人一直在看手机。", "target_word": "旁边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想坐在朋友旁边。", "target_word": "旁边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子一直待在妈妈旁边，不愿意走开。", "target_word": "旁边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在我旁边小声说了几句话。", "target_word": "旁边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位坐在你旁边的先生是谁？", "target_word": "旁边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "狗安静地躺在主人旁边。", "target_word": "旁边", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "旁边儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "旁边（páng biān）：处所名词，指人身边靠近的一侧，如“坐在我旁边”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4928fe74-fd92-43fa-8886-52fe0aa8b3e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90366, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旁边", "is_correct": true, "explanation": "旁边：表示老人坐在“我”的身边，符合语境。"}, {"text": "水里", "is_correct": false, "explanation": "语义：人不能坐在水里，“我水里坐着一位老人”不成立。"}, {"text": "天空", "is_correct": false, "explanation": "语义：人不会“坐”在天空中，与“坐着”的语境冲突。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“我”后直接接“教室”作处所不通顺，需要说“我的教室”，与“坐着”不搭配。"}], "explanations": {"旁边": "旁边：表示老人坐在“我”的身边，符合语境。", "水里": "语义：人不能坐在水里，“我水里坐着一位老人”不成立。", "天空": "语义：人不会“坐”在天空中，与“坐着”的语境冲突。", "教室": "搭配：“我”后直接接“教室”作处所不通顺，需要说“我的教室”，与“坐着”不搭配。"}, "sentence_index": 0, "correct_answer": "旁边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在老师旁边，两人面对面地说话。", "explanation": "“面对面”要求位于对面，与“旁边”的并排位置冲突；这里应说〈对面〉。"}, {"text": "我们约在三点旁边见面吧。", "explanation": "这里应用〈左右〉。“旁边”只表示空间的一侧，表示时间大约要用〈左右〉。"}, {"text": "他在一周旁边就学会了游泳。", "explanation": "这里应用〈之内〉。“旁边”只表示空间的一侧，不能表示时段；一周之内要说〈之内〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旁边", "is_correct": true, "explanation": "旁边：表示孩子待在妈妈的身边，符合“不愿意走开”的语境。"}, {"text": "对岸", "is_correct": false, "explanation": "语义：“对岸”指河流的另一边，不能指人的身边，“待在妈妈对岸”不成立。"}, {"text": "河底", "is_correct": false, "explanation": "搭配：“待在”后面的处所不能是“河底”这种与人无关的地方，与“妈妈”无法搭配。"}, {"text": "山顶", "is_correct": false, "explanation": "语义：“山顶”指山的最高处，不能作“妈妈”身边的处所，与语境不符。"}], "explanations": {"旁边": "旁边：表示孩子待在妈妈的身边，符合“不愿意走开”的语境。", "对岸": "语义：“对岸”指河流的另一边，不能指人的身边，“待在妈妈对岸”不成立。", "河底": "搭配：“待在”后面的处所不能是“河底”这种与人无关的地方，与“妈妈”无法搭配。", "山顶": "语义：“山顶”指山的最高处，不能作“妈妈”身边的处所，与语境不符。"}, "sentence_index": 6, "correct_answer": "旁边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在他的旁边一公里处下了车。", "explanation": "“旁边”指紧靠的一侧，与“一公里处”的远距离矛盾；这里应说〈附近〉。"}, {"text": "我们的感情在旁边很深。", "explanation": "这里应用〈深厚〉。“旁边”只指具体位置的一侧，不能形容抽象的感情；形容感情深要说〈深厚〉。"}, {"text": "他把书放进了我旁边。", "explanation": "“放进”表示放到某物的内部，这里应用〈里面〉；“旁边”指外侧，不能与“放进”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只小猫睡妈妈旁边。", "corrected_sentence": "一只小猫睡在妈妈旁边。", "error_description": "错误在介词：漏掉了“在”，“妈妈旁边”作处所要说“在妈妈旁边”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狗安静地待在姐姐旁边里。", "corrected_sentence": "小狗安静地待在姐姐旁边。", "error_description": "错误在方位词：“旁边”之后多加了“里”，方位词重复，应只说“待在姐姐旁边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
