INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90367, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有希望是说这件事很可能会成功。", "primary_collocate": null, "pronunciation": "yǒu xī wàng", "ipa": "joʊ˨˩˦ ɕi˥˥ wɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这次面试很顺利，我有希望得到这份工作。", "target_word": "有希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的比赛成绩最好，有希望拿冠军。", "target_word": "有希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，明天有希望放晴。", "target_word": "有希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这个办法很有希望治好他。", "target_word": "有希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们已经进入决赛，很有希望赢。", "target_word": "有希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店今年有希望赚到钱。", "target_word": "有希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你准备得这么充分，有希望考出好成绩。", "target_word": "有希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王最近天天练习，有希望考第一。", "target_word": "有希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次谈判有希望成功，大家都很高兴。", "target_word": "有希望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画很好，有希望在比赛中得奖。", "target_word": "有希望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有希望", "label": "否定式"}], "register": "中性", "sense_fingerprint": "有希望：说某件事很可能会成功", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc92a6b-6dc2-4a5f-9877-7bf97a1744bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90367, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有希望", "is_correct": true, "explanation": "有希望：很可能得到这份工作，与「面试很顺利」的语境相符。"}, {"text": "不错", "is_correct": false, "explanation": "搭配：「不错」用于评价状况，不能用来修饰「得到这份工作」。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：「漂亮」说外貌，不能用来说能否得到工作。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」说身材，与能否得到工作无关。"}], "explanations": {"有希望": "有希望：很可能得到这份工作，与「面试很顺利」的语境相符。", "不错": "搭配：「不错」用于评价状况，不能用来修饰「得到这份工作」。", "漂亮": "体貌：「漂亮」说外貌，不能用来说能否得到工作。", "高大": "体貌：「高大」说身材，与能否得到工作无关。"}, "sentence_index": 0, "correct_answer": "有希望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛，我们很有希望输给对手。", "explanation": "这里应该用〈可能〉。「有希望」只用于说有利的前景，说输掉比赛这种不利结果要用〈可能〉。"}, {"text": "我的成绩很有希望考得很差。", "explanation": "这里应该用〈有可能〉。「有希望」只用于说好的结果有实现的可能，说成绩很差要用〈有可能〉。"}, {"text": "这种病很有希望加重。", "explanation": "这里应该用〈可能〉。「有希望」只用于说好的结果可能实现，说病情加重这种坏结果要用〈可能〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90367, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有希望", "is_correct": true, "explanation": "有希望：很可能考出好成绩，与「准备得很充分」的语境相符。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：「懒惰」与「准备得很充分」的意思相矛盾，不能用来说考出好成绩。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：「美丽」形容外貌或景色，不能修饰「考出好成绩」。"}, {"text": "寒冷", "is_correct": false, "explanation": "搭配：「寒冷」形容天气或感觉，不能用来说考试的结果。"}], "explanations": {"有希望": "有希望：很可能考出好成绩，与「准备得很充分」的语境相符。", "懒惰": "语义：「懒惰」与「准备得很充分」的意思相矛盾，不能用来说考出好成绩。", "美丽": "搭配：「美丽」形容外貌或景色，不能修饰「考出好成绩」。", "寒冷": "搭配：「寒冷」形容天气或感觉，不能用来说考试的结果。"}, "sentence_index": 6, "correct_answer": "有希望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子很有希望，用了十年都没坏。", "explanation": "这里应该用〈结实〉。「有希望」只说事情的前景，不能用来形容椅子；形容椅子牢固、不易坏要用〈结实〉。"}, {"text": "他的身高很有希望，比同学都高。", "explanation": "这里应该用〈高〉。「有希望」只用于事情、计划等的前景，不能用来说身高这类身体状况；直接形容身高要用〈高〉。"}, {"text": "这顿饭很有希望，味道很香。", "explanation": "这里应该用〈好吃〉。「有希望」只用于事情、计划等的前景，不能用来形容饭菜；评价饭菜的味道要用〈好吃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90367, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个办法很有希望的解决问题。", "corrected_sentence": "这个办法很有希望解决问题。", "error_description": "结构助词错误：「有希望」后面直接接动词时不能加「的」，应说「很有希望解决问题」，多出的「的」是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90367, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这次准备得很充分，很不有希望拿到奖学金。", "corrected_sentence": "他这次准备得很充分，很有希望拿到奖学金。", "error_description": "错误：「有希望」是肯定形式，前面不能加否定词「不」，多出的「不」是错误的；否定要说「没有希望」。应删去「不」，说「很有希望拿到奖学金」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
