INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90376, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "互相比较。", "primary_collocate": null, "pronunciation": "xiāng bǐ", "ipa": "ɕiaŋ˥ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这两家饭馆的菜很难相比。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和北京相比，这个小城安静得多。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人的汉语水平不能相比。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种手机相比，哪一种更便宜？", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跟我相比，弟弟更喜欢运动。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个球队的力量差得太远，没法相比。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服和那件相比，颜色更好看。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个老师的方法不同，很难相比。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与去年相比，我今年的工作轻松多了。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个办法相比，第二个最省钱。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相比之下", "label": "复合"}], "register": "中性", "sense_fingerprint": "相比：两者互相比较", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b53e4b0-c261-4aa3-a7a3-270daa3968ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相比", "is_correct": true, "explanation": "相比：互相比较，这里指两家饭馆的菜难以放在一起比较。"}, {"text": "讲述", "is_correct": false, "explanation": "搭配：“讲述”的对象是故事、经历等，不与“菜”搭配，句子不通。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”是身体动作，与菜的比较毫不相关，语义不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌，不能用于菜，句子不通。"}], "explanations": {"相比": "相比：互相比较，这里指两家饭馆的菜难以放在一起比较。", "讲述": "搭配：“讲述”的对象是故事、经历等，不与“菜”搭配，句子不通。", "跳": "语义：“跳”是身体动作，与菜的比较毫不相关，语义不通。", "唱": "语义：“唱”的对象是歌，不能用于菜，句子不通。"}, "sentence_index": 0, "correct_answer": "相比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的颜色相比得很强烈。", "explanation": "这里应该用〈对比〉。对比可指颜色的反差，能说“颜色很强烈”；相比只表示互相比较，不能描述颜色的强弱。"}, {"text": "两个老同学在车站相比，一起吃了午饭。", "explanation": "这里应该用〈见面〉。相比表示互相比较，不表示碰面；“在车站见面”才对。"}, {"text": "两队在球场上相比得很激烈。", "explanation": "这里应该用〈比赛〉。相比表示互相比较，不表示竞争；两队在球场上较量，应说“比赛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相比", "is_correct": true, "explanation": "相比：互相比较，这里指两件衣服之间比较颜色。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洁的动作，与比较颜色的语境不相关，句子不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣服本身，不能用于两件衣服之间的比较结构。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要送出的东西和接受者两个成分，“和那件送”不能构成完整句子。"}], "explanations": {"相比": "相比：互相比较，这里指两件衣服之间比较颜色。", "洗": "语义：“洗”是清洁的动作，与比较颜色的语境不相关，句子不通。", "穿": "搭配：“穿”的对象是衣服本身，不能用于两件衣服之间的比较结构。", "送": "配价：“送”需要送出的东西和接受者两个成分，“和那件送”不能构成完整句子。"}, "sentence_index": 6, "correct_answer": "相比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我和妈妈相比去逛商场了。", "explanation": "这里应该用〈一起〉。相比表示互相比较，不表示共同做事；“和妈妈一起去逛商场”才对。"}, {"text": "我下班以后和室友相比，一起去吃了晚饭。", "explanation": "这里应该用〈见面〉。相比表示互相比较，不表示碰面；“见面”才对。"}, {"text": "我们在电话里相比了很久，最后决定明天出发。", "explanation": "这里应该用〈商量〉。相比表示互相比较，不表示交换意见、做决定；“商量了很久”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个孩子的成绩很难互相相比。", "corrected_sentence": "这两个孩子的成绩很难相比。", "error_description": "错误形式「互相相比」，正确形式「相比」。“相比”本身已含“互相”的意思，再加“互相”属于重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两条河被相比，哪条更宽？", "corrected_sentence": "这两条河相比，哪条更宽？", "error_description": "错误形式「被相比」，正确形式「相比」。“相比”是不及物的互相比较，没有受事，不能用“被”构成被动句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
