INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90377, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "黑白是黑色和白色。", "primary_collocate": null, "pronunciation": "hēi bái", "ipa": "xeɪ⁵⁵ paɪ³⁵", "syllable_count": 2, "sentences": [{"text": "这张照片是黑白的。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶喜欢看黑白电影。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "斑马身上有黑白条纹。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿了一件黑白相间的外套。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕突然变成黑白了。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电视是黑白的。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这张画涂成黑白两色。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑白搭配很简单大方。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老照片大多是黑白的。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拍过很多黑白照片。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黑白片", "label": "复合词"}, {"form": "黑白电视", "label": "复合词"}], "register": "中性", "sense_fingerprint": "黑色和白色两种颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b588376-c1a7-4853-aa69-24c24846ed71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90377, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咸", "is_correct": false, "explanation": "语义：「咸」指味道，照片不能是咸的。"}, {"text": "慢", "is_correct": false, "explanation": "语义：「慢」指速度，不能用来描述照片的颜色。"}, {"text": "黑白", "is_correct": true, "explanation": "正确：黑白指黑色和白色，用来描述照片的颜色。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：「聪明」只用于人或动物，不能用来形容照片。"}], "explanations": {"咸": "语义：「咸」指味道，照片不能是咸的。", "慢": "语义：「慢」指速度，不能用来描述照片的颜色。", "黑白": "正确：黑白指黑色和白色，用来描述照片的颜色。", "聪明": "搭配：「聪明」只用于人或动物，不能用来形容照片。"}, "sentence_index": 0, "correct_answer": "黑白"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯茶的味道是黑白的。", "explanation": "这里〈黑白〉用的是颜色义，味道没有颜色，应说〈香〉或〈苦〉。"}, {"text": "这首歌是黑白的。", "explanation": "这里〈黑白〉用的是颜色义，歌曲没有颜色；评价歌曲应说〈好听〉。"}, {"text": "今天的空气是黑白的。", "explanation": "这里〈黑白〉用的是颜色义，空气无色；形容天气应说〈灰蒙蒙〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90377, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彩虹", "is_correct": false, "explanation": "搭配：「涂成……两色」要用颜色词，不能说「彩虹两色」。"}, {"text": "大小", "is_correct": false, "explanation": "语义：「大小」指尺寸，不能表示颜色，句子不通。"}, {"text": "轻重", "is_correct": false, "explanation": "语义：「轻重」指重量，不能用来说明颜色。"}, {"text": "黑白", "is_correct": true, "explanation": "正确：黑白指黑色和白色，与「涂成……两色」搭配。"}], "explanations": {"彩虹": "搭配：「涂成……两色」要用颜色词，不能说「彩虹两色」。", "大小": "语义：「大小」指尺寸，不能表示颜色，句子不通。", "轻重": "语义：「轻重」指重量，不能用来说明颜色。", "黑白": "正确：黑白指黑色和白色，与「涂成……两色」搭配。"}, "sentence_index": 6, "correct_answer": "黑白"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的声音是黑白的。", "explanation": "这里〈黑白〉用的是颜色义，声音没有颜色；形容声音应说〈低沉〉或〈清脆〉。"}, {"text": "这次聚会的气氛是黑白的。", "explanation": "这里〈黑白〉用的是颜色义，气氛没有颜色；形容气氛应说〈热闹〉。"}, {"text": "这顿早饭是黑白的。", "explanation": "这里〈黑白〉用的是颜色义，早饭没有颜色；形容早饭应说〈丰盛〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90377, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家那台旧电视很黑白的。", "corrected_sentence": "我家那台旧电视是黑白的。", "error_description": "错误：“黑白”表示颜色类别（与“彩色”相对），不能受“很”程度修饰。应把“很”换成“是”，说“我家那台旧电视是黑白的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90377, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张照片的黑白对比了很强。", "corrected_sentence": "这张照片的黑白对比很强。", "error_description": "错误：“对比”后面多加了动态助词“了”。“黑白对比很强”是描述性说法，不应加“了”，应说“这张照片的黑白对比很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
