INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90378, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻是非、对错。", "primary_collocate": null, "pronunciation": "hēi bái", "ipa": "xeɪ⁵⁵ paɪ³⁵", "syllable_count": 2, "sentences": [{"text": "做事要讲道理，不能颠倒黑白。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人要分清黑白。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不分黑白就批评了我。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官应该公正，不能混淆黑白。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情的黑白，大家心里都很清楚。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还小，分不清黑白。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真相还没有出来，谁也说不清黑白。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "媒体不能把黑白说反了。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她明辨黑白，从不偏听偏信。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常常提醒我们要分清黑白。", "target_word": "黑白", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黑白分明", "label": "复合词"}, {"form": "黑白颠倒", "label": "复合词"}], "register": "中性", "sense_fingerprint": "比喻是非、对错，如「分清黑白」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b588376-c1a7-4853-aa69-24c24846ed71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷热", "is_correct": false, "explanation": "语义：「冷热」指温度，不能用来说明做事的是非，句子不通。"}, {"text": "咸淡", "is_correct": false, "explanation": "语义：「咸淡」指味道，与做事的是非无关，句子不通。"}, {"text": "黑白", "is_correct": true, "explanation": "正确：「颠倒黑白」指把是非对错弄颠倒，与「不能颠倒」搭配。"}, {"text": "快慢", "is_correct": false, "explanation": "语义：「快慢」指速度，不能用来指是非对错。"}], "explanations": {"冷热": "语义：「冷热」指温度，不能用来说明做事的是非，句子不通。", "咸淡": "语义：「咸淡」指味道，与做事的是非无关，句子不通。", "黑白": "正确：「颠倒黑白」指把是非对错弄颠倒，与「不能颠倒」搭配。", "快慢": "语义：「快慢」指速度，不能用来指是非对错。"}, "sentence_index": 0, "correct_answer": "黑白"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子的黑白很结实。", "explanation": "这里〈黑白〉指是非对错，桌子没有是非，形容桌子应说〈很结实〉或〈很牢固〉。"}, {"text": "他的黑白比哥哥高。", "explanation": "这里〈黑白〉指是非对错，不能比高矮，应说〈个子〉比哥哥高。"}, {"text": "这顿饭的黑白很香。", "explanation": "这里〈黑白〉指是非对错，饭菜没有是非，应说〈味道〉很香。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大小", "is_correct": false, "explanation": "语义：「大小」指尺寸，与真相是否清楚无关，句子不通。"}, {"text": "冷暖", "is_correct": false, "explanation": "语义：「冷暖」指温度，不能用来说明真相的对错。"}, {"text": "黑白", "is_correct": true, "explanation": "正确：「说不清黑白」指分不清是非对错，与「真相还没有出来」搭配。"}, {"text": "咸淡", "is_correct": false, "explanation": "语义：「咸淡」指味道，与真相无关，句子不通。"}], "explanations": {"大小": "语义：「大小」指尺寸，与真相是否清楚无关，句子不通。", "冷暖": "语义：「冷暖」指温度，不能用来说明真相的对错。", "黑白": "正确：「说不清黑白」指分不清是非对错，与「真相还没有出来」搭配。", "咸淡": "语义：「咸淡」指味道，与真相无关，句子不通。"}, "sentence_index": 6, "correct_answer": "黑白"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一只黑白。", "explanation": "这里〈黑白〉指是非对错，是抽象的，不是能买的东西，也不能用量词「只」。"}, {"text": "他把黑白放进了冰箱。", "explanation": "这里〈黑白〉指是非对错，不是实物，不能放进冰箱。"}, {"text": "这次考试的黑白很难。", "explanation": "这里〈黑白〉指是非对错，不能评价考试难易，应说考试的〈题目〉很难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "做人要把分清黑白，不能随便说话。", "corrected_sentence": "做人要分清黑白，不能随便说话。", "error_description": "错误：句中多了「把」，「把」后面要先接宾语，不能直接接动词「分清」。应去掉「把」，说「做人要分清黑白」（或说「把黑白分清」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子还小，分清不黑白。", "corrected_sentence": "孩子还小，分不清黑白。", "error_description": "错误：「不」的位置不对。可能补语的否定式要把「不」放在动词和补语中间，说「分不清」，不说「分清不」。应改为「孩子还小，分不清黑白」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
