INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90379, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "吃饭时，吃一次叫一顿。", "primary_collocate": null, "pronunciation": "dùn", "ipa": "twən˥˩", "syllable_count": 1, "sentences": [{"text": "他一天吃四顿饭。", "target_word": "顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一顿吃了两碗饭。", "target_word": "顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这顿饭是谁做的？", "target_word": "顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈为我们做了一顿晚饭。", "target_word": "顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天只吃了一顿。", "target_word": "顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一顿饭花了不少钱。", "target_word": "顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我请你吃一顿火锅。", "target_word": "顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶一天只吃两顿饭。", "target_word": "顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这顿早饭我们吃了半个小时。", "target_word": "顿", "complexity_tier": "T3", "furigana": "zhè dùn zǎofàn wǒmen chī le bàn gè xiǎoshí.", "sentence_source": "generated"}, {"text": "我们在家吃了一顿饺子。", "target_word": "顿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "量词，计算吃饭的次数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4928fe74-fd92-43fa-8886-52fe0aa8b3e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90379, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "顿", "is_correct": true, "explanation": "顿，dùn，量词，指吃饭的一次，是正确答案。"}, {"text": "吨", "is_correct": false, "explanation": "dūn（第一声）与 dùn（第四声）声调不同，意思是重量单位“吨”。"}, {"text": "蹲", "is_correct": false, "explanation": "dūn（第一声）与 dùn（第四声）声调不同，意思是“蹲下”。"}, {"text": "段", "is_correct": false, "explanation": "duàn 与 dùn 韵母不同（an 与 en），意思是“一段”。"}, {"text": "屯", "is_correct": false, "explanation": "tún 与 dùn 声母和声调都不同，意思是“屯”，指聚集或储存。"}], "explanations": {"顿": "顿，dùn，量词，指吃饭的一次，是正确答案。", "吨": "dūn（第一声）与 dùn（第四声）声调不同，意思是重量单位“吨”。", "蹲": "dūn（第一声）与 dùn（第四声）声调不同，意思是“蹲下”。", "段": "duàn 与 dùn 韵母不同（an 与 en），意思是“一段”。", "屯": "tún 与 dùn 声母和声调都不同，意思是“屯”，指聚集或储存。"}, "sentence_index": null, "correct_answer": "顿"}, "level_3": {"options": [{"text": "只", "is_correct": false, "explanation": "搭配：“只”不计算饭，“吃四只饭”不成立。"}, {"text": "顿", "is_correct": true, "explanation": "顿是吃饭次数的量词，与“吃四……饭”搭配。"}, {"text": "根", "is_correct": false, "explanation": "语义：“根”指细长的东西，与吃饭次数无关。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，不能计算饭。"}], "explanations": {"只": "搭配：“只”不计算饭，“吃四只饭”不成立。", "顿": "顿是吃饭次数的量词，与“吃四……饭”搭配。", "根": "语义：“根”指细长的东西，与吃饭次数无关。", "张": "搭配：“张”用于平面的东西，不能计算饭。"}, "sentence_index": 0, "correct_answer": "顿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天去了一顿医院。", "explanation": "这里应该用〈次〉。去医院的次数要用次，顿只用于一餐饭。"}, {"text": "这顿书很厚。", "explanation": "这里应该用〈本〉。书要用本计量，顿只用于一餐饭。"}, {"text": "我们在学校开了一顿会。", "explanation": "这里可用〈场〉或〈次〉。会议可以用场或次计量，顿只用于一餐饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90379, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "顿", "is_correct": true, "explanation": "顿，dùn，量词，指吃饭的一次，是正确答案。"}, {"text": "墩", "is_correct": false, "explanation": "dūn（第一声）与 dùn（第四声）声调不同，意思是“墩子”。"}, {"text": "对", "is_correct": false, "explanation": "duì 与 dùn 声调相同，韵母不同（ui 与 un），意思是“对”。"}, {"text": "堆", "is_correct": false, "explanation": "duī 与 dùn 韵母不同（ui 与 un）且声调不同，意思是“堆”。"}, {"text": "吞", "is_correct": false, "explanation": "tūn 与 dùn 声母和声调都不同，意思是“吞”。"}], "explanations": {"顿": "顿，dùn，量词，指吃饭的一次，是正确答案。", "墩": "dūn（第一声）与 dùn（第四声）声调不同，意思是“墩子”。", "对": "duì 与 dùn 声调相同，韵母不同（ui 与 un），意思是“对”。", "堆": "duī 与 dùn 韵母不同（ui 与 un）且声调不同，意思是“堆”。", "吞": "tūn 与 dùn 声母和声调都不同，意思是“吞”。"}, "sentence_index": null, "correct_answer": "顿"}, "level_3": {"options": [{"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、桥等大型固定物，不能计算火锅。"}, {"text": "副", "is_correct": false, "explanation": "语义：“副”用于成套的东西，与吃饭的次数无关。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于可握的东西，火锅不能这样计量。"}, {"text": "顿", "is_correct": true, "explanation": "顿指一次吃饭，“请你吃一顿火锅”表示一次聚餐。"}], "explanations": {"座": "搭配：“座”用于山、桥等大型固定物，不能计算火锅。", "副": "语义：“副”用于成套的东西，与吃饭的次数无关。", "把": "搭配：“把”用于可握的东西，火锅不能这样计量。", "顿": "顿指一次吃饭，“请你吃一顿火锅”表示一次聚餐。"}, "sentence_index": 6, "correct_answer": "顿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这顿云很大，遮住了太阳。", "explanation": "这里可用〈朵〉或〈片〉。云可以用朵或片计量，顿只用于一餐饭。"}, {"text": "那顿路很长。", "explanation": "这里可用〈条〉或〈段〉。路可以用条或段计量，顿只用于一餐饭。"}, {"text": "这顿孩子很可爱。", "explanation": "这里应该用〈个〉。孩子是人，要用个计量，顿只用于吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90379, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每天吃两个顿饭。", "corrected_sentence": "我们每天吃两顿饭。", "error_description": "错误形式：“两个顿饭”，多加了“个”；正确形式：“两顿饭”。顿作量词时，数词后直接接顿。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90379, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐为我们做了一个顿午饭。", "corrected_sentence": "姐姐为我们做了一顿午饭。", "error_description": "错误形式：“一个顿午饭”，在“顿”前多加了“个”；正确形式：“一顿午饭”。顿作量词时，数词后直接接顿，不能再加“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
