INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90385, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里很想得到或做到的事。", "primary_collocate": null, "pronunciation": "yuàn wàng", "ipa": "ɥɛn˥˩ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他心里有一个愿望，想有一只小狗。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买一辆自行车是他多年的愿望。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的愿望很简单，就是睡个好觉。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的愿望很小，只想吃妈妈做的饭。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的愿望是得到一个新书包。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学钢琴是我很久以来的愿望。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于做到了，满足了多年的愿望。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对朋友说出了心里的愿望。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的愿望是和家人一起吃饭。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的愿望不大，只想有一间安静的房子。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "愿望清单", "label": "复合"}, {"form": "願望", "label": "繁体"}], "register": "中性", "sense_fingerprint": "愿望：心里很想得到或做到的某件具体的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6cfd6c5-0201-4335-98b8-7045c06a3902') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90385, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习或工作的任务，不是心里想要的东西。"}, {"text": "愿望", "is_correct": true, "explanation": "正确：“愿望”指心里很想得到的事，与“想有一只小狗”相合。"}, {"text": "路标", "is_correct": false, "explanation": "语义：“路标”是道路上的指示牌，不是心里想要的东西。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指过去的事，与“想有一只小狗”的未来意愿矛盾。"}], "explanations": {"作业": "语义：“作业”是学习或工作的任务，不是心里想要的东西。", "愿望": "正确：“愿望”指心里很想得到的事，与“想有一只小狗”相合。", "路标": "语义：“路标”是道路上的指示牌，不是心里想要的东西。", "回忆": "语义：“回忆”指过去的事，与“想有一只小狗”的未来意愿矛盾。"}, "sentence_index": 0, "correct_answer": "愿望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司制定了明年的愿望。", "explanation": "这里应该用〈计划〉。“制定”用于计划、方案等有条理的安排，“愿望”不能被制定。"}, {"text": "他经过讨论，最终做出了愿望。", "explanation": "这里应该用〈决定〉。“做出决定”是常用搭配，“愿望”不能说“做出”。"}, {"text": "这顿饭的愿望很好吃。", "explanation": "这里应该用〈味道〉。“愿望”指心里的想法，不能用来形容饭菜的口味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90385, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "债务", "is_correct": false, "explanation": "搭配：“满足”搭配“愿望、需要、要求”，不能说“满足债务”。"}, {"text": "愿望", "is_correct": true, "explanation": "正确：“满足多年的愿望”是常用说法，与“做到了”相合。"}, {"text": "伤痛", "is_correct": false, "explanation": "语义：“伤痛”指痛苦的感受，不能被“满足”。"}, {"text": "任务", "is_correct": false, "explanation": "搭配：“任务”通常说“完成”，不说“满足”。"}], "explanations": {"债务": "搭配：“满足”搭配“愿望、需要、要求”，不能说“满足债务”。", "愿望": "正确：“满足多年的愿望”是常用说法，与“做到了”相合。", "伤痛": "语义：“伤痛”指痛苦的感受，不能被“满足”。", "任务": "搭配：“任务”通常说“完成”，不说“满足”。"}, "sentence_index": 6, "correct_answer": "愿望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考试前他只剩一线愿望。", "explanation": "这里应该用〈希望〉。“一线希望”是固定说法，“愿望”不能受“一线”修饰。"}, {"text": "我一口气把愿望喝光了。", "explanation": "这里应该用〈牛奶〉。“喝”的对象应是饮品，“愿望”不能被喝。"}, {"text": "他下定了愿望，要戒烟。", "explanation": "这里应该用〈决心〉。“下定决心”是固定说法，“愿望”不能说“下定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90385, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从小就有一只愿望，想当画家。", "corrected_sentence": "我从小就有一个愿望，想当画家。", "error_description": "量词错误：“愿望”前应用量词“个”，不能用“只”（“只”多用于动物或成对的东西）。正确说法是“一个愿望”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90385, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们过生日的时候都会许一张愿望。", "corrected_sentence": "孩子们过生日的时候都会许一个愿望。", "error_description": "量词错误：“愿望”前应用量词“个”，不能用“张”（“张”用于纸、桌子等平面的东西）。正确说法是“许一个愿望”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
