INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90387, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90387, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "等于是两边一样多。二加二等于四。", "primary_collocate": null, "pronunciation": "děng yú", "ipa": "tɤŋ˨˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "二加二等于四。", "target_word": "等于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "三乘三等于九。", "target_word": "等于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "十减三等于七。", "target_word": "等于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "五加五等于几？", "target_word": "等于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一米等于一百厘米。", "target_word": "等于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一百减五十等于五十。", "target_word": "等于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我：六加八等于多少？", "target_word": "等于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我算了一下，三十加四十等于七十。", "target_word": "等于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "四乘五等于二十。", "target_word": "等于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一加一不等于三，你算错了。", "target_word": "等于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不等于", "label": "否定形式"}, {"form": "等於", "label": "繁体"}], "register": "中性", "sense_fingerprint": "算式中两边的数相同：甲等于乙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2a424d-fb6a-4c27-a32b-e3eed49ee37f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90387, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "属于", "is_correct": false, "explanation": "语义：属于表示隶属关系，数字之间不能说“属于”，这里应说“等于”。"}, {"text": "等于", "is_correct": true, "explanation": "正确：“等于”表示两边数量相同，“二加二等于四”是算式的正确说法。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与数字组成算式，“二加二吃四”说不通。"}, {"text": "欠", "is_correct": false, "explanation": "语义：欠表示欠债或欠缺，与算式结果无关，“二加二欠四”说不通。"}], "explanations": {"属于": "语义：属于表示隶属关系，数字之间不能说“属于”，这里应说“等于”。", "等于": "正确：“等于”表示两边数量相同，“二加二等于四”是算式的正确说法。", "吃": "搭配：“吃”不能与数字组成算式，“二加二吃四”说不通。", "欠": "语义：欠表示欠债或欠缺，与算式结果无关，“二加二欠四”说不通。"}, "sentence_index": 0, "correct_answer": "等于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的名字等于小明。", "explanation": "这里应该用〈是〉。等于表示数量或性质相当，不能用来说明名字，应说“我的名字是小明”。"}, {"text": "今天等于星期一。", "explanation": "这里应该用〈是〉。等于用于数量相同的算式，说明今天是星期几要用“是”，应说“今天是星期一”。"}, {"text": "六等于偶数。", "explanation": "这里应该用〈属于〉。等于要求两边数量相同，六只是偶数中的一个，应说“六属于偶数”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90387, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拿", "is_correct": false, "explanation": "搭配：“拿”不能与算式结果组成问句，“六加八拿多少”说不通。"}, {"text": "换", "is_correct": false, "explanation": "配价：“换”需要“换成”的对象，句中没有可以替换的对象，“六加八换多少”说不通。"}, {"text": "失去", "is_correct": false, "explanation": "语义：失去表示丢失，与求算式结果无关，“六加八失去多少”说不通。"}, {"text": "等于", "is_correct": true, "explanation": "正确：问算式结果要用“等于多少”，这是固定的问法。"}], "explanations": {"拿": "搭配：“拿”不能与算式结果组成问句，“六加八拿多少”说不通。", "换": "配价：“换”需要“换成”的对象，句中没有可以替换的对象，“六加八换多少”说不通。", "失去": "语义：失去表示丢失，与求算式结果无关，“六加八失去多少”说不通。", "等于": "正确：问算式结果要用“等于多少”，这是固定的问法。"}, "sentence_index": 6, "correct_answer": "等于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子等于一只猫。", "explanation": "这里应该用〈像〉。等于要求两边数量或性质相当，桌子与猫不能相当；说一物像另一物要用像。"}, {"text": "这些零件等于一台机器。", "explanation": "这里应该用〈组成〉。等于表示数量或性质相当，零件构成整体要用组成，应说“这些零件组成一台机器”。"}, {"text": "我等于北京人。", "explanation": "这里应该用〈是〉。等于表示两边数量相同，说明一个人是哪里人要用“是”，应说“我是北京人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三加三等于不六。", "corrected_sentence": "三加三等于六。", "error_description": "错误：句中多出了否定词“不”，放在了“等于”和“六”之间。“三加三等于六”是肯定句，应删去“不”；否定的说法是“不等于”，不能说“等于不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "八加七等于了十五。", "corrected_sentence": "八加七等于十五。", "error_description": "错误：“等于”后面不能加“了”。算式陈述句中表示相等的“等于”不带“了”，应去掉“了”，写作“八加七等于十五”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
