INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90388, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "数量上相等；性质上无差别，如同。", "primary_collocate": null, "pronunciation": "děng yú", "ipa": "tɤŋ˨˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "不说话等于同意。", "target_word": "等于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "借钱不还等于偷钱。", "target_word": "等于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你这样做等于害了他。", "target_word": "等于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不回答等于拒绝了。", "target_word": "等于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，不吃药等于不治病。", "target_word": "等于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份工作钱太少，等于没有工资。", "target_word": "等于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个人干的活等于三个人干的。", "target_word": "等于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你把钱都花光了，等于白干了半年。", "target_word": "等于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有目标地混日子，等于白白浪费了人生。", "target_word": "等于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对他来说，一天不玩手机等于过了一年。", "target_word": "等于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不等于", "label": "否定形式"}, {"form": "等於", "label": "繁体"}], "register": "中性", "sense_fingerprint": "性质或结果上没有差别，相当于、如同：这样做等于那样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2a424d-fb6a-4c27-a32b-e3eed49ee37f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90388, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "属于", "is_correct": false, "explanation": "语义：属于表示隶属关系，不说话与同意之间不是隶属关系。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“同意”组成这样的比较说法，“不说话吃同意”说不通。"}, {"text": "超过", "is_correct": false, "explanation": "语义：超过表示超出某个数量或标准，“不说话超过同意”说不通。"}, {"text": "等于", "is_correct": true, "explanation": "正确：“等于”表示性质或结果上相当、如同，不说话实际上就是同意。"}], "explanations": {"属于": "语义：属于表示隶属关系，不说话与同意之间不是隶属关系。", "吃": "搭配：“吃”不能与“同意”组成这样的比较说法，“不说话吃同意”说不通。", "超过": "语义：超过表示超出某个数量或标准，“不说话超过同意”说不通。", "等于": "正确：“等于”表示性质或结果上相当、如同，不说话实际上就是同意。"}, "sentence_index": 0, "correct_answer": "等于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的名字等于小明。", "explanation": "这里应该用〈是〉。等于表示性质或数量相当，不能用来说明名字，应说“我的名字是小明”。"}, {"text": "这次考试他考得很差，等于很好。", "explanation": "这里应该用〈却〉或〈可是〉表示转折。等于表示相同或相当，不能连接相反的情况。"}, {"text": "这块石头等于一只鸟。", "explanation": "这里应该用〈像〉。等于表示性质相同或数量相当，石头与鸟并不相当，说一物像另一物要用像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欠", "is_correct": false, "explanation": "语义：欠表示欠债或欠缺，与一个人的活和三个人的活相当的意思无关，这句说不通。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：“拿”不能与工作量组成比较句，“拿三个人干的”说不通。"}, {"text": "换", "is_correct": false, "explanation": "配价：“换”需要“换成”的对象，句中没有能被替换的对象。"}, {"text": "等于", "is_correct": true, "explanation": "正确：说明一个人的工作量与三个人相当，是性质或结果上相当的用法。"}], "explanations": {"欠": "语义：欠表示欠债或欠缺，与一个人的活和三个人的活相当的意思无关，这句说不通。", "拿": "搭配：“拿”不能与工作量组成比较句，“拿三个人干的”说不通。", "换": "配价：“换”需要“换成”的对象，句中没有能被替换的对象。", "等于": "正确：说明一个人的工作量与三个人相当，是性质或结果上相当的用法。"}, "sentence_index": 6, "correct_answer": "等于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子等于一只船。", "explanation": "这里应该用〈像〉。等于表示性质或数量相当，屋子与船并不相当；说一物像另一物要用像。"}, {"text": "这些木头等于一把椅子。", "explanation": "这里应该用〈做成〉。等于表示相当或相同，木头制成椅子要说做成，应说“这些木头做成一把椅子”。"}, {"text": "这颗种子等于一棵树。", "explanation": "这里应该用〈长成〉。等于表示相当，种子长成树要说长成，不能说等于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这样说等于得承认错误。", "corrected_sentence": "他这样说等于承认错误。", "error_description": "错误：“等于”后面不能加“得”。“等于”后直接接动词短语，应去掉“得”，写作“他这样说等于承认错误”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这样学习，等于了白学。", "corrected_sentence": "这样学习，等于白学。", "error_description": "错误：“等于”后面不能加“了”。这里表示结果相当，应去掉“了”，写作“这样学习，等于白学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
