INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90389, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "龙头是水管上拧开就有水流出来的东西。", "primary_collocate": null, "pronunciation": "lóng tóu", "ipa": "luŋ˧˥ tʰou˧˥", "syllable_count": 2, "sentences": [{"text": "他拧开龙头洗手。", "target_word": "龙头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的龙头坏了。", "target_word": "龙头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把龙头关紧。", "target_word": "龙头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龙头一开，水就流出来了。", "target_word": "龙头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在龙头下洗菜。", "target_word": "龙头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龙头没关好，一直滴水。", "target_word": "龙头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我拧了拧龙头，没有水。", "target_word": "龙头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浴室里有两个龙头。", "target_word": "龙头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用龙头接了一杯水。", "target_word": "龙头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，龙头里的水很烫。", "target_word": "龙头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "水龙头", "label": "复合"}, {"form": "龍頭", "label": "繁体"}], "register": "口语", "sense_fingerprint": "水管末端可拧开放水的开关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95593539-6a07-48d3-929c-5995fd291c1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90389, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "龙头", "is_correct": true, "explanation": "龙头：水管末端的开关，拧开就出水，他用它洗手，符合句意。"}, {"text": "瓶盖", "is_correct": false, "explanation": "语义：瓶盖不出水，不能用来洗手。"}, {"text": "肥皂", "is_correct": false, "explanation": "语义：肥皂不是出水的装置，“拧开肥皂洗手”说不通。"}, {"text": "毛巾", "is_correct": false, "explanation": "搭配：“拧开”多搭配瓶盖、龙头，不说拧开毛巾。"}], "explanations": {"龙头": "龙头：水管末端的开关，拧开就出水，他用它洗手，符合句意。", "瓶盖": "语义：瓶盖不出水，不能用来洗手。", "肥皂": "语义：肥皂不是出水的装置，“拧开肥皂洗手”说不通。", "毛巾": "搭配：“拧开”多搭配瓶盖、龙头，不说拧开毛巾。"}, "sentence_index": 0, "correct_answer": "龙头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他按下龙头关灯。", "explanation": "这里应该用〈开关〉。龙头只控制水管出水，关灯要用开关。"}, {"text": "他拧了拧龙头，灯就亮了。", "explanation": "这里应该用〈灯泡〉。龙头控制水流，灯亮要靠灯泡，不能用龙头。"}, {"text": "他拉开龙头走了出去。", "explanation": "这里应该用〈门把手〉。龙头不是门的把手，开门要拉门把手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90389, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "龙头", "is_correct": true, "explanation": "龙头：水管上的开关，拧一拧会有水或没水，符合句意。"}, {"text": "门把手", "is_correct": false, "explanation": "语义：门把手不出水，说“拧了拧门把手，没有水”不合理。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是出水的装置，“没有水”与它无关，句子说不通。"}, {"text": "灯泡", "is_correct": false, "explanation": "搭配：拧灯泡是为了换灯泡，不与“没有水”搭配。"}], "explanations": {"龙头": "龙头：水管上的开关，拧一拧会有水或没水，符合句意。", "门把手": "语义：门把手不出水，说“拧了拧门把手，没有水”不合理。", "钥匙": "语义：钥匙不是出水的装置，“没有水”与它无关，句子说不通。", "灯泡": "搭配：拧灯泡是为了换灯泡，不与“没有水”搭配。"}, "sentence_index": 6, "correct_answer": "龙头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "柜子里放着一张龙头。", "explanation": "这里应该用〈个〉。龙头是小件，量词用“个”，不用“张”。"}, {"text": "他又买了一条龙头。", "explanation": "这里应该用〈个〉。龙头是小件，量词用“个”，不用“条”。"}, {"text": "他买了一根龙头。", "explanation": "这里应该用〈个〉。龙头是小件，量词用“个”，不用“根”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房里的那本龙头坏了。", "corrected_sentence": "厨房里的那个龙头坏了。", "error_description": "量词错误：龙头应用“个”计量，“本”用于书本。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "浴室里的这辆龙头该换了。", "corrected_sentence": "浴室里的这个龙头该换了。", "error_description": "量词错误：龙头应用“个”计量，“辆”只用于车辆。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
