INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90391, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "花钱去吃饭的地方。", "primary_collocate": null, "pronunciation": "fàn diàn", "ipa": "fan˥˩ tiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我们去饭店吃晚饭吧。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的鱼很好吃。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常和朋友在饭店吃饭。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店人太多，我们要等一会儿。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店里的服务员很热情。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天妈妈不做饭，我们去饭店。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家饭店当厨师。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的菜又好吃又便宜。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请客，你知道哪家饭店好吗？", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店门口排着长队。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "飯店", "label": "繁体"}], "register": "口语", "sense_fingerprint": "花钱吃饭的店，餐馆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5695439c-db40-4c72-952c-6632c53558c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90391, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饭店", "is_correct": true, "explanation": "“饭店”是花钱吃饭的地方，“去……吃晚饭”符合语境。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是办理业务的地方，不能去那里吃晚饭。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借书阅读的地方，不是吃饭的场所。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“吃晚饭”需要餐饮场所，“教室”不搭配。"}], "explanations": {"饭店": "“饭店”是花钱吃饭的地方，“去……吃晚饭”符合语境。", "银行": "语义：银行是办理业务的地方，不能去那里吃晚饭。", "图书馆": "语义：图书馆是借书阅读的地方，不是吃饭的场所。", "教室": "搭配：“吃晚饭”需要餐饮场所，“教室”不搭配。"}, "sentence_index": 0, "correct_answer": "饭店"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想吃饭店。", "explanation": "这里应该用〈饭菜〉。“吃”的对象是饭菜；饭店是供应饭菜的店铺，不能吃。"}, {"text": "我下班后要参加饭店。", "explanation": "这里应该用〈饭局〉。“参加”的是聚餐活动，要说“参加饭局”；饭店是店铺，不能参加。"}, {"text": "我把午饭装进饭店带走。", "explanation": "这里应该用〈饭盒〉。装午饭带走要用饭盒；饭店是店铺，不能用来装饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90391, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饭店", "is_correct": true, "explanation": "“饭店”是做饭菜的店，厨师在这里工作，符合语境。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店卖书，不需要厨师。"}, {"text": "诊所", "is_correct": false, "explanation": "语义：诊所是看病的地方，不是做饭的地方。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店是剪头发的地方，不需要厨师。"}], "explanations": {"饭店": "“饭店”是做饭菜的店，厨师在这里工作，符合语境。", "书店": "语义：书店卖书，不需要厨师。", "诊所": "语义：诊所是看病的地方，不是做饭的地方。", "理发店": "语义：理发店是剪头发的地方，不需要厨师。"}, "sentence_index": 6, "correct_answer": "饭店"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些饭店很新鲜。", "explanation": "这里应该用〈食材〉。“新鲜”形容食材；饭店是店铺，不能说新鲜。"}, {"text": "妈妈用饭店炒菜，很快就做好了。", "explanation": "这里应该用〈锅〉。炒菜要用锅；饭店是店铺，不能用来炒菜。"}, {"text": "他很擅长饭店。", "explanation": "这里应该用〈烹饪〉。“擅长”的是做饭的技能；饭店是店铺，不能说擅长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90391, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朋友推荐了一只饭店，我们去尝尝。", "corrected_sentence": "朋友推荐了一家饭店，我们去尝尝。", "error_description": "量词错误：“饭店”用“家”计量，说“一家饭店”，不说“一只饭店”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90391, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去了这把饭店吃饭。", "corrected_sentence": "我们去了这家饭店吃饭。", "error_description": "量词错误：“饭店”用“家”计量，“把”用于有柄的器物，应说“这家饭店”，不说“这把饭店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
