INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90392, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "较大的旅馆，可以住宿的地方。", "primary_collocate": null, "pronunciation": "fàn diàn", "ipa": "fan˥˩ tiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我们住的饭店在海边。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店有两百个房间。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在饭店订了一个房间。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出差时，公司帮我订了饭店。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店的房间很干净，还能看到海。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人住在这家饭店的十楼。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家五星级饭店的房间很贵。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国客人明天到，请先订好饭店。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在饭店住了三天。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店离火车站很近，坐车很方便。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "飯店", "label": "繁体"}], "register": "口语", "sense_fingerprint": "较大的旅馆，可以住宿的饭店", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5695439c-db40-4c72-952c-6632c53558c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饭店", "is_correct": true, "explanation": "“饭店”是可以住宿的旅馆，“我们住的……在海边”符合语境。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆不能住宿，不能说“住的图书馆”。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不能住宿。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“住的”后接住宿场所，“公园”不搭配。"}], "explanations": {"饭店": "“饭店”是可以住宿的旅馆，“我们住的……在海边”符合语境。", "图书馆": "语义：图书馆不能住宿，不能说“住的图书馆”。", "教室": "语义：教室是上课的地方，不能住宿。", "公园": "搭配：“住的”后接住宿场所，“公园”不搭配。"}, "sentence_index": 0, "correct_answer": "饭店"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在饭店坐飞机去海边。", "explanation": "这里应该用〈机场〉。坐飞机要去机场；饭店是住宿的旅馆，不是乘机的地方。"}, {"text": "我明天去饭店参加考试。", "explanation": "这里应该用〈考场〉。参加考试要去考场；饭店是住宿或餐饮的场所，不是考试的地方。"}, {"text": "大学生住在饭店里，学校每月收费很低。", "explanation": "这里应该用〈宿舍〉。学校安排的住处称“宿舍”，饭店是对外营业的旅馆，不是学校的住处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
